def _http_status(port, path='/', timeout=0.15):
    """这个端口上请求这个路径返回的状态码，连不上或者没应答都算 0"""
    try:
        import socket
        s = socket.create_connection(('127.0.0.1', int(port)), timeout)
        try:
            _p = path or '/'
            try:
                from urllib.parse import quote
                _p = quote(_p, safe='/%')
            except Exception:
                pass
            req = 'GET %s HTTP/1.0\r\nHost: localhost\r\n\r\n' % _p
            s.sendall(req.encode('utf-8', 'ignore'))
            data = s.recv(48)
        finally:
            s.close()
        if not data[:5] == b'HTTP/':
            return 0
        try:
            return int(data.split(b' ')[1])
        except Exception:
            return 200
    except Exception:
        return 0


def _probe_rel_file():
    """从 wwwroot 里挑一个真实存在的文件，用来确认哪个端口才是壳的静态服务"""
    now = time.time()
    if _WEB_PROBE_FILE['rel'] and now - _WEB_PROBE_FILE['at'] < 600:
        return _WEB_PROBE_FILE['rel']
    rel = ''
    try:
        root = str(DEFAULT_WWW_ROOT or '').rstrip('/')
        if root and os.path.isdir(root):
            want = ('.html', '.htm', '.php', '.png', '.jpg', '.js', '.css', '.json')
            n = 0
            for base, dirs, files in os.walk(root):
                dirs[:] = [d for d in dirs if not d.startswith('.')][:12]
                for f in sorted(files):
                    if f.startswith('.'):
                        continue
                    if not f.lower().endswith(want) or ' ' in f:
                        continue
                    _r = os.path.relpath(os.path.join(base, f), root).replace('\\', '/')
                    if _r.isascii():
                        rel = _r
                        break
                    if not rel:
                        rel = _r
                n += 1
                if rel or n > 6:
                    break
    except Exception:
        rel = ''
    _WEB_PROBE_FILE['rel'] = rel
    _WEB_PROBE_FILE['at'] = now
    return rel


def _cfg_ports():
    """从壳的配置里翻端口：port 类字段，以及正文里的 localhost:1234"""
    out = []
    try:
        for d in _WEB_PORT_CFG_DIRS:
            if not os.path.isdir(d):
                continue
            try:
                names = os.listdir(d)[:60]
            except Exception:
                continue
            for nm in names:
                low = nm.lower()
                if not (low.endswith('.json') or low.endswith('.xml') or low.endswith('.conf')):
                    continue
                fp = os.path.join(d, nm)
                try:
                    if os.path.getsize(fp) > 400000:
                        continue
                    with open(fp, 'r', encoding='utf-8', errors='ignore') as f:
                        txt = f.read()
                except Exception:
                    continue
                for m in re.finditer(r'["\']?\w*port\w*["\']?\s*[:=]\s*["\']?(\d{2,5})', txt, re.I):
                    out.append(int(m.group(1)))
                for m in re.finditer(r'(?:localhost|127\.0\.0\.1):(\d{2,5})', txt):
                    out.append(int(m.group(1)))
    except Exception:
        pass
    return out


def _port_override():
    """可选的强制端口：/storage/emulated/0/tmp/web_port.txt 里写个数字就行"""
    try:
        p = '/storage/emulated/0/tmp/web_port.txt'
        if os.path.isfile(p):
            with open(p, 'r', encoding='utf-8', errors='ignore') as f:
                m = re.search(r'\d{2,5}', f.read())
            if m:
                v = int(m.group(0))
                if 1 <= v <= 65535:
                    return v
    except Exception:
        pass
    return 0


