def _web_port_log(msg):
    """端口这条路的日志：/storage/emulated/0/tmp/web_port.log（设置不成功时看这里）"""
    try:
        os.makedirs('/storage/emulated/0/tmp', exist_ok=True)
        with open(_WEB_PORT_LOG, 'a', encoding='utf-8') as f:
            f.write('%s %s\n' % (time.strftime('%m-%d %H:%M:%S'), str(msg)[:400]))
    except Exception:
        pass


def _port_user_set():
    """这个端口是不是用户自己在「⚙️ 设置 → 🔌 服务器端口」里定的"""
    try:
        with open(_WEB_PORT_USER_FILE, 'r', encoding='utf-8', errors='ignore') as f:
            return str(f.read()).strip() in ('1', 'true', 'on', 'yes', 'user')
    except Exception:
        return False


def _port_override_save(port):
    """写/清强制端口：port 有效就用它，0 或非法就改回自动。返回 (ok, 现在生效的端口, 出错原因)"""
    p = '/storage/emulated/0/tmp/web_port.txt'
    try:
        try:
            v = int(port)
        except Exception:
            v = 0
        if v and 1 <= v <= 65535:
            os.makedirs(os.path.dirname(p), exist_ok=True)
            with open(p, 'w', encoding='utf-8') as f:
                f.write(str(v))
            with open(_WEB_PORT_USER_FILE, 'w', encoding='utf-8') as f:
                f.write('1')
            _WEB_PORT_HINT.update({'port': v, 'at': 0.0, 'src': '设置'})
            _WWW_OK_PORT.update({'port': 0, 'at': 0.0, 'log': ''})
            _web_port_log('保存端口 %d 成功' % v)
            return True, v, ''
        for _f in (p, _WEB_PORT_USER_FILE):
            try:
                if os.path.isfile(_f):
                    os.remove(_f)
            except Exception as _e0:
                _web_port_log('删不掉 %s：%s' % (_f, _e0))
        _WEB_PORT_HINT.update({'port': 0, 'at': 0.0, 'src': ''})
        _WWW_OK_PORT.update({'port': 0, 'at': 0.0, 'log': ''})
        _web_port_log('已改回自动（清掉 web_port.txt / web_port_user.txt）')
        return True, 0, ''
    except Exception as e:
        _web_port_log('保存端口失败：%s' % e)
        return False, 0, str(e)


def _port_probe(port):
    """这个端口现在有没有人在应答 HTTP（给设置卡显示用）"""
    try:
        _n = int(port)
    except Exception:
        return False
    try:
        _st = _http_status(_n)
        _web_port_log('探 %d → %s' % (_n, _st))
        return _st > 0
    except Exception as e:
        _web_port_log('探 %d 出错：%s' % (_n, e))
        return False


def _web_port_remark():
    """「🔌 服务器端口」卡上那一行长的说明（手动填端口那张卡的提示用）"""
    try:
        ov = _port_override()
        if ov:
            if _port_probe(ov):
                return '现在：%d（自己设的，有人在应答）' % ov
            return '现在：%d（自己设的，这会儿还没人应答）' % ov
        return '现在：%d（自动找的）' % int(_web_port() or 0)
    except Exception:
        return '点开可以选端口'


def _web_port_short():
    """卡片正面那一行（短，别把宿主那个标签撑爆）"""
    try:
        ov = _port_override()
        if ov:
            return ('%d · 自己设的' % ov) + ('（在应答）' if _port_probe(ov) else '（还没人应答）')
        return '%d · 自动找的' % int(_web_port() or 0)
    except Exception:
        return '点开选端口'


def _web_port_normalize(raw):
    """把各种形状的输入（字符串 / dict / list / 宿主弹窗回来的值）挤成一个字符串"""
    try:
        if isinstance(raw, dict):
            raw = raw.get('text') or raw.get('input') or raw.get('value') or ''
        if isinstance(raw, (list, tuple)):
            _p = []
            for _x in raw:
                if isinstance(_x, dict):
                    _p.append(str(_x.get('value') or _x.get('text') or ''))
                else:
                    _p.append(str(_x))
            raw = ' '.join(_p)
        return str(raw if raw is not None else '').strip()
    except Exception:
        return ''


def _web_port_apply(raw):
    """设置提交的值：数字＝用这个端口，0/留空＝改回自动。返回 (ok, 给用户看的话)"""
    _w = _web_port_normalize(raw)
    _web_port_log('收到设置值：%s' % _w[:80])
    m = re.search(r'\d{1,6}', _w)
    if not m or int(m.group(0)) == 0:
        ok, _v, err = _port_override_save(0)
        if not ok:
            return False, '改回自动没写成功：%s\n（写不进 /storage/emulated/0/tmp，看看壳有没有存储权限）' % (err or '未知原因')
        return True, '✅ 已改回自动找端口\n' + _web_port_remark()
    v = int(m.group(0))
    if not (1 <= v <= 65535):
        return False, '端口要在 1-65535 之间，你填的是 %d' % v
    ok, _v, err = _port_override_save(v)
    if not ok:
        return False, ('写不进 /storage/emulated/0/tmp/web_port.txt：%s\n'
                       '（手动建一个 tmp 目录，或看 tmp/web_port.log）' % (err or '未知原因'))
    if _port_probe(v):
        return True, ('✅ 端口已设成 %d\n工具里的 html/php 就按这个端口打开\n'
                      '这个端口现在有人在应答，直接用' % v)
    return True, ('✅ 端口已设成 %d\n工具里的 html/php 就按这个端口打开\n'
                  '⚠️ 现在还探不到这个端口有人应答：端口要和壳的网页服务一致，壳那边换了端口就改这里' % v)


def _wport_rows():
    """端口页要列出来的候选：自己设的、当前在用的、常见的那几个"""
    out = []
    try:
        _cur = int(_web_port() or 0)
    except Exception:
        _cur = 0
    try:
        _ov = int(_port_override() or 0)
    except Exception:
        _ov = 0
    for _p in [_ov, _cur] + list(_WEB_PORT_COMMON):
        try:
            _p = int(_p)
        except Exception:
            continue
        if 1 <= _p <= 65535 and _p not in out:
            out.append(_p)
    return out[:10]


def _wport_item(title, remarks, cmd, pic, style='grid'):
    it = {
        'vod_id': json.dumps({'actionId': cmd}, ensure_ascii=False),
        'action': cmd,
        'vod_name': title,
        'vod_pic': pic,
        'vod_remarks': remarks,
        'vod_tag': 'action',
    }
    it['style'] = {'type': 'list'} if style == 'list' else {'type': 'grid', 'ratio': 1}
    return it


def _wport_page():
    """「🔌 服务器端口」点开后的那一页：状态 + 自动找 + 常见端口（每个都标着现在有没有人应答）"""
    try:
        ov = int(_port_override() or 0)
    except Exception:
        ov = 0
    try:
        cur = int(_web_port() or 0)
    except Exception:
        cur = 0
    out = [_wport_item('🔌 现在用的是 %d' % cur,
                       '来源：%s\n点下面哪个就用哪个（点完回这一页看状态）' % ('自己在设置里定的' if ov else '自动找的'),
                       '服务器端口刷新', WPPORT_COVER, 'list')]
    out.append(_wport_item('🔄 自动找端口', '不指定，脚本自己探到哪个用哪个', '端口设置|auto', WPPORT_AUTO_COVER))
    for _p in _wport_rows():
        _alive = _port_probe(_p)
        _extra = ''
        if _p == ov:
            _extra = '（当前·自己设的）'
        elif _p == cur:
            _extra = '（当前）'
        out.append(_wport_item('%d' % _p,
                               ('✅ 有人在应答' if _alive else '现在没人应答') + _extra + '\n点一下就用这个端口',
                               '端口设置|%d' % _p, WPPORT_PORT_COVER))
    out.append(_wport_item('✍️ 手动填端口', '弹个框自己填（填 0 或留空＝改回自动找）', '服务器端口手动', WPPORT_MANUAL_COVER, 'list'))
    return {'page': 1, 'pagecount': 1, 'limit': len(out), 'total': len(out), 'list': out}


_WWW_OK_PORT = {'port': 0, 'at': 0.0, 'log': ''}


def _web_files_port(force=False):
    """找出真正能把 wwwroot 里的文件供出来的端口：必须用真实文件探到 200，探不到返回 0"""
    now = time.time()
    rel = _probe_rel_file()
    if not rel:
        return 0
    if not force and _WWW_OK_PORT['port'] and now - _WWW_OK_PORT['at'] < 120:
        if _http_status(_WWW_OK_PORT['port'], '/' + rel) == 200:
            return _WWW_OK_PORT['port']
    seen = []
    for p in list(_cfg_ports()) + list(_WEB_PORT_COMMON):
        try:
            p = int(p)
        except Exception:
            continue
        if p in seen:
            continue
        seen.append(p)
        if _http_status(p, '/' + rel) == 200:
            _WWW_OK_PORT.update({'port': p, 'at': now})
            return p
    _WWW_OK_PORT.update({'port': 0, 'at': now})
    return 0


def _web_port(force=False):
    """当前网页服务端口；缓存 5 分钟，force=True 重新找"""
    now = time.time()
    _ttl = 20 if _WEB_PORT_HINT.get('src') == 'default' else 300
    if not force and _WEB_PORT_HINT['port'] and now - _WEB_PORT_HINT['at'] < _ttl:
        if _http_status(_WEB_PORT_HINT['port'], '/') > 0:
            return _WEB_PORT_HINT['port']
        # 缓存的那个端口现在没人应答（比如服务重启换了端口），别再用它拼网址，重新现查
    ov = _port_override()
    if ov:
        _rel0 = _probe_rel_file()
        _ok = _http_status(ov, '/') > 0 or (_rel0 and _http_status(ov, '/' + _rel0) > 0)
        if _ok:
            _WEB_PORT_HINT.update({'port': ov, 'at': now, 'src': 'override'})
            return ov
        if _port_user_set():
            # 2026-11-11 v202：这个端口是用户在「⚙️ 设置 → 🔌 服务器端口」里自己定的，就是它，
            # 别再被自动探测顶掉；卡面上会写清楚现在有没有人应答，随时能改回去
            _WEB_PORT_HINT.update({'port': ov, 'at': now, 'src': '设置'})
            return ov
        # /storage/emulated/0/tmp/web_port.txt 里写了个没人应答的端口（常见是留了个 7000 之类的旧值），
        # 别拿它拼网址，忽略掉继续现查
    cands = []
    for p in list(_cfg_ports()) + list(_WEB_PORT_COMMON):
        try:
            p = int(p)
        except Exception:
            continue
        if 1 <= p <= 65535 and p not in cands:
            cands.append(p)
    cands = cands[:12]
    rel = _probe_rel_file()
    port, src = 0, ''
    if rel:
        for p in cands:
            if _http_status(p, '/' + rel) == 200:
                port, src = p, 'wwwroot'
                break
    if not port:
        for p in cands:
            if _http_status(p, '/') > 0:
                port, src = p, 'http'
                break
    if not port:
        port, src = (cands[0] if cands else 8901), 'default'
    _WEB_PORT_HINT.update({'port': port, 'at': now, 'src': src})
    return port

