class CustomSourceManager:
    """自定义源读写：一份 json，三个列表 live / short / gallery"""

    @classmethod
    def load_all(cls):
        data = {k: [] for k in CUSTOM_SOURCE_KINDS}
        try:
            if os.path.isfile(CUSTOM_SOURCE_FILE):
                with open(CUSTOM_SOURCE_FILE, 'r', encoding='utf-8') as fh:
                    raw = json.load(fh)
                if isinstance(raw, dict):
                    for k in CUSTOM_SOURCE_KINDS:
                        rows = raw.get(k)
                        if not isinstance(rows, list):
                            continue
                        out = []
                        for it in rows:
                            if isinstance(it, dict) and str(it.get('url') or '').strip():
                                row = {'name': str(it.get('name') or '').strip() or str(it['url']).strip(),
                                       'url': str(it['url']).strip()}
                                for _ek in CUSTOM_SOURCE_EXTRA_KEYS:
                                    _ev = it.get(_ek)
                                    if isinstance(_ev, str):
                                        if _ev.strip():
                                            row[_ek] = _ev.strip()
                                    elif _ev not in (None, '', [], {}):
                                        row[_ek] = _ev
                                out.append(row)
                            elif isinstance(it, str) and it.strip():
                                out.append({'name': it.strip(), 'url': it.strip()})
                        data[k] = out
        except Exception:
            pass
        return data

    @classmethod
    def list(cls, kind):
        if kind not in CUSTOM_SOURCE_KINDS:
            return []
        return cls.load_all().get(kind) or []

    @classmethod
    def save_all(cls, data):
        try:
            os.makedirs(os.path.dirname(CUSTOM_SOURCE_FILE), exist_ok=True)
            tmp = CUSTOM_SOURCE_FILE + '.tmp'
            with open(tmp, 'w', encoding='utf-8') as fh:
                json.dump(data, fh, ensure_ascii=False, indent=2)
            os.replace(tmp, CUSTOM_SOURCE_FILE)
            return True
        except Exception:
            return False

    @classmethod
    def add(cls, kind, name, url, cover='', extra=None):
        """加一条；同名或同链接已存在就覆盖。extra 可带 type/remarks/ua/referer/playerType 等。返回 (ok, 说明)"""
        if kind not in CUSTOM_SOURCE_KINDS:
            return False, '未知类型'
        url = str(url or '').strip().strip('"').strip("'")
        if not url:
            return False, '链接不能为空'
        if not url.startswith(('http://', 'https://', 'rtmp://', 'rtsp://')):
            url = 'http://' + url
        name = str(name or '').strip() or url
        data = cls.load_all()
        rows = data.setdefault(kind, [])
        hit = None
        for it in rows:
            if it.get('name') == name or it.get('url') == url:
                hit = it
                break
        if hit is not None:
            rows.remove(hit)
        rec = {'name': name, 'url': url}
        if str(cover or '').strip():
            rec['cover'] = str(cover).strip()
        if isinstance(extra, dict):
            for _ek, _ev in extra.items():
                if _ek in CUSTOM_SOURCE_EXTRA_KEYS and _ev not in (None, '', [], {}):
                    rec[_ek] = _ev
        rows.append(rec)
        ok = cls.save_all(data)
        return ok, '%s：%s\n%s' % ('已覆盖' if hit is not None else '已添加', name, url)

    @classmethod
    def remove(cls, kind, key):
        if kind not in CUSTOM_SOURCE_KINDS:
            return False, '未知类型'
        key = str(key or '').strip()
        data = cls.load_all()
        rows = data.get(kind) or []
        keep, gone = [], []
        for it in rows:
            if it.get('name') == key or it.get('url') == key:
                gone.append(it)
            else:
                keep.append(it)
        if not gone:
            return False, '没找到「%s」' % key
        data[kind] = keep
        ok = cls.save_all(data)
        return ok, '已删除：' + '、'.join([str(it.get('name') or '') for it in gone])

