# 动作里「🔀 界面排列」写这个文件；所有列表页返回前统一照它改写 style。
VIEW_MODE_FILE = '/storage/emulated/0/tmp/view_mode.json'
VIEW_MODE_GRID = 'grid'
VIEW_MODE_LIST = 'list'
DEFAULT_VIEW_MODE = VIEW_MODE_GRID


class ViewModeConfig:
    """界面排列方式：grid=网格，list=列表"""

    @staticmethod
    def load_config():
        default_config = {'view_mode': DEFAULT_VIEW_MODE}
        try:
            if os.path.exists(VIEW_MODE_FILE):
                with open(VIEW_MODE_FILE, 'r', encoding='utf-8') as f:
                    config = json.load(f)
                if not isinstance(config, dict):
                    config = {}
                if str(config.get('view_mode') or '').strip() not in (VIEW_MODE_GRID, VIEW_MODE_LIST):
                    config['view_mode'] = DEFAULT_VIEW_MODE
                return config
            return default_config
        except Exception:
            return default_config

    @staticmethod
    def save_config(config):
        try:
            os.makedirs(os.path.dirname(VIEW_MODE_FILE), exist_ok=True)
            with open(VIEW_MODE_FILE, 'w', encoding='utf-8') as f:
                json.dump(config, f, ensure_ascii=False, indent=2)
            return True
        except Exception:
            return False

    @staticmethod
    def get_mode():
        try:
            return str(ViewModeConfig.load_config().get('view_mode') or DEFAULT_VIEW_MODE)
        except Exception:
            return DEFAULT_VIEW_MODE

    @staticmethod
    def set_mode(mode):
        config = ViewModeConfig.load_config()
        config['view_mode'] = VIEW_MODE_LIST if str(mode) == VIEW_MODE_LIST else VIEW_MODE_GRID
        return ViewModeConfig.save_config(config)

    @staticmethod
    def toggle():
        """在 网格 / 列表 之间来回切，返回切换后的值"""
        new_mode = VIEW_MODE_LIST if ViewModeConfig.get_mode() == VIEW_MODE_GRID else VIEW_MODE_GRID
        if not ViewModeConfig.set_mode(new_mode):
            return ViewModeConfig.get_mode()
        return new_mode

    @staticmethod
    def get_label():
        return '🖼 网格排列' if ViewModeConfig.get_mode() != VIEW_MODE_LIST else '📋 列表排列'

    @staticmethod
    def get_short_label():
        return '🖼 网格' if ViewModeConfig.get_mode() != VIEW_MODE_LIST else '📋 列表'


def apply_view_mode(data):
    """按当前排列方式，把返回里每一项的 style 统一成网格或列表。
    只动 style 这一个键：条目、数量、顺序、其它字段一律不碰。
    网格：沿用每项原来的 ratio（分类墙是 1，海报是 0.75），没有就 0.75。
    列表：统一 {'type': 'list'}。"""
    try:
        if not isinstance(data, dict):
            return data
        rows = data.get('list')
        if not isinstance(rows, list) or not rows:
            return data
        mode = ViewModeConfig.get_mode()
        for it in rows:
            if not isinstance(it, dict):
                continue
            if mode == VIEW_MODE_LIST:
                it['style'] = {'type': 'list'}
                continue
            old = it.get('style') if isinstance(it.get('style'), dict) else {}
            try:
                ratio = float(old.get('ratio'))
            except Exception:
                ratio = 0.75
            if ratio <= 0 or ratio > 3:
                ratio = 0.75
            if ratio == int(ratio):
                ratio = int(ratio)
            it['style'] = {'type': 'grid', 'ratio': ratio}
    except Exception:
        return data
    return data


def _view_mode_apply_custom(func):
    """详情入口里那些自制页面（文件操作 / 压缩包 / 修改 / 选目标文件夹）也要跟着排列方式走"""
    def _wrapper(self, ids, *args, **kwargs):
        data = func(self, ids, *args, **kwargs)
        try:
            _id = ''
            if isinstance(ids, (list, tuple)) and ids:
                _id = str(ids[0])
            elif isinstance(ids, str):
                _id = ids
            _prefs = (getattr(self, 'FILOP_PREFIX', 'fsop://'), 'zip://', 'fssel://', 'fsdest://', 'zipdest://',
                      'zipdir://', 'fsenter://', 'fsdo://', 'zipdo://', 'edit://', 'editdir://', 'editfiles://',
                      'editview://', 'editat://')
            if _id.startswith(_prefs):
                return apply_view_mode(data)
        except Exception:
            return data
        return data
    return _wrapper


def _view_mode_apply(func):
    """首页 / 分类 / 搜索 / 动作 四个入口统一套上排列方式（详情页不动）"""
    def _wrapper(self, *args, **kwargs):
        try:
            data = func(self, *args, **kwargs)
        except Exception:
            raise
        return apply_view_mode(data)
    try:
        _wrapper.__name__ = func.__name__
        _wrapper.__doc__ = func.__doc__
    except Exception:
        pass
    return _wrapper


