# ==================== XLS/XLSX 磁力文件解析器（支持随机抽取） ====================

class XLSXMagnetParser:
    """XLSX磁力链接文件解析器 - 纯二进制版（支持随机抽取）"""
    
    @staticmethod
    def parse_magnet_from_xlsx(file_path):
        items = []
        try:
            import zipfile
            all_text = ""
            with zipfile.ZipFile(file_path, 'r') as zf:
                for name in zf.namelist():
                    if name.endswith('.xml'):
                        try:
                            content = zf.read(name).decode('utf-8', errors='ignore')
                            all_text += content
                        except:
                            pass
            if not all_text:
                with open(file_path, 'rb') as f:
                    all_text = f.read(MAX_XLSX_READ_SIZE).decode('utf-8', errors='ignore')
            
            magnet_pattern = re.compile(r'magnet:\?[^\s\'"<>《》]+', re.I)
            ed2k_pattern = re.compile(r'ed2k://[^\s\'"<>《》\|]+(?:\|[^\s\'"<>《》]+)*', re.I)
            
            all_magnets = list(dict.fromkeys(magnet_pattern.findall(all_text)))
            all_ed2ks = list(dict.fromkeys(ed2k_pattern.findall(all_text)))
            
            read_mode = MagnetConfigManager.get_read_mode()
            max_items = MagnetConfigManager.get_max_items()
            
            magnets = []
            ed2ks = []
            
            if read_mode == MAGNET_READ_MODE_RANDOM:
                # 随机模式：从全部磁力链接中随机抽取 max_items 条
                if len(all_magnets) >= max_items:
                    magnets = random.sample(all_magnets, max_items)
                else:
                    magnets = all_magnets[:]
                    random.shuffle(magnets)
                    remaining = max_items - len(magnets)
                    if len(all_ed2ks) >= remaining:
                        ed2ks = random.sample(all_ed2ks, remaining)
                    else:
                        ed2ks = all_ed2ks[:]
                        random.shuffle(ed2ks)
            else:
                # 顺序模式：取前 max_items 条
                magnets = all_magnets[:max_items]
                remaining = max_items - len(magnets)
                if remaining > 0:
                    ed2ks = all_ed2ks[:remaining]
            
            for magnet in magnets:
                name_match = re.search(r'dn=([^&]+)', magnet)
                if name_match:
                    name = urllib.parse.unquote(name_match.group(1))
                else:
                    name = f"磁力链接{len(items)+1}"
                name = name.replace('\n', ' ').replace('\r', ' ').strip()
                items.append({'name': name, 'url': magnet})
                if len(items) >= max_items:
                    break
            
            remaining = max_items - len(items)
            for ed2k in ed2ks[:remaining]:
                name_match = re.search(r'/([^/|]+)(?:\||$)', ed2k)
                if name_match:
                    name = name_match.group(1)
                else:
                    name = f"电驴链接{len(items)+1}"
                name = name.replace('\n', ' ').replace('\r', ' ').strip()
                items.append({'name': name, 'url': ed2k})
                if len(items) >= max_items:
                    break
            
            if items:
                mode_display = "随机抽取" if read_mode == MAGNET_READ_MODE_RANDOM else "顺序"
                print(f"✅ XLSX解析完成: {os.path.basename(file_path)}, 共 {len(items)} 条 (模式: {mode_display})")
        except Exception as e:
            print(f"❌ XLSX解析失败: {e}")
        return items
    
    @staticmethod
    def _parse_binary(file_path):
        items = []
        try:
            with open(file_path, 'rb') as f:
                content = f.read(MAX_XLSX_READ_SIZE)
            all_text = content.decode('utf-8', errors='ignore')
            if len(all_text) < 100:
                all_text = content.decode('latin-1', errors='ignore')
            
            magnet_pattern_simple = re.compile(r'magnet:\?[^\s\'"<>]+', re.I)
            ed2k_pattern_simple = re.compile(r'ed2k://[^\s\'"<>]+', re.I)
            
            all_magnets = list(dict.fromkeys(magnet_pattern_simple.findall(all_text)))
            all_ed2ks = list(dict.fromkeys(ed2k_pattern_simple.findall(all_text)))
            
            read_mode = MagnetConfigManager.get_read_mode()
            max_items = MagnetConfigManager.get_max_items()
            
            magnets = []
            ed2ks = []
            
            if read_mode == MAGNET_READ_MODE_RANDOM:
                if len(all_magnets) >= max_items:
                    magnets = random.sample(all_magnets, max_items)
                else:
                    magnets = all_magnets[:]
                    random.shuffle(magnets)
                    remaining = max_items - len(magnets)
                    if len(all_ed2ks) >= remaining:
                        ed2ks = random.sample(all_ed2ks, remaining)
                    else:
                        ed2ks = all_ed2ks[:]
                        random.shuffle(ed2ks)
            else:
                magnets = all_magnets[:max_items]
                remaining = max_items - len(magnets)
                if remaining > 0:
                    ed2ks = all_ed2ks[:remaining]
            
            for magnet in magnets:
                name_match = re.search(r'dn=([^&]+)', magnet)
                if name_match:
                    name = urllib.parse.unquote(name_match.group(1))
                else:
                    xt_match = re.search(r'xt=urn:btih:([^&]+)', magnet)
                    if xt_match:
                        name = f"磁力_{xt_match.group(1)[:16]}"
                    else:
                        name = f"磁力链接{len(items)+1}"
                name = name.replace('\n', ' ').replace('\r', ' ').strip()
                name = re.sub(r'[<>:"/\\|?*]', '_', name)
                if len(name) > 80:
                    name = name[:77] + '...'
                items.append({'name': name, 'url': magnet})
                if len(items) >= max_items:
                    break
            
            remaining = max_items - len(items)
            for ed2k in ed2ks[:remaining]:
                name = XLSXMagnetParser._extract_ed2k_name(ed2k)
                if not name or len(name) < 1:
                    name = f"电驴链接{len(items)+1}"
                name = name.replace('\n', ' ').replace('\r', ' ').strip()
                if len(name) > 80:
                    name = name[:77] + '...'
                items.append({'name': name, 'url': ed2k})
                if len(items) >= max_items:
                    break
            
            if items:
                mode_display = "随机抽取" if read_mode == MAGNET_READ_MODE_RANDOM else "顺序"
                print(f"✅ 二进制解析完成: {os.path.basename(file_path)}, 共 {len(items)} 条 (模式: {mode_display})")
        except Exception as e:
            print(f"❌ 二进制解析失败: {e}")
        return items
    
    @staticmethod
    def _extract_ed2k_name(ed2k):
        name = None
        file_match = re.search(r'\|file\|([^|]+)\|', ed2k, re.I)
        if file_match:
            name = file_match.group(1)
        else:
            last_slash = ed2k.rfind('/')
            if last_slash != -1:
                temp = ed2k[last_slash + 1:]
                pipe_pos = temp.find('|')
                if pipe_pos != -1:
                    name = temp[:pipe_pos]
                else:
                    name = temp
        if name:
            name = name.replace('\n', ' ').replace('\r', ' ').strip()
            name = urllib.parse.unquote(name)
            name = re.sub(r'[<>:"/\\|?*]', '_', name)
            if len(name) > 80:
                name = name[:77] + '...'
        return name


# ==================== 磁力/TXT链接解析器（增强正则匹配 + 随机抽取） ====================

class MagnetLinkParser:
    """磁力链接和电驴链接解析器（支持TXT文件，增强正则匹配）"""
    
    @staticmethod
    def parse_magnet_from_txt(file_path):
        items = []
        try:
            with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read()
            
            # 更宽松的正则 - 匹配磁力链接直到遇到空格或换行或引号
            magnet_pattern = re.compile(r'magnet:\?[^\s\n\r\'"<>《》]+', re.I)
            ed2k_pattern = re.compile(r'ed2k://[^\s\n\r\'"<>《》]+', re.I)
            
            all_magnets = list(dict.fromkeys(magnet_pattern.findall(content)))
            all_ed2ks = list(dict.fromkeys(ed2k_pattern.findall(content)))
            
            read_mode = MagnetConfigManager.get_read_mode()
            max_items = MagnetConfigManager.get_max_items()
            
            magnets = []
            ed2ks = []
            
            if read_mode == MAGNET_READ_MODE_RANDOM:
                if len(all_magnets) >= max_items:
                    magnets = random.sample(all_magnets, max_items)
                else:
                    magnets = all_magnets[:]
                    random.shuffle(magnets)
                    remaining = max_items - len(magnets)
                    if len(all_ed2ks) >= remaining:
                        ed2ks = random.sample(all_ed2ks, remaining)
                    else:
                        ed2ks = all_ed2ks[:]
                        random.shuffle(ed2ks)
            else:
                magnets = all_magnets[:max_items]
                remaining = max_items - len(magnets)
                if remaining > 0:
                    ed2ks = all_ed2ks[:remaining]
            
            for magnet in magnets:
                name_match = re.search(r'dn=([^&]+)', magnet)
                if name_match:
                    name = urllib.parse.unquote(name_match.group(1))
                else:
                    xt_match = re.search(r'xt=urn:btih:([^&]+)', magnet)
                    if xt_match:
                        name = f"磁力_{xt_match.group(1)[:16]}"
                    else:
                        name = f"磁力链接{len(items)+1}"
                name = name.replace('\n', ' ').replace('\r', ' ').strip()
                name = re.sub(r'[<>:"/\\|?*]', '_', name)
                if len(name) > 80:
                    name = name[:77] + '...'
                items.append({'name': name, 'url': magnet})
                if len(items) >= max_items:
                    break
            
            remaining = max_items - len(items)
            for ed2k in ed2ks[:remaining]:
                name_match = re.search(r'/([^/|]+)(?:\||$)', ed2k)
                if name_match:
                    name = name_match.group(1)
                else:
                    name = f"电驴链接{len(items)+1}"
                name = name.replace('\n', ' ').replace('\r', ' ').strip()
                if len(name) > 80:
                    name = name[:77] + '...'
                items.append({'name': name, 'url': ed2k})
                if len(items) >= max_items:
                    break
            
            if items:
                mode_display = "随机抽取" if read_mode == MAGNET_READ_MODE_RANDOM else "顺序"
                print(f"✅ TXT解析完成: {os.path.basename(file_path)}, 共 {len(items)} 条 (模式: {mode_display})")
            else:
                # 如果没解析到，尝试用更宽松的逐行方式
                print(f"⚠️ 未解析到磁力链接，尝试逐行解析: {os.path.basename(file_path)}")
                items = MagnetLinkParser._parse_line_by_line(file_path, max_items, read_mode)
        except Exception as e:
            print(f"❌ TXT解析失败: {e}")
        return items
    
    @staticmethod
    def _parse_line_by_line(file_path, max_items, read_mode):
        """逐行解析备用方法"""
        items = []
        try:
            with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                lines = f.readlines()
            
            all_magnets = []
            all_ed2ks = []
            
            for line in lines:
                line = line.strip()
                if not line:
                    continue
                # 磁力链接
                mag_match = re.search(r'magnet:\?[^\s\n\r\'"<>《》]+', line, re.I)
                if mag_match:
                    all_magnets.append(mag_match.group(0))
                    continue
                # 电驴链接
                ed_match = re.search(r'ed2k://[^\s\n\r\'"<>《》]+', line, re.I)
                if ed_match:
                    all_ed2ks.append(ed_match.group(0))
                    continue
            
            # 去重
            all_magnets = list(dict.fromkeys(all_magnets))
            all_ed2ks = list(dict.fromkeys(all_ed2ks))
            
            magnets = []
            ed2ks = []
            
            if read_mode == MAGNET_READ_MODE_RANDOM:
                if len(all_magnets) >= max_items:
                    magnets = random.sample(all_magnets, max_items)
                else:
                    magnets = all_magnets[:]
                    random.shuffle(magnets)
                    remaining = max_items - len(magnets)
                    if len(all_ed2ks) >= remaining:
                        ed2ks = random.sample(all_ed2ks, remaining)
                    else:
                        ed2ks = all_ed2ks[:]
                        random.shuffle(ed2ks)
            else:
                magnets = all_magnets[:max_items]
                remaining = max_items - len(magnets)
                if remaining > 0:
                    ed2ks = all_ed2ks[:remaining]
            
            for magnet in magnets:
                name_match = re.search(r'dn=([^&]+)', magnet)
                if name_match:
                    name = urllib.parse.unquote(name_match.group(1))
                else:
                    xt_match = re.search(r'xt=urn:btih:([^&]+)', magnet)
                    if xt_match:
                        name = f"磁力_{xt_match.group(1)[:16]}"
                    else:
                        name = f"磁力链接{len(items)+1}"
                name = name.replace('\n', ' ').replace('\r', ' ').strip()
                name = re.sub(r'[<>:"/\\|?*]', '_', name)
                if len(name) > 80:
                    name = name[:77] + '...'
                items.append({'name': name, 'url': magnet})
                if len(items) >= max_items:
                    break
            
            remaining = max_items - len(items)
            for ed2k in ed2ks[:remaining]:
                name_match = re.search(r'/([^/|]+)(?:\||$)', ed2k)
                if name_match:
                    name = name_match.group(1)
                else:
                    name = f"电驴链接{len(items)+1}"
                name = name.replace('\n', ' ').replace('\r', ' ').strip()
                if len(name) > 80:
                    name = name[:77] + '...'
                items.append({'name': name, 'url': ed2k})
                if len(items) >= max_items:
                    break
            
            if items:
                mode_display = "随机抽取" if read_mode == MAGNET_READ_MODE_RANDOM else "顺序"
                print(f"✅ 逐行解析完成: {os.path.basename(file_path)}, 共 {len(items)} 条 (模式: {mode_display})")
        except Exception as e:
            print(f"❌ 逐行解析失败: {e}")
        return items
    
    @staticmethod
    def _extract_ed2k_name(ed2k):
        name = None
        file_match = re.search(r'\|file\|([^|]+)\|', ed2k, re.I)
        if file_match:
            name = file_match.group(1)
        else:
            last_slash = ed2k.rfind('/')
            if last_slash != -1:
                temp = ed2k[last_slash + 1:]
                pipe_pos = temp.find('|')
                if pipe_pos != -1:
                    name = temp[:pipe_pos]
                else:
                    name = temp
        if name:
            name = name.replace('\n', ' ').replace('\r', ' ').strip()
            name = urllib.parse.unquote(name)
            name = re.sub(r'[<>:"/\\|?*]', '_', name)
            if len(name) > 80:
                name = name[:77] + '...'
        return name
    
    @staticmethod
    def is_magnet_txt_file(file_path):
        try:
            with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                preview = f.read(8192)
            if re.search(r'magnet:\?', preview, re.I):
                return True
            if re.search(r'ed2k://', preview, re.I):
                return True
            return False
        except:
            return False


# ==================== 种子文件（.torrent）解析 ====================
class TorrentFileParser:
    """把 .torrent（bencode）拆成种子名 / infohash / 文件清单，再拼成磁力链接

    壳子只会播磁力、电驴这类链接，种子里本身没有链接，所以这里自己算 infohash，
    拼 magnet:?xt=urn:btih:...&dn=...&tr=...。多文件的种子先给一格「整个种子」，
    再把里面的文件各列一格（点的还是同一个种子，只是方便看清里面有什么）。
    """

    MAX_FILES = 200

    @staticmethod
    def _decode(data, idx=0):
        """最小 bencode 解析：返回 (值, 下一个字节位置)"""
        if idx >= len(data):
            raise ValueError('种子不完整')
        c = data[idx:idx + 1]
        if c == b'i':
            end = data.index(b'e', idx)
            return int(data[idx + 1:end]), end + 1
        if c == b'l':
            idx += 1
            out = []
            while data[idx:idx + 1] != b'e':
                val, idx = TorrentFileParser._decode(data, idx)
                out.append(val)
            return out, idx + 1
        if c == b'd':
            idx += 1
            out = {}
            while data[idx:idx + 1] != b'e':
                key, idx = TorrentFileParser._decode(data, idx)
                val, idx = TorrentFileParser._decode(data, idx)
                if isinstance(key, (bytes, bytearray)):
                    key = key.decode('utf-8', 'replace')
                out[key] = val
            return out, idx + 1
        colon = data.index(b':', idx)
        length = int(data[idx:colon])
        start = colon + 1
        return data[start:start + length], start + length

    @staticmethod
    def _top(data):
        """拆最外层字典，顺手留着 info 的原始字节（infohash 必须按原样字节算）"""
        if data[:1] != b'd':
            raise ValueError('不是 bencode 种子')
        out = {}
        idx = 1
        while data[idx:idx + 1] != b'e':
            key, idx = TorrentFileParser._decode(data, idx)
            start = idx
            val, idx = TorrentFileParser._decode(data, idx)
            name = key.decode('utf-8', 'replace') if isinstance(key, (bytes, bytearray)) else str(key)
            out[name] = (val, data[start:idx])
        return out

    @staticmethod
    def _text(val):
        """种子里的名字不一定是 utf-8：老的中文种子多用 gbk，逐个试"""
        if isinstance(val, (bytes, bytearray)):
            raw = bytes(val)
            for enc in ('utf-8', 'gbk', 'big5'):
                try:
                    return raw.decode(enc)
                except Exception:
                    continue
            return raw.decode('utf-8', 'replace')
        return '' if val is None else str(val)

    @staticmethod
    def _size(num):
        try:
            val = float(num)
        except Exception:
            return ''
        for unit in ('B', 'KB', 'MB', 'GB', 'TB'):
            if val < 1024 or unit == 'TB':
                return ('%d%s' % (val, unit)) if unit == 'B' else ('%.1f%s' % (val, unit))
            val /= 1024.0
        return ''

    @staticmethod
    def _clean(name):
        """名字里不能带 $ 和 #，宿主用它们分隔标题和地址"""
        text = str(name or '').replace('$', ' ').replace('#', ' ')
        text = text.replace('\r', ' ').replace('\n', ' ').strip()
        return re.sub(r'[<>:"/\\|?*]', '_', text)

    @staticmethod
    def parse(file_path, max_files=None):
        """返回 [{'name','url','remarks'}]；不是种子或读不出来返回 []"""
        limit = int(max_files or TorrentFileParser.MAX_FILES)
        try:
            with open(file_path, 'rb') as f:
                data = f.read()
        except Exception:
            return []
        if not data or data[:1] != b'd':
            return []
        try:
            top = TorrentFileParser._top(data)
        except Exception:
            return []
        info, raw = top.get('info') or (None, b'')
        if not isinstance(info, dict) or not raw:
            return []
        try:
            info_hash = hashlib.sha1(raw).hexdigest()
        except Exception:
            return []
        name = TorrentFileParser._clean(TorrentFileParser._text(info.get('name')))
        if not name:
            name = os.path.splitext(os.path.basename(file_path))[0]
        trackers = []
        try:
            announce = top.get('announce')
            if announce and announce[0]:
                trackers.append(TorrentFileParser._text(announce[0]))
            for tier in ((top.get('announce-list') or (None, b''))[0] or []):
                for one in (tier or []):
                    trackers.append(TorrentFileParser._text(one))
        except Exception:
            pass
        seen = set()
        uniq = []
        for tr in trackers:
            tr = str(tr or '').strip()
            if not tr or tr in seen:
                continue
            seen.add(tr)
            uniq.append(tr)
        magnet = 'magnet:?xt=urn:btih:%s&dn=%s' % (info_hash, urllib.parse.quote(name))
        for tr in uniq[:8]:
            magnet += '&tr=' + urllib.parse.quote(tr, safe='')
        out = []
        files = info.get('files')
        if isinstance(files, list) and files:
            total = 0
            for one in files:
                if isinstance(one, dict):
                    try:
                        total += int(one.get('length') or 0)
                    except Exception:
                        pass
            out.append({'name': '%s（%d 个文件 · %s）' % (name, len(files), TorrentFileParser._size(total)),
                        'url': magnet, 'remarks': '整个种子'})
            for one in files[:limit]:
                if not isinstance(one, dict):
                    continue
                path = '/'.join([TorrentFileParser._text(part) for part in (one.get('path') or []) if part])
                path = TorrentFileParser._clean(path) or name
                size = TorrentFileParser._size(one.get('length'))
                out.append({'name': ('%s · %s' % (path, size)) if size else path,
                            'url': magnet, 'remarks': '同一种子'})
        else:
            size = TorrentFileParser._size(info.get('length'))
            out.append({'name': ('%s · %s' % (name, size)) if size else name,
                        'url': magnet, 'remarks': '单文件种子'})
        return out


