    def handle_action(self, action_obj):
        try:
            if isinstance(action_obj, str):
                obj = json.loads(action_obj)
            else:
                obj = action_obj
            action_id = obj.get('actionId', '')
            value = obj.get('value', '')
            input_text = ''
            if isinstance(value, dict):
                input_text = value.get('text', '').strip()
            elif isinstance(value, str):
                input_text = value.strip()
            if action_id == 'OPEN_URL':
                url = obj.get('url', '')
                if url:
                    _tt2 = obj.get('title', '')
                    if self._webview_open(url, _tt2):
                        return {'toast': '🌐 已用全屏浏览器打开：%s' % (_tt2 or url)[:40]}
                    return self._open_url_action(url, _tt2)
            return None
        except:
            return None


