# ==================== PHP 接口：聚合器 / 本地扫描器 ====================
# 聚合器（本地爬虫聚合、远程url爬虫聚合）本质是转发宿主本地接口：
#   <api>&ac=detail[&t=分类&pg=页码] / &ac=detail&ids=ID / &ac=play&id= / &ac=search&wd=
# 本地扫描器（本地资源管理器、全能王）本质是扫固定目录里的 txt/m3u/json/db 再铺成条目。


class PhpSiteAgg(PhpSiteBase):
    """爬虫聚合：源列表 → 源的分类 → 片单 → 详情 → 播放，全部转发给 127.0.0.1:9978"""
    name = '爬虫聚合'

    def __init__(self, http, source='', sources=None, title='爬虫聚合'):
        PhpSiteBase.__init__(self, http, source)
        self.sources = sources or {}
        self.name = title

    def _api(self, name):
        cfg = self.sources.get(name) or {}
        api = cfg.get('api') if isinstance(cfg, dict) else cfg
        return str(api or '')

    def classes(self):
        n = len(self.sources)
        if not n:
            return []
        return [{'type_id': 'agg', 'type_name': '%s（%d 个源）' % (self.name, n)}]

    def _get(self, url):
        txt = self.http(url)
        if not txt:
            return None
        try:
            return json.loads(txt)
        except Exception:
            return None

    def list_videos(self, cid, pg, extend=None):
        cid = str(cid or '')
        if cid in ('', 'agg'):
            items = [{'vod_id': 'src::' + k, 'vod_name': (v.get('name') if isinstance(v, dict) else k) or k,
                      'vod_pic': '', 'vod_remarks': '源', 'is_folder': True}
                     for k, v in self.sources.items()]
            return {'list': items, 'page': 1, 'pagecount': 1, 'limit': len(items), 'total': len(items)}

        if cid.startswith('src::'):
            name = cid[5:]
            api = self._api(name)
            data = self._get(api + '&ac=detail') if api else None
            classes = (data or {}).get('class') or []
            items = []
            for c in classes:
                tid = str((c or {}).get('type_id') or '')
                if not tid:
                    continue
                items.append({'vod_id': 'cat::%s::%s' % (name, tid),
                              'vod_name': str(c.get('type_name') or tid),
                              'vod_pic': '', 'vod_remarks': '分类', 'is_folder': True})
            if not items:
                items = [{'vod_id': 'cat::%s::%s' % (name, i[0]), 'vod_name': i[1],
                          'vod_pic': '', 'vod_remarks': '分类', 'is_folder': True}
                         for i in (('1', '电影'), ('2', '电视剧'), ('3', '综艺'), ('4', '动漫'))]
            return {'list': items, 'page': 1, 'pagecount': 1, 'limit': len(items), 'total': len(items)}

        if cid.startswith('cat::'):
            parts = cid.split('::')
            name = parts[1] if len(parts) > 1 else ''
            tid = parts[2] if len(parts) > 2 else ''
            api = self._api(name)
            data = self._get('%s&ac=detail&t=%s&pg=%s' % (api, urllib.parse.quote(tid), urllib.parse.quote(str(pg or 1)))) if api else None
            out = []
            for it in ((data or {}).get('list') or []):
                if not isinstance(it, dict):
                    continue
                vid = str(it.get('vod_id') or '').strip()
                if not vid:
                    continue
                out.append({'vod_id': 'vod::%s::%s' % (name, vid),
                            'vod_name': str(it.get('vod_name') or ''),
                            'vod_pic': str(it.get('vod_pic') or ''),
                            'vod_remarks': str(it.get('vod_remarks') or '')})
            page = int((data or {}).get('page') or pg or 1)
            pagecount = int((data or {}).get('pagecount') or page)
            return {'list': out, 'page': page, 'pagecount': max(pagecount, page),
                    'limit': len(out), 'total': (data or {}).get('total') or len(out)}

        return {'list': [], 'page': 1, 'pagecount': 1, 'total': 0}

    def detail(self, vid):
        vid = str(vid or '')
        if vid.startswith('vod::'):
            parts = vid.split('::', 2)
            name = parts[1] if len(parts) > 1 else ''
            real = parts[2] if len(parts) > 2 else ''
            order = ([name] if name in self.sources else []) + [k for k in self.sources if k != name]
        else:
            real = vid
            order = list(self.sources.keys())
        for key in order:
            api = self._api(key)
            if not api:
                continue
            data = self._get(api + '&ac=detail&ids=' + urllib.parse.quote(real))
            lst = (data or {}).get('list') or []
            if lst and isinstance(lst[0], dict):
                vod = dict(lst[0])
                vod['vod_id'] = vid
                if not vod.get('vod_play_url'):
                    url0 = vod.get('url') or vid
                    vod['vod_play_url'] = '第1集$%s' % url0
                if not vod.get('vod_play_from'):
                    vod['vod_play_from'] = key
                if not vod.get('vod_pic'):
                    vod['vod_pic'] = ''
                vod['vod_remarks'] = (vod.get('vod_remarks') or '') + ' · ' + key
                return vod
        return None

    def play(self, addr):
        addr = str(addr or '')
        for key in self.sources:
            api = self._api(key)
            if not api:
                continue
            data = self._get(api + '&ac=play&id=' + urllib.parse.quote(addr))
            if isinstance(data, dict) and data.get('url'):
                return {'parse': int(data.get('parse') or 0), 'url': data.get('url'),
                        'header': data.get('header') or {}}
        return {'parse': 0, 'url': addr, 'header': {}}


class PhpSiteFiles(PhpSiteBase):
    """本地扫描器：把固定目录里的 txt/m3u/json/db 当成一个个分类，条目直出播放地址"""
    name = '本地资源'

    _SCAN_CACHE = {}

    def __init__(self, http, source='', paths=None, title='本地资源'):
        PhpSiteBase.__init__(self, http, source)
        self.paths = paths or []
        self.name = title

    # ---------- 扫描 ----------
    def _scan(self):
        key = '|'.join(self.paths)
        hit = PhpSiteFiles._SCAN_CACHE.get(key)
        if hit and (time.time() - hit[0]) < 120:
            return hit[1]
        files, seen = [], set()
        for base in self.paths:
            if not base or not os.path.isdir(base):
                continue
            base_depth = base.rstrip('/').count('/')
            for root, dirs, names in os.walk(base):
                if root.count('/') - base_depth >= 4:
                    dirs[:] = []
                    continue
                for nm in names:
                    ext = os.path.splitext(nm)[1].lower().lstrip('.')
                    if ext not in ('txt', 'm3u', 'm3u8', 'json', 'db', 'sqlite', 'sqlite3', 'db3'):
                        continue
                    fp = os.path.join(root, nm)
                    if fp in seen:
                        continue
                    seen.add(fp)
                    try:
                        size = os.path.getsize(fp)
                    except Exception:
                        size = 0
                    if size <= 0 or size > 200 * 1024 * 1024:
                        continue
                    files.append({'path': fp, 'name': nm, 'ext': ext, 'size': size,
                                  'dir': os.path.basename(root)})
                if len(files) > 600:
                    break
        PhpSiteFiles._SCAN_CACHE[key] = (time.time(), files)
        return files

    def classes(self):
        files = self._scan()
        out = []
        for i, f in enumerate(files):
            tag = {'txt': '📄', 'm3u': '📺', 'm3u8': '📺', 'json': '📊'}.get(f['ext'], '🗃️')
            out.append({'type_id': 'f::%d' % i,
                        'type_name': '%s %s' % (tag, f['name']),
                        'type_file': f['path']})
        return out

    # ---------- 解析 ----------
    _LINK_RE = re.compile(r'^(magnet:\?[^\s]+|ed2k://[^\s]+|https?://[^\s]+)$', re.I)

    def _entries(self, f):
        ext = f['ext']
        try:
            if ext == 'txt':
                return self._parse_txt(f)
            if ext in ('m3u', 'm3u8'):
                return self._parse_m3u(f)
            if ext == 'json':
                return self._parse_json(f)
            return self._parse_db(f)
        except Exception:
            return []

    def _parse_txt(self, f):
        out = []
        try:
            with open(f['path'], 'r', encoding='utf-8', errors='ignore') as fh:
                lines = fh.readlines()
        except Exception:
            return out
        for i, line in enumerate(lines):
            line = (line or '').strip()
            if not line or line.startswith('#'):
                continue
            m = self._LINK_RE.match(line)
            if not m:
                continue
            link = m.group(1)
            name = ''
            if link.startswith('magnet:'):
                mm = re.search(r'[?&]dn=([^&]+)', link)
                if mm:
                    name = urllib.parse.unquote(mm.group(1))
            if not name:
                name = os.path.basename(link.split('?')[0]) or ('第%d行' % (i + 1))
            out.append({'name': name[:80], 'url': link})
            if len(out) >= 5000:
                break
        return out

    def _parse_m3u(self, f):
        out, cur = [], ''
        try:
            with open(f['path'], 'r', encoding='utf-8', errors='ignore') as fh:
                for line in fh:
                    line = (line or '').strip()
                    if line.startswith('#EXTINF'):
                        _, _, title = line.partition(',')
                        cur = title.strip()
                    elif line and not line.startswith('#'):
                        if line.lower().startswith('http') or self._LINK_RE.match(line):
                            out.append({'name': (cur or line)[:80], 'url': line})
                            cur = ''
                        if len(out) >= 5000:
                            break
        except Exception:
            pass
        return out

    def _parse_json(self, f):
        out = []
        try:
            with open(f['path'], 'r', encoding='utf-8', errors='ignore') as fh:
                data = json.load(fh)
        except Exception:
            return out

        def walk(node, depth=0):
            if len(out) >= 3000 or depth > 6:
                return
            if isinstance(node, list):
                # 像 [{name,url}] 的数组
                added = False
                for it in node:
                    if isinstance(it, dict):
                        url = it.get('url') or it.get('link') or it.get('play_url') or it.get('vod_url')
                        if isinstance(url, str) and self._LINK_RE.match(url.strip()):
                            nm = it.get('name') or it.get('title') or it.get('vod_name') or url
                            out.append({'name': str(nm)[:80], 'url': url.strip()})
                            added = True
                if not added:
                    for it in node[:80]:
                        walk(it, depth + 1)
            elif isinstance(node, dict):
                for v in list(node.values())[:80]:
                    walk(v, depth + 1)

        walk(data)
        return out

    def _parse_db(self, f):
        out = []
        try:
            con = sqlite3.connect('file:%s?mode=ro' % f['path'], uri=True)
        except Exception:
            return out
        try:
            cur = con.cursor()
            cur.execute("SELECT name FROM sqlite_master WHERE type='table'")
            tables = [r[0] for r in cur.fetchall()][:40]
            for tb in tables:
                try:
                    cur.execute('SELECT * FROM "%s" LIMIT 800' % tb.replace('"', ''))
                    cols = [d[0] for d in cur.description]
                    low = [c.lower() for c in cols]
                    url_i = next((i for i, c in enumerate(low) if c in
                                  ('url', 'vod_url', 'link', 'play_url', 'magnet', 'address', 'path')), None)
                    name_i = next((i for i, c in enumerate(low) if c in
                                   ('name', 'vod_name', 'title', 'vod_title', 'episode')), None)
                    if url_i is None:
                        continue
                    for row in cur.fetchall():
                        u = row[url_i]
                        if not isinstance(u, str) or not u.strip():
                            continue
                        u = u.strip()
                        if not (u.startswith('http') or u.startswith('magnet:') or u.startswith('ed2k://')):
                            continue
                        nm = row[name_i] if name_i is not None and row[name_i] else u
                        out.append({'name': str(nm)[:80], 'url': u})
                        if len(out) >= 3000:
                            break
                except Exception:
                    continue
                if len(out) >= 3000:
                    break
        finally:
            try:
                con.close()
            except Exception:
                pass
        return out

    # ---------- 接口 ----------
    def list_videos(self, cid, pg, extend=None):
        files = self._scan()
        idx = 0
        if str(cid).startswith('f::'):
            try:
                idx = int(str(cid)[3:])
            except Exception:
                idx = -1
        if idx < 0 or idx >= len(files):
            return {'list': [], 'page': 1, 'pagecount': 1, 'total': 0}
        f = files[idx]
        entries = self._entries(f)
        try:
            pgn = max(int(pg or 1), 1)
        except Exception:
            pgn = 1
        per = 200
        chunk = entries[(pgn - 1) * per: pgn * per]
        out = []
        for j, e in enumerate(chunk):
            payload = self.b64u(json.dumps({'f': f['path'], 'n': e['name'], 'u': e['url']}, ensure_ascii=False))
            out.append({'vod_id': 'lnk::' + payload,
                        'vod_name': e['name'],
                        'vod_pic': '',
                        'vod_remarks': '%s · 第%d页' % (f['name'], pgn),
                        'play_url': e['url'],
                        'play_name': e['name']})
        pagecount = max(1, (len(entries) + per - 1) // per)
        return {'list': out, 'page': pgn, 'pagecount': pagecount, 'limit': per, 'total': len(entries)}

    @staticmethod
    def b64u(text):
        return base64.urlsafe_b64encode(str(text).encode('utf-8', 'surrogateescape')).decode('utf-8').rstrip('=')

    @staticmethod
    def b64d(text):
        return base64.urlsafe_b64decode(str(text) + '=' * (-len(str(text)) % 4)).decode('utf-8')

    def detail(self, vid):
        vid = str(vid or '')
        name, url = '', ''
        if vid.startswith('lnk::'):
            try:
                meta = json.loads(self.b64d(vid[5:]))
                name = str(meta.get('n') or os.path.basename(str(meta.get('f') or '')))
                url = str(meta.get('u') or '')
            except Exception:
                name, url = '', ''
        elif vid.startswith('magnet:') or vid.startswith('http') or vid.startswith('ed2k://'):
            url = vid
        if not url:
            return None
        nm = name or (os.path.basename(url.split('?')[0]) or '本地资源')
        return {'vod_id': vid, 'vod_name': nm[:80], 'vod_pic': '',
                'vod_remarks': '本地资源', 'vod_content': url[:300],
                'vod_play_from': '本地直链',
                'vod_play_url': '正片$' + url}

    def play(self, addr):
        addr = str(addr or '')
        if addr.startswith('magnet:') or addr.startswith('ed2k://'):
            return {'parse': 1, 'url': addr, 'header': {}}
        return {'parse': 0, 'url': addr, 'header': {}}


