    def _magnet_info_item(self, file_path, title, message):
        """磁力这条路的提示格子（沿用 db 的提示样式，只换图标）"""
        item = self._db_info_item(file_path, title, message)
        try:
            item['vod_pic'] = self._magnet_pic()
        except Exception:
            pass
        return item

    def _magnet_entries(self, file_path):
        """读文件里的磁力/电驴链接（名字 + 地址），按文件版本缓存，翻页不重复解析"""
        try:
            st = os.stat(file_path)
            key = (file_path, st.st_mtime, st.st_size)
        except Exception:
            return [], '文件无法访问', 0
        cache = getattr(self, '_magnet_grid_cache', None)
        if cache is None:
            self._magnet_grid_cache = {}
            cache = self._magnet_grid_cache
        if key in cache:
            data = cache[key]
            return data, '', len(data)
        try:
            raw = self._parse_magnet_file(file_path) or []
        except Exception as e:
            return [], '磁力文件读取失败：%s' % e, 0
        out = []
        for item in raw:
            if not isinstance(item, dict):
                continue
            url = str(item.get('url') or '').strip()
            if not url:
                continue
            name = str(item.get('name') or '').strip()
            if not name:
                name = '链接%d' % (len(out) + 1)
            out.append({'name': name, 'url': url,
                        'remarks': str(item.get('remarks') or '').strip()})
        cache[key] = out
        if len(cache) > 3:
            for k in list(cache.keys())[:-3]:
                cache.pop(k, None)
        return out, '', len(out)

    def _magnet_more_item(self, file_path, shown, total):
        payload = self.b64u_encode(json.dumps({'f': file_path, 'o': shown}, ensure_ascii=False))
        return {
            'vod_id': self.MAGNET_MORE_PREFIX + payload,
            'vod_name': '➕ 加载更多（剩余 %d 条）' % (total - shown),
            'vod_pic': self._magnet_pic(),
            'vod_remarks': '%d / %d' % (shown, total),
            'style': {'type': 'grid', 'ratio': 1}
        }

    def _magnet_entry_item(self, file_path, idx, entry, total, pg=1, sel_on=False, picked=False):
        name = entry.get('name') or ('链接%d' % (idx + 1))
        remarks = entry.get('remarks') or ('%d / %d' % (idx + 1, total))
        try:
            payload = self.b64u_encode(json.dumps({'f': file_path, 'i': idx, 'p': int(pg or 1)},
                                                 ensure_ascii=False))
        except Exception:
            payload = self.b64u_encode(json.dumps({'f': file_path, 'i': idx}, ensure_ascii=False))
        if sel_on:
            # 2026-11-11 v205：多选开着时点一下＝勾上/取消。走「系统气泡 + 只回一句话」，页面不刷新，
            # 列表停在原处，可以接着往下点（和文件选择模式一个路子）
            cmd = '磁力勾选|' + payload
            return {
                'vod_id': json.dumps({'actionId': cmd}, ensure_ascii=False),
                'action': cmd,
                'vod_name': ('☑️ ' if picked else '⬜ ') + name,
                'vod_pic': self._magnet_pic(),
                'vod_remarks': (('已勾上 · 再点一下取消' if picked else '点一下勾上') + ' · ' + remarks),
                'vod_tag': 'action',
                'style': {'type': 'grid', 'ratio': 1}
            }
        return {
            'vod_id': self.MAGNET_ENTRY_PREFIX + payload,
            'vod_name': name,
            'vod_pic': self._magnet_pic(),
            'vod_remarks': remarks,
            'vod_tag': 'magnetlink',
            'style': {'type': 'grid', 'ratio': 1}
        }

    def _magnet_grid(self, file_path, pg=1):
        """第一层：文件里的每一条磁力/电驴链接一格，50 条一页"""
        limit = self._magnet_page_limit()
        try:
            pg = max(1, int(pg or 1))
        except Exception:
            pg = 1
        file_name = os.path.basename(file_path) if file_path else '磁力文件'
        self._magnet_cur_file = str(file_path or '')
        entries, err, total = self._magnet_entries(file_path)
        if not entries:
            return {'page': 1, 'pagecount': 1, 'limit': limit, 'total': 0,
                    'list': [self._magnet_info_item(file_path, file_name,
                                                    err or '这个文件里没解析到磁力/电驴链接，点击打开原始文件')]}
        pagecount = max(1, (total + limit - 1) // limit)
        if pg > pagecount:
            pg = pagecount
        start = (pg - 1) * limit
        window = entries[start:start + limit]
        _sel_on = self._magnet_sel_on(file_path)
        _selset = self._magnet_sel_set(file_path) if _sel_on else set()
        items = []
        if _sel_on:
            items.extend(self._magnet_sel_cards(file_path, pg, total))
        else:
            items.extend(self._magnet_sel_entry(file_path, pg))
        items.extend([self._magnet_entry_item(file_path, start + i, e, total, pg, _sel_on,
                                              (start + i) in _selset)
                      for i, e in enumerate(window)])
        return {'page': pg, 'pagecount': pagecount, 'limit': limit, 'total': total, 'list': items}

    def _magnet_dir_content(self, tid, pg=1):
        """宿主按「文件夹」进来时走这里：返回第 pg 页链接网格"""
        try:
            file_path = self.b64u_decode(tid[len(self.MAGNET_PREFIX):])
        except Exception:
            file_path = ''
        if not file_path or not os.path.exists(file_path):
            return {'page': 1, 'pagecount': 1, 'limit': self._magnet_page_limit(), 'total': 0,
                    'list': [self._magnet_info_item(file_path or '', '磁力文件', '文件不存在或无法访问')]}
        return self._magnet_grid(file_path, pg)

    def _handle_magnet_detail(self, file_path, vod_id):
        """宿主走详情这条路时：第一页链接网格 + 「加载更多」格子（和 db/json 的详情层一致）"""
        if not file_path or not os.path.exists(file_path) or not os.path.isfile(file_path):
            return {'list': [self._magnet_info_item(file_path or '', '磁力文件', '文件不存在或无法访问')]}
        grid = self._magnet_grid(file_path, 1)
        items = list(grid.get('list') or [])
        total = int(grid.get('total') or 0)
        try:
            _lim = int(grid.get('limit') or self._magnet_page_limit())
            shown = min(total, max(0, int(grid.get('page') or 1) * _lim))
        except Exception:
            shown = 0
        if total > shown:
            items.append(self._magnet_more_item(file_path, shown, total))
        return {'list': items}

    def _handle_magnet_more(self, id_val):
        try:
            payload = json.loads(self.b64u_decode(id_val[len(self.MAGNET_MORE_PREFIX):]))
            file_path = payload.get('f')
            offset = max(0, int(payload.get('o', 0)))
        except Exception:
            return {'list': [self._magnet_info_item('', '磁力文件', '分页参数无效，请返回重新进入')]}
        limit = self._magnet_page_limit()
        entries, err, total = self._magnet_entries(file_path)
        if not entries:
            return {'list': [self._magnet_info_item(file_path or '',
                                                   os.path.basename(file_path or '磁力文件'),
                                                   err or '这个文件里没解析到磁力/电驴链接')]}
        window = entries[offset:offset + limit]
        _sel_on = self._magnet_sel_on(file_path)
        _selset = self._magnet_sel_set(file_path) if _sel_on else set()
        items = [self._magnet_entry_item(file_path, offset + i, e, total, 1, _sel_on,
                                         (offset + i) in _selset)
                 for i, e in enumerate(window)]
        shown = offset + len(window)
        if total > shown:
            items.append(self._magnet_more_item(file_path, shown, total))
        return {'list': items}

    def _handle_magnet_link_detail(self, id_val):
        """点某一条链接：只带这一条去播放（磁力/电驴交给宿主原样处理）"""
        try:
            payload = json.loads(self.b64u_decode(id_val[len(self.MAGNET_ENTRY_PREFIX):]))
            file_path = payload.get('f')
            idx = int(payload.get('i', 0))
        except Exception:
            return {'list': [self._magnet_info_item('', '磁力链接', '条目参数无效，请返回重新进入')]}
        entries, err, total = self._magnet_entries(file_path)
        if not entries or idx < 0 or idx >= len(entries):
            return {'list': [self._magnet_info_item(file_path or '', '磁力链接',
                                                   err or '这条链接已不在文件里，请返回重新进入')]}
        entry = entries[idx]
        url = entry.get('url') or ''
        name = str(entry.get('name') or '').replace('$', ' ').replace('#', ' ').strip()
        if not name:
            name = '链接%d' % (idx + 1)
        return {'list': [{
            'vod_id': id_val,
            'vod_name': name,
            'vod_pic': self._magnet_pic(),
            'vod_play_from': '磁力链接',
            'vod_play_url': '%s$%s' % (name, url),
            'vod_remarks': '第 %d 条 / 共 %d 条' % (idx + 1, total),
            'style': {'type': 'list'}
        }]}


    # ==================== 磁力/电驴链接多选：勾几条一起交给壳子（2026-11-11 v202）====================
    def _magnet_sel_set(self, file_path):
        """按文件记已勾的下标"""
        if not isinstance(getattr(self, '_magnet_sel', None), dict):
            self._magnet_sel = {}
        key = str(file_path or '')
        s = self._magnet_sel.get(key)
        if not isinstance(s, set):
            s = set()
            self._magnet_sel[key] = s
        return s

    def _magnet_sel_on(self, file_path):
        """这个文件现在开着多选没"""
        try:
            return bool(file_path) and str(getattr(self, '_magnet_sel_file', '') or '') == str(file_path)
        except Exception:
            return False

    def _magnet_sel_enable(self, file_path):
        self._magnet_sel_file = str(file_path or '')
        self._magnet_sel_set(file_path)
        return bool(file_path)

    def _magnet_sel_off(self, file_path=''):
        self._magnet_sel_file = ''
        return True

    def _magnet_sel_toggle(self, file_path, idx):
        try:
            idx = int(idx)
        except Exception:
            return False, '这条没有编号，返回重新进一次'
        if idx < 0:
            return False, '这条没有编号，返回重新进一次'
        s = self._magnet_sel_set(file_path)
        if idx in s:
            s.discard(idx)
            return True, '⬜ 取消第 %d 条（已勾 %d 条）' % (idx + 1, len(s))
        s.add(idx)
        return True, '☑️ 勾上第 %d 条（已勾 %d 条）' % (idx + 1, len(s))

    def _magnet_sel_cards(self, file_path, pg, total):
        """网格顶部那组按钮：不进筛选面板也能多选（不依赖宿主渲染筛选）"""
        try:
            payload = self.b64u_encode(json.dumps({'f': file_path, 'p': int(pg or 1)},
                                                 ensure_ascii=False))
        except Exception:
            payload = self.b64u_encode(json.dumps({'f': file_path}, ensure_ascii=False))
        n = len(self._magnet_sel_set(file_path))

        def _nav(op, extra=None):
            _d = {'f': file_path, 'p': int(pg or 1), 'op': op}
            if isinstance(extra, dict):
                _d.update(extra)
            try:
                _e = self.b64u_encode(json.dumps(_d, ensure_ascii=False))
            except Exception:
                _e = self.b64u_encode(json.dumps({'f': file_path, 'op': op}, ensure_ascii=False))
            return getattr(self, 'MAGNET_SEL_PREFIX', 'magsel://') + _e

        out = [{
            'vod_id': _nav('show'),
            'vod_name': '🧲 已勾 %d / 共 %d 条' % (n, total),
            'vod_pic': MAGNET_SEL_COVERS['status'],
            'vod_remarks': '点下面的链接勾选，勾好点「▶️ 播放选中的」（点这张卡可刷新）',
            'vod_tag': 'folder',
            'style': {'type': 'list'}
        }]
        _btns = [('☑️ 全部选择', 'all', '把这份文件里的链接一次全勾上', MAGNET_SEL_COVERS['all']),
                 ('▶️ 播放选中的(%d)' % n, 'play', '把勾上的合成一个播放列表，点开就是那几条',
                  MAGNET_SEL_COVERS['play']),
                 ('⬜ 清空选择', 'none', '把勾上的都取消', MAGNET_SEL_COVERS['none']),
                 ('🔴 关闭选择', 'off', '关掉多选，点链接就变回只播这一条', MAGNET_SEL_COVERS['off'])]
        for _nm, _op, _rm, _pic in _btns:
            if _op == 'play':
                # 播放这条必须走详情路（宿主拿 magnetplay:// 去取详情），回页面在 action 那条路上会被丢掉
                out.append({
                    'vod_id': self.MAGNET_PLAY_PREFIX + payload,
                    'vod_name': _nm,
                    'vod_pic': _pic,
                    'vod_remarks': _rm,
                    'vod_tag': 'magnetlink',
                    'style': {'type': 'grid', 'ratio': 1}
                })
                continue
            out.append({
                'vod_id': _nav(_op),
                'vod_name': _nm,
                'vod_pic': _pic,
                'vod_remarks': _rm,
                'vod_tag': 'folder',
                'style': {'type': 'grid', 'ratio': 1}
            })
        return out

    def _magnet_sel_entry(self, file_path, pg):
        """没开多选时网格顶上那张卡：点一下就进多选（二级筛选那一组已经去掉了，入口就靠它）"""
        try:
            payload = self.b64u_encode(json.dumps({'f': file_path, 'p': int(pg or 1)},
                                                 ensure_ascii=False))
        except Exception:
            payload = self.b64u_encode(json.dumps({'f': file_path}, ensure_ascii=False))
        try:
            _sp = self.b64u_encode(json.dumps({'f': file_path, 'p': int(pg or 1), 'op': 'on'},
                                              ensure_ascii=False))
        except Exception:
            _sp = self.b64u_encode(json.dumps({'f': file_path, 'op': 'on'}, ensure_ascii=False))
        return [{
            'vod_id': getattr(self, 'MAGNET_SEL_PREFIX', 'magsel://') + _sp,
            'vod_name': '🧲 磁力多选：点这里开启',
            'vod_pic': MAGNET_SEL_COVERS['status'],
            'vod_remarks': '开启后点链接就是勾选（有气泡提示），勾几条一起播放',
            'vod_tag': 'folder',
            'style': {'type': 'grid', 'ratio': 1}
        }]

    def _magnet_play_page(self, file_path):
        """把勾上的链接合成一个播放列表，交给壳子去解析播放"""
        entries, err, total = self._magnet_entries(file_path)
        s = self._magnet_sel_set(file_path)
        picked = [i for i in sorted(s) if 0 <= i < len(entries)]
        if not entries:
            return {'list': [self._magnet_info_item(file_path or '', '磁力多选',
                                                    err or '这个文件里没解析到磁力/电驴链接')],
                    'page': 1, 'pagecount': 1}
        if not picked:
            return {'list': [self._magnet_info_item(file_path or '', '⚠️ 还一条都没勾',
                                                    '点下面的链接勾上，再点「▶️ 播放选中的」')],
                    'page': 1, 'pagecount': 1}
        plays = []
        used = set()
        for i in picked:
            e = entries[i]
            nm = str(e.get('name') or ('链接%d' % (i + 1))).replace('$', ' ').replace('#', ' ').strip()
            if not nm:
                nm = '链接%d' % (i + 1)
            if nm in used:
                nm = '%s(%d)' % (nm, i + 1)
            used.add(nm)
            u = str(e.get('url') or '').strip()
            if u:
                plays.append('%s$%s' % (nm, u))
        if not plays:
            return {'list': [self._magnet_info_item(file_path or '', '❌ 勾的这几条里没有可用地址',
                                                    '返回重新勾几条试试')],
                    'page': 1, 'pagecount': 1}
        try:
            _pl = self.b64u_encode(json.dumps({'f': file_path}, ensure_ascii=False))
        except Exception:
            _pl = self.b64u_encode('{}')
        return {
            'toast': '已把 %d 条交给壳子' % len(plays),
            'page': 1, 'pagecount': 1, 'limit': 1, 'total': 1,
            'list': [{
                'vod_id': self.MAGNET_PLAY_PREFIX + _pl,
                'vod_name': '▶️ 播放选中的 %d 条' % len(plays),
                'vod_pic': self._magnet_pic(),
                'vod_play_from': '磁力链接',
                'vod_play_url': '#'.join(plays),
                'vod_remarks': '点开就交给壳子解析播放；这 %d 条在同一个播放列表里，能一条条往下换' % len(plays),
                'style': {'type': 'list'}
            }]
        }

    def _magnet_play_page_from_id(self, id_val):
        """宿主拿着 magnetplay:// 又来找详情时，用当前这份选择重建同一页"""
        f = ''
        try:
            _pp = json.loads(self.b64u_decode(id_val[len(self.MAGNET_PLAY_PREFIX):]))
            f = str(_pp.get('f') or '')
        except Exception:
            f = ''
        if not f:
            f = str(getattr(self, '_magnet_cur_file', '') or '')
        try:
            _n = len(self._magnet_sel_set(f))
            self._nat_toast('▶️ 已把勾上的 %d 条整理成播放列表' % _n)
        except Exception:
            pass
        return self._magnet_play_page(f)

    def _magnet_sel_page_from_id(self, id_val):
        """宿主拿 magsel:// 来取这一页：先按 op 改勾选状态，弹一句气泡，再把刷新后的整页回给它"""
        try:
            _d = json.loads(self.b64u_decode(id_val[len(getattr(self, 'MAGNET_SEL_PREFIX', 'magsel://')):])) or {}
        except Exception:
            _d = {}
        f = str(_d.get('f') or getattr(self, '_magnet_cur_file', '') or '')
        try:
            pg = max(1, int(_d.get('p') or 1))
        except Exception:
            pg = 1
        op = str(_d.get('op') or '')
        msg = ''
        try:
            self._magnet_cur_file = f or getattr(self, '_magnet_cur_file', '')
            if op == 'pick':
                self._magnet_sel_enable(f)
                _ok, msg = self._magnet_sel_toggle(f, _d.get('i', -1))
            elif op == 'on':
                self._magnet_sel_enable(f)
                msg = '🧲 磁力多选已开：点链接就是勾选'
            elif op == 'off':
                self._magnet_sel_off(f)
                msg = '🔴 磁力多选已关掉，点链接恢复成只播这一条'
            elif op == 'all':
                self._magnet_sel_enable(f)
                _en, _er, _tt = self._magnet_entries(f)
                _s = self._magnet_sel_set(f)
                _s.clear()
                _s.update(range(len(_en)))
                msg = '☑️ 全部选择：已勾 %d 条' % len(_s)
            elif op == 'none':
                self._magnet_sel_enable(f)
                self._magnet_sel_set(f).clear()
                msg = '⬜ 已清空选择'
            else:
                _n = len(self._magnet_sel_set(f))
                msg = '🧲 已勾 %d 条' % _n
        except Exception as _e:
            msg = '⚠️ 磁力多选操作失败：%s' % _e
        if msg:
            try:
                self._nat_toast(msg)
            except Exception as _te:
                self._dlg_log('磁力气泡弹不出来：%s' % _te)
        if not f:
            return {'list': [self._magnet_info_item('', '磁力多选',
                                                    '先点开一个磁力/电驴链接文件，再来开多选')]}
        return self._magnet_grid(f, pg)

    def _magnet_action(self, cmd):
        """磁力多选这组命令；不是这组就返回 None"""
        try:
            if not isinstance(cmd, str) or not cmd.startswith('磁力'):
                return None
            head, _, rest = cmd.partition('|')
            payload = {}
            if rest:
                try:
                    payload = json.loads(self.b64u_decode(rest)) or {}
                except Exception:
                    payload = {}
            f = str(payload.get('f') or getattr(self, '_magnet_cur_file', '') or '')
            try:
                pg = max(1, int(payload.get('p') or 1))
            except Exception:
                pg = 1
            if head == '磁力勾选':
                _ok, msg = self._magnet_sel_toggle(f, payload.get('i', -1))
                # 能自己弹系统气泡就只回一句话：页面不动、列表不跳回最上面、可以接着点下一个
                if self._nat_toast(msg):
                    # 气泡已经自己弹过了，回话里就别再带 msg，省得壳又吐一句
                    return {'toast': msg}
                # 气泡弹不出来才退回「整页 + toast」，至少提示还在
                _g = self._magnet_grid(f, pg)
                _g['toast'] = msg
                return _g
            if head == '磁力关闭':
                self._magnet_sel_off(f)
                if not f:
                    return {'list': [self._magnet_info_item('', '磁力多选',
                                                            '先点开一个磁力/电驴链接文件')],
                            'page': 1, 'pagecount': 1}
                _g = self._magnet_grid(f, pg)
                _g['toast'] = '🔴 磁力多选已关掉'
                return _g
            if not f:
                return {'list': [self._magnet_info_item('', '磁力多选',
                                                        '先点开一个磁力/电驴链接文件，再来开多选')],
                        'page': 1, 'pagecount': 1}
            if head in ('磁力状态', '磁力开启'):
                self._magnet_sel_enable(f)
                _g = self._magnet_grid(f, pg)
                _g['toast'] = '🧲 磁力多选已开，点链接勾选'
                return _g
            entries, err, total = self._magnet_entries(f)
            if head == '磁力全选':
                self._magnet_sel_enable(f)
                s = self._magnet_sel_set(f)
                s.clear()
                s.update(range(len(entries)))
                _g = self._magnet_grid(f, pg)
                _g['toast'] = '☑️ 全部选择：已勾 %d 条' % len(s)
                return _g
            if head == '磁力清空':
                self._magnet_sel_enable(f)
                self._magnet_sel_set(f).clear()
                _g = self._magnet_grid(f, pg)
                _g['toast'] = '⬜ 已清空选择'
                return _g
            if head == '磁力播放':
                return self._magnet_play_page(f)
            return None
        except Exception as e:
            try:
                self.log('磁力多选出错：%s' % e)
            except Exception:
                pass
            return {'list': [self._magnet_info_item('', '❌ 磁力多选出错', str(e)[:120])],
                    'page': 1, 'pagecount': 1}

    # ==================== 原有方法继续 ====================
    
    def _should_hide_file(self, filename, dir_path=None, audio_names=None):
        name_lower = filename.lower()
        name_without_ext = os.path.splitext(filename)[0]
        is_image = any(name_lower.endswith(ext) for ext in ['.jpg', '.jpeg', '.png', '.gif', '.bmp', '.webp'])
        is_lyric = any(name_lower.endswith(ext) for ext in ['.lrc', '.krc', '.qrc', '.yrc', '.trc'])
        if not is_image and not is_lyric:
            return False
        if audio_names is not None:
            for audio_name in audio_names:
                if audio_name.lower() == name_without_ext.lower():
                    return True
        if name_without_ext.lower() in self.common_cover_names:
            return True
        return False
    
    def _hide_cover_cache(self):
        """把歌曲封面缓存整目录藏起来（2026-11-02 用户要求「和电台封面一样」）：
        ① 目录名带点（.covers，媒体扫描不进）
        ② 图片文件名带点（.{md5}.jpg）
        ③ 目录内 .nomedia 每次启动补上
        ④ 旧版可见目录 covers/ 里的东西整目录搬进来：图片改成点号名，其它文件（cover_net_neg.json 等）原名搬
        任何一步失败都不影响封面显示。
        """
        hidden_dir = COVER_CACHE_DIR
        legacy_dir = COVER_CACHE_DIR_LEGACY
        try:
            os.makedirs(hidden_dir, exist_ok=True)
        except Exception:
            pass
        img_exts = ('.jpg', '.jpeg', '.png', '.webp', '.gif', '.bmp', '.heic')
        # ① 旧目录整体搬迁
        try:
            if os.path.isdir(legacy_dir) and os.path.normpath(legacy_dir) != os.path.normpath(hidden_dir):
                for name in os.listdir(legacy_dir):
                    if name == '.nomedia':
                        continue
                    src = os.path.join(legacy_dir, name)
                    if not os.path.isfile(src):
                        continue
                    base = name[1:] if name.startswith('.') else name
                    stem, ext = os.path.splitext(base)
                    if ext.lower() in img_exts:
                        dst_name = '.' + stem + ext
                    else:
                        dst_name = name
                    dst = os.path.join(hidden_dir, dst_name)
                    if os.path.exists(dst):
                        try:
                            os.remove(src)
                        except Exception:
                            pass
                        continue
                    try:
                        os.replace(src, dst)
                    except Exception:
                        try:
                            shutil.move(src, dst)
                        except Exception:
                            pass
                try:
                    left = [n for n in os.listdir(legacy_dir) if n != '.nomedia']
                    if not left:
                        nomedia_old = os.path.join(legacy_dir, '.nomedia')
                        if os.path.exists(nomedia_old):
                            os.remove(nomedia_old)
                        os.rmdir(legacy_dir)
                except Exception:
                    pass
        except Exception:
            pass
        # ② 新目录里遗留的可见图片补点号
        try:
            for name in os.listdir(hidden_dir):
                if not name or name.startswith('.'):
                    continue
                if os.path.splitext(name)[1].lower() not in img_exts:
                    continue
                src = os.path.join(hidden_dir, name)
                if not os.path.isfile(src):
                    continue
                dst = os.path.join(hidden_dir, '.' + name)
                if os.path.exists(dst):
                    continue
                try:
                    os.rename(src, dst)
                except Exception:
                    pass
        except Exception:
            pass
        # ③ .nomedia
        try:
            nomedia_path = os.path.join(hidden_dir, '.nomedia')
            if not os.path.exists(nomedia_path):
                with open(nomedia_path, 'w') as f:
                    f.write('# keep cover cache out of the media scanner\n')
        except Exception:
            pass

    def _get_cover_cache_dir(self):
        return COVER_CACHE_DIR
    
    def _valid_cover_file(self, path):
        """封面文件必须真实存在、非空，而且开头确实是图片魔数
        （以前只判断"非空"，0.x KB 的半截图/文本也会被当成封面交给宿主，结果就是路径对、图显示不出来）"""
        try:
            if not path or not os.path.isfile(path):
                return False
            if os.path.getsize(path) < 512:
                return False
            with open(path, 'rb') as f:
                head = f.read(16)
            return bool(NetMusicProvider._is_image_bytes(head))
        except Exception:
            return False

    def _get_cached_cover_path(self, audio_path):
        file_hash = hashlib.md5(audio_path.encode('utf-8', 'surrogateescape')).hexdigest()
        hidden_file = f"{COVER_CACHE_DIR}.{file_hash}.jpg"
        legacy_file = f"{COVER_CACHE_DIR}{file_hash}.jpg"
        for cache_file in (hidden_file, legacy_file):
            if self._valid_cover_file(cache_file):
                if cache_file == legacy_file:
                    # 老版本的非隐藏文件，顺手改名成隐藏，别让相册再扫到
                    try:
                        os.replace(legacy_file, hidden_file)
                        if self._valid_cover_file(hidden_file):
                            return hidden_file
                    except Exception:
                        pass
                return cache_file
            if os.path.exists(cache_file):
                # 坏图（0 字节/半截/不是图片）留着只会一直显示不出来
                try:
                    os.remove(cache_file)
                except Exception:
                    pass
        return None
    
