    def _hide_radio_cover_cache(self):
        """把电台封面缓存彻底藏起来（2026-11-02 用户要求「让别的应用发现不了」）：
        ① 目录名带点（.radio_covers，媒体扫描根本不会进）
        ② 文件名带点（.{id}.jpg）
        ③ 目录里放 .nomedia（双保险，连同隐藏目录一起挡住）
        ④ 旧版可见目录 radio_covers 里的封面整目录搬进来，搬空后删掉旧目录
        任何一步失败都不影响封面正常显示。
        """
        hidden_dir = RADIO_COVER_CACHE_DIR
        legacy_dir = RADIO_COVER_CACHE_DIR_LEGACY
        try:
            os.makedirs(hidden_dir, exist_ok=True)
        except Exception:
            pass
        # ① 旧目录整体搬迁（旧版把封面存成可见的 {id}.jpg）
        try:
            if os.path.isdir(legacy_dir) and os.path.normpath(legacy_dir) != os.path.normpath(hidden_dir):
                for name in os.listdir(legacy_dir):
                    if name == '.nomedia':
                        continue
                    src = os.path.join(legacy_dir, name)
                    if not os.path.isfile(src):
                        continue
                    base = name[1:] if name.startswith('.') else name
                    stem, ext = os.path.splitext(base)
                    if not ext:
                        ext = '.jpg'
                    dst = os.path.join(hidden_dir, '.' + stem + ext)
                    if os.path.exists(dst):
                        try:
                            os.remove(src)
                        except Exception:
                            pass
                        continue
                    try:
                        os.replace(src, dst)
                    except Exception:
                        try:
                            shutil.move(src, dst)
                        except Exception:
                            pass
                # 旧目录只剩 .nomedia 就一起清掉，别留个空壳被扫到
                try:
                    left = [n for n in os.listdir(legacy_dir) if n != '.nomedia']
                    if not left:
                        nomedia_old = os.path.join(legacy_dir, '.nomedia')
                        if os.path.exists(nomedia_old):
                            os.remove(nomedia_old)
                        os.rmdir(legacy_dir)
                except Exception:
                    pass
        except Exception:
            pass
        # ② 新目录里万一还有可见的图片，补点号
        try:
            for name in os.listdir(hidden_dir):
                if name.startswith('.') or not name:
                    continue
                ext = os.path.splitext(name)[1].lower()
                if ext not in ('.jpg', '.jpeg', '.png', '.webp', '.gif', '.bmp', '.heic'):
                    continue
                src = os.path.join(hidden_dir, name)
                if not os.path.isfile(src):
                    continue
                dst = os.path.join(hidden_dir, '.' + name)
                if os.path.exists(dst):
                    continue
                try:
                    os.rename(src, dst)
                except Exception:
                    pass
        except Exception:
            pass
        # ③ .nomedia 每次启动都补上
        try:
            nomedia_path = os.path.join(hidden_dir, '.nomedia')
            if not os.path.exists(nomedia_path):
                with open(nomedia_path, 'w') as f:
                    f.write('# keep radio covers out of the media scanner\n')
        except Exception:
            pass

    def _get_radio_cached_cover_path(self, radio_id):
        cache_file1 = f"{RADIO_COVER_CACHE_DIR}.{radio_id}.jpg"
        cache_file2 = f"{RADIO_COVER_CACHE_DIR}{radio_id}.jpg"
        if os.path.exists(cache_file1):
            return cache_file1
        if os.path.exists(cache_file2):
            return cache_file2
        return None
    
    def _cache_radio_cover(self, radio_id, image_url):
        if not image_url:
            return None
        try:
            cache_file = f"{RADIO_COVER_CACHE_DIR}.{radio_id}.jpg"
            if os.path.exists(cache_file):
                self.cached_radio_ids.add(str(radio_id))
                return cache_file
            headers = {
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
                "Referer": "http://www.qingting.fm/"
            }
            response = self.session.get(image_url, headers=headers, timeout=15)
            if response.status_code == 200:
                img_data = response.content
                if len(img_data) > 500 * 1024:
                    img_data = UltraFastCoverExtractor._compress_image(img_data, max_size=(300, 300), quality=65)
                tmp_file = cache_file + '.part'
                with open(tmp_file, 'wb') as f:
                    f.write(img_data)
                os.replace(tmp_file, cache_file)
                self.cached_radio_ids.add(str(radio_id))
                RadioCoverRecord.mark_cached(radio_id)
                return cache_file
            return None
        except:
            return None
    
    def _load_cached_radio_ids(self):
        try:
            if os.path.exists(RADIO_COVER_CACHE_DIR):
                for filename in os.listdir(RADIO_COVER_CACHE_DIR):
                    if filename.endswith('.jpg') and not filename == '.nomedia':
                        radio_id = filename.replace('.', '').replace('jpg', '')
                        if radio_id and radio_id.isdigit():
                            self.cached_radio_ids.add(radio_id)
        except:
            pass
    
    def _refresh_cached_radio_ids(self):
        self.cached_radio_ids.clear()
        self._load_cached_radio_ids()
    
    def find_local_cover_image(self, audio_path):
        audio_dir = os.path.dirname(audio_path)
        audio_name = os.path.splitext(os.path.basename(audio_path))[0]
        exact_names = [
            f"{audio_name}.jpg", f"{audio_name}.jpeg", f"{audio_name}.png",
            f"{audio_name}.webp", f"{audio_name}.gif",
            f"{audio_name}.JPG", f"{audio_name}.JPEG", f"{audio_name}.PNG"
        ]
        for cover_name in exact_names:
            cover_path = os.path.join(audio_dir, cover_name)
            if os.path.exists(cover_path) and os.path.isfile(cover_path):
                return cover_path
        common_exts = [".jpg", ".jpeg", ".png", ".webp", ".gif"]
        for base in getattr(self, "common_cover_names", []):
            for ce in common_exts:
                cover_path = os.path.join(audio_dir, base + ce)
                if os.path.exists(cover_path) and os.path.isfile(cover_path):
                    return cover_path
        return None
    
    def _save_cover_bytes(self, audio_path, img_data):
        """把封面字节写入脚本既有的封面缓存目录（非隐藏文件名），返回真实存在的路径；失败返回 None"""
        try:
            if not img_data or len(img_data) < 100:
                return None
            if not NetMusicProvider._is_image_bytes(img_data):
                return None
            if len(img_data) > 500 * 1024:
                img_data = UltraFastCoverExtractor._compress_image(img_data, max_size=(300, 300), quality=65) or img_data
            if not NetMusicProvider._is_image_bytes(img_data) or len(img_data) < 512:
                return None
            os.makedirs(COVER_CACHE_DIR, exist_ok=True)
            file_hash = hashlib.md5(audio_path.encode('utf-8', 'surrogateescape')).hexdigest()
            cache_file = f"{COVER_CACHE_DIR}.{file_hash}.jpg"
            tmp_file = cache_file + '.part'
            with open(tmp_file, 'wb') as f:
                f.write(img_data)
                f.flush()
                try:
                    os.fsync(f.fileno())
                except Exception:
                    pass
            os.replace(tmp_file, cache_file)
            if self._valid_cover_file(cache_file):
                return cache_file
            try:
                os.remove(cache_file)
            except Exception:
                pass
        except Exception as e:
            self.log('⚠️ 封面写入失败: %s' % e)
        return None

    def cache_cover_image(self, audio_path, source_path):
        try:
            with open(source_path, 'rb') as f:
                img_data = f.read()
            return self._save_cover_bytes(audio_path, img_data)
        except Exception as e:
            self.log('⚠️ 本地封面读取失败: %s' % e)
            return None

    def _extract_embedded_cover(self, file_path):
        """读取音频内嵌封面，返回 data:image/... 字符串或 None"""
        ext = self.get_file_ext(file_path)
        try:
            if ext == 'mp3':
                return UltraFastCoverExtractor.extract_mp3_cover(file_path)
            if ext == 'flac':
                return UltraFastCoverExtractor.extract_flac_cover(file_path)
            if ext in ['m4a', 'mp4', 'm4b', 'm4p', 'aac']:
                return UltraFastCoverExtractor.extract_m4a_cover(file_path)
        except Exception:
            pass
        return None

    def _cover_from_data_uri(self, file_path, cover_url):
        """把内嵌封面 data:image/base64 写成缓存文件，返回真实存在的路径或 None"""
        try:
            if not cover_url or not cover_url.startswith('data:image'):
                return None
            match = re.match(r'data:image/(\w+);base64,(.+)', cover_url)
            if not match:
                return None
            img_data = base64.b64decode(match.group(2))
            return self._save_cover_bytes(file_path, img_data)
        except Exception:
            return None
    
    def get_audio_cover_ultra_fast(self, file_path):
        """单曲（详情/播放）封面：本地优先 -> 缓存优先 -> 网络四来源；返回路径保证文件真实存在且非空"""
        cached_path = self._get_cached_cover_path(file_path)
        if cached_path:
            return f"file://{cached_path}"
        try:
            cover_path = self.find_local_cover_image(file_path)
            if cover_path and self._valid_cover_file(cover_path):
                return f"file://{cover_path}"
            embed_uri = self._embed_cover_ref(file_path)
            if embed_uri:
                return embed_uri
        except Exception as cover_err:
            try:
                self.log('⚠️ 本地封面读取失败: %s' % cover_err)
            except Exception:
                pass
        net_cached = self._get_cached_network_cover(file_path)
        if net_cached:
            return f"file://{net_cached}"
        if self.enable_online_cover and not self._cover_net_skip(file_path):
            net = self._fetch_network_cover_for(file_path)
            if net:
                return net
        return self.DEFAULT_AUDIO_ICON

    def _fetch_network_cover_for(self, file_path):
        """按歌曲身份联网取封面（本地/内嵌都没有时才会走到这里）；成功返回 file://，失败按原因决定要不要记负缓存"""
        base = ''
        try:
            base = os.path.basename(file_path)
            artist, song = self.extract_song_info(base)
            if not song:
                song = os.path.splitext(base)[0]
            net = self.get_network_cover(song, artist, file_path)
            if net:
                return net
            # 没匹配到（多半是「歌名 - 歌手」被当成了「歌手 - 歌名」）：换过来再试一次
            if getattr(self, '_cover_last_reason', '') == 'nomatch' and artist and song and artist != song:
                alt = self.get_network_cover(artist, song, file_path)
                if alt:
                    self.log('✅ 换个顺序匹配到封面: %s' % base)
                    return alt
            reason = getattr(self, '_cover_last_reason', '')
            if reason in ('net', 'disabled'):
                # 网络抖动/下载失败不是「这首歌没有封面」，下次进来还要再试
                self.log('⏳ 网络封面暂时取不到(%s)，不记负缓存: %s' % (reason, base))
                return None
        except Exception as e:
            self.log('⚠️ 网络封面处理失败: %s' % e)
            return None
        self._mark_cover_net_tried(file_path)
        return None

    def _cover_list_online_budget_ok(self):
        """列目录限流：每个时间窗内只允许少量联网取封面，超出丢后台补图，避免列表接口被拖慢"""
        try:
            now = time.time()
            win = getattr(self, '_cover_online_window', 0)
            cnt = getattr(self, '_cover_online_count', 0)
            span = getattr(self, 'cover_list_window_seconds', 5)
            limit = getattr(self, 'cover_list_inline_limit', 12)
            if (now - win) > span:
                self._cover_online_window = now
                self._cover_online_count = 1
                return True
            if cnt < limit:
                self._cover_online_count = cnt + 1
                return True
        except Exception:
            return True
        return False

    def _schedule_cover_preload(self, file_path):
        """把联网补封面丢到已有后台线程池，同一首去重；列表本次先返回默认图"""
        try:
            pending = getattr(self, '_cover_bg_pending', None)
            if pending is None:
                self._cover_bg_pending = set()
                pending = self._cover_bg_pending
            if file_path in pending:
                return
            pending.add(file_path)

            def _job(p):
                try:
                    if not self._get_cached_network_cover(p):
                        self._fetch_network_cover_for(p)
                finally:
                    try:
                        self._cover_bg_pending.discard(p)
                    except Exception:
                        pass

            self.preload_executor.submit(_job, file_path)
        except Exception:
            pass

    def get_list_cover(self, file_path, allow_network=True):
        """目录列表/播放列表封面：本地 -> 已有缓存 -> 内嵌 -> 网络（限流），返回的路径保证真实存在；
        allow_network=False 时只查本地与已有缓存，绝不联网（列表用，保证秒开）；网络封面在播放该曲时再取"""
        cached_path = self._get_cached_cover_path(file_path)
        if cached_path:
            return f"file://{cached_path}"
        try:
            cover_path = self.find_local_cover_image(file_path)
            if cover_path and self._valid_cover_file(cover_path):
                return f"file://{cover_path}"
            embed_uri = self._embed_cover_ref(file_path)
            if embed_uri:
                return embed_uri
        except Exception as cover_err:
            try:
                self.log('⚠️ 本地封面读取失败: %s' % cover_err)
            except Exception:
                pass
        net_cached = self._get_cached_network_cover(file_path)
        if net_cached:
            return f"file://{net_cached}"
        if not allow_network:
            return self.DEFAULT_AUDIO_ICON
        if self.enable_online_cover and not self._cover_net_skip(file_path):
            if self._cover_list_online_budget_ok():
                net = self._fetch_network_cover_for(file_path)
                if net:
                    return net
            else:
                self._schedule_cover_preload(file_path)
        return self.DEFAULT_AUDIO_ICON
    
    def preload_covers_batch(self, file_paths, max_count=500):
        if not file_paths:
            return
        uncached_paths = []
        for file_path in file_paths:
            if not CoverScanRecord.is_cover_cached(file_path):
                uncached_paths.append(file_path)
        if not uncached_paths:
            return
        uncached_paths = uncached_paths[:max_count]
        def load_single(file_path):
            self.get_audio_cover_ultra_fast(file_path)
        for path in uncached_paths:
            self.preload_executor.submit(load_single, path)
    
    def collect_audios_in_dir(self, dir_path, force_refresh=False):
        """收集目录下的音频文件
        force_refresh=True 时跳过缓存，每次实时扫描
        """
        try:
            if not os.path.exists(dir_path) or not os.path.isdir(dir_path):
                return []
            current_time = time.time()
            if not force_refresh and dir_path in self.audio_list_cache:
                cache_time = self.audio_list_cache_time.get(dir_path, 0)
                if current_time - cache_time < self.audio_cache_duration:
                    return self.audio_list_cache[dir_path]
            audios = []
            start_time = current_time
            try:
                for name in os.listdir(dir_path):
                    if time.time() - start_time > self.audio_scan_timeout:
                        break
                    if name.startswith('.'):
                        continue
                    full_path = os.path.join(dir_path, name)
                    if os.path.isdir(full_path):
                        continue
                    ext = self.get_file_ext(name)
                    if ext in self.audio_exts:
                        try:
                            if os.access(full_path, os.R_OK):
                                audios.append({
                                    'name': name,
                                    'path': full_path,
                                    'ext': ext,
                                    'mtime': os.path.getmtime(full_path)
                                })
                        except:
                            pass
                        if len(audios) >= self.max_audio_per_scan:
                            break
            except:
                pass
            audios.sort(key=lambda x: x['name'])
            if not force_refresh:
                self.audio_list_cache[dir_path] = audios
                self.audio_list_cache_time[dir_path] = current_time
            return audios
        except:
            return []

    def extract_song_info(self, filename):
        name = os.path.splitext(filename)[0]
        name = re.sub(r'^\d+\.\s*', '', name)
        patterns_to_remove = [
            r'【.*?】', r'\[.*?\]', r'\{.*?\}', r'（.*?）',
            r'-\s*(?:320k|128k|192k|HQ|SQ|无损|高品质|高音质)',
            r'-\s*(?:Live|现场版|演唱会|歌词版|伴奏版)',
            r'\s*\(feat\..*?\)', r'\s*\(Feat\..*?\)',
            r'\s*ft\..*$', r'\s*Ft\..*$',
            r'-\d{8,}-\d+$',
            r'-\d+$',
        ]
        for pattern in patterns_to_remove:
            name = re.sub(pattern, '', name, flags=re.IGNORECASE)
        name = re.sub(r'\s+', ' ', name).strip()
        artist = ""
        song = name
        for sep in [' - ', '-', '–', '—', '：', ':']:
            if sep in name:
                parts = name.split(sep, 1)
                left = parts[0].strip()
                right = parts[1].strip()
                # 「歌手 - 歌名」是主流命名；歌名只有两个字（如《晴天》）时也算歌名，
                # 不能因为右边短就把它当歌手（旧逻辑会颠倒）
                if left and right and len(left) <= 20 and len(right) <= 40:
                    artist, song = left, right
                    break
        if not artist and ' - ' in name:
            parts = name.split(' - ', 1)
            song, artist = parts[0].strip(), parts[1].strip()
        if not artist:
            feat_match = re.search(r'(.+?)\s*\(feat\.\s*(.+?)\)', name, re.IGNORECASE)
            if feat_match:
                song = feat_match.group(1).strip()
                artist = feat_match.group(2).strip()
        song = re.sub(r'[《》〈〉『』〔〕]', '', song).strip()
        artist = re.sub(r'热门歌曲.*$', '', artist).strip()
        artist = re.sub(r'：.*$', '', artist).strip()
        song = re.sub(r'-\d{8,}-\d+$', '', song)
        song = re.sub(r'-\d+$', '', song)
        if len(artist) > 30 and len(song) < 20:
            common_artists = [
                'G.E.M.', '邓紫棋', '周杰伦', '林俊杰', '陈奕迅', '蔡依林', '张惠妹',
                '王菲', '那英', '孙燕姿', '梁静茹', '洋澜一', '海来阿木', '程响'
            ]
            for ca in common_artists:
                if ca in artist:
                    song = artist.replace(ca, '').strip()
                    artist = ca
                    break
        return artist, song
    
    def search_qq_song(self, song_name, artist_name=""):
        song_name = re.sub(r'-\d{8,}-\d+$', '', song_name)
        song_name = re.sub(r'-\d+$', '', song_name)
        song_name = song_name.strip()
        cache_key = f"qq_search_{song_name}_{artist_name}"
        if cache_key in self.song_info_cache:
            cache_time = self.song_info_cache.get(cache_key + "_time", 0)
            if time.time() - cache_time < 3600:
                return self.song_info_cache[cache_key]
        try:
            if artist_name and artist_name not in song_name:
                keyword = f"{song_name} {artist_name}"
            else:
                keyword = song_name
            keyword = keyword.strip()
            url = f"{self.QQ_OFFICIAL_SEARCH}?is_xml=0&format=json&key={urllib.parse.quote(keyword)}"
            headers = {
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
                "Referer": "https://y.qq.com/",
                "Accept": "application/json"
            }
            resp = self.session.get(url, headers=headers, timeout=10)
            if resp.status_code == 200:
                data = resp.json()
                songs = data.get('data', {}).get('song', {}).get('itemlist', [])
                if songs:
                    best_match = None
                    for song in songs:
                        song_artist = song.get('singer', '')
                        song_name_api = song.get('name', '')
                        if artist_name and artist_name in song_artist:
                            best_match = song
                            break
                        if song_name.lower() in song_name_api.lower():
                            if not best_match:
                                best_match = song
                    if not best_match:
                        best_match = songs[0]
                    song_info = {
                        'name': best_match.get('name', ''),
                        'singer': best_match.get('singer', ''),
                        'mid': best_match.get('mid', ''),
                        'album': best_match.get('album', {}).get('name', '') if isinstance(best_match.get('album'), dict) else best_match.get('album', ''),
                        'interval': best_match.get('interval', 0)
                    }
                    if song_info['mid']:
                        self.song_info_cache[cache_key] = song_info
                        self.song_info_cache[cache_key + "_time"] = time.time()
                        return song_info
        except:
            pass
        return None
    
    def get_qq_song_lyrics(self, song_mid):
        cache_key = f"qq_lyrics_{song_mid}"
        if cache_key in self.network_lyrics_cache:
            cache_time = self.network_lyrics_cache.get(cache_key + "_time", 0)
            if time.time() - cache_time < 86400:
                return self.network_lyrics_cache[cache_key]
        try:
            url = f"{self.QQ_OFFICIAL_LYRIC}?format=json&nobase64=0&songmid={song_mid}"
            headers = {
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
                "Referer": "https://y.qq.com/",
                "Origin": "https://y.qq.com"
            }
            resp = self.session.get(url, headers=headers, timeout=10)
            if resp.status_code == 200:
                data = resp.json()
                if data.get('retcode') == 0:
                    lyrics = data.get('lyric', '')
                    if lyrics:
                        lyrics = base64.b64decode(lyrics).decode('utf-8')
                        if lyrics and len(lyrics) > 50:
                            self.network_lyrics_cache[cache_key] = lyrics
                            self.network_lyrics_cache[cache_key + "_time"] = time.time()
                            return lyrics
        except:
            pass
        return None
    
    def _get_local_lyrics(self, file_path):
        audio_dir = os.path.dirname(file_path)
        audio_name = os.path.splitext(os.path.basename(file_path))[0]
        artist, song = self.extract_song_info(audio_name)
        cached_lyrics = LyricsCacheManager.load_lyrics(song, artist)
        if cached_lyrics:
            return cached_lyrics
        for lrc_ext in self.lrc_exts:
            test_path = os.path.join(audio_dir, f"{audio_name}.{lrc_ext}")
            if os.path.exists(test_path):
                try:
                    with open(test_path, 'r', encoding='utf-8', errors='ignore') as f:
                        content = f.read()
                        if content and len(content) > 20:
                            return content
                except:
                    pass
            test_path = os.path.join(audio_dir, f"{audio_name}.{lrc_ext.upper()}")
            if os.path.exists(test_path):
                try:
                    with open(test_path, 'r', encoding='utf-8', errors='ignore') as f:
                        content = f.read()
                        if content and len(content) > 20:
                            return content
                except:
                    pass
        for subdir in ['Lyrics', 'lyrics', '歌词', 'LRC', 'lrc']:
            lyrics_dir = os.path.join(audio_dir, subdir)
            if os.path.exists(lyrics_dir) and os.path.isdir(lyrics_dir):
                for name in os.listdir(lyrics_dir):
                    if name.startswith('.'):
                        continue
                    ext = self.get_file_ext(name)
                    if ext in self.lrc_exts:
                        lrc_name = os.path.splitext(name)[0]
                        if lrc_name == audio_name or lrc_name.lower() == audio_name.lower():
                            full_path = os.path.join(lyrics_dir, name)
                            try:
                                with open(full_path, 'r', encoding='utf-8', errors='ignore') as f:
                                    content = f.read()
                                    if content and len(content) > 20:
                                        return content
                            except:
                                pass
        return None
    
    def _add_audio_info_fast(self, result, file_path):
        filename = os.path.basename(file_path)
        artist, song = self.extract_song_info(filename)
        result["title"] = song or filename
        result["artist"] = artist or ""
        # 如果已经有封面（来自URL传递），不要覆盖
        if 'artwork' not in result or not result['artwork']:
            cover_url = self.get_audio_cover_ultra_fast(file_path)
            if self._is_real_cover(cover_url):
                result["vod_pic"] = cover_url
                result["artwork"] = cover_url
        lyrics = self._get_local_lyrics(file_path)
        if lyrics:
            result["lrc"] = lyrics
        else:
            if song and self.enable_online_lyrics:
                try:
                    net_lyrics = self.get_network_lyrics(song, artist)
                    if net_lyrics:
                        result["lrc"] = net_lyrics
                except:
                    pass
    
    # ==================== 网络歌词/封面（缓存优先，移植自 简助手.js） ====================
    def _cover_cache_file_for_key(self, key):
        """封面缓存一律用点开头的隐藏文件名：相册/文件管理器/其它应用默认扫不到"""
        file_hash = hashlib.md5(key.encode('utf-8', 'surrogateescape')).hexdigest()
        return "%s.%s.jpg" % (COVER_CACHE_DIR, file_hash)

    def _cover_net_neg_file(self):
        return os.path.join(COVER_CACHE_DIR, 'cover_net_neg.json')

    def _cover_net_neg_key(self, song, artist):
        raw = 'netneg_%s_%s' % ((song or '').strip(), (artist or '').strip())
        return hashlib.md5(raw.encode('utf-8', 'surrogateescape')).hexdigest()

    def _cover_net_neg_load(self):
        try:
            if os.path.exists(self._cover_net_neg_file()):
                with open(self._cover_net_neg_file(), 'r', encoding='utf-8') as f:
                    return json.load(f)
        except Exception:
            pass
        return {}

    def _cover_net_skip(self, file_path):
        """某曲网络封面刚失败过就先不重复联网（负缓存）；首次 20 分钟、连续失败逐次翻倍，最长 6 小时"""
        try:
            base = os.path.basename(file_path)
            artist, song = self.extract_song_info(base)
            if not song:
                song = os.path.splitext(base)[0]
            rec = self._cover_net_neg_load()
            item = rec.get(self._cover_net_neg_key(song, artist))
            if not item:
                return False
            if isinstance(item, dict):
                ts = float(item.get('t') or 0)
                tries = int(item.get('n') or 1)
            else:
                ts = float(item or 0)
                tries = 1
            base_iv = getattr(self, 'cover_net_retry_interval', 20 * 60)
            max_iv = getattr(self, 'cover_net_retry_max', 6 * 3600)
            iv = min(max_iv, base_iv * (2 ** max(0, min(tries, 6) - 1)))
            return (time.time() - ts) < iv
        except Exception:
            return False

    def _mark_cover_net_tried(self, file_path):
        try:
            base = os.path.basename(file_path)
            artist, song = self.extract_song_info(base)
            if not song:
                song = os.path.splitext(base)[0]
            rec = self._cover_net_neg_load()
            key = self._cover_net_neg_key(song, artist)
            old = rec.get(key)
            if isinstance(old, dict):
                tries = int(old.get('n') or 1) + 1
            elif old:
                tries = 2
            else:
                tries = 1
            rec[key] = {'t': time.time(), 'n': tries}
            if len(rec) > 5000:
                rec = dict(list(rec.items())[-3000:])
            os.makedirs(COVER_CACHE_DIR, exist_ok=True)
            with open(self._cover_net_neg_file(), 'w', encoding='utf-8') as f:
                json.dump(rec, f)
        except Exception:
            pass

    def get_network_lyrics(self, song, artist=""):
        """网络歌词：命中歌词缓存直接返回，未命中才联网获取并写入脚本既有的歌词缓存目录"""
        song = (song or '').strip()
        artist = (artist or '').strip()
        if not song:
            return None
        if LyricsCacheManager.is_lyrics_cached(song, artist):
            cached = LyricsCacheManager.load_lyrics(song, artist)
            if cached:
                return cached
        if not self.enable_online_lyrics:
            return None
        try:
            lyrics = NetMusicProvider.fetch_lyrics(song, artist, self.session, self.log)
        except Exception as e:
            self.log('⚠️ 网络歌词获取异常: %s' % e)
            lyrics = ''
        if lyrics and len(lyrics) > 20:
            try:
                LyricsCacheManager.save_lyrics(song, artist, lyrics)
                self.log('✅ 已缓存网络歌词: %s - %s' % (song, artist))
            except Exception:
                pass
            return lyrics
        self.log('⚠️ 未找到网络歌词: %s - %s' % (song, artist))
        return None

    def _net_cover_cache_path(self, song, artist=""):
        return self._cover_cache_file_for_key('netcover_%s_%s' % ((song or '').strip(), (artist or '').strip()))

    def _net_cover_cache_path_legacy(self, song, artist=""):
        """老版本用的非隐藏文件名，只用于迁移"""
        raw = 'netcover_%s_%s' % ((song or '').strip(), (artist or '').strip())
        return "%s%s.jpg" % (COVER_CACHE_DIR, hashlib.md5(raw.encode('utf-8', 'surrogateescape')).hexdigest())

    def _get_cached_network_cover(self, file_path):
        """按歌曲身份（歌手+歌名）查找已缓存的网络封面；文件缺失或为空则视为未缓存"""
        try:
            base = os.path.basename(file_path)
            artist, song = self.extract_song_info(base)
            if not song:
                song = os.path.splitext(base)[0]
            p = self._net_cover_cache_path(song, artist)
            if self._valid_cover_file(p):
                return p
            legacy = self._net_cover_cache_path_legacy(song, artist)
            if self._valid_cover_file(legacy):
                try:
                    os.replace(legacy, p)
                    if self._valid_cover_file(p):
                        return p
                except Exception:
                    pass
                return legacy
            for stale in (p, legacy):
                if os.path.exists(stale):
                    # 坏图（半截/非图片）留着只会一直显示不出来，删掉让它重下
                    try:
                        os.remove(stale)
                    except Exception:
                        pass
        except Exception:
            pass
        return None

    def _clear_cover_net_neg(self, song, artist=""):
        try:
            rec = self._cover_net_neg_load()
            key = self._cover_net_neg_key(song, artist)
            if key in rec:
                rec.pop(key, None)
                with open(self._cover_net_neg_file(), 'w', encoding='utf-8') as f:
                    json.dump(rec, f)
        except Exception:
            pass

    def get_network_cover(self, song, artist="", audio_path=None):
        """网络封面：按歌曲身份命中封面缓存直接返回；未命中则逐个候选来源下载，校验为真实图片后再落盘"""
        song = (song or '').strip()
        artist = (artist or '').strip()
        if not song:
            return None
        self._cover_last_reason = ''
        cached_path = self._net_cover_cache_path(song, artist)
        if os.path.exists(cached_path) and os.path.getsize(cached_path) > 0:
            self._cover_last_reason = 'cached'
            return 'file://' + cached_path
        if not self.enable_online_cover:
            self._cover_last_reason = 'disabled'
            return None
        try:
            candidates = NetMusicProvider.fetch_cover_candidates(song, artist, self.session, self.log)
        except Exception as e:
            self.log('⚠️ 网络封面获取异常: %s' % e)
            candidates = []
            self._cover_last_reason = 'net'
        if not candidates:
            if not self._cover_last_reason:
                no_net = (getattr(NetMusicProvider, '_net_ok', 0) == 0 and
                          getattr(NetMusicProvider, '_net_fail', 0) > 0)
                if getattr(NetMusicProvider, '_cover_sources_err', 0) >= 4 or no_net:
                    self._cover_last_reason = 'net'
                else:
                    self._cover_last_reason = 'nomatch'
            self.log('⚠️ 未找到网络封面(%s): %s - %s' % (self._cover_last_reason, song, artist))
            return None
        self.log('🔎 封面候选 %d 个: %s - %s' % (len(candidates), song, artist))
        tried = []
        for cand in candidates:
            url = str(cand.get('url') or '')
            if not url or url in tried:
                continue
            tried.append(url)
            headers = {
                'User-Agent': NET_UA_PC,
                'Referer': cand.get('referer') or NetMusicProvider._referer_for_url(url),
                'Accept': 'image/avif,image/webp,image/apng,image/*,*/*;q=0.8',
                'Accept-Encoding': 'identity',
                'Connection': 'keep-alive'
            }
            try:
                img_data = NetMusicProvider._http_get_bytes(url, headers, 12, 1, self.session)
            except Exception as e:
                self.log('⚠️ 封面下载异常 %s: %s' % (url, e))
                img_data = b''
            if not img_data or not NetMusicProvider._is_image_bytes(img_data):
                self.log('⚠️ 封面无效(非图片或空) 长度=%d 来源=%s' % (len(img_data or b''), url))
                continue
            try:
                if len(img_data) > 500 * 1024:
                    img_data = UltraFastCoverExtractor._compress_image(img_data, max_size=(300, 300), quality=65)
                os.makedirs(COVER_CACHE_DIR, exist_ok=True)
                with open(cached_path, 'wb') as f:
                    f.write(img_data)
                self.log('✅ 已缓存网络封面(%d字节): %s - %s' % (len(img_data), song, artist))
                self._cover_last_reason = 'ok'
                self._clear_cover_net_neg(song, artist)
                return 'file://' + cached_path
            except Exception as e:
                self.log('⚠️ 网络封面保存失败: %s' % e)
        self.log('⚠️ 网络封面全部来源失败: %s - %s' % (song, artist))
        self._cover_last_reason = 'download'
        return None

    def scan_directory(self, dir_path):
        try:
            if not os.path.exists(dir_path) or not os.path.isdir(dir_path):
                return []
            audio_names = []
            all_items = []
            for name in os.listdir(dir_path):
                if name.startswith('.') or name in ['.', '..']:
                    continue
                full_path = os.path.join(dir_path, name)
                is_dir = os.path.isdir(full_path)
                ext = self.get_file_ext(name)
                all_items.append({
                    'name': name,
                    'path': full_path,
                    'is_dir': is_dir,
                    'ext': ext,
                    'mtime': os.path.getmtime(full_path) if not is_dir else 0,
                })
                if not is_dir and ext in self.audio_exts:
                    audio_names.append(os.path.splitext(name)[0])
            files = []
            for item in all_items:
                name = item['name']
                is_dir = item['is_dir']
                if is_dir:
                    files.append(item)
                    continue
                if self._should_hide_file(name, dir_path, audio_names):
                    continue
                files.append(item)
            files.sort(key=lambda x: (not x['is_dir'], x['name'].lower()))
            return files
        except:
            return []
    
    def _scan_directory_simple(self, dir_path):
        try:
            if not os.path.exists(dir_path) or not os.path.isdir(dir_path):
                return []
            files = []
            for name in os.listdir(dir_path):
                if name.startswith('.'):
                    continue
                full_path = os.path.join(dir_path, name)
                is_dir = os.path.isdir(full_path)
                files.append({
                    'name': name,
                    'path': full_path,
                    'is_dir': is_dir,
                    'ext': self.get_file_ext(name),
                })
            files.sort(key=lambda x: (not x['is_dir'], x['name'].lower()))
            return files
        except:
            return []
    
    def _extract_filter_value(self, extend):
        if not extend or not isinstance(extend, dict):
            return None
        letter_keys = ['letter_row1', 'letter_row2', 'letter_row3', 'letter_row4']
        for key in letter_keys:
            if key in extend and extend[key] and extend[key] != '全部':
                return extend[key]
        if 'digit_row' in extend and extend['digit_row'] and extend['digit_row'] != '全部':
            return extend['digit_row']
        return None
    
    def _apply_filter_to_files(self, files, filter_value):
        if not filter_value or filter_value == '全部' or not files:
            for f in files:
                f.pop('match_score', None)
            return files
        for f in files:
            name = f['name']
            f['match_score'] = 0
            if not name:
                continue
            first_char = name[0]
            if filter_value == 'all_digits':
                if first_char.isdigit():
                    f['match_score'] = 1
            elif filter_value.isdigit():
                if first_char.isdigit() and first_char == filter_value:
                    f['match_score'] = 1
            else:
                if first_char.upper() == filter_value.upper():
                    f['match_score'] = 1
                elif '\u4e00' <= first_char <= '\u9fff':
                    pinyin_initial = _get_chinese_pinyin_initial(name[0])
                    if pinyin_initial == filter_value.upper():
                        f['match_score'] = 1
        filtered = [f for f in files if f.get('match_score', 0) == 1]
        if filtered:
            filtered.sort(key=lambda x: (-x.get('match_score', 0), x['name'].lower()))
            return filtered
        files.sort(key=lambda x: (-x.get('match_score', 0), x['name'].lower()))
        return files
    
    def collect_videos_in_dir(self, dir_path):
        files = self.scan_directory(dir_path)
        return [f for f in files if not f['is_dir'] and f['ext'] in self.media_exts]
    
    def collect_images_in_dir(self, dir_path):
        files = self.scan_directory(dir_path)
        return [f for f in files if not f['is_dir'] and f['ext'] in self.image_exts]
    
    def get_file_icon(self, ext, is_dir=False):
        if is_dir:
            return '📁'
        if ext in self.media_exts:
            return '🎬'
        if ext in self.audio_exts:
            return '🎵'
        if ext in self.image_exts:
            return '🖼'
        if ext in self.comic_exts:
            return '📚'
        if ext in self.list_exts:
            return '📋'
        if ext in self.lrc_exts:
            return '📝'
        if ext in self.db_exts:
            return '🗄️'
        if ext in self.magnet_exts:
            return '🧲'
        if ext == 'php':
            return '🐘'
        if ext == 'py':
            return '🐍'
        if ext in self.archive_exts:
            return '🗜️'
        return '📄'
    
    def is_playable_url(self, url):
        u = str(url).lower().strip()
        if not u:
            return False
        protocols = [
            'http://', 'https://', 'rtmp://', 'rtsp://', 'udp://', 'rtp://', 
            'file://', 'pics://', 'mp3://', 'magnet:', 'ed2k://', 'thunder://', 'ftp://',
            'vod://', 'bilibili://', 'youtube://', 'rtmps://', 'rtmpt://', 'hls://',
            'http-live://', 'https-live://', 'tvbus://', 'tvbox://', 'live://', 'novel://', 'text://'
        ]
        if any(u.startswith(p) for p in protocols):
            return True
        exts = [
            '.mp4', '.mkv', '.avi', '.rmvb', '.mov', '.wmv', '.flv', 
            '.m3u8', '.ts', '.mp3', '.m4a', '.aac', '.flac', '.wav', 
            '.webm', '.ogg', '.m4v', '.f4v', '.3gp', '.mpg', '.mpeg',
            '.m3u', '.pls', '.asf', '.asx', '.wmx'
        ]
        if any(ext in u for ext in exts):
            return True
        patterns = [
            'youtu.be/', 'youtube.com/', 'bilibili.com/', 'iqiyi.com/', 
            'v.qq.com/', 'youku.com/', 'tudou.com/', 'mgtv.com/',
            'sohu.com/', 'acfun.cn/', 'douyin.com/', 'kuaishou.com/',
            'huya.com/', 'douyu.com/', 'twitch.tv/', 'live.'
        ]
        return any(p in u for p in patterns)
    
    def _generate_colored_icon(self, color, text):
        svg = f'''<svg xmlns="http://www.w3.org/2000/svg" width="200" height="200" viewBox="0 0 200 200">
            <rect width="200" height="200" rx="40" ry="40" fill="{color}"/>
            <circle cx="100" cy="100" r="70" fill="white" opacity="0.3"/>
            <text x="100" y="140" font-size="100" text-anchor="middle" fill="white" font-family="Arial" font-weight="bold">{text}</text>
        </svg>'''
        return f"data:image/svg+xml;base64,{base64.b64encode(svg.encode('utf-8', 'surrogateescape')).decode()}"
    
    def parse_json_file(self, file_path):
        items = []
        try:
            with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read(150 * 1024 * 1024)
            if content.startswith('\ufeff'):
                content = content[1:]
            data = json.loads(content)
            if isinstance(data, list):
                item_list = data
            elif isinstance(data, dict):
                if 'vod_play_url' in data:
                    return self._handle_vod_format(data, file_path)
                if 'vod_play_from' in data and 'vod_play_url' in data:
                    return self._handle_multi_line_vod(data, file_path)
                possible_keys = ['list', 'data', 'items', 'videos', 'vod', 'results', 'rows']
                item_list = None
                for key in possible_keys:
                    if key in data and isinstance(data[key], list):
                        item_list = data[key]
                        break
                if item_list is None and all(isinstance(v, dict) for v in data.values()):
                    item_list = list(data.values())
                if item_list is None:
                    item_list = [data]
            else:
                return items
            for idx, item in enumerate(item_list):
                if not isinstance(item, dict):
                    if isinstance(item, str) and self.is_playable_url(item):
                        items.append({
                            'name': f'链接{idx+1}',
                            'url': item,
                            'pic': '',
                            'remarks': ''
                        })
                    continue
                name = self._extract_json_field(item, ['name', 'title', 'vod_name', 'video_name', 'show_name'])
                if not name:
                    name = f"项目{idx+1}"
                url = self._extract_json_field(item, ['url', 'link', 'play_url', 'video_url', 'vod_url', 'vod_play_url'])
                if not url:
                    play_url_raw = self._extract_json_field(item, ['vod_play_url', 'play_url'])
                    if play_url_raw and ('$' in play_url_raw or '#' in play_url_raw):
                        episodes = self._parse_multi_episodes(play_url_raw, name)
                        for ep in episodes:
                            ep_item = {
                                'name': ep['name'],
                                'url': ep['url'],
                                'pic': self._extract_json_field(item, ['pic', 'cover', 'image', 'vod_pic'], True),
                                'remarks': self._extract_json_field(item, ['remarks', 'vod_remarks', 'note'])
                            }
                            items.append(ep_item)
                        continue
                    elif play_url_raw:
                        url = play_url_raw
                if not url or not self.is_playable_url(url):
                    continue
                pic = self._extract_json_field(item, ['pic', 'cover', 'image', 'vod_pic'], True)
                remarks = self._extract_json_field(item, ['remarks', 'vod_remarks', 'note'])
                items.append({
                    'name': name,
                    'url': url,
                    'pic': pic,
                    'remarks': remarks
                })
        except:
            pass
        return items
    
    def _handle_vod_format(self, data, file_path):
        items = []
        name = data.get('vod_name') or data.get('name') or os.path.splitext(os.path.basename(file_path))[0]
        play_url = data.get('vod_play_url', '')
        pic = data.get('vod_pic') or data.get('pic') or ''
        remarks = data.get('vod_remarks', '')
        if play_url and ('$' in play_url or '#' in play_url):
            episodes = self._parse_multi_episodes(play_url, name)
            for ep in episodes:
                items.append({
                    'name': ep['name'],
                    'url': ep['url'],
                    'pic': pic,
                    'remarks': remarks
                })
        else:
            items.append({
                'name': name,
                'url': play_url,
                'pic': pic,
                'remarks': remarks
            })
        return items
    
    def _handle_multi_line_vod(self, data, file_path):
        items = []
        vod_name = data.get('vod_name') or data.get('name') or os.path.splitext(os.path.basename(file_path))[0]
        vod_pic = data.get('vod_pic') or data.get('pic') or ''
        play_from = data.get('vod_play_from', '')
        play_url = data.get('vod_play_url', '')
        from_list = play_from.split('$$$') if play_from else ['默认线路']
        url_list = play_url.split('$$$') if play_url else ['']
        for from_name, url_group in zip(from_list, url_list):
            if url_group and ('$' in url_group or '#' in url_group):
                episodes = self._parse_multi_episodes(url_group, f"{vod_name}[{from_name}]")
                for ep in episodes:
                    items.append({
                        'name': ep['name'],
                        'url': ep['url'],
                        'pic': vod_pic,
                        'remarks': f'线路:{from_name}'
                    })
        return items
    
    def _parse_multi_episodes(self, play_url_raw, base_name):
        episodes = []
        groups = play_url_raw.split('$$$')
        for group in groups:
            if not group:
                continue
            parts = group.split('#')
            for part in parts:
                if not part:
                    continue
                if '$' in part:
                    ep_name, ep_url = part.split('$', 1)
                    episodes.append({
                        'name': ep_name.strip(),
                        'url': ep_url.strip()
                    })
                else:
                    episodes.append({
                        'name': f"{base_name} - 节目{len(episodes)+1}",
                        'url': part.strip()
                    })
        return episodes
    
    def _extract_json_field(self, item, field_names, is_image=False):
        for field in field_names:
            if field in item and item[field]:
                value = item[field]
                if isinstance(value, dict):
                    for url_field in ['url', 'src', 'path', 'file']:
                        if url_field in value and value[url_field]:
                            return str(value[url_field])
                    if is_image:
                        for img_field in ['large', 'medium', 'small', 'thumb']:
                            if img_field in value and value[img_field]:
                                return str(value[img_field])
                    return str(value)
                elif isinstance(value, list) and value:
                    if is_image:
                        first = value[0]
                        if isinstance(first, dict):
                            for url_field in ['url', 'src', 'path']:
                                if url_field in first and first[url_field]:
                                    return str(first[url_field])
                            return str(first)
                        else:
                            return str(first)
                    else:
                        for v in value:
                            if v and isinstance(v, str):
                                return v
                        return str(value[0]) if value else ''
                else:
                    return str(value).strip()
        return ''
    
    def parse_db_file(self, file_path):
        return self.db_reader.read_sqlite(file_path, MAX_DB_RESULTS)
    
    def _get_domain_from_url(self, url):
        try:
            from urllib.parse import urlparse
            domain = urlparse(url).netloc
            return domain.split(':')[0] if ':' in domain else domain
        except:
            return ""
    
    def _fetch_with_auto_headers(self, url, source=None):
        domain = self._get_domain_from_url(url)
        if source:
            custom_headers = {}
            if source.get('ua'):
                custom_headers['User-Agent'] = source['ua']
            if source.get('referer'):
                custom_headers['Referer'] = source['referer']
            if source.get('origin'):
                custom_headers['Origin'] = source['origin']
            if custom_headers:
                custom_headers['Accept'] = '*/*'
                custom_headers['Accept-Language'] = 'zh-CN,zh;q=0.9,en;q=0.8'
                custom_headers['Connection'] = 'keep-alive'
                custom_headers['Accept-Encoding'] = 'gzip, deflate'
                try:
                    print(f"🌐 [UA生效] {source.get('name', '直播源')} 使用 UA: {custom_headers.get('User-Agent', '')[:50]}...")
                    resp = self.session.get(url, headers=custom_headers, timeout=15)
                    if resp.status_code == 200:
                        return resp.text
                    else:
                        print(f"⚠️ UA请求失败，状态码: {resp.status_code}")
                except Exception as e:
                    print(f"❌ UA请求异常: {e}")
        if domain in self.domain_specific_headers:
            for headers_info in self.domain_specific_headers[domain]:
                try:
                    print(f"🌐 [域名专用] {domain} 使用 {headers_info.get('name', '默认')}")
                    resp = self.session.get(url, headers=headers_info['headers'], timeout=15)
                    if resp.status_code == 200:
                        return resp.text
                except:
                    continue
        for headers_info in self.common_headers_list:
            try:
                resp = self.session.get(url, headers=headers_info['headers'], timeout=10)
                if resp.status_code == 200:
                    print(f"🌐 [通用UA] 使用 {headers_info.get('name', '默认')} 成功")
                    return resp.text
            except:
                continue
        try:
            print(f"🌐 [默认UA] 使用默认浏览器UA")
            resp = self.session.get(url, headers=self.headers, timeout=15)
            if resp.status_code == 200:
                return resp.text
        except:
            pass
        print(f"❌ 所有UA尝试均失败: {url}")
        return None
    
    def _get_live_programs(self, source):
        source_id = source['id']
        current_time = time.time()
        if source_id in self.live_cache and current_time - self.live_cache_time.get(source_id, 0) < self.live_cache_duration:
            return self.live_cache[source_id]
        content = self._fetch_with_auto_headers(source['url'], source)
        if not content:
            return []
        programs = self._parse_live_content(content, source)
        if programs:
            self.live_cache[source_id] = programs
            self.live_cache_time[source_id] = current_time
        return programs
    
    def _parse_live_content(self, content, source):
        if source.get('type') == 'txt' or ',#genre#' in content:
            return self._parse_txt_live(content)
        elif content.strip().startswith(('{', '[')):
            return self._parse_json_live(content)
        progs = self._parse_m3u_live(content)
        if progs:
            return progs
        # 自定义直播源可能是不带 #genre# 的「名称,地址」txt：m3u 解不出来再按 txt 试一次
        return self._parse_txt_live(content)
    
    def _parse_m3u_live(self, content):
        programs = []
        lines = content.split('\n')
        current_name = None
        current_group = ''
        for line in lines:
            line = line.strip()
            if not line:
                continue
            if line.startswith('#EXTINF:'):
                name_match = re.search(r',(.+)$', line) or re.search(r'tvg-name="([^"]+)"', line)
                current_name = name_match.group(1).strip() if name_match else None
                _g = re.search(r'group-title="([^"]*)"', line)
                current_group = (_g.group(1).strip() if _g else '')
            elif line and not line.startswith('#') and current_name:
                if self.is_playable_url(line):
                    programs.append({'name': current_name, 'url': line, 'group': current_group})
                current_name = None
        return programs
    
    def _parse_txt_live(self, content):
        programs = []
        lines = content.split('\n')
        current_cat = None
        for line in lines:
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            if ',#genre#' in line:
                current_cat = line.split(',')[0].strip()
                continue
            if ',' in line:
                parts = line.split(',', 1)
                name = parts[0].strip()
                url = parts[1].strip()
                if self.is_playable_url(url):
                    display_name = f"[{current_cat}] {name}" if current_cat else name
                    programs.append({'name': display_name, 'url': url, 'group': (current_cat or '')})
        return programs
    
    def _parse_json_live(self, content):
        programs = []
        try:
            data = json.loads(content)
            items = []
            if isinstance(data, dict):
                for key in ['list', 'data', 'items', 'videos']:
                    if key in data and isinstance(data[key], list):
                        items = data[key]
                        break
                if not items:
                    items = [data]
            else:
                items = data
            for item in items:
                if isinstance(item, dict):
                    name = item.get('name') or item.get('title')
                    url = item.get('url') or item.get('play_url')
                    if name and url and self.is_playable_url(url):
                        _g2 = item.get('group') or item.get('group-title') or item.get('category') or ''
                        programs.append({'name': name, 'url': url, 'group': str(_g2)})
        except:
            pass
        return programs
    
    def _is_txt_live_source(self, content, file_path=None):
        if ',#genre#' in content.lower():
            return True
        if file_path:
            file_name_lower = os.path.basename(file_path).lower()
            if any(kw in file_name_lower for kw in ['直播', 'live', '抖音', 'douyin', '视频', 'video']):
                url_count = 0
                lines = content.split('\n')[:50]
                for line in lines:
                    if 'http://' in line or 'https://' in line:
                        url_count += 1
                        if url_count >= 2:
                            return True
        url_count = 0
        lines = content.split('\n')[:50]
        for line in lines:
            if 'http://' in line or 'https://' in line:
                url_count += 1
                if url_count >= 3:
                    return True
        return False
    
    def _is_txt_novel(self, content, file_path=None):
        chapter_patterns = [
            r'第[一二三四五六七八九十百千万0-9]+章',
            r'第[一二三四五六七八九十百千万0-9]+节',
            r'序章|楔子|尾声',
            r'Chapter\s+\d+'
        ]
        preview = content[:5000]
        chapter_count = 0
        for pattern in chapter_patterns:
            matches = re.findall(pattern, preview)
            chapter_count += len(matches)
            if chapter_count >= 3:
                return True
        if file_path:
            file_name_lower = os.path.basename(file_path).lower()
            if any(kw in file_name_lower for kw in ['小说', 'novel', 'book', 'txt']):
                url_count = len(re.findall(r'https?://', preview))
                if url_count < 5 and len(preview) > 2000:
                    return True
        return False
    
    def _merge_split_urls(self, content):
        lines = [line.rstrip('\r\n') for line in content.split('\n') if line.strip()]
        merged_lines = []
        current_url = ""
        i = 0
        while i < len(lines):
            line = lines[i].strip()
            if re.match(r'^\d+\s*$', line):
                merged_lines.append(line)
                i += 1
                continue
            if line.startswith(('http://', 'https://')):
                current_url = line
                i += 1
                while i < len(lines):
                    next_line = lines[i].strip()
                    if re.match(r'^\d+\s*$', next_line) or next_line.startswith(('http://', 'https://')):
                        break
                    current_url += next_line
                    i += 1
                merged_lines.append(current_url)
                current_url = ""
            elif re.match(r'^\d+\s*[, ]', line):
                merged_lines.append(line)
                i += 1
            else:
                merged_lines.append(line)
                i += 1
        result_lines = []
        for line in merged_lines:
            if 'http://' in line or 'https://' in line:
                line = re.sub(r'(https?://[^\s]*?)\s+([^\s]+)', r'\1\2', line)
                line = line.replace(' ', '').replace('\t', '').replace('\r', '').replace('\n', '')
            result_lines.append(line)
        return '\n'.join(result_lines)
    
    def _parse_txt_file(self, file_path):
        items = []
        try:
            with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                content = f.read()
            content = self._merge_split_urls(content)
            is_live = self._is_txt_live_source(content, file_path)
            if not is_live and self._is_txt_novel(content, file_path):
                return []
            lines = []
            for line in content.split('\n'):
                line = line.strip()
                if not line:
                    continue
                lines.append(line)
            current_cat = None
            for line in lines:
                if ',#genre#' in line:
                    current_cat = line.split(',')[0].strip()
                    continue
                if line.startswith(('http://', 'https://')):
                    if self.is_playable_url(line):
                        name = current_cat if current_cat else f"视频{len(items)+1}"
                        items.append({'name': name, 'url': line})
                    continue
                if re.match(r'^\d+\s*[, ]', line):
                    url_match = re.search(r'[, ](https?://.+)', line)
                    if url_match:
                        url = url_match.group(1).strip()
                        url = re.sub(r'\s+', '', url)
                        name_match = re.match(r'^(\d+)\s*[, ]', line)
                        name = f"视频{name_match.group(1)}" if name_match else "视频"
                        if self.is_playable_url(url):
                            display_name = f"[{current_cat}] {name}" if current_cat else name
                            items.append({'name': display_name, 'url': url})
                    continue
                if ',' in line:
                    parts = line.split(',', 1)
                    name = parts[0].strip()
                    url = parts[1].strip()
                    url = re.sub(r'\s+', '', url)
                    if self.is_playable_url(url):
                        display_name = f"[{current_cat}] {name}" if current_cat else name
                        items.append({'name': display_name, 'url': url})
            seen = set()
            unique_items = []
            for item in items:
                key = f"{item['name']}|{item['url']}"
                if key not in seen:
                    seen.add(key)
                    unique_items.append(item)
            return unique_items
        except:
            return []
    
