    @_view_mode_apply
    def _raw_homeContent(self, filter):
        classes = []
        for i, path in enumerate(self.root_paths):
            if os.path.exists(path):
                name = self.path_to_chinese.get(path, os.path.basename(path.rstrip('/')) or f'目录{i}')
                classes.append({"type_id": f"root_{i}", "type_name": name})
        # 挂载：在动作里「➕ 添加新的挂载」加的那些，每个在「📌 常用路径」前面铺一个分类，随启动就有
        # （py书签 只是个收藏列表，不在主分类展示）
        try:
            for _mnt in self.web_action_browser._load_home_mounts_static():
                _mp = str(_mnt.get('path') or '').strip()
                if not _mp or not os.path.exists(_mp):
                    continue
                _mnm = str(_mnt.get('name') or '').strip() or (os.path.basename(_mp.rstrip('/')) or 'py书签')
                if _mnm.lower().endswith('.py'):
                    _mnm = _mnm[:-3]
                classes.append({"type_id": self.PYPLUGM_PREFIX + self.b64u_encode(_mp),
                                "type_name": "🧩 " + _mnm})
        except Exception:
            pass
        _cpath_n = len(self.web_action_browser._load_common_paths_static())
        classes.append({"type_id": "cpath://root", "type_name": "📌 常用路径" + ("(%d)" % _cpath_n if _cpath_n else "")})
        _pymnt_n = len(self.web_action_browser._load_py_mounts_static())
        classes.append({"type_id": "pymnt://root", "type_name": "🧩 py书签" + ("(%d)" % _pymnt_n if _pymnt_n else "")})
