    def _delete_folder_to_trash(self, folder_path):
        try:
            if not os.path.exists(folder_path):
                return False, "文件夹不存在"
            if not os.path.isdir(folder_path):
                return False, "不是文件夹"
            folder_name = os.path.basename(folder_path)
            unique_name = f"{int(time.time())}_{folder_name}"
            trash_path = os.path.join(self.trash_dir, unique_name)
            shutil.move(folder_path, trash_path)
            self._trash_record(unique_name, folder_path)
            self.dir_cache.pop(f"dir_{folder_path}", None)
            self.dir_cache_time.pop(f"dir_{folder_path}", None)
            self.audio_list_cache.pop(folder_path, None)
            self.audio_list_cache_time.pop(folder_path, None)
            cache_keys_to_delete = []
            for key in self.dir_cache.keys():
                if key.startswith(f"dir_{folder_path}"):
                    cache_keys_to_delete.append(key)
            for key in cache_keys_to_delete:
                self.dir_cache.pop(key, None)
                self.dir_cache_time.pop(key, None)
            return True, f"已删除文件夹: {folder_name} (及其所有内容)"
        except Exception as e:
            return False, f"删除文件夹失败: {e}"
    
    # ==================== 文件操作页（选中一个文件 → 复制 / 剪切 / 删除 / 重命名）====================

    @staticmethod
    def _filop_size(path):
        try:
            num = float(os.path.getsize(path))
        except Exception:
            return ''
        for unit in ('B', 'KB', 'MB', 'GB', 'TB'):
            if num < 1024 or unit == 'TB':
                return ('%d%s' % (num, unit)) if unit == 'B' else ('%.1f%s' % (num, unit))
            num /= 1024.0
        return ''

    def _edit_is_text(self, path):
        try:
            ext = path.rsplit('.', 1)[-1].lower() if '.' in path else ''
            if ext in ('txt', 'json', 'conf', 'ini', 'cfg', 'm3u', 'm3u8', 'xml', 'html', 'htm', 'css', 'js',
                       'py', 'sh', 'md', 'log', 'csv', 'tsv', 'yml', 'yaml', 'properties', 'srt', 'ass', 'lrc',
                       'php', 'bat', 'prop', 'tpl', 'text', 'vue', 'ts', 'sql', 'env', 'toml', 'db'):
                return True
            if os.path.getsize(path) > 512 * 1024:
                return False
            with open(path, 'rb') as f:
                head = f.read(4096)
            return b'\x00' not in head
        except Exception:
            return False

    def _edit_read(self, path):
        with open(path, 'rb') as f:
            raw = f.read()
        if b'\x00' in raw[:8192]:
            raise ValueError('这是二进制文件，改不了')
        for enc in ('utf-8', 'gbk', 'utf-16', 'latin-1'):
            try:
                return raw.decode(enc), enc
            except Exception:
                continue
        raise ValueError('编码认不出来')

    def _edit_write(self, path, text, enc):
        bak = path + '.bak'
        if not os.path.exists(bak):
            try:
                shutil.copy2(path, bak)
            except Exception:
                pass
        with open(path, 'wb') as f:
            f.write(text.encode(enc, 'replace'))

    def _edit_dispatch(self, tid):
        raw = str(tid)
        if raw.startswith('editat://'):
            body = raw[len('editat://'):]
            enc0, _sep, lno = body.partition('|')
            path = self.b64u_decode(enc0)
            try:
                text, _enc = self._edit_read(path)
            except Exception as e:
                return {'list': [self._filop_card('打不开', str(e), '#F44336', 'x')], 'page': 1, 'pagecount': 1}
            try:
                off = max(0, (int(lno or 0) // 30) * 30)
            except Exception:
                off = 0
            return {'list': [self._edit_chunk_item(path, text, off),
                             self._filop_card('回文件', os.path.basename(path), '#607D8B', '<',
                                              raw_id=True, link='edit://' + enc0)],
                    'page': 1, 'pagecount': 1}
        if raw.startswith('editview://'):
            return self._edit_view_page(self.b64u_decode(raw[len('editview://'):].split('|')[0]))
        if raw.startswith('editfiles://'):
            _p = self.b64u_decode(raw[len('editfiles://'):].split('|')[0])
            self.edit_mode_enabled = True
            self.edit_mode_dir = _p
            return self._edit_list_page(_p, inline=True)
        if raw.startswith('editdir://'):
            body = raw[len('editdir://'):]
            enc0, _sep, verb = body.partition('|')
            path = self.b64u_decode(enc0)
            if verb == 'off':
                # 只把这个文件夹记成「先不看修改列表」，模式本身留着，下次筛选还能开
                try:
                    self._edit_off_dirs.add(path)
                    if len(self._edit_off_dirs) > 50:
                        self._edit_off_dirs = set(list(self._edit_off_dirs)[-50:])
                except Exception:
                    pass
                self.edit_mode_dir = path
                if path and os.path.isdir(path):
                    try:
                        return self.categoryContent(self.FOLDER_PREFIX + self.b64u_encode(path), 1, None, None)
                    except Exception:
                        pass
                return {'list': [self._filop_card('已回到普通列表', path, '#4CAF50', 'v', icon_key='status')],
                        'page': 1, 'pagecount': 1}
            self.edit_mode_enabled = True
            self.edit_mode_dir = path
            try:
                self._edit_off_dirs.discard(path)
            except Exception:
                pass
            return self._edit_list_page(path)
        return self._edit_page(self.b64u_decode(raw[len('edit://'):].split('|')[0]))

    def _edit_list_page(self, dir_path, inline=False):
        if not dir_path or not os.path.isdir(dir_path):
            return {'list': [self._filop_card('找不到这个文件夹', str(dir_path), '#F44336', 'x')],
                    'page': 1, 'pagecount': 1}
        enc = self.b64u_encode(dir_path)
        items = []
        parent = os.path.dirname(dir_path.rstrip('/'))
        if parent and parent != dir_path:
            items.append(self._filop_card('返回 ' + (os.path.basename(parent) or parent), '上一层',
                                          '#2196F3', '<', raw_id=True, link='editdir://' + self.b64u_encode(parent)))
        items.append(self._filop_card('修改模式：点文件直接用 MT 打开改' if not inline else '脚本内编辑：点文件进内容弹窗',
                                      '改完 MT 里存一下就行；原文是否留 .bak 看 MT 的设置'
                                      if not inline else '适合小改动，改完自动存，原文留一份 .bak',
                                      '#FF9800', 'E', raw_id=True, link='editdir://' + enc, icon_key='rename'))
        items.append(self._filop_card('脚本内编辑（弹窗改）' if not inline else '改回「点文件开 MT」',
                                      '不想装 MT 或者只想改一两行，用这个' if not inline else '回到一点就开 MT 的方式',
                                      '#3F51B5', 'W', raw_id=True,
                                      link=('editfiles://' + enc) if not inline else ('editdir://' + enc),
                                      icon_key='pen'))

        try:
            names = sorted(os.listdir(dir_path),
                           key=lambda n: (not os.path.isdir(os.path.join(dir_path, n)), n.lower()))
        except Exception as e:
            return {'list': [self._filop_card('目录读不出来', str(e), '#F44336', 'x')], 'page': 1, 'pagecount': 1}
        for n in names[:500]:
            full = os.path.join(dir_path, n)
            if os.path.isdir(full):
                items.append(self._filop_card('📁 ' + n, '文件夹 · 点进去', '#607D8B', 'F',
                                              raw_id=True, link='editdir://' + self.b64u_encode(full), icon_key='folder'))
            elif self._edit_is_text(full):
                try:
                    _sz = os.path.getsize(full)
                except Exception:
                    _sz = 0
                if inline:
                    items.append(self._filop_card('📝 ' + n, '%d 字节 · 点开用弹窗改' % _sz,
                                                  '#4CAF50', 'E', raw_id=True,
                                                  link='edit://' + self.b64u_encode(full), icon_key='rename'))
                else:
                    items.append({
                        'vod_id': '系统打开文本|' + self.b64u_encode(full),
                        'vod_name': '📝 ' + n,
                        'vod_pic': self._filop_icon('rename', '#4CAF50', 'E'),
                        'vod_remarks': '%d 字节 · 点一下直接开 MT 管理器改' % _sz,
                        'vod_tag': 'action',
                        'style': {'type': 'list'}
                    })
            else:
                items.append({
                    'vod_id': '系统打开文本|' + self.b64u_encode(full),
                    'vod_name': '📱 ' + n,
                    'vod_pic': self._filop_icon('approve', '#009688', 'O'),
                    'vod_remarks': '不当文本判断，直接丢给文本查看器打开',
                    'vod_tag': 'action',
                    'style': {'type': 'list'}
                })
        return {'list': items, 'page': 1, 'pagecount': 1}

    def _edit_view_page(self, path):
        try:
            text, enc = self._edit_read(path)
        except Exception as e:
            return {'list': [self._filop_card('打不开', str(e), '#F44336', 'x'),
                             self._filop_card('回文件', path, '#607D8B', '<',
                                              raw_id=True, link='edit://' + self.b64u_encode(path))],
                    'page': 1, 'pagecount': 1}
        lines = text.split('\n')[:120]
        items = [self._filop_card('前 %d 行 · %s' % (len(lines), enc), os.path.basename(path),
                                  '#2196F3', 'R', raw_id=True, link='edit://' + self.b64u_encode(path))]
        for i, ln in enumerate(lines, 1):
            items.append({'vod_id': 'edit_noop', 'vod_name': '%d  %s' % (i, ln[:90] or ' '),
                          'vod_pic': self._generate_colored_icon('#90A4AE', '.'),
                          'vod_remarks': '', 'style': {'type': 'list'}})
        return {'list': items, 'page': 1, 'pagecount': 1}

    def _edit_page(self, path):
        if not path or not os.path.isfile(path):
            return {'list': [self._filop_card('这个文件不在了', str(path), '#F44336', 'x')],
                    'page': 1, 'pagecount': 1}
        enc_path = self.b64u_encode(path)
        try:
            text, enc = self._edit_read(path)
        except Exception as e:
            return {'list': [self._filop_card('打不开这个文件', str(e), '#F44336', 'x'),
                             self._filop_card('回文件夹', os.path.dirname(path), '#607D8B', '<',
                                              raw_id=True, link='editdir://' + self.b64u_encode(os.path.dirname(path)))],
                    'page': 1, 'pagecount': 1}
        msg = str(getattr(self, '_edit_msg', '') or '')
        nl = text.count('\n') + 1
        try:
            sz = os.path.getsize(path)
        except Exception:
            sz = len(text)
        preview = text[:80].replace('\n', ' / ')
        items = [self._filop_card('📝 ' + os.path.basename(path),
                                  '%d 字节 · %d 行 · %s%s' % (sz, nl, enc, ('　' + msg) if msg else ''),
                                  '#4CAF50', 'E', raw_id=True, link='edit://' + enc_path, icon_key='rename')]
        items.append({
            'vod_id': '文本复制|' + enc_path,
            'vod_name': '📋 复制全文到剪贴板',
            'vod_pic': self._filop_icon('copy', '#795548', 'C'),
            'vod_remarks': '查看器里是空的就用这个：复制后自己去记事本粘贴',
            'vod_tag': 'action',
            'style': {'type': 'grid', 'ratio': 1}
        })
        items.append({
            'vod_id': '系统打开文本|' + enc_path,
            'vod_name': '📱 用系统查看器打开',
            'vod_pic': self._filop_icon('approve', '#009688', 'O'),
            'vod_remarks': '交给手机上的文本 App 看和改（记事本 / WPS / MT）',
            'vod_tag': 'action',
            'style': {'type': 'grid', 'ratio': 1}
        })
        items.append(self._filop_card(('开头：' + preview) if preview else '空文件',
                                      '点开看全文' if preview else '点下面「末尾加一行」开始写',
                                      '#607D8B', 'R', raw_id=True, link='editview://' + enc_path))
        items.append(self._edit_chunk_item(path, text, 0))
        items.append({
            'vod_id': json.dumps({'actionId': '文本追加|' + enc_path, 'id': 'text', 'type': 'input',
                                  'title': '末尾加一行', 'tip': '输入要加的内容，会在最后新起一行', 'value': ''},
                                 ensure_ascii=False),
            'vod_name': '➕ 末尾加一行', 'vod_pic': self._filop_icon('plus', '#4CAF50', '+'),
            'vod_remarks': '不动原有内容，只在最后加一行', 'vod_tag': 'action',
            'style': {'type': 'grid', 'ratio': 1}
        })
        items.append({
            'vod_id': json.dumps({'actionId': '文本换行|' + enc_path, 'id': 'text', 'type': 'input',
                                  'title': '替换某一行', 'tip': '格式：行号|新内容，例：3|title=abc', 'value': ''},
                                 ensure_ascii=False),
            'vod_name': '🔁 替换第几行', 'vod_pic': self._filop_icon('pen', '#FF9800', 'R'),
            'vod_remarks': '输入「行号|新内容」，只改那一行', 'vod_tag': 'action',
            'style': {'type': 'grid', 'ratio': 1}
        })
        items.append({
            'vod_id': json.dumps({'actionId': '文本删行|' + enc_path, 'id': 'text', 'type': 'input',
                                  'title': '删掉某一行', 'tip': '输入行号，例：5', 'value': ''},
                                 ensure_ascii=False),
            'vod_name': '🗑️ 删掉第几行', 'vod_pic': self._filop_icon('delete', '#F44336', 'D'),
            'vod_remarks': '输入行号，整行删掉', 'vod_tag': 'action',
            'style': {'type': 'grid', 'ratio': 1}
        })
        items.append({
            'vod_id': json.dumps({'actionId': '文本替换|' + enc_path, 'id': 'text', 'type': 'input',
                                  'title': '查找替换', 'tip': '格式：旧内容|新内容，全文替换', 'value': ''},
                                 ensure_ascii=False),
            'vod_name': '🔍 查找替换', 'vod_pic': self._filop_icon('approve', '#9C27B0', 'S'),
            'vod_remarks': '输入「旧内容|新内容」，全文全换', 'vod_tag': 'action',
            'style': {'type': 'grid', 'ratio': 1}
        })

        if nl > 30:
            _seg = (nl + 29) // 30
            for _i in range(1, _seg):
                items.append(self._edit_chunk_item(path, text, _i * 30))
            items.append({
                'vod_id': json.dumps({'actionId': '文本查找|' + enc_path, 'id': 'text', 'type': 'input',
                                      'title': '🔍 找内容在第几行', 'tip': '输入要找的一段字，例：url', 'value': ''},
                                     ensure_ascii=False),
                'vod_name': '🔍 找内容在第几行',
                'vod_pic': self._filop_icon('approve', '#3F51B5', '?'),
                'vod_remarks': '共 %d 行，分 %d 段；搜到行号再跳过去改' % (nl, _seg),
                'vod_tag': 'action',
                'style': {'type': 'grid', 'ratio': 1}
            })
        items.append(self._filop_card('回文件夹', os.path.dirname(path), '#607D8B', '<',
                                      raw_id=True, link='editdir://' + self.b64u_encode(os.path.dirname(path))))
        return {'list': items, 'page': 1, 'pagecount': 1}

    def _edit_chunk_item(self, path, text, off, per=30):
        lines = text.split('\n')
        total = len(lines)
        if off >= total:
            off = max(0, ((total - 1) // per) * per)
        chunk = lines[off:off + per]
        fields = []
        for i, ln in enumerate(chunk):
            fields.append({'id': 'l%d' % i, 'name': '%d' % (off + i + 1), 'tip': '', 'value': ln})
        fields.append({'id': '__extra__', 'name': '追加一行', 'tip': '要加内容写这里，留空不加', 'value': ''})
        return {
            'vod_id': json.dumps({
                'actionId': '文本行改|%s|%d' % (self.b64u_encode(path), off),
                'type': 'multiInput',
                'title': '%s 第 %d-%d 行' % (os.path.basename(path)[:18], off + 1, min(off + per, total)),
                'msg': '共 %d 行，这一段每行一个框，改完点确定就存' % total,
                'input': fields,
            }, ensure_ascii=False),
            'vod_name': '✏️ 内容弹窗（第 %d-%d 行）' % (off + 1, min(off + per, total)),
            'vod_pic': self._filop_icon('rename', '#2196F3', 'E'),
            'vod_remarks': '这一段 %d 行全在弹窗里，能看能改' % len(chunk),
            'vod_tag': 'action',
            'style': {'type': 'grid', 'ratio': 1}
        }

    def _edit_by_keyword(self, path, kw):
        try:
            text, enc = self._edit_read(path)
        except Exception as e:
            return {'list': [self._filop_card('打不开', str(e), '#F44336', 'x')], 'page': 1, 'pagecount': 1}
        lines = text.split('\n')
        hits = [(i + 1, ln) for i, ln in enumerate(lines) if kw in ln][:80]
        items = [self._filop_card('🔍 「%s」找到 %d 行' % (kw[:24], len(hits)),
                                  '点哪一行就跳到那一段的弹窗',
                                  '#3F51B5', '?', raw_id=True, link='edit://' + self.b64u_encode(path))]
        for no, ln in hits:
            items.append(self._filop_card('%d  %s' % (no, ln[:80] or ' '), '点开第 %d 行那一段' % no,
                                          '#607D8B', '.', raw_id=True,
                                          link='editat://%s|%d' % (self.b64u_encode(path), no - 1)))
        if not hits:
            items.append(self._filop_card('没找到', '换个关键词试试', '#FF9800', '0'))
        return {'list': items, 'page': 1, 'pagecount': 1}

    def _edit_apply(self, path, kind, arg):
        text, enc = self._edit_read(path)
        if kind == 'set':
            new = arg.replace('\\n', '\n')
        elif kind == 'append':
            if not arg:
                raise ValueError('什么都没输入')
            new = text + ('' if (not text or text.endswith('\n')) else '\n') + arg
        elif kind == 'replace_line':
            if '|' not in arg:
                raise ValueError('要写成 行号|新内容')
            no_s, val = arg.split('|', 1)
            no = int(no_s.strip())
            lines = text.split('\n')
            if no < 1 or no > len(lines):
                raise ValueError('行号超范围，共 %d 行' % len(lines))
            lines[no - 1] = val
            new = '\n'.join(lines)
        elif kind == 'del_line':
            no = int(str(arg).strip())
            lines = text.split('\n')
            if no < 1 or no > len(lines):
                raise ValueError('行号超范围，共 %d 行' % len(lines))
            lines.pop(no - 1)
            new = '\n'.join(lines)
        elif kind == 'swap':
            if '|' not in arg:
                raise ValueError('要写成 旧内容|新内容')
            old, new_s = arg.split('|', 1)
            if not old:
                raise ValueError('旧内容不能为空')
            if old not in text:
                raise ValueError('文件里没找到「%s」' % old[:20])
            new = text.replace(old, new_s)
        else:
            raise ValueError('不认识的操作')
        self._edit_write(path, new, enc)
        return len(new.split('\n'))

    def _filop_card(self, text, remark, color='#FF9800', glyph='!', link='', icon_key='', raw_id=False):
        """提示卡：点了也有动作（不会掉进播放器）。raw_id=True 时 link 原样当地址，不再套 fsop://"""
        vid = (str(link or '') if raw_id else self._filop_nav_id(link or ''))
        return {
            'vod_id': vid,
            'vod_name': text,
            'vod_pic': self._filop_icon(icon_key, color, glyph) if icon_key else self._generate_colored_icon(color, glyph),
            'vod_remarks': remark,
            'vod_tag': 'folder',
            'style': {'type': 'list'},
            'vod_player': '书'
        }

    def _filop_nav_id(self, path):
        return self.FILOP_PREFIX + self.b64u_encode(path)

    def _filop_is_nav(self, tid):
        return isinstance(tid, str) and tid.startswith(getattr(self, 'FILOP_PREFIX', 'fsop://'))

    def _filop_nav_path(self, tid):
        try:
            return self.b64u_decode(tid[len(self.FILOP_PREFIX):])
        except Exception:
            return ''

    def _filop_go_item(self, path, name, remarks, pic=None):
        """点一下跳到这个路径：动作卡，不走播放器"""
        return {
            'vod_id': self._filop_nav_id(path),
            'vod_name': name,
            'vod_pic': pic or (self.file_icons.get('folder') if os.path.isdir(path) else self.file_icons.get('file')),
            'vod_remarks': remarks,
            'vod_tag': 'folder',
            'style': {'type': 'grid', 'ratio': 1}
        }

    def _filop_toggle_id(self, dir_path, target):
        """点一下直接切换选中状态，不弹框；末尾带序号，保证每次点都是新的页"""
        try:
            self._filop_click_n = int(getattr(self, '_filop_click_n', 0)) + 1
        except Exception:
            self._filop_click_n = 1
        return (self.FILOP_PREFIX + self.b64u_encode(dir_path) + '|t:'
                + self.b64u_encode(target) + '|' + str(self._filop_click_n))

    def _zip_toggle_id(self, archive, inner, member):
        try:
            self._zip_click_n = int(getattr(self, '_zip_click_n', 0)) + 1
        except Exception:
            self._zip_click_n = 1
        return (self.ZIP_PREFIX + self.b64u_encode(archive) + '|' + self.b64u_encode(inner or '')
                + '|t:' + self.b64u_encode(member) + '|' + str(self._zip_click_n))

    def _filop_page(self, raw):
        """raw = <b64 路径>[|动作]：目录就列文件（带选中/复制/粘贴），文件就给四个操作"""
        raw = str(raw)
        enc, _sep, verb = raw.partition('|')
        try:
            path = self.b64u_decode(enc)
        except Exception:
            path = ''
        if not path or not os.path.exists(path):
            return {'list': [self._filop_card('❌ 找不到这个路径', path or '(空)', '#F44336', 'x')],
                    'page': 1, 'pagecount': 1}
        if os.path.isdir(path):
            if verb:
                try:
                    self._filop_do_verb(verb, path)
                except Exception as _ve:
                    self._filop_msg = '⚠️ 操作失败：%s' % _ve
                if verb in ('c', 'x') and (self.copy_buffer or {}).get('paths'):
                    return self._fsdest_page('fsdest://' + self.b64u_encode(path))
            return self._filop_list_page(path)
        return self._filop_selected_page(path)

    def _filop_sel_set(self):
        if not isinstance(getattr(self, '_filop_sel', None), set):
            self._filop_sel = set()
        return self._filop_sel

    def _filop_unique(self, dest_dir, name):
        target = os.path.join(dest_dir, name)
        base_name, ext = os.path.splitext(name)
        count = 1
        while os.path.exists(target):
            target = os.path.join(dest_dir, '%s (%d)%s' % (base_name, count, ext))
            count += 1
            if count > 500:
                break
        return target

    def _filop_do_verb(self, verb, dir_path):
        """不带弹框的即时动作：选中 / 全选 / 清空 / 复制 / 剪切 / 粘贴"""
        verb = str(verb or '')
        if '|' in verb:
            verb = verb.split('|')[0]
        sel = self._filop_sel_set()
        if verb.startswith('t:'):
            target = self.b64u_decode(verb[2:])
            if not target or not os.path.exists(target):
                self._filop_msg = '⚠️ 这个文件已经不在了'
            elif target in sel:
                sel.discard(target)
                self._filop_msg = '⬜ 取消 %s（已选 %d 个）' % (os.path.basename(target), len(sel))
            else:
                sel.add(target)
                self._filop_msg = '☑️ 选中 %s（已选 %d 个）' % (os.path.basename(target), len(sel))
            return
        if verb == 'all':
            sel.clear()
            try:
                sel.update([os.path.join(dir_path, n) for n in sorted(os.listdir(dir_path))
                            if os.path.isfile(os.path.join(dir_path, n))][:200])
            except Exception:
                pass
            self._filop_msg = '☑️ 全选 %d 个' % len(sel)
            return
        if verb == 'none':
            sel.clear()
            self._filop_msg = '⬜ 已清空选择'
            return
        if verb in ('c', 'x'):
            paths = [p for p in sorted(sel) if os.path.exists(p)]
            if not paths:
                self._filop_msg = '⚠️ 还没选文件，先点下面的文件名'
                return
            self.copy_buffer = {'type': 'move' if verb == 'x' else 'copy', 'paths': paths}
            sel.clear()
            self._filop_msg = (('✂️ 已剪切 %d 个' if verb == 'x' else '📋 已复制 %d 个') % len(paths)
                               + '，去目标文件夹点「📌 粘贴到这里」')
            return
        if verb == 'v':
            buf = self.copy_buffer or {}
            paths = [p for p in (buf.get('paths') or []) if os.path.exists(p)]
            if not paths:
                self._filop_msg = '⚠️ 剪贴板是空的，先选文件点复制或剪切'
                return
            ok = 0
            fail = 0
            for src in paths:
                try:
                    if os.path.normpath(os.path.dirname(src)) == os.path.normpath(dir_path):
                        continue
                    target = self._filop_unique(dir_path, os.path.basename(src))
                    if buf.get('type') == 'move':
                        shutil.move(src, target)
                    elif os.path.isdir(src):
                        shutil.copytree(src, target)
                    else:
                        shutil.copy2(src, target)
                    ok += 1
                except Exception:
                    fail += 1
            if buf.get('type') == 'move':
                self.copy_buffer = None
                sel.clear()
            self._filop_msg = '📌 粘贴完成：成功 %d 个%s' % (ok, ('，失败 %d 个' % fail) if fail else '')
            return

    def _filop_jump(self, dest, msg=''):
        try:
            self.dir_cache.pop('dir_%s' % dest, None)
            self.dir_cache_time.pop('dir_%s' % dest, None)
        except Exception:
            pass
        try:
            res = self.categoryContent(self.FOLDER_PREFIX + self.b64u_encode(dest), 1, None, None)
            if isinstance(res, dict):
                if msg:
                    res['toast'] = msg
                return res
        except Exception:
            pass
        return self._filop_list_page(dest)

    def _fsenter_page(self, tid):
        cur = self.b64u_decode(re.sub(r'^fsenter://', '', str(tid)).split('|')[0])
        if not cur or not os.path.isdir(cur):
            return {'list': [self._filop_card('❌ 找不到这个文件夹', cur or '(空)', '#F44336', 'x')], 'page': 1, 'pagecount': 1}
        up = os.path.dirname(cur.rstrip('/')) or '/'
        items = []
        if up and up != cur:
            items.append(self._filop_go_item(up, '⬅️ 上一层', up))
        try:
            names = sorted([n for n in os.listdir(cur) if os.path.isdir(os.path.join(cur, n))], key=lambda x: x.lower())
        except Exception as e:
            names = []
            items.append(self._filop_card('❌ 打不开', str(e), '#F44336', 'x'))
        for n in names[:200]:
            items.append(self._filop_go_item(os.path.join(cur, n), '📁 ' + n, '点进去'))
        if not names:
            items.append(self._filop_card('📭 这里没有子文件夹', cur, '#FF9800', '0'))
        return {'list': items, 'page': 1, 'pagecount': 1}

    def _filop_dirs(self):
        if not isinstance(getattr(self, '_filop_sel_dirs', None), set):
            self._filop_sel_dirs = set()
        return self._filop_sel_dirs

    def _fssel_page(self, tid):
        raw = str(tid)
        rest = re.sub(r'^fssel://', '', raw)
        enc, _sep, verb = rest.partition('|')
        try:
            cur = self.b64u_decode(enc)
        except Exception:
            cur = ''
        if not cur or not os.path.isdir(cur):
            return {'list': [self._filop_card('❌ 找不到这个文件夹', cur or '(空)', '#F44336', 'x')], 'page': 1, 'pagecount': 1}
        dirs_sel = self._filop_dirs()
        if verb in ('copy', 'move'):
            paths = [p for p in sorted(dirs_sel) if os.path.isdir(p)]
            if not paths:
                self._filop_msg = '⚠️ 还没勾文件夹'
                return self._fssel_page('fssel://' + self.b64u_encode(cur))
            self.copy_buffer = {'type': verb, 'paths': paths}
            dirs_sel.clear()
            self._filop_msg = (('✂️ 已剪切 %d 个文件夹' if verb == 'move' else '📋 已复制 %d 个文件夹') % len(paths))
            return self._fsdest_page('fsdest://' + self.b64u_encode(cur))
        if verb == 'all':
            try:
                dirs_sel.update([os.path.join(cur, n) for n in sorted(os.listdir(cur))
                                 if os.path.isdir(os.path.join(cur, n))][:200])
            except Exception:
                pass
            self._filop_msg = '☑️ 已勾 %d 个文件夹' % len(dirs_sel)
            return self._fssel_page('fssel://' + self.b64u_encode(cur))
        if verb == 'none':
            dirs_sel.clear()
            self._filop_msg = '⬜ 已清空勾选'
            return self._fssel_page('fssel://' + self.b64u_encode(cur))
        try:
            names = sorted([n for n in os.listdir(cur) if os.path.isdir(os.path.join(cur, n))], key=lambda x: x.lower())
        except Exception as e:
            names = []
            self._filop_msg = '⚠️ 打不开：%s' % e
        buf = self.copy_buffer or {}
        buf_n = len([p for p in (buf.get('paths') or []) if os.path.exists(p)])
        sel_here = [p for p in sorted(dirs_sel) if p.startswith(cur.rstrip('/') + '/') or p == cur]
        items = [self._filop_card('✅ 已勾 %d 个文件夹 · 剪贴板 %d 个' % (len(sel_here), buf_n),
                                  str(getattr(self, '_filop_msg', '') or cur), '#2196F3', 'v',
                                  link=cur, icon_key='status')]
        items.append({
            'vod_id': 'fssel://' + self.b64u_encode(cur) + '|copy',
            'vod_name': '📋 复制勾选的',
            'vod_pic': self._filop_icon('copy', '#2196F3', 'C'),
            'vod_remarks': '%d 个文件夹 → 下一步选放哪' % len(sel_here),
            'vod_tag': 'folder',
            'style': {'type': 'grid', 'ratio': 1}
        })
        items.append({
            'vod_id': 'fssel://' + self.b64u_encode(cur) + '|move',
            'vod_name': '✂️ 剪切勾选的',
            'vod_pic': self._filop_icon('cut', '#9C27B0', 'M'),
            'vod_remarks': '%d 个文件夹 → 下一步选放哪' % len(sel_here),
            'vod_tag': 'folder',
            'style': {'type': 'grid', 'ratio': 1}
        })
        items.append({
            'vod_id': 'fssel://' + self.b64u_encode(cur) + '|all',
            'vod_name': '☑️ 全选文件夹',
            'vod_pic': self._filop_icon('all', '#607D8B', 'A'),
            'vod_remarks': '这一层 %d 个文件夹全勾上' % len(names),
            'vod_tag': 'folder',
            'style': {'type': 'grid', 'ratio': 1}
        })
        items.append({
            'vod_id': 'fssel://' + self.b64u_encode(cur) + '|none',
            'vod_name': '⬜ 清空勾选',
            'vod_pic': self._filop_icon('none', '#795548', 'O'),
            'vod_remarks': '把勾上的文件夹都取消',
            'vod_tag': 'folder',
            'style': {'type': 'grid', 'ratio': 1}
        })
        if buf_n:
            items.append({
                'vod_id': 'fsdest://' + self.b64u_encode(cur),
                'vod_name': '📌 去选目标文件夹粘贴',
                'vod_pic': self._filop_icon('paste', '#4CAF50', 'V'),
                'vod_remarks': '剪贴板已有 %d 个，直接去选位置' % buf_n,
                'vod_tag': 'folder',
                'style': {'type': 'grid', 'ratio': 1}
            })
        items.append(self._filop_go_item(cur, '⬅️ 回文件操作页', '当前文件夹'))
        for n in names[:200]:
            full = os.path.join(cur, n)
            picked = full in dirs_sel
            items.append({
                'vod_id': json.dumps({
                    'actionId': '文件操作选文件夹|' + self.b64u_encode(cur) + '|' + self.b64u_encode(full),
                    'id': 'text',
                    'type': 'input',
                    'title': ('⬜ 取消文件夹：' if picked else '☑️ 勾上文件夹：') + n[:22],
                    'tip': '点「确定」就' + ('取消勾选' if picked else '勾上这个文件夹') + '；点「取消」不动',
                    'value': '确定',
                }, ensure_ascii=False),
                'vod_name': ('☑️ 📁 ' if picked else '⬜ 📁 ') + n,
                'vod_pic': self.file_icons.get('folder'),
                'vod_remarks': '已勾上' if picked else '点一下勾上（整个文件夹一起复制）',
                'vod_tag': 'action',
                'style': {'type': 'grid', 'ratio': 1}
            })
        if not names:
            items.append(self._filop_card('📭 这一层没有文件夹', cur, '#FF9800', '0'))
        return {'list': items, 'page': 1, 'pagecount': 1}

    def _fsdest_page(self, tid):
        rest = re.sub(r'^fsdest://', '', str(tid)).split('|')[0]
        cur = self.b64u_decode(rest) if rest else ''
        if not cur or not os.path.isdir(cur):
            cur = self.root_paths[0] if self.root_paths else '/storage/emulated/0'
        buf = self.copy_buffer or {}
        n = len([p for p in (buf.get('paths') or []) if os.path.exists(p)])
        act = '剪切' if buf.get('type') == 'move' else '复制'
        items = [{
            'vod_id': 'fsdo://' + self.b64u_encode(cur),
            'vod_name': '📌 粘贴到这个文件夹',
            'vod_pic': self._filop_icon('paste', '#4CAF50', 'V'),
            'vod_remarks': '把%s的 %d 个粘到 %s' % (act, n, cur),
            'vod_tag': 'folder',
            'style': {'type': 'grid', 'ratio': 1}
        }]
        up = os.path.dirname(cur.rstrip('/')) or '/'
        if up and up != cur:
            items.append({
                'vod_id': 'fsdest://' + self.b64u_encode(up),
                'vod_name': '⬅️ 上一层文件夹',
                'vod_pic': self.file_icons.get('folder'),
                'vod_remarks': up,
                'vod_tag': 'folder',
                'style': {'type': 'grid', 'ratio': 1}
            })
        for q, qn in (('/storage/emulated/0', '手机存储'), ('/storage/emulated/0/Download', 'Download'),
                      ('/storage/emulated/0/Music', 'Music'), ('/storage/emulated/0/Movies', 'Movies')):
            if not os.path.isdir(q) or q == cur:
                continue
            items.append({
                'vod_id': 'fsdest://' + self.b64u_encode(q),
                'vod_name': '📌 ' + qn,
                'vod_pic': self.file_icons.get('folder'),
                'vod_remarks': q,
                'vod_tag': 'folder',
                'style': {'type': 'grid', 'ratio': 1}
            })
        try:
            names = sorted([x for x in os.listdir(cur) if os.path.isdir(os.path.join(cur, x))], key=lambda x: x.lower())
        except Exception as e:
            names = []
            items.append(self._filop_card('❌ 这个文件夹打不开', str(e), '#F44336', 'x'))
        for x in names[:200]:
            items.append({
                'vod_id': 'fsdest://' + self.b64u_encode(os.path.join(cur, x)),
                'vod_name': '📁 ' + x,
                'vod_pic': self.file_icons.get('folder'),
                'vod_remarks': '点进去',
                'vod_tag': 'folder',
                'style': {'type': 'grid', 'ratio': 1}
            })
        if not names:
            items.append(self._filop_card('📭 这里没有子文件夹', cur, '#FF9800', '0'))
        items.append(self._filop_card('⬅️ 回文件操作页', cur, '#607D8B', '<', link=cur))
        return {'list': items, 'page': 1, 'pagecount': 1}

    def _fsdo_paste(self, tid):
        cur = self.b64u_decode(re.sub(r'^fsdo://', '', str(tid)))
        if not os.path.isdir(cur):
            return {'toast': '这个文件夹打不开：%s' % cur,
                    'list': [self._filop_card('❌ 这个文件夹打不开', cur, '#F44336', 'x')], 'page': 1, 'pagecount': 1}
        try:
            self._filop_do_verb('v', cur)
        except Exception as e:
            return {'toast': '粘贴失败：%s' % e,
                    'list': [self._filop_card('❌ 粘贴失败', str(e), '#F44336', 'x')], 'page': 1, 'pagecount': 1}
        return self._filop_jump(cur, str(getattr(self, '_filop_msg', '') or ''))

    def _filop_file_pic(self, full, name, idx=0):
        """文件操作页里也用普通列表那一套图标：音乐封面、视频封面、漫画封面、各扩展名小图标"""
        try:
            if idx >= 150:
                _ext0 = name.rsplit('.', 1)[1].lower() if '.' in name else ''
                return self.file_icons.get(_ext0) or self.file_icons.get('file')
        except Exception:
            pass
        try:
            _ext = name.rsplit('.', 1)[1].lower() if '.' in name else ''
            _base = self._create_file_item_with_flags({'name': name, 'path': full, 'ext': _ext, 'is_dir': False})
            if _base and _base.get('vod_pic'):
                return _base['vod_pic']
        except Exception:
            pass
        try:
            _ext = name.rsplit('.', 1)[1].lower() if '.' in name else ''
            return self.file_icons.get(_ext) or self.file_icons.get('file')
        except Exception:
            return ''

    # ==================== 压缩包：点开看里面 / 解压 ====================
    ZIP_EXTS = ('zip', 'rar', '7z', 'tar', 'tgz', 'gz', 'bz2', 'xz')

    def _is_archive_name(self, name):
        n = str(name or '').lower()
        for tail in ('.tar.gz', '.tar.bz2', '.tar.xz', '.tar'):
            if n.endswith(tail):
                return True
        return (n.rsplit('.', 1)[-1] if '.' in n else '') in self.ZIP_EXTS

    def _zip_size(self, n):
        try:
            n = float(n)
        except Exception:
            return ''
        for u in ('B', 'KB', 'MB', 'GB'):
            if n < 1024 or u == 'GB':
                return ('%d%s' % (n, u)) if u == 'B' else ('%.1f%s' % (n, u))
            n = n / 1024.0
        return ''

    def _zip_ext_pic(self, fname):
        try:
            ext = str(fname).rsplit('.', 1)[-1].lower() if '.' in str(fname) else ''
            if self.is_media_file(ext):
                return self.file_icons.get('video')
            return self.file_icons.get(ext) or self.file_icons.get('file')
        except Exception:
            return ''

    def _zip_nav_id(self, archive, inner=''):
        vid = self.ZIP_PREFIX + self.b64u_encode(archive)
        if inner:
            vid += '|' + self.b64u_encode(inner)
        return vid

    def _zip_parse_nav(self, tid):
        rest = tid[len(self.ZIP_PREFIX):] if isinstance(tid, str) and tid.startswith(self.ZIP_PREFIX) else tid
        parts = str(rest).split('|')
        verb = ''
        if parts and parts[-1] in ('all', 'none'):
            verb = parts[-1]
            parts = parts[:-1]
        elif len(parts) >= 3 and str(parts[2]).startswith('t:'):
            verb = '|'.join(parts[2:])
            parts = parts[:2]
        archive = self.b64u_decode(parts[0]) if parts and parts[0] else ''
        inner = self.b64u_decode(parts[1]) if len(parts) > 1 and parts[1] else ''
        return archive, inner, verb

    def _zip_sel_set(self, archive):
        """包内勾选集合：按包分开存，路径写法不同（带不带结尾斜杠、相对绝对）也认得是同一个包"""
        try:
            key = os.path.abspath(os.path.normpath(str(archive)))
        except Exception:
            key = str(archive)
        _m = getattr(self, '_zip_sel_map', None)
        if not isinstance(_m, dict):
            _m = {}
            self._zip_sel_map = _m
        if getattr(self, '_zip_sel_arc', None) != key:
            self._zip_sel_arc = key
            self._zip_sel = _m.setdefault(key, set())
        if not isinstance(getattr(self, '_zip_sel', None), set):
            self._zip_sel = _m.setdefault(key, set())
        return self._zip_sel

    def _zip_fix_name(self, info):
        try:
            n = info.filename
            if not (getattr(info, 'flag_bits', 0) & 0x800):
                try:
                    n = n.encode('cp437').decode('gbk')
                except Exception:
                    try:
                        n = n.encode('cp437').decode('utf-8')
                    except Exception:
                        pass
            return str(n).replace(chr(92), '/')
        except Exception:
            return str(getattr(info, 'filename', '') or '')

    def _zip_ctx_file(self):
        return '/storage/emulated/0/tmp/zip_open_ctx.json'

    def _zip_ctx_load(self):
        cache = getattr(self, '_zip_ctx', None)
        if isinstance(cache, dict):
            return cache
        cache = {}
        try:
            p = self._zip_ctx_file()
            if os.path.isfile(p):
                with open(p, 'r', encoding='utf-8') as f:
                    d = json.load(f)
                if isinstance(d, dict):
                    for k, v in d.items():
                        if isinstance(v, dict):
                            cache[str(k)] = v
        except Exception:
            pass
        self._zip_ctx = cache
        return cache

    def _zip_ctx_save(self):
        try:
            os.makedirs('/storage/emulated/0/tmp', exist_ok=True)
            with open(self._zip_ctx_file(), 'w', encoding='utf-8') as f:
                json.dump(self._zip_ctx_load(), f, ensure_ascii=False)
        except Exception:
            pass

    def _zip_ctx_set(self, path, archive, inner, member, cdir):
        d = self._zip_ctx_load()
        if not path:
            return
        d[str(path)] = {'a': str(archive or ''), 'i': str(inner or ''), 'm': str(member or ''),
                        'd': str(cdir or ''), 't': time.time()}
        if len(d) > 200:
            for k in sorted(d.keys(), key=lambda x: d[x].get('t') or 0)[:len(d) - 200]:
                d.pop(k, None)
        self._zip_ctx_save()

    def _zip_ctx_get(self, path):
        try:
            v = self._zip_ctx_load().get(str(path or ''))
            return v if isinstance(v, dict) and v.get('a') else None
        except Exception:
            return None

    def _zip_cache_clear(self, archive):
        """删掉这个压缩包解出来的缓存（退出压缩包时调用）"""
        n = 0
        d = self._zip_ctx_load()
        for k in list(d.keys()):
            v = d.get(k) or {}
            if str(v.get('a') or '') != str(archive or ''):
                continue
            cdir = str(v.get('d') or '')
            try:
                if cdir and os.path.isdir(cdir):
                    shutil.rmtree(cdir, ignore_errors=True)
                    n += 1
                elif k and os.path.isfile(k):
                    os.remove(k)
            except Exception:
                pass
            d.pop(k, None)
        self._zip_ctx_save()
        try:
            for base in ('/storage/emulated/0/tmp/zipcache', '/tmp/zipcache'):
                if not os.path.isdir(base):
                    continue
                for nm in os.listdir(base):
                    p = os.path.join(base, nm)
                    if not os.path.isdir(p):
                        continue
                    if len(os.listdir(p)) == 0:
                        try:
                            os.rmdir(p)
                        except Exception:
                            pass
        except Exception:
            pass
        return n

    def _zip_exit_page(self, id_val):
        """退出压缩包：先清缓存，再回文件列表"""
        rest = str(id_val)[len('zipexit://'):]
        try:
            a, b = rest.split('|', 1)
            arc, back = self.b64u_decode(a), self.b64u_decode(b)
        except Exception:
            arc, back = '', ''
        _parent = self._zip_ctx_get(arc)
        if arc:
            try:
                self._zip_cache_clear(arc)
            except Exception:
                pass
        if _parent:
            # 这个包本身是从别的包里解出来的：退回外层压缩包原来那一层
            return self.categoryContent(self.ZIP_PREFIX + self.b64u_encode(_parent.get('a'))
                                        + '|' + self.b64u_encode(_parent.get('i') or ''), 1, None, None)
        if not back:
            back = os.path.dirname(arc) or '/'
        return self.categoryContent(self.FOLDER_PREFIX + self.b64u_encode(back), 1, None, None)

    def _zip_open_mode(self, archive):
        """点文件是「直接打开」还是「勾选」：每 1 打开，每 0 勾选；记在 tmp/zip_open_mode.json"""
        cache = getattr(self, '_zip_mode_cache', None)
        if not isinstance(cache, dict):
            cache = {}
            try:
                p = '/storage/emulated/0/tmp/zip_open_mode.json'
                if os.path.isfile(p):
                    with open(p, 'r', encoding='utf-8') as f:
                        d = json.load(f)
                    if isinstance(d, dict):
                        for k, v in d.items():
                            try:
                                cache[str(k)] = 1 if int(v) else 0
                            except Exception:
                                pass
            except Exception:
                pass
            self._zip_mode_cache = cache
        v = cache.get(str(archive))
        return 1 if v is None else int(v)

    def _zip_open_mode_set(self, archive, val):
        cache = getattr(self, '_zip_mode_cache', None)
        if not isinstance(cache, dict):
            cache = {}
            self._zip_mode_cache = cache
        cache[str(archive)] = 1 if val else 0
        try:
            os.makedirs('/storage/emulated/0/tmp', exist_ok=True)
            with open('/storage/emulated/0/tmp/zip_open_mode.json', 'w', encoding='utf-8') as f:
                json.dump(cache, f, ensure_ascii=False)
        except Exception:
            pass

    def _zip_member_split(self, id_val, prefix):
        try:
            rest = str(id_val)[len(prefix):]
            a, b = rest.split('|', 1)
            return self.b64u_decode(a), self.b64u_decode(b)
        except Exception:
            return '', ''

    def _zip_member_path(self, archive, member, inner=''):
        """把包里的单个文件解到 tmp/zipcache，返回本地路径；已经解过的直接用"""
        try:
            key = hashlib.md5((str(archive) + '|' + str(member)).encode('utf-8', 'surrogateescape')).hexdigest()[:12]
        except Exception:
            return '', '算缓存名失败'
        name = os.path.basename(str(member).rstrip('/')) or 'file'
        for base in ('/storage/emulated/0/tmp/zipcache', '/tmp/zipcache'):
            d = os.path.join(base, key)
            try:
                os.makedirs(d, exist_ok=True)
            except Exception:
                continue
            hit = os.path.join(d, name)
            try:
                if os.path.isfile(hit) and os.path.getsize(hit) > 0:
                    try:
                        self._zip_ctx_set(hit, archive, inner, member, d)
                    except Exception:
                        pass
                    return hit, ''
            except Exception:
                pass
            try:
                self._zip_extract(archive, member, d, members=[member])
            except Exception as e:
                return '', '解压失败：%s' % e
            try:
                for cur, _dirs, files in os.walk(d):
                    for fn in files:
                        if fn == name:
                            p = os.path.join(cur, fn)
                            if os.path.getsize(p) > 0:
                                try:
                                    self._zip_ctx_set(p, archive, inner, member, d)
                                except Exception:
                                    pass
                                return p, ''
            except Exception:
                pass
            return '', (getattr(self, '_zip_skip_note', '') or '没解出来：这个条目可能是压缩存的 rar，或者是加密包')
        return '', '没有可写目录'

    def _zip_member_split3(self, id_val, prefix):
        """zipopen://a|b|c → (archive, member, inner)，老的两段式也认"""
        try:
            rest = str(id_val)[len(prefix):]
            parts = rest.split('|')
            arc = self.b64u_decode(parts[0]) if len(parts) > 0 else ''
            mem = self.b64u_decode(parts[1]) if len(parts) > 1 else ''
            inner = self.b64u_decode(parts[2]) if len(parts) > 2 else ''
            return arc, mem, inner
        except Exception:
            return '', '', ''

    def _zip_open_page(self, id_val):
        """打开包里的 db/json/txt/m3u：先解到缓存，再按普通文件打开"""
        arc, mem, inner = self._zip_member_split3(id_val, 'zipopen://')
        if not arc or not mem:
            return {'list': [self._filop_card('❌ 参数不对', '', '#F44336', 'x')]}
        path, err = self._zip_member_path(arc, mem, inner)
        if not path:
            return {'list': [self._filop_card('❌ 打不开包里这个文件', err or '', '#F44336', 'x')]}
        ext = str(self.get_file_ext(path) or '').lower()
        try:
            if ext in ('zip', 'rar', '7z', 'tar', 'gz', 'tgz', 'bz2', 'xz'):
                # 包里的压缩包：解出来继续当压缩包点进去
                return self.categoryContent(self.ZIP_PREFIX + self.b64u_encode(path) + '|' + self.b64u_encode(''), 1, None, None)
            if ext == 'json' or self.is_db_file(ext):
                return self.categoryContent(self.DB_DIR_PREFIX + self.b64u_encode(path), 1, None, None)
            if ext in ('xlsx', 'xls') or self.is_magnet_file(ext):
                return self.categoryContent(self.MAGNET_PREFIX + self.b64u_encode(path), 1, None, None)
            if ext in ('txt', 'm3u', 'm3u8') or self.is_list_file(ext):
                return self.categoryContent(self.LIST_PREFIX + self.b64u_encode(path), 1, None, None)
            # 其余类型（py/php/图片/漫画/文档…）跟外面一样走详情
            return self._handle_file_detail(path)
        except Exception as e:
            return {'list': [self._filop_card('❌ 打开失败', str(e), '#F44336', 'x')]}

    def _zip_member_detail(self, id_val):
        """包里的视频/音频：解到缓存再播"""
        arc, mem, inner = self._zip_member_split3(id_val, 'zipfile://')
        name = os.path.basename(str(mem).rstrip('/')) or '包里的文件'
        path, err = self._zip_member_path(arc, mem, inner)
        if not path:
            return {'list': [self._db_info_item(arc, name, '包里的这个文件没解出来：%s' % (err or '可能是压缩存的 rar，或者是加密包'))]}
        try:
            res = self._handle_file_detail(path)
            if isinstance(res, dict) and (res.get('list') or []):
                return res
        except Exception:
            pass
        try:
            sz = os.path.getsize(path)
        except Exception:
            sz = 0
        return {'list': [{
            'vod_id': id_val,
            'vod_name': name,
            'vod_pic': self._zip_ext_pic(mem),
            'vod_content': '从压缩包里解到缓存后播放，缓存在 /storage/emulated/0/tmp/zipcache，删掉即清。\n本地路径：%s' % path,
            'vod_remarks': self._zip_size(sz),
            'vod_play_from': '包内文件',
            'vod_play_url': '文件$file://%s#直连$%s' % (path, path),
        }]}

    def _zip_mode_page(self, id_val):
        """切换「点文件」行为：打开 / 勾选"""
        rest = str(id_val)[len('zipmode://'):]
        try:
            a, b = rest.split('|', 1)
            arc, inner = self.b64u_decode(a), self.b64u_decode(b)
        except Exception:
            arc, inner = '', ''
        if arc:
            self._zip_open_mode_set(arc, 0 if self._zip_open_mode(arc) else 1)
        if not arc:
            return {'list': [self._filop_card('❌ 参数不对', '', '#F44336', 'x')]}
        return self.categoryContent(self.ZIP_PREFIX + self.b64u_encode(arc) + '|' + self.b64u_encode(inner), 1, None, None)

    def _zip_entries(self, archive):
        """列包内条目，按「路径 + 修改时间 + 大小」缓存，大包二次进不再重扫"""
        _t0 = time.time()
        _key = None
        try:
            _st = os.stat(archive)
            _key = (archive, int(_st.st_mtime), _st.st_size)
        except Exception:
            _key = None
        _c = getattr(self, '_zip_entry_cache', None)
        if not isinstance(_c, dict):
            _c = {}
            self._zip_entry_cache = _c
        if _key and _key in _c:
            return _c[_key]
        out = self._zip_entries_raw(archive)
        try:
            self._zip_log('列目录 %s：%d 条，%.0fms' % (os.path.basename(archive), len(out),
                                                   (time.time() - _t0) * 1000))
        except Exception:
            pass
        if _key:
            try:
                if len(_c) > 6:
                    _c.clear()
                _c[_key] = out
            except Exception:
                pass
        return out

    def _zip_entries_raw(self, archive):
        low = archive.lower()
        out = []
        if low.endswith('.7z'):
            with SevenZipReader(archive) as z7:
                return z7.entries()
        if low.endswith('.rar'):
            with RarReader(archive) as rr:
                if rr.encrypted:
                    raise RarError('这个 rar 有密码（或者是加密文件头），手机这边解不开')
                if rr.volume:
                    raise RarError('这是分卷 rar（xxx.part1.rar 这种），要把所有分卷放同一个文件夹一起解；手机这边还不行')
                return rr.entries()
        if low.endswith('.zip'):
            import zipfile
            with zipfile.ZipFile(archive) as zf:
                for info in zf.infolist():
                    out.append((self._zip_fix_name(info), info.file_size, info.is_dir()))
            return out
        import tarfile
        with tarfile.open(archive, 'r:*') as tf:
            for m in tf.getmembers():
                out.append((str(m.name).replace(chr(92), '/'), m.size, m.isdir()))
        return out

    def _zip_page(self, tid):
        archive, inner, verb = self._zip_parse_nav(tid)
        name = os.path.basename(archive)
        try:
            self._zip_log('请求 %s' % str(tid)[:130])
        except Exception:
            pass
        if not os.path.isfile(archive):
            return {'list': [self._filop_card('❌ 压缩包不在了', archive, '#F44336', 'x')], 'page': 1, 'pagecount': 1}
        try:
            entries = self._zip_entries(archive)
        except Exception as e:
            _hint = ''
            if name.lower().endswith('.7z'):
                _hint = '　（7z 支持 Copy / LZMA / LZMA2，带 x86 BCJ 的也能解；加密包、或用了 BCJ2 / PPMd / Delta 的包解不开）'
            elif name.lower().endswith('.rar'):
                _hint = '　（rar 能看目录；只有「不压缩」存的条目能解出来，压缩存的解不开，加密和分卷的也不行）'
            elif name.lower().endswith(('.xz', '.bz2')):
                _hint = '　这种格式要额外的库，手机壳子里的 Python 一般没装；可以先在电脑上解压，或者换成 zip / 7z 再放进来'
            return {'list': [self._filop_card('❌ 这个压缩包打不开', '%s：%s%s' % (name, e, _hint), '#F44336', 'x'),
                             self._filop_card('⬅️ 返回文件列表', os.path.dirname(archive) or archive,
                                              '#2196F3', '<', link=os.path.dirname(archive) or archive)],
                    'page': 1, 'pagecount': 1}
        base = (inner.rstrip('/') + '/') if inner else ''
        try:
            self._zip_log('进包 %s inner=%r 条目 %d' % (name, inner, len(entries)))
        except Exception:
            pass
        _miss = False
        if base and not any(str(fn).startswith(base) for fn, _s2, _d2 in entries if fn):
            _cand = sorted({str(fn)[:_len_ok] for fn, _s2, _d2 in entries
                            if fn and str(fn).lower().startswith(base.lower())
                            for _len_ok in [len(base)]})
            if len(_cand) == 1:
                base = _cand[0]
                self._zip_log('  层名对不上，按大小写纠正成 %r' % base)
            else:
                _miss = True
        if _miss:
            _rootdirs = sorted({str(fn).split('/')[0] for fn, _s2, _d2 in entries if fn and '/' in str(fn)})
            _items = [self._filop_card('📂 这层没找到：%s' % inner,
                                       '包里名字跟这一层对不上（可能是大小写或斜杠的差别），点下面回包根目录再进',
                                       '#FF9800', '?')]
            _items.append({
                'vod_id': self.ZIP_PREFIX + self.b64u_encode(archive) + '|',
                'vod_name': '⬅️ 回包根目录',
                'vod_pic': self._filop_icon('folder', '#2196F3', '<'),
                'vod_remarks': '包里有 %d 层文件夹，从这里重新进' % len(_rootdirs),
                'vod_tag': 'folder',
                'style': {'type': 'grid', 'ratio': 1},
            })
            return {'list': _items, 'page': 1, 'pagecount': 1}
        dirs, files = [], []
        for fname, fsize, isdir in entries:
            if not fname or not fname.startswith(base):
                continue
            rest = fname[len(base):].lstrip('/')
            if not rest:
                continue
            if '/' in rest or isdir:
                top = rest.split('/')[0]
                if top and top not in dirs:
                    dirs.append(top)
            else:
                files.append((rest, fsize))
        dd = os.path.dirname(archive) or '/'
        stem = os.path.splitext(os.path.basename(archive))[0] or '解压结果'
        def_dest = os.path.join(dd, stem)
        _sel = self._zip_sel_set(archive)
        _toast = ''
        if isinstance(verb, str) and verb.startswith('t:'):
            try:
                _mem = self.b64u_decode(verb[2:].split('|')[0])
            except Exception:
                _mem = ''
            if _mem:
                if _mem in _sel:
                    _sel.discard(_mem)
                    _toast = '⬜ 取消 %s' % os.path.basename(_mem.rstrip('/'))
                else:
                    _sel.add(_mem)
                    _toast = '☑️ 选中 %s' % os.path.basename(_mem.rstrip('/'))
                _n_in = len([m for m in _sel if m.startswith(base) and not m.endswith('/')])
                _toast += '（这层共选中 %d 个）' % _n_in
        if verb in ('all', 'none'):
            if verb == 'none':
                _sel.clear()
            else:
                for f, _sz in files:
                    _sel.add(base + f)
                for _d in dirs:
                    _sel.add(base + _d + '/')
                # 全选本层不要求先切模式：点它就全勾上，并顺手切到勾选模式让每张卡都显示 ☑️
                try:
                    self._zip_open_mode_set(archive, 0)
                except Exception:
                    pass
        _sel_now = [m for m in _sel if m.startswith(base) and not m.endswith('/')]
        _sel_dirs = [m for m in _sel if m.startswith(base) and m.endswith('/')]
        items = []
        def _zcard(text, remark, vid, color='#2196F3', glyph='>', icon_key='', pic=''):
            return {
                'vod_id': vid,
                'vod_name': text,
                'vod_pic': pic or (self._filop_icon(icon_key, color, glyph) if icon_key else self._generate_colored_icon(color, glyph)),
                'vod_remarks': remark,
                'vod_tag': 'folder',
                'style': {'type': 'grid', 'ratio': 1}
            }
        def _zdest_id(dest, scope):
            return ('zipdest://' + self.b64u_encode(archive) + '|' + self.b64u_encode(inner)
                    + '|' + self.b64u_encode(dest) + '|' + scope)
        if inner:
            up = inner.rstrip('/').rsplit('/', 1)[0] if '/' in inner.rstrip('/') else ''
            items.append(_zcard('⬅️ 返回上一层', os.path.basename(inner.rstrip('/')) or name,
                                self._zip_nav_id(archive, up), '#2196F3', '<',
                                pic=self.file_icons.get('folder', '')))
        else:
            items.append(_zcard('⬅️ 返回文件列表', dd + '（退出会清缓存）',
                                'zipexit://' + self.b64u_encode(archive) + '|' + self.b64u_encode(dd),
                                '#2196F3', '<', pic=self.file_icons.get('folder', '')))
        _open_mode = self._zip_open_mode(archive)
        _sel_tip = '点文件勾上，再点下面「解压选中」'
        if _sel_dirs:
            _sel_tip = '另有 %d 个文件夹被勾上（在「选文件夹」里取消）' % len(_sel_dirs)
        items.append(_zcard('✅ 已选 %d 个文件 · 这层 %d 个文件' % (len(_sel_now), len(files)),
                            _sel_tip,
                            self.ZIP_PREFIX + self.b64u_encode(archive) + '|' + self.b64u_encode(inner),
                            '#2196F3', 'v', 'status'))
        if _toast:
            items.append(_zcard(_toast, '再点一次就取消', self.ZIP_PREFIX + self.b64u_encode(archive)
                                + '|' + self.b64u_encode(inner), '#2196F3', 'v', 'status'))
        items.append(_zcard('🔀 点文件：%s' % ('直接打开' if _open_mode else '勾选'),
                            '点一下切换（勾选模式才是「解压选中」那套）',
                            'zipmode://' + self.b64u_encode(archive) + '|' + self.b64u_encode(inner),
                            '#9C27B0', 'S', 'switch' if _open_mode else 'checkbox'))
        items.append(_zcard('☑️ 选文件夹(%d)' % len(_sel_dirs), '把整个文件夹一起勾上',
                            'zipdir://' + self.b64u_encode(archive) + '|' + self.b64u_encode(inner),
                            '#3F51B5', 'D', 'all'))
        items.append(_zcard('📤 解压选中(%d)' % (len(_sel_now) + len(_sel_dirs)), '选好目标文件夹再解压',
                            _zdest_id(dd, 'sel'), '#4CAF50', 'U', 'zipout'))
        items.append(_zcard('📤 解压这一层全部', '共 %d 个文件夹、%d 个文件' % (len(dirs), len(files)),
                            _zdest_id(dd, 'all'), '#009688', 'U', 'zipout'))
        items.append(_zcard('☑️ 全选本层', '这一层的文件全勾上',
                            self.ZIP_PREFIX + self.b64u_encode(archive) + '|' + self.b64u_encode(inner) + '|all',
                            '#607D8B', 'A', 'all'))
        items.append(_zcard('⬜ 清空选择', '把勾上的都取消',
                            self.ZIP_PREFIX + self.b64u_encode(archive) + '|' + self.b64u_encode(inner) + '|none',
                            '#795548', 'O', 'none'))
        for d in sorted(dirs, key=lambda x: x.lower()):
            items.append({
                'vod_id': self._zip_nav_id(archive, base + d),
                'vod_name': ('☑️ 📁 ' if (base + d + '/') in _sel else '📁 ') + d,
                'vod_pic': self.file_icons.get('folder'),
                'vod_remarks': ('整个文件夹已勾上 · ' if (base + d + '/') in _sel else '文件夹 · 点进去'),
                'vod_tag': 'folder',
                'style': {'type': 'grid', 'ratio': 1}
            })
        _OPEN_EXT = ('.db', '.sqlite', '.sqlite3', '.json', '.txt', '.m3u', '.m3u8', '.xlsx', '.xls',
                     '.zip', '.rar', '.7z', '.tar', '.gz', '.tgz', '.bz2', '.xz',
                     '.magnet', '.ed2k', '.torrent')
        for f, size in sorted(files, key=lambda x: x[0].lower())[:300]:
            _m = base + f
            _picked = _m in _sel
            _low = str(f).lower()
            if _open_mode and _low.endswith(_OPEN_EXT):
                items.append({
                    'vod_id': ('zipopen://' + self.b64u_encode(archive) + '|' + self.b64u_encode(_m)
                               + '|' + self.b64u_encode(inner)),
                    'vod_name': f,
                    'vod_pic': self._zip_ext_pic(f),
                    'vod_remarks': '点开直接看 · ' + self._zip_size(size),
                    'vod_tag': 'folder',
                    'style': {'type': 'grid', 'ratio': 1}
                })
                continue
            if _open_mode:
                items.append({
                    'vod_id': ('zipfile://' + self.b64u_encode(archive) + '|' + self.b64u_encode(_m)
                               + '|' + self.b64u_encode(inner)),
                    'vod_name': f,
                    'vod_pic': self._zip_ext_pic(f),
                    'vod_remarks': '点开就用外面那套打开 · ' + self._zip_size(size),
                    'vod_tag': 'dbentry',
                    'style': {'type': 'grid', 'ratio': 1}
                })
                continue
            items.append({
                'vod_id': (self.ZIP_PREFIX + self.b64u_encode(archive) + '|' + self.b64u_encode(inner)
                           + '|t:' + self.b64u_encode(_m)),
                'vod_name': ('☑️ ' if _picked else '⬜ ') + f,
                'vod_pic': self._zip_ext_pic(f),
                'vod_remarks': ('已选中 · 点一下取消 · ' if _picked else '点一下选中 · ') + self._zip_size(size),
                'vod_tag': 'folder',
                'style': {'type': 'grid', 'ratio': 1}
            })
        if not dirs and not files:
            items.append(self._filop_card('📭 这个位置是空的', inner or name, '#FF9800', '0'))
        return {'list': items, 'page': 1, 'pagecount': 1}

    def _zip_log(self, msg):
        try:
            p = '/storage/emulated/0/tmp/zip_extract.log'
            os.makedirs(os.path.dirname(p), exist_ok=True)
            with open(p, 'a', encoding='utf-8') as f:
                f.write('%s %s\n' % (time.strftime('%m-%d %H:%M:%S'), msg))
        except Exception:
            pass

    def _zipdir_page(self, tid):
        rest = re.sub(r'^zipdir://', '', str(tid))
        p = rest.split('|')
        arc = self.b64u_decode(p[0]) if p and p[0] else ''
        inner = self.b64u_decode(p[1]) if len(p) > 1 and p[1] else ''
        if not os.path.isfile(arc):
            return {'list': [self._filop_card('❌ 压缩包不在了', arc, '#F44336', 'x')], 'page': 1, 'pagecount': 1}
        try:
            entries = self._zip_entries(arc)
        except Exception as e:
            return {'list': [self._filop_card('❌ 这个压缩包打不开', str(e), '#F44336', 'x')], 'page': 1, 'pagecount': 1}
        base = (inner.rstrip('/') + '/') if inner else ''
        dirs = []
        for fname, _sz, isdir in entries:
            if not fname or not fname.startswith(base):
                continue
            rest2 = fname[len(base):].lstrip('/')
            if not rest2:
                continue
            if '/' in rest2 or isdir:
                top = rest2.split('/')[0]
                if top and top not in dirs:
                    dirs.append(top)
        _sel = self._zip_sel_set(arc)
        back = self.ZIP_PREFIX + self.b64u_encode(arc) + '|' + self.b64u_encode(inner)
        items = [{
            'vod_id': back,
            'vod_name': '⬅️ 回压缩包',
            'vod_pic': self._filop_icon('zip', '#607D8B', 'Z'),
            'vod_remarks': os.path.basename(arc),
            'vod_tag': 'folder',
            'style': {'type': 'grid', 'ratio': 1}
        }]
        items.append({
            'vod_id': json.dumps({
                'actionId': '压缩包全选文件夹|' + self.b64u_encode(arc) + '|' + self.b64u_encode(base),
            }, ensure_ascii=False),
            'vod_name': '☑️ 全选本层文件夹',
            'vod_pic': self._filop_icon('all', '#607D8B', 'A'),
            'vod_remarks': '这一层 %d 个文件夹一起勾上' % len(dirs),
            'vod_tag': 'action',
            'style': {'type': 'grid', 'ratio': 1}
        })
        for dn in sorted(dirs, key=lambda x: x.lower()):
            key = base + dn + '/'
            picked = key in _sel
            items.append({
                'vod_id': json.dumps({
                    'actionId': '压缩包选文件夹|' + self.b64u_encode(arc) + '|' + self.b64u_encode(key),
                    'id': 'text',
                    'type': 'input',
                    'title': ('⬜ 移出选择：' if picked else '☑️ 选中文件夹：') + dn[:22],
                    'tip': '点「确定」就' + ('取消勾选' if picked else '把这个文件夹整个勾上') + '；点「取消」不动',
                    'value': '确定',
                }, ensure_ascii=False),
                'vod_name': ('☑️ 📁 ' if picked else '⬜ 📁 ') + dn,
                'vod_pic': self.file_icons.get('folder'),
                'vod_remarks': ('已选中整个文件夹 · ' if picked else '点一下选中整个文件夹 · ') + key,
                'vod_tag': 'action',
                'style': {'type': 'grid', 'ratio': 1}
            })
        if not dirs:
            items.append(self._filop_card('📭 这一层没有文件夹', inner or os.path.basename(arc), '#FF9800', '0'))
        return {'list': items, 'page': 1, 'pagecount': 1}

    def _zipdest_parse(self, tid):
        rest = re.sub(r'^(zipdest|zipdo)://', '', str(tid))
        p = rest.split('|')
        dec = lambda x: self.b64u_decode(x) if x else ''
        arc = dec(p[0]) if len(p) > 0 else ''
        inner = dec(p[1]) if len(p) > 1 else ''
        cur = dec(p[2]) if len(p) > 2 else ''
        scope = p[3] if len(p) > 3 and p[3] else 'sel'
        return arc, inner, cur, scope

    def _zipdest_page(self, tid):
        arc, inner, cur, scope = self._zipdest_parse(tid)
        if not os.path.isdir(cur):
            cur = os.path.dirname(arc) or '/storage/emulated/0'
        _sel = self._zip_sel_set(arc)
        base = (inner.rstrip('/') + '/') if inner else ''
        n_sel = len([m for m in _sel if m.startswith(base)])
        items = []
        do_id = ('zipdo://' + self.b64u_encode(arc) + '|' + self.b64u_encode(inner)
                 + '|' + self.b64u_encode(cur) + '|' + scope)
        items.append({
            'vod_id': do_id,
            'vod_name': '✅ 就解压到这里',
            'vod_pic': self._filop_icon('zipout', '#4CAF50', 'U'),
            'vod_remarks': cur + ('　（解 %d 个选中的）' % n_sel if scope == 'sel' else '　（解这一层全部）'),
            'vod_tag': 'folder',
            'style': {'type': 'grid', 'ratio': 1}
        })
        _cur2 = os.path.dirname(cur.rstrip('/')) or '/'
        if _cur2 != cur:
            items.append({
                'vod_id': ('zipdest://' + self.b64u_encode(arc) + '|' + self.b64u_encode(inner)
                           + '|' + self.b64u_encode(_cur2) + '|' + scope),
                'vod_name': '⬅️ 上一层文件夹',
                'vod_pic': self.file_icons.get('folder'),
                'vod_remarks': _cur2,
                'vod_tag': 'folder',
                'style': {'type': 'grid', 'ratio': 1}
            })
        _quick = [('/storage/emulated/0', '手机存储'), ('/storage/emulated/0/Download', 'Download'),
                  (os.path.dirname(arc) or '/', '压缩包所在')]
        for q, _qn in _quick:
            if not os.path.isdir(q) or q == cur:
                continue
            items.append({
                'vod_id': ('zipdest://' + self.b64u_encode(arc) + '|' + self.b64u_encode(inner)
                           + '|' + self.b64u_encode(q) + '|' + scope),
                'vod_name': '📌 ' + _qn,
                'vod_pic': self.file_icons.get('folder'),
                'vod_remarks': q,
                'vod_tag': 'folder',
                'style': {'type': 'grid', 'ratio': 1}
            })
        try:
            names = sorted([n for n in os.listdir(cur) if os.path.isdir(os.path.join(cur, n))], key=lambda x: x.lower())
        except Exception as e:
            names = []
            items.append(self._filop_card('❌ 这个文件夹打不开', str(e), '#F44336', 'x'))
        for n in names[:200]:
            items.append({
                'vod_id': ('zipdest://' + self.b64u_encode(arc) + '|' + self.b64u_encode(inner)
                           + '|' + self.b64u_encode(os.path.join(cur, n)) + '|' + scope),
                'vod_name': '📁 ' + n,
                'vod_pic': self.file_icons.get('folder'),
                'vod_remarks': '点进去',
                'vod_tag': 'folder',
                'style': {'type': 'grid', 'ratio': 1}
            })
        return {'list': items, 'page': 1, 'pagecount': 1}

    def _zip_do_extract(self, tid):
        arc, inner, cur, scope = self._zipdest_parse(tid)
        base = (inner.rstrip('/') + '/') if inner else ''
        members = None
        if scope == 'sel':
            members = [m for m in sorted(self._zip_sel_set(arc)) if m.startswith(base)]
            if not members:
                return {'toast': '还没选中文件', 'list': [self._filop_card('ℹ️ 还没选中文件', '先回压缩包里点文件把它勾上', '#FF9800', 'i',
                                                                          link=self._zip_nav_id(arc, inner))],
                        'page': 1, 'pagecount': 1}
        if not os.path.isfile(arc):
            return {'toast': '压缩包不在了', 'list': [self._filop_card('❌ 压缩包不在了', arc, '#F44336', 'x')], 'page': 1, 'pagecount': 1}
        self._zip_log('解压 scope=%s 到 %s' % (scope, cur))
        _strip = (inner.rstrip('/') + '/') if inner else ''
        n, out = self._zip_extract(arc, inner, cur, members=members, strip=_strip)
        if scope == 'sel':
            self._zip_sel_set(arc).clear()
        self._zip_log('完成 %d -> %s' % (n, out))
        if not n:
            _msg = '一个文件都没解出来，目标目录：%s%s' % (out, getattr(self, '_zip_skip_note', ''))
            self._zip_log('0 个文件：%s' % _msg)
            return {'toast': '没解出东西，看这张卡',
                    'list': [self._filop_card('❌ 一个都没解出来', _msg, '#F44336', 'x'),
                             self._filop_card('⬅️ 回到压缩包', os.path.basename(arc),
                                              '#2196F3', '<', link=self._zip_nav_id(arc, inner))],
                    'page': 1, 'pagecount': 1}
        return self._zip_jump(out, n)

    def _zip_jump(self, out, n):
        """解压完：刷新并直接跳到解压到的那个文件夹列表"""
        try:
            self.dir_cache.pop('dir_%s' % out, None)
            self.dir_cache_time.pop('dir_%s' % out, None)
        except Exception:
            pass
        _toast = '已解压 %d 个文件到 %s%s' % (n, out, getattr(self, '_zip_skip_note', ''))
        try:
            res = self.categoryContent(self.FOLDER_PREFIX + self.b64u_encode(out), 1, None, None)
            if isinstance(res, dict) and res.get('list'):
                res['toast'] = _toast
                return res
        except Exception as _je:
            self._zip_log('跳转失败 %s' % _je)
        return {'toast': _toast, 'list': [
            self._filop_card('✅ 解压完成：%d 个文件' % n, '在 ' + out, '#4CAF50', 'v', link=out),
            self._filop_card('📂 打开这个文件夹', out, '#2196F3', '>', link=out),
        ], 'page': 1, 'pagecount': 1}

    def _rar_ext(self, archive, dest, members=None, strip=''):
        """rar：手机上有 unrar / 7z / bsdtar 就先交给它；没有就用内置的（只解不压缩的）"""
        try:
            return self._rar_ext_in(archive, dest, members, strip)
        except Exception as _re:
            try:
                import traceback
                self._zip_log('rar 解压异常 %s: %s' % (type(_re).__name__, _re))
                self._zip_log(traceback.format_exc()[-1200:])
            except Exception:
                pass
            raise

    def _rar_ext_in(self, archive, dest, members=None, strip=''):
        self._zip_log('rar 开始 arc=%s inner_strip=%r dest=%s members=%r' % (archive, strip, dest, (members or [])[:4]))
        if not members and not strip:
            _ext = self._rar_external(archive, dest)
            if _ext is not None:
                self._zip_log('rar 交给外部命令 %s，%d 个文件' % (_ext[1], _ext[0]))
                return _ext[0]
        with RarReader(archive) as rr:
            if rr.encrypted:
                raise RarError('这个 rar 有密码（或者是加密文件头），手机这边解不开；先在电脑上解压')
            if rr.volume:
                raise RarError('这是分卷 rar（xxx.part1.rar 这种），要把所有分卷放同一个文件夹一起解；手机这边还不行')
            self._zip_log('rar 内置解析 ver=%s 条目=%d 可解=%d 加密=%s 分卷=%s' %
                          (rr.ver, len(rr.files), len([x for x in rr.files if self._rar_store(x)]),
                           rr.encrypted, rr.volume))
            n = rr.extract(dest, members=members, strip=strip)
            self._zip_log('rar 内置完成 解出=%d 跳过=%d CRC错=%d' % (n, len(rr.skipped), getattr(rr, 'bad_crc', 0)))
            if rr.skipped:
                _sk = rr.skipped[:3]
                self._zip_skip_note = ('　（有 %d 个是压缩存的解不开，跳过了：%s%s）'
                                       % (len(rr.skipped), '、'.join([os.path.basename(x.rstrip('/')) for x in _sk]),
                                          ' 等' if len(rr.skipped) > 3 else ''))
            if rr.bad_crc:
                self._zip_log('rar 解出 %d 个，其中 %d 个校验对不上（多半是分卷或文件损坏）' % (n, rr.bad_crc))
            return n

    def _rar_external(self, archive, dest):
        """找手机上的 unrar / 7z / bsdtar；没有就返回 None"""
        try:
            import subprocess
        except Exception:
            return None
        try:
            os.makedirs(dest, exist_ok=True)
        except Exception:
            pass
        for exe, args in (('unrar', ['x', '-o+', '-y', archive, dest.rstrip('/') + '/']),
                          ('7z', ['x', '-y', '-o' + dest, archive]),
                          ('7za', ['x', '-y', '-o' + dest, archive]),
                          ('bsdtar', ['-xf', archive, '-C', dest])):
            try:
                path = shutil.which(exe)
            except Exception:
                path = None
            if not path:
                continue
            try:
                _r = subprocess.run([path] + args, stdout=subprocess.DEVNULL,
                                    stderr=subprocess.DEVNULL, timeout=1800)
                if _r.returncode == 0:
                    n = 0
                    for _root, _dirs, _files in os.walk(dest):
                        n += len(_files)
                    self._zip_log('外部命令 %s 返回 0，共解出 %d 个文件' % (exe, n))
                    if n > 0:
                        return n, exe
                    continue
            except Exception:
                continue
        return None

    @staticmethod
    def _rar_store(f):
        return bool(f.get('is_dir')) or f.get('method') in (0, 0x30)

    def _zip_extract(self, archive, member, dest, members=None, strip=''):
        self._zip_skip_note = ''
        dest = (dest or '').strip() or os.path.join(os.path.dirname(archive),
                                                    os.path.splitext(os.path.basename(archive))[0] or '解压结果')
        dest = os.path.expanduser(dest)
        if not os.path.isdir(dest):
            os.makedirs(dest, exist_ok=True)
        cnt = 0
        _strip = (strip or '')
        _mset = set(members or [])
        low = archive.lower()
        if low.endswith('.zip'):
            import zipfile
            with zipfile.ZipFile(archive) as zf:
                for info in zf.infolist():
                    if info.is_dir():
                        continue
                    fname = self._zip_fix_name(info)
                    if _mset and not (fname in _mset or any(d.endswith('/') and fname.startswith(d) for d in _mset)):
                        continue
                    if not _mset and member and not (fname == member or fname.startswith(member.rstrip('/') + '/')):
                        continue
                    _rel = fname[len(_strip):] if (_strip and fname.startswith(_strip)) else fname
                    parts = [x for x in _rel.split('/') if x not in ('', '.', '..')]
                    if not parts:
                        continue
                    out = os.path.join(dest, *parts)
                    os.makedirs(os.path.dirname(out), exist_ok=True)
                    with zf.open(info) as src, open(out, 'wb') as dst:
                        shutil.copyfileobj(src, dst)
                    cnt += 1
        elif low.endswith('.rar'):
            _m7 = None
            if _mset:
                _m7 = sorted(_mset)
            elif member:
                _m7 = [member, member.rstrip('/') + '/']
            _done = self._rar_ext(archive, dest, _m7, _strip)
            cnt = _done if _done is not None else cnt
        elif low.endswith('.7z'):
            _m7 = None
            if _mset:
                _m7 = sorted(_mset)
            elif member:
                _m7 = [member, member.rstrip('/') + '/']
            with SevenZipReader(archive) as z7:
                cnt = z7.extract(dest, members=_m7, strip=_strip)
        else:
            import tarfile
            with tarfile.open(archive, 'r:*') as tf:
                for m in tf.getmembers():
                    if not m.isfile():
                        continue
                    fname = str(m.name).replace(chr(92), '/')
                    if _mset and not (fname in _mset or any(d.endswith('/') and fname.startswith(d) for d in _mset)):
                        continue
                    if not _mset and member and not (fname == member or fname.startswith(member.rstrip('/') + '/')):
                        continue
                    _rel = fname[len(_strip):] if (_strip and fname.startswith(_strip)) else fname
                    parts = [x for x in _rel.split('/') if x not in ('', '.', '..')]
                    if not parts:
                        continue
                    out = os.path.join(dest, *parts)
                    os.makedirs(os.path.dirname(out), exist_ok=True)
                    src = tf.extractfile(m)
                    if not src:
                        continue
                    with src, open(out, 'wb') as dst:
                        shutil.copyfileobj(src, dst)
                    cnt += 1
        return cnt, dest

    def _filop_icon(self, key, color='#2196F3', glyph='!'):
        try:
            return (getattr(self, 'FILOP_ICONS', {}) or {}).get(key) or self._generate_colored_icon(color, glyph)
        except Exception:
            return ''

