    def _wv_make_fullscreen(self, dlg):
        """让浏览器这个对话框盖住手机状态栏，做成真正全屏。

        2026-11-12 v232：三条路都试一遍，谁认算谁的——
          a) 老办法（所有版本都认）：窗口加 FLAG_FULLSCREEN | FLAG_LAYOUT_NO_LIMITS |
             FLAG_LAYOUT_IN_SCREEN | FLAG_LAYOUT_INSET_DECOR，再 setSystemUiVisibility 铺满；
          b) 新办法（Android 11+）：setDecorFitsSystemWindows(False) + insetController.hide(状态栏)；
          c) 状态栏底色刷成纯黑（万一没藏住，看起来也像全屏）。
        任何一步失败都只记一行日志，不影响浏览器打开。
        """
        try:
            from java import jclass
            if dlg is None:
                return False
            _win = dlg.getWindow()
            if _win is None:
                self._dlg_log('全屏：拿不到窗口（这版壳可能不支持），跳过')
                return False
            # 1024=FLAG_FULLSCREEN 512=FLAG_LAYOUT_NO_LIMITS 256=FLAG_LAYOUT_IN_SCREEN
            # 65536=FLAG_LAYOUT_INSET_DECOR
            _want = 1024 | 512 | 256 | 65536
            try:
                _win.addFlags(_want)
            except Exception as _e1:
                self._dlg_log('全屏：加窗口 flag 没成（%s）' % _e1)
            try:
                _win.setLayout(-1, -1)          # MATCH_PARENT x MATCH_PARENT
            except Exception:
                pass
            try:
                _lp = _win.getAttributes()
                _lp.width = -1
                _lp.height = -1
                _win.setAttributes(_lp)
            except Exception:
                pass
            # 老办法：系统栏 UI 标志铺满 + 藏状态栏
            #   4=SYSTEM_UI_FLAG_FULLSCREEN 1024=LAYOUT_FULLSCREEN 256=LAYOUT_STABLE 512=LAYOUT_HIDE_NAVIGATION
            try:
                _win.getDecorView().setSystemUiVisibility(4 | 1024 | 256 | 512)
            except Exception as _e2:
                self._dlg_log('全屏：老办法设置没成（%s）' % _e2)
            # 新办法：Android 11 起推荐这套
            try:
                _win.setDecorFitsSystemWindows(False)
            except Exception:
                pass
            try:
                _ic = _win.getInsetsController()
                if _ic is not None:
                    _ic.hide(1)                 # 1 = WindowInsets.Type.statusBars()
            except Exception:
                pass
            # 兜底：状态栏底色刷黑
            try:
                _win.setStatusBarColor(-16777216)
            except Exception:
                pass
            self._dlg_log('全屏：已让浏览器盖住状态栏（FLAG_FULLSCREEN + 隐藏状态栏）')
            return True
        except Exception as _e:
            self._dlg_log('全屏设置失败（不影响浏览）：%s' % _e)
            return False

