    _WV_DL_EXTS = ('zip', 'rar', '7z', 'tar', 'gz', 'tgz', 'bz2', 'xz', 'iso', 'apk', 'exe', 'msi',
                   'bin', 'img', 'dmg', 'txt', 'json', 'jsonl', 'csv', 'tsv', 'xml', 'md', 'log',
                   'yml', 'yaml', 'ini', 'conf', 'cfg', 'py', 'sql', 'db', 'pdf', 'epub', 'mobi',
                   'azw3', 'doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx', 'dat', 'bak', 'torrent')

    # 这些类型系统能直接打开看，交给下载器前得换成 octet-stream，不然点下载结果变成「打开」
    _WV_VIEW_MIMES = ('text/', 'application/json', 'application/ld+json', 'application/xml',
                      'application/xhtml', 'application/javascript', 'application/x-javascript')

    _WV_URLPARAM_KEYS = ('url', 'target', 'to', 'jumpurl', 'redirect', 'link', 'u', 'urls',
                         'weburl', 'web_url', 'h5url', 'h5', 'surl', 'murl', 'shareurl',
                         'content_url', 'openurl', 'fallback', 'fallbackurl', 'goto', 'uri',
                         'href', 'src', 'page')

    _WV_ASSET_HOSTS = ('bdstatic.com', 'bdimg.com', 'gstatic.com', 'googleusercontent.com',
                       'alicdn.com', 'byteimg.com', 'hdslb.com', 'qhimg.com', 'pstatp.com',
                       'bdurl.net')

    def _wv_find_http(self, s, rounds=3, skip_asset=True):
        """在一串（可能被编码好几层的）文本里挖出第一个能当网页打开的 http(s) 地址。

        图片/脚本/字体这类资源地址（尾缀能看出来的、或者常见 CDN 图床域名）不算，
        免得把一张图标拼图当成要打开的网页。挖不到回空串。
        """
        try:
            _t = str(s or '')
        except Exception:
            return ''
        try:
            from urllib.parse import unquote as _uq
        except Exception:
            def _uq(x):
                return x
        _bad_tail = ('.png', '.jpg', '.jpeg', '.gif', '.webp', '.svg', '.ico', '.css', '.js',
                     '.jsn', '.json', '.woff', '.woff2', '.ttf', '.mp4', '.m3u8')
        for _r in range(max(1, int(rounds))):
            try:
                _ms = re.findall(r'https?://[^\s"\'<>\\^`，。、；：（）【】]+', _t)
            except Exception:
                _ms = []
            for _cand in _ms:
                _u = _cand.rstrip('.,);]}&%')
                if len(_u) <= 12:
                    continue
                _path = _u.lower().split('?')[0]
                if skip_asset and _path.endswith(_bad_tail):
                    continue
                if skip_asset:
                    _host = _u.split('//', 1)[-1].split('/', 1)[0].lower()
                    if any(_h in _host for _h in self._WV_ASSET_HOSTS):
                        continue
                return _u
            try:
                _n = _uq(_t)
            except Exception:
                _n = _t
            if _n == _t:
                break
            _t = _n
        return ''

    def _wv_search_term(self, raw):
        """从 search://… 这种「只能在 App 里搜」的链接里抠一个关键词；抠不出回空串。

        先认 wd= / word= / q= 这类参数；没有就把里面连着两个以上的汉字当关键词。
        """
        try:
            _t = str(raw or '')
        except Exception:
            return ''
        try:
            from urllib.parse import unquote as _uq
        except Exception:
            def _uq(x):
                return x
        for _r in range(4):
            try:
                _n = _uq(_t)
            except Exception:
                _n = _t
            if _n == _t:
                break
            _t = _n
        try:
            _m = re.search(r'(?:^|[?&#/])(?:wd|word|q|query|keyword|kw)=([^&#\s]{1,80})', _t, re.I)
            if _m:
                _v = _m.group(1).strip()
                if _v:
                    return _v
        except Exception:
            pass
        try:
            _c = re.findall(u'[\u4e00-\u9fff]{2,}', _t)
            if _c:
                return max(_c, key=len)[:30]
        except Exception:
            pass
        return ''

    def _wv_inner_url(self, raw):
        """从 baiduboxapp://…?url=<编码>、intent://host/path#Intent;… 这类「得用外部 App 开」的链接里，
        拆出浏览器能直接打开的网址；拆不出回空串。

        2026-11-12 v214 拆得更深：常见的 url= 这类参数名认得更全、值编好几层也认；
        整个链接里任意位置嵌着的 http(s) 地址也挖（图片那种不算）；
        百度 search://… 这种「只能在 App 里搜」的，把关键词抠出来换成百度搜索页。
        """
        try:
            _s = str(raw or '').strip()
            if not _s:
                return ''
            _low = _s.lower()
            if _low.startswith(('http://', 'https://')):
                return ''
            if _low.startswith('intent://'):
                _body = _s[len('intent://'):].split('#Intent')[0].split(';end')[0]
                _cand = 'https://' + _body.lstrip('/')
                return _cand if len(_cand) > 12 else ''
            try:
                from urllib.parse import unquote as _uq
            except Exception:
                def _uq(x):
                    return x
            _i = _s.find('?')
            _q = _s[_i + 1:] if _i >= 0 else ''
            _pairs = {}
            for _kv in _q.split('&'):
                if '=' not in _kv:
                    continue
                _k, _, _v = _kv.partition('=')
                _pairs[_k.strip().lower()] = _v
            for _k in self._WV_URLPARAM_KEYS:
                if _k not in _pairs:
                    continue
                _v = _pairs[_k]
                # 逐层解开，但一看到 http(s) 就停：再多解一层会把网址里本来就该留着的 %E7%94%B5 这种
                # 转义也吃掉（变成真汉字），交回 WebView 时反而不稳。百度那种一层编码的最常见。
                for _round in (0, 1, 2, 3):
                    try:
                        _nv = _uq(_v)
                    except Exception:
                        _nv = _v
                    if _nv == _v:
                        break
                    _v = _nv
                    if _v.strip().lower().startswith(('http://', 'https://')):
                        break
                _v = _v.strip()
                if _v.lower().startswith(('http://', 'https://')):
                    return _v
                _h = self._wv_find_http(_v)
                if _h:
                    return _h
            _h2 = self._wv_find_http(_s)
            if _h2:
                return _h2
            # 只有百度这种「App 内搜索」的链接才去做关键词替换，别的自定义协议不乱猜
            if ('search://' in _low) or ('baidu' in _low and 'search' in _low):
                _term = self._wv_search_term(_s)
                if _term:
                    try:
                        from urllib.parse import quote as _qt
                    except Exception:
                        def _qt(x, safe=''):
                            return x
                    self._dlg_log('外部链接里抠出关键词，改成百度搜一下：%s' % _term[:40])
                    return 'https://www.baidu.com/s?wd=' + _qt(_term)
            return ''
        except Exception as _ie:
            self._dlg_log('拆内层地址出错：%s' % _ie)
            return ''

    def _wv_mime_by_name(self, name):
        """按文件名猜个类型（塞进网页的 File 对象要用，网页有时会看 type）"""
        try:
            _n = str(name or '').lower()
        except Exception:
            _n = ''
        _e = _n.rsplit('.', 1)[-1] if '.' in _n else ''
        _m = {
            'txt': 'text/plain', 'log': 'text/plain', 'md': 'text/markdown', 'py': 'text/x-python',
            'json': 'application/json', 'csv': 'text/csv', 'xml': 'application/xml',
            'html': 'text/html', 'htm': 'text/html', 'css': 'text/css', 'js': 'text/javascript',
            'jpg': 'image/jpeg', 'jpeg': 'image/jpeg', 'png': 'image/png', 'gif': 'image/gif',
            'webp': 'image/webp', 'bmp': 'image/bmp', 'svg': 'image/svg+xml', 'ico': 'image/x-icon',
            'mp4': 'video/mp4', 'mkv': 'video/x-matroska', 'avi': 'video/x-msvideo',
            'mp3': 'audio/mpeg', 'm4a': 'audio/mp4', 'wav': 'audio/wav', 'flac': 'audio/flac',
            'zip': 'application/zip', 'rar': 'application/x-rar-compressed', '7z': 'application/x-7z-compressed',
            'gz': 'application/gzip', 'tar': 'application/x-tar', 'apk': 'application/vnd.android.package-archive',
            'pdf': 'application/pdf', 'doc': 'application/msword',
            'docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
            'xls': 'application/vnd.ms-excel',
            'xlsx': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            'epub': 'application/epub+zip', 'ttf': 'font/ttf', 'otf': 'font/otf',
        }
        return _m.get(_e, 'application/octet-stream')

    def _wv_upload_ask(self, act=None, why='', multi=False):
        """网页要选上传文件，但系统那个选择器弹不出来（没有「刚点过」的凭证时系统会拒绝）：
        脚本自己弹框挑，挑好了把文件内容塞进网页那个文件框（哪些框能用见 _wv_upload_fill_js）。"""
        try:
            if act is None:
                act = self._dlg_activity()
            if not act:
                self._dlg_log('接管上传：拿不到 Activity')
                return False
            try:
                self._nat_toast('挑要上传的文件（点文件是勾选，可多选，选完点「确定」）' if multi
                                else ('挑个文件交给网页（和设置里那个选择文件一个框）' if why
                                      else '用脚本自己的文件框挑上传文件'))
            except Exception:
                pass
            self._dlg_pick(act, '/storage/emulated/0',
                           lambda p: self._wv_upload_fill(self._wv_cur, p),
                           None,
                           '选择要上传的文件' + ('（可多选）' if multi else ''),
                           multi)
            self._dlg_log('接管上传：已弹出脚本自己的文件框')
            return True
        except Exception as _e:
            self._dlg_log('接管上传出错：%s' % _e)
            return False

    def _wv_log_text(self, lines=60):
        """最近几十行日志（浏览器里点 ℹ 就能看，报问题时截图给我就行）"""
        try:
            _p = '/storage/emulated/0/tmp/ui_dialog.log'
            if not os.path.isfile(_p):
                return '还没有日志文件：%s' % _p
            with open(_p, 'r', encoding='utf-8', errors='replace') as _f:
                _all = _f.read().split('\n')
            while _all and not str(_all[-1]).strip():
                _all.pop()
            return '\n'.join(_all[-max(1, int(lines)):])[-6000:]
        except Exception as _e:
            return '读日志失败：%s' % _e

    def _wv_log_view(self, act=None):
        """浏览器悬浮条上那个「ℹ」：把最近日志摊开看一眼"""
        try:
            if act is None:
                act = self._dlg_activity()
            if not act:
                self._nat_toast('弹窗打不开，先看 tmp/ui_dialog.log')
                return False
            from java import jclass, dynamic_proxy
            from java.lang import Runnable
            AlertDialog = jclass('android.app.AlertDialog')
            LinearLayout = jclass('android.widget.LinearLayout')
            TextView = jclass('android.widget.TextView')
            ScrollView = jclass('android.widget.ScrollView')
            Color = jclass('android.graphics.Color')
            _body = self._wv_log_text(60)
            _act = act

            class _R(dynamic_proxy(Runnable)):
                def __init__(s):
                    super().__init__()

                def run(s):
                    try:
                        sc = ScrollView(_act)
                        lay = LinearLayout(_act)
                        lay.setOrientation(1)
                        tv = TextView(_act)
                        tv.setText(str(_body))
                        tv.setTextSize(11.5)
                        tv.setTextColor(Color.rgb(33, 33, 33))
                        lay.addView(tv)
                        sc.addView(lay)
                        b = AlertDialog.Builder(_act)
                        b.setTitle('ℹ 最近日志')
                        b.setView(sc)
                        b.setPositiveButton('关闭', None)
                        b.create().show()
                    except Exception as _e:
                        self._dlg_log('日志窗失败：%s' % _e)

            act.runOnUiThread(_R())
            return True
        except Exception as _e:
            self._dlg_log('日志窗异常：%s' % _e)
            return False

    def _wv_upload_mode(self):
        """上传走哪条路。默认 'js'：脚本自己的文件框挑，再把内容直接塞进网页的文件框——实测过能用。

        2026-11-12 v222：'sys'（叫系统文件管理器、挂 Fragment 收结果）改成要手动开才会用——
        那段我没在真机上验过，用户报「选择文件会刷新到新页面」后先摘掉。
        /storage/emulated/0/tmp/webview_upload_mode.txt 里写 uri（老办法：交 file:// 地址）
        或 sys（叫系统文件管理器）才改走别的路。
        """
        try:
            _p = '/storage/emulated/0/tmp/webview_upload_mode.txt'
            if os.path.isfile(_p):
                with open(_p, 'r', encoding='utf-8') as _f:
                    _v = str(_f.read()).strip().lower()
                if _v in ('uri', 'file', 'link', 'file://'):
                    return 'uri'
                if _v in ('sys', 'system', 'fragment', '系统'):
                    return 'sys'
        except Exception:
            pass
        return 'js'

    def _wv_upload_fill(self, wv, paths, cb=None):
        """把本地文件的内容塞进网页的文件框（一次可以好几个）。

        paths 可以是一个路径，也可以是一串路径（多选）。单文件最大 8MB、加起来最多 20MB，
        超了就跳过并在日志/气泡里说清（这么塞要把内容编码后过一遍 JS，太大扛不住）。
        """
        try:
            if wv is None:
                return False
            if isinstance(paths, (list, tuple)):
                _list = [str(x) for x in paths if str(x or '').strip()]
            else:
                _list = [str(paths)] if str(paths or '').strip() else []
            if not _list:
                self._dlg_log('上传填充跳过：没有文件')
                return False
            import json as _json
            _max1 = 8 * 1024 * 1024
            _maxall = 20 * 1024 * 1024
            _ok = []
            _total = 0
            for _p in _list:
                try:
                    _sz = int(os.path.getsize(_p))
                except Exception:
                    _sz = 0
                if _sz <= 0:
                    self._dlg_log('上传填充跳过（空的或读不到大小）：%s' % _p[:60])
                    continue
                if _sz > _max1:
                    self._dlg_log('上传填充跳过（单个太大 %d 字节）：%s' % (_sz, _p[:60]))
                    continue
                if _total + _sz > _maxall:
                    self._dlg_log('上传填充：加起来超过 20MB，后面的先不交：%s' % _p[:60])
                    break
                _ok.append((_p, _sz))
                _total += _sz
            if not _ok:
                try:
                    self._nat_toast('这些文件太大或读不到，这样传不上去（看 ℹ 日志）')
                except Exception:
                    pass
                return False
            try:
                from java import jclass as _jc
                ValueCallback = _jc('android.webkit.ValueCallback')
                from java import dynamic_proxy as _dpx

                class _Log(_dpx(ValueCallback)):
                    def __init__(s):
                        super().__init__()

                    def onReceiveValue(s, val):
                        try:
                            self._dlg_log('上传填充结果：%s' % str(val)[:120])
                        except Exception:
                            pass

                _cb2 = _Log()
            except Exception as _ve:
                self._dlg_log('上传填充：日志回调建不出来（不影响填充）：%s' % _ve)
                _cb2 = None
            # 先把两个小函数装上，再清空数组，然后一个一个文件放进去，最后一次性塞给网页
            wv.evaluateJavascript(WV_UPLOAD_FILL_JS, None)
            wv.evaluateJavascript('window.__hd_files=[];window.__hd_b64="";', None)
            _step = 180000
            _pieces = 0
            for _p, _sz in _ok:
                try:
                    with open(_p, 'rb') as _f:
                        _raw = _f.read()
                except Exception as _re:
                    self._dlg_log('上传填充读文件失败（%s）：%s' % (_p[:40], _re))
                    continue
                try:
                    import base64 as _b64
                    _s = _b64.b64encode(_raw).decode('ascii')
                except Exception as _be:
                    self._dlg_log('上传填充编码失败：%s' % _be)
                    continue
                _name = os.path.basename(_p)
                _mime = self._wv_mime_by_name(_name)
                _n = 0
                while _n < len(_s):
                    _part = _s[_n:_n + _step]
                    _n += _step
                    _pieces += 1
                    wv.evaluateJavascript('window.__hd_b64=(window.__hd_b64||"")+"%s";' % _part, None)
                wv.evaluateJavascript('window.__hd_push(%s,%s);'
                                      % (_json.dumps(_name), _json.dumps(_mime)), None)
            wv.evaluateJavascript('window.__hd_apply();', _cb2)
            self._dlg_log('上传：已把 %d 个文件（共 %d 字节，分 %d 片）塞进网页的文件框'
                          % (len(_ok), _total, _pieces))
            if len(_ok) < len(_list):
                try:
                    self._nat_toast('只交了 %d 个（其余的太大或读不到），看 ℹ 日志' % len(_ok))
                except Exception:
                    pass
            return True
        except Exception as _e:
            self._dlg_log('上传填充出错：%s' % _e)
            return False

    def _wv_from_act(self, act):
        """从 Activity 身上找到脚本自己那个全屏 WebView（用来把文件内容塞进网页）"""
        try:
            _w = getattr(self, '_wv_ref', None)
            if _w is not None:
                return _w
        except Exception:
            pass
        return None

    def _wv_accept_hint(self, types, limit=3):
        """网页 input 的 accept 列表 -> 一句提示（只影响标题文字，不影响能挑哪些文件）"""
        try:
            _out = []
            for _t in (types or []):
                _s = str(_t or '').strip()
                if _s and _s not in _out:
                    _out.append(_s)
                if len(_out) >= int(limit):
                    break
            return '、'.join(_out)[:60]
        except Exception:
            return ''

    def _wv_upload_ok_path(self, path):
        """上传要挑的是「文件」：回 (能不能用, 不能用时提示什么)"""
        try:
            _p = str(path or '').strip()
        except Exception:
            _p = ''
        if not _p:
            return False, '没选到文件'
        try:
            if os.path.isdir(_p):
                return False, '这是文件夹，要选里面的文件'
            if not os.path.exists(_p):
                return False, '这个文件找不到了'
        except Exception as _e:
            return False, '看不了这个路径：%s' % _e
        return True, ''

    def _wv_upload_cancel(self, cb):
        """网页那个上传框不选了：必须回一个空值，不然它一直是「正在选择」"""
        try:
            cb.onReceiveValue(None)
            self._dlg_log('上传：这一轮没选文件（已告诉网页）')
        except Exception as _e:
            self._dlg_log('上传取消回话失败：%s' % _e)
        return False

    def _wv_upload_pick_do(self, path, cb, wv=None):
        """把挑好的文件交回网页的 <input type=file>；交不了就当取消，别把那个框卡住。

        2026-11-12 v217：默认走「把内容塞进网页文件框」这条路（_wv_upload_fill）——WebView 认
        content:// 而我们没有自己的 FileProvider，自己拼 file:// 在 Android 10 以后基本不被认，
        这就是「选了文件却传不上去」最可能的原因。想改回交地址：tmp/webview_upload_mode.txt 写 uri。
        """
        try:
            _ok, _why = self._wv_upload_ok_path(path)
            if not _ok:
                self._dlg_log('上传选文件不行：%s（%s）' % (_why, str(path)[:60]))
                try:
                    self._nat_toast(_why)
                except Exception:
                    pass
                return self._wv_upload_cancel(cb)
            _mode = 'js'
            try:
                _mode = self._wv_upload_mode()
            except Exception:
                _mode = 'js'
            if _mode == 'uri':
                try:
                    from java import jclass as _jc
                    Uri = _jc('android.net.Uri')
                    FileJ = _jc('java.io.File')
                    cb.onReceiveValue([Uri.fromFile(FileJ(str(path)))])
                    self._dlg_log('上传：已按文件地址交给网页（file://，若失败可改回 js 方式）')
                    return True
                except Exception as _je:
                    self._dlg_log('交文件地址失败，改用填充方式：%s' % _je)
            # 先把网页那个「正在选择」收掉（取消），再自己把内容塞进它的文件框：
            # 顺序反了的话，这里回的取消会把已经塞进去的文件又清掉。
            self._wv_upload_cancel(cb)
            _filled = self._wv_upload_fill(wv, path, cb)
            if _filled:
                self._dlg_log('上传：文件内容已交给网页（%s）' % str(path)[:80])
            else:
                try:
                    self._nat_toast('这个文件没能交给网页，看 tmp/ui_dialog.log')
                except Exception:
                    pass
            return _filled
        except Exception as _e:
            self._dlg_log('上传处理出错：%s' % _e)
            return False

    def _wv_pick_upload(self, act, cb, params=None):
        """网页点「选择文件」时走这里：先用系统的文件管理器挑，装不上再退回脚本自带的浏览框。

        2026-11-12 v216：改成优先用系统文件管理器——用户要的就是「到手机里选文件」。
        脚本自己实现不了 Activity.onActivityResult，但可以往宿主的 FragmentManager 里挂一个
        没有界面的 Fragment，让 Fragment 去 startActivityForResult 并收结果；这样拿到的还是
        content:// 地址（WebView 最认这种，自己拼 file:// 有些版本会不认）。
        """
        _acc = ''
        try:
            if params is not None:
                _acc = self._wv_accept_hint(params.getAcceptTypes())
        except Exception:
            _acc = ''
        self._dlg_log('网页要选上传文件：%s' % (_acc or '不限类型'))
        try:
            self._wv_cur = self._wv_from_act(act)
        except Exception:
            self._wv_cur = None
        _mode = 'js'
        try:
            _mode = self._wv_upload_mode()
        except Exception:
            _mode = 'js'
        if _mode == 'sys':
            # 只有手动开了才走这条（真机没验过，默认不用）
            try:
                if self._wv_upload_sys(act, cb, params):
                    return True
            except Exception as _se:
                self._dlg_log('系统文件管理器这条路出错，改用自带的框：%s' % _se)
        else:
            self._dlg_log('按默认走脚本自己的文件框（要用系统文件管理器：tmp/webview_upload_mode.txt 写 sys）')
        return self._wv_pick_upload_own(act, cb, params)

    def _wv_pick_upload_own(self, act, cb, params=None):
        """备用：脚本自己的文件浏览框（系统那个挂不上时用）"""
        try:
            _acc = ''
            try:
                if params is not None:
                    _acc = self._wv_accept_hint(params.getAcceptTypes())
            except Exception:
                _acc = ''
            _title = '选择要上传的文件' + (('（%s）' % _acc) if _acc else '')
            self._dlg_log('改用脚本自带的浏览框挑上传文件')
            try:
                self._nat_toast('用脚本自己的文件框挑上传文件')
            except Exception:
                pass
            self._dlg_pick(act, '/storage/emulated/0',
                           lambda p: self._wv_upload_pick_do(p, cb, self._wv_cur),
                           lambda: self._wv_upload_cancel(cb),
                           _title)
            return True
        except Exception as _e:
            self._dlg_log('上传选文件出错：%s' % _e)
            return self._wv_upload_cancel(cb)

    def _wv_upload_sys(self, act, cb, params=None):
        """用系统的文件管理器挑上传文件（挂个没界面的 Fragment 收结果）。

        回 True 表示「已经交给系统选择器了」；回 False 表示这条路走不通，让调用方用自带的框。
        """
        try:
            from java import jclass, static_proxy, dynamic_proxy
            from java.lang import Runnable
            Intent = jclass('android.content.Intent')
            # 2026-11-12 v217：support 版（androidx）和系统版（android.app）两种 Fragment 都试，
            # 哪边能挂上就用哪边，宿主是哪一路都能覆盖到。
            _mode = ''
            fm = None
            FragCls = None
            try:
                fm = act.getSupportFragmentManager()
                if fm is not None:
                    _mode = 'support'
                    FragCls = 'androidx.fragment.app.Fragment'
            except Exception as _fe:
                self._dlg_log('support 版 FragmentManager 拿不到：%s' % _fe)
            if fm is None:
                try:
                    fm = act.getFragmentManager()
                    if fm is not None:
                        _mode = 'framework'
                        FragCls = 'android.app.Fragment'
                except Exception as _fe2:
                    self._dlg_log('系统版 FragmentManager 也拿不到：%s' % _fe2)
            if fm is None or not FragCls:
                self._dlg_log('系统选择器用不了（两种 FragmentManager 都没有）')
                return False
            _REQ = int(getattr(self, '_WV_UPLOAD_REQ', 0x5756))
            _self = self
            _st = {'done': False, 'frag': None}
            _types = []
            try:
                for _x in (params.getAcceptTypes() if params is not None else []):
                    _s = str(_x or '').strip()
                    if _s and _s not in _types:
                        _types.append(_s)
            except Exception:
                _types = []
            _multi = False
            try:
                if params is not None and int(params.getMode()) == 2:   # MODE_OPEN_MULTIPLE
                    _multi = True
            except Exception:
                _multi = False

            def _drop(s):
                try:
                    _mg = s.getFragmentManager()
                    if _mg is not None:
                        _mg.beginTransaction().remove(s).commitAllowingStateLoss()
                except Exception:
                    pass

            def _late():
                """结果一直没回来（宿主没往下发）就别把网页那个框卡着"""
                if _st['done']:
                    return
                _st['done'] = True
                _self._dlg_log('系统文件管理器一直没回结果，按取消算')
                try:
                    cb.onReceiveValue(None)
                except Exception:
                    pass
                _f0 = _st.get('frag')
                if _f0 is not None:
                    _drop(_f0)

            class _Frag(static_proxy(FragCls)):
                def onCreate(s, b):
                    try:
                        super().onCreate(b)
                    except Exception:
                        pass
                    try:
                        it = Intent(Intent.ACTION_GET_CONTENT)
                        try:
                            it.addCategory(Intent.CATEGORY_OPENABLE)
                        except Exception:
                            pass
                        _ty = '*/*'
                        for _x in _types:
                            if '/' in _x:
                                _ty = _x
                                break
                        it.setType(_ty)
                        try:
                            if len(_types) > 1:
                                it.putExtra(Intent.EXTRA_MIME_TYPES, _types)
                        except Exception:
                            pass
                        try:
                            if _multi:
                                it.putExtra(Intent.EXTRA_ALLOW_MULTIPLE, True)
                        except Exception:
                            pass
                        it.addFlags(1)      # FLAG_GRANT_READ_URI_PERMISSION
                        s.startActivityForResult(it, _REQ)
                        try:
                            _self._nat_toast('用系统文件管理器挑上传文件')
                        except Exception:
                            pass
                        _self._dlg_log('已叫出系统文件管理器挑上传文件（要 %s，%s 版 Fragment）' % (_ty, _mode))
                    except Exception as _ie:
                        _self._dlg_log('叫系统文件管理器失败，改用自带的框：%s' % _ie)
                        try:
                            _self._wv_pick_upload_own(act, cb, params)
                        except Exception:
                            try:
                                cb.onReceiveValue(None)
                            except Exception:
                                pass

                def onActivityResult(s, code, resultCode, data):
                    try:
                        if int(code) != _REQ:
                            return
                        _st['done'] = True
                        _uris = []
                        try:
                            if data is not None:
                                _u0 = data.getData()
                                if _u0 is not None:
                                    _uris.append(_u0)
                                _cl = data.getClipData()
                                if _cl is not None:
                                    for _i in range(int(_cl.getItemCount())):
                                        _uris.append(_cl.getItemAt(_i).getUri())
                        except Exception as _pe:
                            _self._dlg_log('读系统选文件结果出错：%s' % _pe)
                        if _uris:
                            cb.onReceiveValue(_uris)
                            _self._dlg_log('系统文件管理器选好了：%d 个，已交给网页' % len(_uris))
                        else:
                            cb.onReceiveValue(None)
                            _self._dlg_log('系统文件管理器没选（已告诉网页）')
                    except Exception as _re:
                        _self._dlg_log('处理选文件结果失败：%s' % _re)
                        try:
                            cb.onReceiveValue(None)
                        except Exception:
                            pass
                    finally:
                        _drop(s)

            _f = _Frag()
            _st['frag'] = _f
            _tr = fm.beginTransaction()
            _tr.add(_f, 'wv_upload_pick')
            _tr.commitAllowingStateLoss()
            try:
                _H = jclass('android.os.Handler')
                _L = jclass('android.os.Looper')

                class _Late(dynamic_proxy(Runnable)):
                    def __init__(s):
                        super().__init__()

                    def run(s):
                        _late()

                _H(_L.getMainLooper()).postDelayed(_Late(), 90000)
            except Exception:
                pass
            self._dlg_log('收结果的 Fragment 已挂上，等系统选择器回话')
            return True
        except Exception as _e:
            self._dlg_log('系统文件管理器这条路不通：%s' % _e)
            return False

    def _wv_dl_exts(self):
        """按扩展名接管下载的清单：默认一套；想改就在 /storage/emulated/0/tmp/webview_dl_ext.txt
        里写逗号分隔的清单（写 0 / off / 关 就把这条规则整个关掉）"""
        try:
            _p = '/storage/emulated/0/tmp/webview_dl_ext.txt'
            if os.path.isfile(_p):
                with open(_p, 'r', encoding='utf-8') as _f:
                    _raw = str(_f.read()).strip().lower()
                if _raw in ('0', 'off', 'false', '关'):
                    return ()
                _lst = [x.replace('.', ' ').strip() for x in _raw.replace('，', ',').split(',')]
                _out = tuple(x for x in _lst if x)
                if _out:
                    return _out
        except Exception:
            pass
        return self._WV_DL_EXTS

    def _wv_dl_ext_of(self, url):
        """这个网址看着是要下载的文件吗（看扩展名）：是就回扩展名，不是回空串。

        路径和查询串都看一眼——有些网盘是 /download?path=/xx/斯玛特.txt 这种形式。
        """
        try:
            _u = str(url or '')
        except Exception:
            return ''
        _low = _u.strip().lower()
        if not _low.startswith(('http://', 'https://', 'ftp://')):
            return ''
        try:
            _exts = self._wv_dl_exts()
        except Exception:
            _exts = ()
        if not _exts:
            return ''
        try:
            from urllib.parse import unquote as _uq
        except Exception:
            def _uq(x):
                return x
        _cand = []
        try:
            _cand.append(_uq(_u.split('#')[0].split('?')[0]))
        except Exception:
            pass
        try:
            if '?' in _u:
                _cand.append(_uq(_u.split('?', 1)[1][-160:]))
        except Exception:
            pass
        if not _cand:
            _cand = [str(url)]
        for _c in _cand:
            _tail = str(_c).rsplit('/', 1)[-1].strip()
            if '.' not in _tail:
                continue
            _e = re.sub(r'[^0-9a-z]', '', _tail.rsplit('.', 1)[-1].lower())[:6]
            if _e and _e in _exts:
                return _e
        return ''

    def _wv_dl_plan(self, url, mime='', disp=''):
        """下载前先想清楚：这个地址能不能交给下载器；顺手把文件名从 Content-Disposition 里抠出来"""
        try:
            _u = str(url or '').strip()
        except Exception:
            _u = ''
        _low = _u.lower()
        _name = ''
        try:
            _d = str(disp or '')
            _m = re.search(r"filename\*\s*=\s*[^']*''([^;]+)", _d, re.I)
            if _m:
                try:
                    from urllib.parse import unquote as _uq
                    _name = _uq(_m.group(1).strip())
                except Exception:
                    _name = _m.group(1).strip()
            else:
                _m2 = re.search(r'filename\s*=\s*"?([^";]+)"?', _d, re.I)
                if _m2:
                    _name = _m2.group(1).strip()
            _name = str(_name).replace('\\', '/').split('/')[-1].strip()[:80]
        except Exception:
            _name = ''
        _mt0 = str(mime or '').strip()
        _mt = _mt0 or 'application/octet-stream'
        # 2026-11-12 v216：text/plain、application/json 这种系统能直接打开看的类型，
        # 原样交给系统会被文本查看器接走（用户说的是「txt/json 变成打开了」）。
        # 发给下载器时统一换成 application/octet-stream，系统才会老实列下载工具。
        try:
            _lowt = _mt.lower()
            if any((_lowt.startswith(_x) or (_x in _lowt)) for _x in self._WV_VIEW_MIMES):
                _mt = 'application/octet-stream'
        except Exception:
            pass
        if not _u:
            return {'ok': False, 'why': '这个下载地址是空的', 'url': '', 'mime': _mt, 'name': _name,
                    'orig': _mt0}
        if _low.startswith('blob:'):
            return {'ok': False, 'why': 'blob 地址（网页用 JS 拼的文件）交给下载器拿不到内容',
                    'url': _u, 'mime': _mt, 'name': _name, 'orig': _mt0}
        if _low.startswith('data:'):
            return {'ok': False, 'why': 'data 地址没法交给下载器', 'url': _u, 'mime': _mt, 'name': _name,
                    'orig': _mt0}
        if not _low.startswith(('http://', 'https://', 'ftp://')):
            return {'ok': False, 'why': '这个协议下载器接不了', 'url': _u, 'mime': _mt, 'name': _name,
                    'orig': _mt0}
        return {'ok': True, 'why': '', 'url': _u, 'mime': _mt, 'name': _name, 'orig': _mt0}

    # ================= 内置多线程下载器（2026-11-12 v223 从「多线程下载」工具搬进来） =================
    def _dl_mode(self):
        """浏览器里点下载怎么走。默认 'builtin'：先弹下载面板（能改保存路径、看进度）。
        在 /storage/emulated/0/tmp/webview_dl_mode.txt 里写：
          app   交给系统里的下载器（IDM 等）
          auto  不弹面板，直接后台下载（进度看 tmp/download.log 和 ℹ）
        """
        try:
            if os.path.isfile(DL_MODE_FILE):
                with open(DL_MODE_FILE, 'r', encoding='utf-8') as _f:
                    _v = str(_f.read()).strip().lower()
                if _v in ('app', 'external', 'idm', '外部'):
                    return 'app'
                if _v in ('auto', 'silent', 'now', '静默'):
                    return 'auto'
        except Exception:
            pass
        return 'builtin'

    def _dl_default_dir(self):
        """默认保存目录。想换又不想点面板：在 /storage/emulated/0/tmp/webview_dl_dir.txt 里写一行目录。

        2026-11-12 v226：给「想换下载路径」留一条不依赖界面弹窗的路。
        """
        try:
            if os.path.isfile(DL_DIR_FILE):
                with open(DL_DIR_FILE, 'r', encoding='utf-8') as _f:
                    _v = str(_f.readline() or '').strip()
                if _v:
                    if not _v.endswith('/'):
                        _v = _v + '/'
                    return _v
        except Exception:
            pass
        return DL_DEFAULT_DIR

    def _dl_log(self, msg):
        """下载日志：写 tmp/download.log（进度也写这儿，ℹ 那个日志只记开始/结束，免得刷屏）；
        下载面板开着的时候，同一行也推给它，面板里能实时看到。"""
        try:
            _q = getattr(self, '_dl_queue', None)
            if _q is not None:
                try:
                    _q.put(str(msg))
                except Exception:
                    pass
        except Exception:
            pass
        try:
            _line = '[%s] %s' % (time.strftime('%m-%d %H:%M:%S'), str(msg))
            try:
                os.makedirs(os.path.dirname(DL_LOG_PATH) or '.', exist_ok=True)
            except Exception:
                pass
            with open(DL_LOG_PATH, 'a', encoding='utf-8') as _f:
                _f.write(_line + chr(10))
            try:
                print('DL ' + _line)
            except Exception:
                pass
        except Exception:
            pass

    def _dl_fmt_size(self, n):
        """把字节数写成好看的样子"""
        try:
            _n = float(n)
        except Exception:
            return '?'
        if _n < 1024:
            return '%d B' % int(_n)
        for _u in ('KB', 'MB', 'GB'):
            _n /= 1024.0
            if _n < 1024 or _u == 'GB':
                return '%.2f %s' % (_n, _u)
        return '%.2f GB' % _n

    def _dl_guess_name(self, url, resp_headers=None):
        """从 Content-Disposition 或网址里猜文件名（服务器给的名字优先）"""
        _name = ''
        try:
            _cd = ''
            try:
                _cd = str((resp_headers or {}).get('content-disposition') or '')
            except Exception:
                _cd = ''
            if _cd:
                _m = re.search(r"filename\*\s*=\s*[^']*''([^;]+)", _cd, re.I)
                if _m:
                    try:
                        from urllib.parse import unquote as _uq
                        _name = _uq(_m.group(1).strip())
                    except Exception:
                        _name = _m.group(1).strip()
                else:
                    _m2 = re.search(r'filename\s*=\s*"?([^";]+)"?', _cd, re.I)
                    if _m2:
                        _name = _m2.group(1).strip()
        except Exception:
            _name = ''
        if not _name:
            try:
                from urllib.parse import urlsplit as _us, unquote as _uq2
                _p = _us(str(url or '')).path or ''
                _name = _uq2(_p.rstrip('/').split('/')[-1]) if _p else ''
            except Exception:
                _name = ''
        try:
            _name = str(_name).replace('\\', '/').split('/')[-1].strip()
            _name = re.sub(r'[\x00-\x1f<>:"|?*]', '_', _name)[:120]
        except Exception:
            _name = ''
        return _name

    def _dl_ext_by_type(self, ctype):
        """按 Content-Type 猜扩展名（名字里没扩展名时才用）"""
        _c = str(ctype or '').split(';')[0].strip().lower()
        _map = {
            'video/mp4': '.mp4', 'video/x-matroska': '.mkv', 'video/webm': '.webm', 'video/mpeg': '.mpg',
            'video/quicktime': '.mov', 'video/x-flv': '.flv', 'video/3gpp': '.3gp',
            'audio/mpeg': '.mp3', 'audio/mp4': '.m4a', 'audio/aac': '.aac', 'audio/flac': '.flac',
            'audio/wav': '.wav', 'audio/ogg': '.ogg', 'audio/x-ms-wma': '.wma',
            'image/jpeg': '.jpg', 'image/png': '.png', 'image/gif': '.gif', 'image/webp': '.webp',
            'image/bmp': '.bmp', 'image/svg+xml': '.svg', 'image/tiff': '.tif',
            'application/pdf': '.pdf', 'application/zip': '.zip', 'application/x-zip-compressed': '.zip',
            'application/x-rar-compressed': '.rar', 'application/vnd.rar': '.rar',
            'application/x-7z-compressed': '.7z', 'application/gzip': '.gz', 'application/x-gzip': '.gz',
            'application/x-tar': '.tar', 'application/x-bzip2': '.bz2', 'application/x-xz': '.xz',
            'application/vnd.android.package-archive': '.apk', 'application/epub+zip': '.epub',
            'application/x-iso9660-image': '.iso', 'application/vnd.ms-excel': '.xls',
            'application/msword': '.doc', 'application/vnd.ms-powerpoint': '.ppt',
            'application/vnd.openxmlformats-officedocument.wordprocessingml.document': '.docx',
            'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': '.xlsx',
            'application/vnd.openxmlformats-officedocument.presentationml.presentation': '.pptx',
            'application/json': '.json', 'application/xml': '.xml', 'text/xml': '.xml',
            'text/plain': '.txt', 'text/html': '.html', 'text/css': '.css', 'text/csv': '.csv',
            'text/x-python': '.py', 'application/javascript': '.js', 'text/javascript': '.js',
            'application/octet-stream': '.bin', 'application/x-msdownload': '.exe',
            'font/ttf': '.ttf', 'font/otf': '.otf', 'application/vnd.apple.mpegurl': '.m3u8',
            'application/x-mpegurl': '.m3u8', 'video/mp2t': '.ts',
        }
        return _map.get(_c, '')

    def _dl_fix_path(self, path, url, resp_headers=None):
        """把保存路径收拾好：只给文件夹就自动起名；名字没扩展名就按类型补一个。"""
        _p = str(path or '').strip() or self._dl_default_dir()
        _name = self._dl_guess_name(url, resp_headers)
        _is_dir = False
        try:
            if _p.endswith('/') or _p.endswith(os.sep):
                _is_dir = True
            elif os.path.isdir(_p):
                _is_dir = True
        except Exception:
            _is_dir = False
        if _is_dir:
            if not _name:
                _name = 'download_' + time.strftime('%Y%m%d_%H%M%S')
            _p = os.path.join(_p.rstrip('/'), _name)
        try:
            _base = os.path.basename(_p)
            if _base and '.' not in _base:
                _ext = ''
                if _name and '.' in _name:
                    _ext = '.' + _name.rsplit('.', 1)[1]
                if not _ext and resp_headers:
                    _ext = self._dl_ext_by_type(resp_headers.get('content-type'))
                if _ext:
                    _p = _p + _ext
        except Exception:
            pass
        return _p

    def _dl_unique_path(self, path, size=0):
        """要存的文件已经存在、大小又正好对得上时，另起一个名字（绝不悄悄覆盖用户的东西）"""
        try:
            if not os.path.exists(path):
                return path
            if os.path.isfile(path + '.parts.json'):
                return path          # 有断点文件＝上次没下完，接着下
            if int(size or 0) > 0 and os.path.getsize(path) == int(size):
                _base, _ext = os.path.splitext(path)
                for _i in range(2, 100):
                    _np = '%s(%d)%s' % (_base, _i, _ext)
                    if (not os.path.exists(_np)) and (not os.path.isfile(_np + '.parts.json')):
                        self._dl_log('同名文件已存在，改存成：%s' % os.path.basename(_np))
                        return _np
        except Exception:
            pass
        return path

    def _dl_probe(self, url, headers):
        """探一次：拿总大小、看对方支不支持分段。回 (最终地址, 大小, 支持分段, 类型, disposition, 错误)"""
        _final, _size, _ranges, _ctype, _cd, _err = str(url or ''), 0, False, '', '', ''
        def _one(_with_range):
            _h = dict(headers or {})
            if _with_range:
                _h['Range'] = 'bytes=0-0'
            with self.session.get(url, headers=_h, stream=True, timeout=(10, 25),
                                  allow_redirects=True, verify=False) as _r:
                _code = int(_r.status_code)
                if _code >= 400:
                    raise RuntimeError('HTTP %d' % _code)
                return (str(_r.url or url), _code,
                        int(_r.headers.get('content-length') or 0),
                        str(_r.headers.get('accept-ranges') or '').lower(),
                        str(_r.headers.get('content-range') or ''),
                        str(_r.headers.get('content-type') or ''),
                        str(_r.headers.get('content-disposition') or ''))
        try:
            _a = _one(True)
        except Exception:
            try:
                _a = _one(False)
            except Exception as _e2:
                return _final, 0, False, '', '', str(_e2)
        _final, _code, _clen, _ar, _cr, _ctype, _cd = _a
        _ranges = (_code == 206) or (_ar == 'bytes')
        if _code == 206:
            _m = re.search(r'/(\d+)\s*$', _cr)
            if _m:
                _size = int(_m.group(1))
        if not _size:
            _size = int(_clen or 0)
        if _ranges and not _size:
            try:
                _hr = self.session.head(_final, headers=dict(headers or {}), timeout=10,
                                        allow_redirects=True, verify=False)
                if int(_hr.status_code) < 400:
                    _size = int(_hr.headers.get('content-length') or 0)
            except Exception:
                pass
        return _final, _size, _ranges, _ctype, _cd, _err

    def _dl_ranged(self, url, headers, path, size, threads=4):
        """分段并发下载（各写各的偏移），断点续传靠 <路径>.parts.json"""
        _size = int(size)
        os.makedirs(os.path.dirname(path) or '.', exist_ok=True)
        _state_path = path + '.parts.json'
        _par = 256 * 1024
        _want = int(max(1, min(int(threads or 4), (_size + _par - 1) // _par)))
        _seg = (_size + _want - 1) // _want
        _bounds = []
        _pos = 0
        while _pos < _size:
            _bounds.append((_pos, min(_pos + _seg - 1, _size - 1)))
            _pos += _seg
        _done = [0] * len(_bounds)
        try:
            if os.path.isfile(_state_path):
                with open(_state_path, 'r', encoding='utf-8') as _f:
                    _state = json.load(_f) or {}
                if (isinstance(_state, dict) and int(_state.get('size') or 0) == _size
                        and _state.get('bounds') == [list(x) for x in _bounds]
                        and isinstance(_state.get('done'), list)
                        and len(_state.get('done')) == len(_bounds)):
                    _done = [max(0, int(x or 0)) for x in _state['done']]
        except Exception:
            pass
        # 续传前先核对物理文件：大小对不上（被删过/截过）就当进度作废
        _stale = False
        try:
            if (not os.path.exists(path)) or os.path.getsize(path) != _size:
                _stale = True
        except Exception:
            _stale = True
        if _stale:
            _done = [0] * len(_bounds)
        try:
            with open(path, 'r+b') as _f:
                _f.truncate(_size)
        except Exception:
            with open(path, 'wb') as _f:
                _f.truncate(_size)
        _done = [min(int(_done[i] or 0), _bounds[i][1] - _bounds[i][0] + 1) for i in range(len(_bounds))]
        _got0 = sum(_done)
        if _got0:
            self._dl_log('🔄 接着上次下：已经有 %s / %s'
                         % (self._dl_fmt_size(_got0), self._dl_fmt_size(_size)))
        _lock = threading.Lock()
        _stop = {'no': False}
        _prog = {'got': _got0, 'last': time.time(), 't0': time.time()}

        def _save_state():
            try:
                with open(_state_path + '.tmp', 'w', encoding='utf-8') as _f:
                    json.dump({'size': _size, 'bounds': [list(x) for x in _bounds], 'done': _done, 'url': url}, _f)
                try:
                    os.replace(_state_path + '.tmp', _state_path)
                except Exception:
                    os.rename(_state_path + '.tmp', _state_path)
            except Exception:
                pass

        def _worker(_i):
            _start, _end = _bounds[_i]
            _need = _end - _start + 1
            for _try in range(3):
                if _stop.get('no'):
                    return
                _from = _start + int(_done[_i] or 0)
                if _from > _end:
                    with _lock:
                        _done[_i] = _need
                    return
                try:
                    _h = dict(headers or {})
                    _h['Range'] = 'bytes=%d-%d' % (_from, _end)
                    _w = _from
                    with open(path, 'r+b') as _f:
                        _f.seek(_from)
                        with self.session.get(url, headers=_h, stream=True, timeout=(10, 30),
                                              verify=False) as _r:
                            _code = int(_r.status_code)
                            if _code == 200:
                                raise RuntimeError('对方不认分段（回 200）')
                            if _code != 206:
                                raise RuntimeError('HTTP %d' % _code)
                            for _chunk in _r.iter_content(chunk_size=256 * 1024):
                                if not _chunk:
                                    continue
                                if _stop.get('no'):
                                    return
                                _f.write(_chunk)
                                _w += len(_chunk)
                                with _lock:
                                    _done[_i] = _w - _start
                                    _prog['got'] += len(_chunk)
                                    _now = time.time()
                                    if _now - _prog['last'] > 1.2:
                                        _prog['last'] = _now
                                        _pct = (_prog['got'] / float(_size)) * 100
                                        _sp = _prog['got'] / max(0.001, _now - _prog['t0'])
                                        self._dl_log('⏳ 进度 %.1f%% (%s / %s) 约 %s/s'
                                                     % (_pct, self._dl_fmt_size(_prog['got']),
                                                        self._dl_fmt_size(_size), self._dl_fmt_size(_sp)))
                                        _save_state()
                                if _w > _end:
                                    break
                    if _w - _start >= _need:
                        with _lock:
                            _done[_i] = _need
                            _save_state()
                        return
                except Exception as _we:
                    with _lock:
                        self._dl_log('⚠️ 第 %d 段出错（第 %d 次）：%s' % (_i + 1, _try + 1, _we))
                        _save_state()
                    time.sleep(0.8)
            with _lock:
                _stop['no'] = True
                self._dl_log('❌ 第 %d 段试了 3 次都没成（下次再点下载会接着下）' % (_i + 1))

        _ts = []
        for _i in range(len(_bounds)):
            _th = threading.Thread(target=_worker, args=(_i,), daemon=True)
            _ts.append(_th)
            _th.start()
        for _th in _ts:
            _th.join()
        if _stop.get('no'):
            raise RuntimeError('有分段没下完')
        _got = sum(_done)
        if _got < _size:
            raise RuntimeError('只下了 %s / %s' % (self._dl_fmt_size(_got), self._dl_fmt_size(_size)))
        try:
            with open(path, 'r+b') as _f:
                _f.truncate(_size)
        except Exception:
            pass
        try:
            os.remove(_state_path)
        except Exception:
            pass
        _el = max(0.001, time.time() - _prog['t0'])
        self._dl_log('🎉 下载完毕：%s，用时 %.1f 秒（平均 %s/s）'
                     % (self._dl_fmt_size(_size), _el, self._dl_fmt_size(_size / _el)))

    def _dl_single_stream(self, url, headers, path, size=0):
        """单线程流式下载（对方不支持分段、或拿不到大小时用这条）"""
        os.makedirs(os.path.dirname(path) or '.', exist_ok=True)
        _got = 0
        _t0 = time.time()
        _last = 0.0
        with self.session.get(url, headers=headers, stream=True, timeout=(10, 30), verify=False) as r:
            r.raise_for_status()
            try:
                if int(size or 0) <= 0:
                    size = int(r.headers.get('content-length') or 0)
            except Exception:
                size = 0
            with open(path, 'wb') as f:
                for chunk in r.iter_content(chunk_size=512 * 512):
                    if not chunk:
                        continue
                    f.write(chunk)
                    _got += len(chunk)
                    _now = time.time()
                    if _now - _last > 1.5:
                        _last = _now
                        if size > 0:
                            self._dl_log('⏳ 进度 %.1f%% (%s / %s)'
                                         % (_got * 100.0 / size, self._dl_fmt_size(_got),
                                            self._dl_fmt_size(size)))
                        else:
                            self._dl_log('⏳ 已下载 %s' % self._dl_fmt_size(_got))
        _el = max(0.001, time.time() - _t0)
        self._dl_log('🎉 下载完毕：%s，用时 %.1f 秒（平均 %s/s）'
                     % (self._dl_fmt_size(_got), _el, self._dl_fmt_size(_got / _el)))

    def _dl_fail_log(self, err):
        """下载失败时给一句人话（别只丢一堆 traceback）"""
        _msg = str(err)
        self._dl_log('❌ 下载失败：%s' % _msg)
        self._dlg_log('内置下载器失败：%s' % _msg[:160])
        if any(_k in _msg for _k in ('403', '401', '404', '410')):
            self._dl_log('👉 多半是防盗链或链接过期：这个地址先在浏览器里点开看看；能开但下不动，'
                         '多半要带上 Referer/Cookie（脚本已经带上了当前网页的 Referer）。')
        elif any(_k in _msg.lower() for _k in ('timeout', 'timed out', 'connection', 'ssl')):
            self._dl_log('👉 多半是网络/证书问题：稍后重试，或换个线路。')
        else:
            self._dl_log('👉 把这一行连同链接发我，我按这个站改。')

    def _dl_save_data_url(self, url, save):
        """data: 地址（网页自己拼的小文件）直接在本地解开存下来"""
        try:
            _head, _, _body = str(url).partition(',')
            _name = ''
            _m = re.search(r'name=([^;]+)', _head, re.I)
            if _m:
                try:
                    from urllib.parse import unquote as _uq
                    _name = _uq(_m.group(1))
                except Exception:
                    _name = _m.group(1)
            if not _name:
                _mt = ''
                _m2 = re.search(r'data:([^;,]+)', _head, re.I)
                if _m2:
                    _mt = _m2.group(1).strip().lower()
                _name = 'download_' + time.strftime('%Y%m%d_%H%M%S') + (self._dl_ext_by_type(_mt) or '.bin')
            _path = os.path.join(str(save or self._dl_default_dir()).rstrip('/') or self._dl_default_dir(),
                                 os.path.basename(_name))
            if ';base64' in _head.lower():
                import base64 as _b64
                _data = _b64.b64decode(_body)
            else:
                from urllib.parse import unquote_to_bytes as _u2b
                _data = _u2b(_body)
            os.makedirs(os.path.dirname(_path) or '.', exist_ok=True)
            with open(_path, 'wb') as _f:
                _f.write(_data)
            self._dl_log('🎉 已存下 data: 里的小文件：%s（%s）' % (_path, self._dl_fmt_size(len(_data))))
            return True, _path, ''
        except Exception as _e:
            self._dl_log('❌ data: 地址存不下来：%s' % _e)
            return False, '', str(_e)

    def _dl_download_any(self, url, headers=None, path=None, threads=4):
        """内置多线程下载器主入口（阻塞）：什么文件都能下。回 (成功, 最终路径, 说明)"""
        _u = str(url or '').strip()
        if not _u:
            return False, '', '链接是空的'
        _h = dict(headers or {})
        if 'User-Agent' not in _h:
            try:
                _h['User-Agent'] = (self.headers or {}).get('User-Agent') or 'Mozilla/5.0'
            except Exception:
                _h['User-Agent'] = 'Mozilla/5.0'
        _save = str(path or '').strip() or self._dl_default_dir()
        if _u.lower().startswith('data:'):
            return self._dl_save_data_url(_u, _save)
        if not _u.lower().startswith(('http://', 'https://', 'ftp://')):
            return False, '', '这个协议内置下载器接不了'
        self._dl_log('🔗 开始下载：%s' % _u[:140])
        _final, _size, _ranges, _ctype, _cd, _err = self._dl_probe(_u, _h)
        _path = self._dl_fix_path(_save, _final, {'content-type': _ctype, 'content-disposition': _cd})
        _path = self._dl_unique_path(_path, _size)
        self._dl_log('📁 保存到：%s' % _path)
        if _ctype:
            self._dl_log('🧾 服务器类型：%s' % _ctype)
        if _size > 0:
            self._dl_log('📦 大小：%s' % self._dl_fmt_size(_size))
        if _err:
            self._dl_log('⚠️ 探测没成功（%s），直接用单线程试' % _err)
            try:
                self._dl_single_stream(_u, _h, _path, _size)
                return True, _path, ''
            except Exception as _e0:
                self._dl_fail_log(_e0)
                return False, _path, str(_e0)
        if _ranges and _size > 0:
            self._dl_log('🧵 对方支持分段，用多线程下载')
            try:
                self._dl_ranged(_final, _h, _path, _size, threads)
                return True, _path, ''
            except Exception as _re:
                _progressed = 0
                try:
                    _sf = _path + '.parts.json'
                    if os.path.isfile(_sf):
                        with open(_sf, 'r', encoding='utf-8') as _f:
                            _sd = json.load(_f) or {}
                        _progressed = sum([int(x or 0) for x in (_sd.get('done') or [])])
                except Exception:
                    _progressed = 0
                if _progressed > 0:
                    self._dl_log('⚠️ 分段没下完（%s）；已经下好的 %s 留着，再点一次下载会接着下'
                                 % (_re, self._dl_fmt_size(_progressed)))
                    return False, _path, '下了一部分，再点一次接着下'
                self._dl_log('⚠️ 分段没成（%s），清掉重来，改单线程' % _re)
                try:
                    os.remove(_path)
                except Exception:
                    pass
                try:
                    os.remove(_path + '.parts.json')
                except Exception:
                    pass
        else:
            self._dl_log('🧵 对方不支持分段或没给大小，走单线程流式（照样能下完）')
        try:
            self._dl_single_stream(_u, _h, _path, _size)
            return True, _path, ''
        except Exception as _e1:
            self._dl_fail_log(_e1)
            return False, _path, str(_e1)

    def _dl_panel(self, act, url='', mime='', disp='', name='', size='', headers=None, path=None):
        """下载面板：链接、保存路径（自己填或点「选择文件夹」挑）、请求头、实时日志。

        2026-11-12 v224：浏览器里点下载先弹这个——想换保存位置、想看进度都在这里；
        面板打不开（拿不到 Activity）就回 False，让调用方退回后台静默下载，别让下载丢掉。
        """
        try:
            import queue as _queue_mod          # 2026-11-12 v225：这个文件原本没 import queue（v224 的坑）
            if act is None:
                act = self._dlg_activity()
            if not act:
                self._dl_log('下载面板打不开（拿不到 Activity）')
                self._dlg_log('下载面板打不开：拿不到 Activity，已退回后台静默下载')
                return False
            from java import jclass, dynamic_proxy
            from java.lang import Runnable
            Builder = jclass('android.app.AlertDialog$Builder')
            LinearLayout = jclass('android.widget.LinearLayout')
            ScrollView = jclass('android.widget.ScrollView')
            TextView = jclass('android.widget.TextView')
            EditText = jclass('android.widget.EditText')
            Button = jclass('android.widget.Button')
            LP = jclass('android.widget.LinearLayout$LayoutParams')
            Handler = jclass('android.os.Handler')
            Looper = jclass('android.os.Looper')
            Click = jclass('android.view.View$OnClickListener')
            box = {}
            _start_path = str(path or '').strip() or self._dl_default_dir()

            class _Run(dynamic_proxy(Runnable)):
                def __init__(s2):
                    super().__init__()

                def run(s2):
                    try:
                        root = LinearLayout(act)
                        root.setOrientation(1)
                        _pad = int(14 * act.getResources().getDisplayMetrics().density)

                        def _mk_label(_txt):
                            _tv = TextView(act)
                            try:
                                _tv.setText(str(_txt))
                                _tv.setTextSize(13.0)
                            except Exception:
                                pass
                            root.addView(_tv, LP(-1, -2))

                        def _mk_edit(_val, _hint=''):
                            _et = EditText(act)
                            try:
                                _et.setText(str(_val or ''))
                                if _hint:
                                    _et.setHint(str(_hint))
                                _et.setSingleLine(True)
                            except Exception:
                                pass
                            return _et

                        def _mk_btn(_txt, _fn):
                            _b = Button(act)
                            try:
                                _b.setText(str(_txt))
                            except Exception:
                                pass

                            class _C(dynamic_proxy(Click)):
                                def __init__(s3):
                                    super().__init__()

                                def onClick(s3, v):
                                    try:
                                        _fn()
                                    except Exception as _ce:
                                        self._dl_log('按钮出错：%s' % _ce)

                            _b.setOnClickListener(_C())
                            return _b

                        _mk_label('下载链接:')
                        link_edit = _mk_edit(url, 'http://... 什么文件都能下')
                        root.addView(link_edit, LP(-1, -2))
                        _mk_label('保存位置（文件夹，或写完整的文件名）:')
                        path_edit = _mk_edit(_start_path)
                        root.addView(path_edit, LP(-1, -2))
                        path_row = LinearLayout(act)
                        path_row.setOrientation(0)

                        def _pick_dir():
                            try:
                                _cur = str(path_edit.getText() or '').strip() or self._dl_default_dir()
                                if not os.path.isdir(_cur):
                                    _cur = os.path.dirname(_cur.rstrip('/')) or self._dl_default_dir()
                            except Exception:
                                _cur = self._dl_default_dir()

                            def _set(p):
                                try:
                                    path_edit.setText(str(p).rstrip('/') + '/')
                                except Exception:
                                    pass

                            self._dlg_pick(act, _cur, _set, None, '选择保存文件夹')

                        path_row.addView(_mk_btn('📂 选择文件夹', _pick_dir), LP(-2, -2, 1.0))
                        root.addView(path_row, LP(-1, -2))
                        _mk_label('日志:')
                        log_view = TextView(act)
                        scroll = ScrollView(act)
                        try:
                            log_view.setTextSize(11.0)
                            log_view.setText('点「开始下载」，这里会实时显示进度。' + chr(10))
                            scroll.addView(log_view, LP(-1, -2))
                            _h2 = int(act.getResources().getDisplayMetrics().heightPixels)
                            _lh = int(min(_h2 * 0.3, 200 * act.getResources().getDisplayMetrics().density))
                            scroll.setLayoutParams(LP(-1, max(int(60 * act.getResources().getDisplayMetrics().density), _lh)))
                        except Exception:
                            pass
                        root.addView(scroll, LP(-1, -2))
                        btn_row = LinearLayout(act)
                        btn_row.setOrientation(0)

                        def _do_start():
                            try:
                                _u = str(link_edit.getText() or '').strip()
                                _p = str(path_edit.getText() or '').strip() or DL_DEFAULT_DIR
                                self._dl_start(_u, mime, disp, name, size, act, path=_p)
                            except Exception as _se:
                                self._dl_log('开始下载出错：%s' % _se)

                        btn_row.addView(_mk_btn('🚀 开始下载', _do_start), LP(-2, -2, 1.0))
                        btn_row.addView(_mk_btn('✖ 关闭', lambda: box['dlg'].dismiss()), LP(-2, -2, 1.0))
                        root.addView(btn_row, LP(-1, -2))

                        self._dl_queue = _queue_mod.Queue()
                        self._dl_view = {'log': log_view, 'scroll': scroll}
                        b = Builder(act)
                        b.setTitle('下载')
                        b.setView(root)
                        dlg = b.create()
                        box['dlg'] = dlg
                        try:
                            _OnDismiss = jclass('android.content.DialogInterface$OnDismissListener')

                            class _Dz(dynamic_proxy(_OnDismiss)):
                                def __init__(s3):
                                    super().__init__()

                                def onDismiss(s3, d):
                                    # 面板关了就别再往它推日志（也把队列放开，免得一直攒）
                                    try:
                                        self._dl_view = None
                                        self._dl_queue = None
                                    except Exception:
                                        pass

                            dlg.setOnDismissListener(_Dz())
                        except Exception as _de:
                            self._dl_log('面板关闭回调没装上（不影响下载）：%s' % _de)
                        dlg.show()
                        _h = Handler(Looper.getMainLooper())

                        class _Pump(dynamic_proxy(Runnable)):
                            def __init__(s3):
                                super().__init__()

                            def run(s3):
                                try:
                                    if not getattr(self, '_dl_view', None):
                                        return
                                    _batch = []
                                    try:
                                        while not self._dl_queue.empty():
                                            _batch.append(self._dl_queue.get_nowait())
                                    except Exception:
                                        pass
                                    if _batch:
                                        _cur = str(self._dl_view['log'].getText() or '')
                                        _new = _cur + chr(10) + chr(10).join([str(x) for x in _batch])
                                        if len(_new) > 6000:
                                            _new = _new[-6000:]
                                        self._dl_view['log'].setText(_new)
                                        try:
                                            self._dl_view['scroll'].fullScroll(130)
                                        except Exception:
                                            pass
                                    _h.postDelayed(s3, 400)
                                except Exception:
                                    pass

                        _h.post(_Pump())
                        self._dl_log('下载面板已打开，保存位置：%s' % _start_path)
                        box['ok'] = True
                    except Exception as _pe:
                        box['ok'] = False
                        self._dl_log('下载面板没建起来：%s' % _pe)
                        self._dlg_log('下载面板没建起来：%s（已退回后台静默下载）' % str(_pe)[:150])

            act.runOnUiThread(_Run())
            if box.get('ok') is False:
                return False
            return True
        except Exception as _e:
            self._dl_log('下载面板出错：%s' % _e)
            self._dlg_log('下载面板出错：%s' % str(_e)[:150])
            return False

    def _dl_start(self, url, mime='', disp='', name='', size='', act=None, path=None, extra_headers=None):
        """浏览器里点了下载：默认用内置下载器后台跑（进度写 tmp/download.log）"""
        try:
            _low = str(url or '').strip().lower()
            if not _low.startswith(('http://', 'https://', 'ftp://', 'data:')):
                self._dl_log('这个协议不归内置下载器管：%s' % _low[:30])
                return False
            _h = {}
            try:
                _h['User-Agent'] = (self.headers or {}).get('User-Agent') or 'Mozilla/5.0'
            except Exception:
                _h['User-Agent'] = 'Mozilla/5.0'
            try:
                if self._wv_ref is not None:
                    _page = str(self._wv_ref.getUrl() or '')
                    if _page.startswith('http'):
                        _h['Referer'] = _page      # 防盗链站多半就认这个
            except Exception:
                pass
            try:
                if isinstance(extra_headers, dict):
                    for _hk, _hv in extra_headers.items():
                        _h[str(_hk)] = str(_hv)
            except Exception:
                pass
            _save = str(path or '').strip() or self._dl_default_dir()
            _label = str(name or self._dl_guess_name(url) or url)[:40]

            def _work():
                try:
                    _ok, _p, _why = self._dl_download_any(url, _h, _save)
                    if _ok:
                        self._dl_log('🎉 保存至：%s' % _p)
                        self._dlg_log('内置下载完成：%s' % _p)
                        try:
                            self._nat_toast('下载完成：%s' % os.path.basename(_p))
                        except Exception:
                            pass
                    else:
                        self._dlg_log('内置下载没成：%s' % str(_why or '')[:120])
                        try:
                            self._nat_toast('下载没成：%s（看 ℹ 日志）' % str(_why or '')[:24])
                        except Exception:
                            pass
                except Exception as _we:
                    self._dl_fail_log(_we)

            self._dl_log('🔘 浏览器点了下载：%s | 类型 %s | 名字 %s'
                         % (_low[:120], str(mime or '-'), str(name or '-')))
            threading.Thread(target=_work, daemon=True).start()
            try:
                _where = '面板日志' if getattr(self, '_dl_view', None) else 'ℹ 日志'
                self._nat_toast('开始下载：%s（进度看%s）' % (_label, _where))
            except Exception:
                pass
            self._dlg_log('已交给内置多线程下载器：%s' % _low[:90])
            return True
        except Exception as _e:
            self._dl_log('启动内置下载失败：%s' % _e)
            return False

    def _wv_download(self, url, user_agent='', disp='', mime='', size='', act=None):
        """网页要下载东西：把地址交给系统，弹「用哪个应用」——装了 IDM 就选 IDM。

        主路是 VIEW + mimetype（IDM 和各种下载器都注册了这个），备路是「分享一段纯文本链接」
        （有的下载器只认分享）。两条都不行就把链接复制到剪贴板。
        """
        try:
            _p = self._wv_dl_plan(url, mime, disp)
            self._dlg_log('网页要下载：%s | 类型 %s->%s | 名字 %s | 大小 %s'
                          % (str(url)[:90], _p.get('orig') or '-', _p['mime'],
                             _p['name'] or '-', str(size or '-')[:20]))
            _mode = 'builtin'
            try:
                _mode = self._dl_mode()
            except Exception:
                _mode = 'builtin'
            if _mode != 'app':
                # 2026-11-12 v223：默认用脚本自带的多线程下载器（什么文件都能下，进度写 tmp/download.log）
                # 2026-11-12 v224：先弹下载面板（能改保存位置、能看进度、能填请求头）；
                #   面板打不开就退回后台静默下载。想换别的：tmp/webview_dl_mode.txt 写 app / auto
                if _mode == 'builtin' and self._dl_panel(act, _p.get('url') or url, _p.get('mime', ''),
                                                         disp, _p.get('name', ''), size):
                    return True
                if self._dl_start(_p.get('url') or url, _p.get('mime', ''), disp,
                                  _p.get('name', ''), size, act):
                    return True
                self._dl_log('内置下载器没接手（协议不支持之类），按老路交给系统里的下载器')
            if not _p['ok']:
                try:
                    self._nat_toast(_p['why'])
                except Exception:
                    pass
                try:
                    self._pyplug_copy_text(_p['url'])
                except Exception:
                    pass
                return False
            if act is None:
                act = self._dlg_activity()
            if not act:
                try:
                    self._nat_toast('叫不起下载器（拿不到 Activity），链接已复制')
                except Exception:
                    pass
                try:
                    self._pyplug_copy_text(_p['url'])
                except Exception:
                    pass
                return False
            from java import jclass as _jc
            Intent = _jc('android.content.Intent')
            Uri = _jc('android.net.Uri')
            _view = Intent(Intent.ACTION_VIEW)
            _view.setDataAndType(Uri.parse(_p['url']), _p['mime'])
            _view.addFlags(0x10000000)
            try:
                _view.putExtra(Intent.EXTRA_TEXT, _p['url'])
                if user_agent:
                    _view.putExtra('android.webkit.extra.USER_AGENT', str(user_agent))
            except Exception:
                pass
            _send = Intent(Intent.ACTION_SEND)
            _send.setType('text/plain')
            _send.putExtra(Intent.EXTRA_TEXT, _p['url'])
            try:
                _send.putExtra(Intent.EXTRA_SUBJECT, _p['name'] or _p['url'][-40:])
            except Exception:
                pass
            _send.addFlags(0x10000000)
            _ch = Intent.createChooser(_view, '下载：%s' % (_p['name'] or _p['url'][:40]))
            _ch.addFlags(0x10000000)
            try:
                _ch.putExtra(Intent.EXTRA_INITIAL_INTENTS, [_send])
            except Exception:
                pass
            act.startActivity(_ch)
            try:
                self._nat_toast('已把下载链接交给下载器：%s' % (_p['name'] or _p['url'][:30]))
            except Exception:
                pass
            return True
        except Exception as _e:
            self._dlg_log('交给下载器失败：%s' % _e)
            try:
                self._pyplug_copy_text(str(url))
                self._nat_toast('下载器叫不起来，链接已复制到剪贴板')
            except Exception:
                pass
            return False

    def _wv_norm_url(self, text):
        """把敲进来的网址收拾成能直接加载的样子。

        没写 http/https 就按网页补上；带别的协议（ftp:// 这类）原样交出去；
        看着根本不像网址（没点没冒号）就回空串，让调用方提示一句，别去加载一个假地址。
        """
        try:
            _u = str(text or '').strip()
        except Exception:
            return ''
        if not _u:
            return ''
        _u = _u.split('\n')[0].strip()
        if ' ' in _u:
            _u = _u.split(' ')[0].strip()
        if not _u:
            return ''
        if _u.startswith(('http://', 'https://', 'file://', 'about:')):
            return _u
        if '://' in _u:
            return _u
        _host = _u.split('/')[0]
        if '.' not in _host and ':' not in _host and _host.lower() != 'localhost':
            return ''
        return 'https://' + _u

    def _wv_goto_do(self, text, wv=None):
        """输入网址小窗里点了「打开」：就在当前这个窗口里换页（不新开窗口）"""
        try:
            _u = self._wv_norm_url(text)
            if not _u:
                self._nat_toast('这不像网址，写全一点，例如 baidu.com')
                self._dlg_log('输入网址看不懂：%s' % str(text)[:60])
                return False
            if wv is not None:
                try:
                    self._wv_open_last = (_u, time.time())
                except Exception:
                    pass
                wv.loadUrl(_u)
            self._nat_toast('正在打开：%s' % _u[:40])
            self._dlg_log('输入网址打开：%s' % _u[:80])
            return True
        except Exception as _e:
            self._dlg_log('输入网址打开失败：%s' % _e)
            return False

    def _wv_goto(self, cur_url='', act=None, wv=None):
        """悬浮条上的「⌨ 输入网址」：小窗口，先把当前地址填好，改完点打开就换页"""
        try:
            if act is None:
                act = self._dlg_activity()
            if not act:
                self._nat_toast('弹窗打不开，先看 tmp/ui_dialog.log')
                return False
            from java import jclass, dynamic_proxy
            from java.lang import Runnable
            AlertDialog = jclass('android.app.AlertDialog')
            LinearLayout = jclass('android.widget.LinearLayout')
            TextView = jclass('android.widget.TextView')
            EditText = jclass('android.widget.EditText')
            ScrollView = jclass('android.widget.ScrollView')
            Color = jclass('android.graphics.Color')
            TypedValue = jclass('android.util.TypedValue')
            DialogInterface = jclass('android.content.DialogInterface')
            _OnClick = DialogInterface.OnClickListener

            def _dp(v):
                try:
                    return int(TypedValue.applyDimension(1, float(v),
                               act.getResources().getDisplayMetrics()) + 0.5)
                except Exception:
                    return int(float(v) * 2)

            _box = {'et': None}

            class _Pos(dynamic_proxy(_OnClick)):
                def __init__(s):
                    super().__init__()

                def onClick(s, dlg, which):
                    try:
                        dlg.dismiss()
                    except Exception:
                        pass
                    try:
                        _t = str(_box['et'].getText().toString()) if _box['et'] is not None else ''
                    except Exception:
                        _t = ''
                    self._wv_goto_do(_t, wv)

            class _R(dynamic_proxy(Runnable)):
                def __init__(s):
                    super().__init__()

                def run(s):
                    try:
                        sc = ScrollView(act)
                        lay = LinearLayout(act)
                        lay.setOrientation(1)
                        lay.setPadding(_dp(18), _dp(12), _dp(18), _dp(4))
                        tv = TextView(act)
                        tv.setText('现在这一页：\n' + (str(cur_url or '')[:120] or '（还没打开网页）'))
                        tv.setTextSize(12.5)
                        tv.setTextColor(Color.rgb(117, 117, 117))
                        lay.addView(tv)
                        et = EditText(act)
                        try:
                            et.setText(str(cur_url or '')[:300])
                            et.setHint('写网址，例如 baidu.com')
                            et.setSingleLine(True)
                        except Exception:
                            pass
                        lay.addView(et)
                        _box['et'] = et
                        sc.addView(lay)
                        b = AlertDialog.Builder(act)
                        b.setTitle('⌨ 输入网址')
                        b.setView(sc)
                        b.setPositiveButton('打开', _Pos())
                        b.setNegativeButton('取消', None)
                        b.create().show()
                        try:
                            et.requestFocus()
                        except Exception:
                            pass
                        self._dlg_log('弹出输入网址小窗：%s' % str(cur_url or '')[:60])
                    except Exception as _e:
                        self._dlg_log('输入网址小窗失败：%s' % _e)

            act.runOnUiThread(_R())
            return True
        except Exception as _e:
            self._dlg_log('输入网址异常：%s' % _e)
            return False

    # ================= 浏览器里的书签（和设置里的书签同一份数据）=================
    def _wv_bm_save(self, url, name='', cover=''):
        """把一条书签存进 web_action_browser.bookmarks —— 和「⚙️ 设置 → 添加书签」同一个文件
        (/storage/emulated/0/tmp/web_bookmarks.json)，所以两边是通的。返回 True 表示新加了。
        封面：http/https 图片地址、data:image、或者手机里存在的图片路径（会自动变成 file://…）；
        填的不是这些就当没填，书签用默认图标，别让一条坏封面把整个书签列表拖坏。"""
        try:
            _bm = self.web_action_browser
            _url = str(url or '').strip()
            if not _url:
                return False
            _nm = str(name or '').strip() or _url
            _cov = ''
            try:
                _cov = str(self.web_action_browser._normalize_cover_url(str(cover or '').strip()) or '')
            except Exception:
                _cov = str(cover or '').strip()
            if str(cover or '').strip() and not _cov:
                self._dlg_log('封面图不可用，改用默认图标：%s' % str(cover)[:70])
            for _x in (getattr(_bm, 'bookmarks', None) or []):
                if str(_x.get('url') or '') == _url:
                    self._nat_toast('这个网址已经在书签里了：%s' % str(_x.get('title') or '')[:20])
                    self._dlg_log('书签已存在，没重复加：%s' % _url[:60])
                    return False
            _bm.bookmarks.append({
                'id': hashlib.md5(_url.encode('utf-8', 'surrogateescape')).hexdigest()[:8],
                'url': _url,
                'title': _nm,
                'cover': _cov,
                'add_time': time.time(),
            })
            try:
                _bm._save_bookmarks()
            except Exception as _se:
                self._dlg_log('写书签文件失败：%s' % _se)
            self._nat_toast('已添加书签：%s' % _nm[:20])
            self._dlg_log('已添加书签：%s | %s | 封面：%s（共 %d 条）'
                          % (_nm[:30], _url[:60], _cov[:60] or '默认图标', len(_bm.bookmarks)))
            return True
        except Exception as _e:
            self._dlg_log('存书签失败：%s' % _e)
            self._nat_toast('存书签失败：%s' % _e)
            return False

    def _wv_bm_add(self, url, page_title='', act=None, page_cover='', wv=None):
        """悬浮条上的「☆ 添加书签」：小窗口，名字已经填好当前网页标题，
        下面还能填/挑封面图（留空就用默认图标，网页有 og:image 首图会自动填进封面框）"""
        try:
            _url = str(url or '').strip()
            if not _url or not _url.lower().startswith(('http://', 'https://', 'file://')):
                self._nat_toast('这一页还没打开，等页面出来再收藏')
                self._dlg_log('添加书签：当前地址不能收藏：%s' % _url[:60])
                return False
            if act is None:
                act = self._dlg_activity()
            if not act:
                self._nat_toast('弹窗打不开，先看 tmp/ui_dialog.log')
                return False
            from java import jclass, dynamic_proxy
            from java.lang import Runnable
            AlertDialog = jclass('android.app.AlertDialog')
            LinearLayout = jclass('android.widget.LinearLayout')
            TextView = jclass('android.widget.TextView')
            EditText = jclass('android.widget.EditText')
            ScrollView = jclass('android.widget.ScrollView')
            Color = jclass('android.graphics.Color')
            TypedValue = jclass('android.util.TypedValue')
            Button = jclass('android.widget.Button')
            View = jclass('android.view.View')
            DialogInterface = jclass('android.content.DialogInterface')
            _OnClick = DialogInterface.OnClickListener

            def _dp(v):
                try:
                    return int(TypedValue.applyDimension(1, float(v),
                               act.getResources().getDisplayMetrics()) + 0.5)
                except Exception:
                    return int(float(v) * 2)

            _box = {'et': None, 'cv': None}

            class _Pos(dynamic_proxy(_OnClick)):
                def __init__(s):
                    super().__init__()

                def onClick(s, dlg, which):
                    try:
                        dlg.dismiss()
                    except Exception:
                        pass
                    try:
                        _nm = str(_box['et'].getText().toString()).strip() if _box['et'] is not None else ''
                    except Exception:
                        _nm = ''
                    try:
                        _cv = str(_box['cv'].getText().toString()).strip() if _box.get('cv') is not None else ''
                    except Exception:
                        _cv = ''
                    self._wv_bm_save(_url, _nm, _cv)

            class _R(dynamic_proxy(Runnable)):
                def __init__(s):
                    super().__init__()

                def run(s):
                    try:
                        sc = ScrollView(act)
                        lay = LinearLayout(act)
                        lay.setOrientation(1)
                        lay.setPadding(_dp(18), _dp(12), _dp(18), _dp(4))
                        tv = TextView(act)
                        tv.setText('这一页：\n' + _url[:120])
                        tv.setTextSize(12.5)
                        tv.setTextColor(Color.rgb(117, 117, 117))
                        lay.addView(tv)
                        et = EditText(act)
                        try:
                            et.setText(str(page_title or '')[:60] or _url[:40])
                            et.setHint('给这个书签起个名字')
                        except Exception:
                            pass
                        lay.addView(et)
                        _box['et'] = et
                        _cl = TextView(act)
                        _cl.setText('封面图（图片网址；也可以点右边选手机里的图）')
                        _cl.setTextSize(12.0)
                        _cl.setTextColor(Color.rgb(96, 125, 139))
                        _cl.setPadding(0, _dp(10), 0, 0)
                        lay.addView(_cl)
                        _crow = LinearLayout(act)
                        _crow.setOrientation(0)
                        try:
                            _crow.setGravity(16)
                        except Exception:
                            pass
                        cv = EditText(act)
                        try:
                            cv.setText(str(page_cover or '')[:300])
                            cv.setHint('留空就用默认图标')
                        except Exception:
                            pass
                        try:
                            _crow.addView(cv, LinearLayout.LayoutParams(0, -2, 1.0))
                        except Exception:
                            _crow.addView(cv)
                        bt = Button(act)
                        try:
                            bt.setText('选图…')
                        except Exception:
                            pass
                        try:
                            _crow.addView(bt, LinearLayout.LayoutParams(-2, -2))
                        except Exception:
                            _crow.addView(bt)
                        lay.addView(_crow)
                        _box['cv'] = cv

                        class _PickCover(dynamic_proxy(View.OnClickListener)):
                            def __init__(s):
                                super().__init__()

                            def onClick(s, v):
                                try:
                                    self._dlg_log('按了选封面图')
                                    self._dlg_pick(act, '/storage/emulated/0',
                                                   lambda p: cv.setText(str(p)))
                                except Exception as _pe:
                                    self._dlg_log('选封面图失败：%s' % _pe)

                        bt.setOnClickListener(_PickCover())
                        sc.addView(lay)
                        b = AlertDialog.Builder(act)
                        b.setTitle('☆ 添加书签')
                        b.setView(sc)
                        b.setPositiveButton('保存', _Pos())
                        b.setNegativeButton('取消', None)
                        b.create().show()
                        self._dlg_log('弹出添加书签小窗：%s' % _url[:60])
                        # 顺手问网页要张首图当封面：只在封面框还空着的时候填，填不上就算了
                        if wv is not None:
                            try:
                                ValueCallback = jclass('android.webkit.ValueCallback')

                                class _Cov(dynamic_proxy(ValueCallback)):
                                    def __init__(s):
                                        super().__init__()

                                    def onReceiveValue(s, val):
                                        try:
                                            _v = str(val or '').strip().strip('"')
                                            if not _v or _v == 'null':
                                                return
                                            if not _v.lower().startswith(('http://', 'https://', 'data:image')):
                                                return
                                            if str(cv.getText().toString()).strip():
                                                return
                                            cv.setText(_v[:300])
                                            self._dlg_log('封面框自动填了网页首图：%s' % _v[:70])
                                        except Exception:
                                            pass

                                _JS_OG = """(function(){try{var m=document.querySelector('meta[property="og:image"]')||document.querySelector('meta[name="og:image"]')||document.querySelector('link[rel="apple-touch-icon"]');if(!m)return '';var v=m.content||m.href||'';if(!v)return '';try{return new URL(v,location.href).href;}catch(e){return v;}}catch(e){return '';}})()"""
                                wv.evaluateJavascript(_JS_OG, _Cov())
                            except Exception as _ce:
                                self._dlg_log('封面自动填跳过：%s' % _ce)
                    except Exception as _e:
                        self._dlg_log('添加书签小窗失败：%s' % _e)

            act.runOnUiThread(_R())
            return True
        except Exception as _e:
            self._dlg_log('添加书签异常：%s' % _e)
            return False

    def _wv_bm_rows(self):
        """书签小窗口的每一行：最新的排前面；名字里读不出来的字节先洗掉（只留标题，太长截断）"""
        _bm = self.web_action_browser
        _all = [x for x in (getattr(_bm, 'bookmarks', None) or []) if str(x.get('url') or '').strip()]
        _show = list(reversed(_all))
        rows = []
        for _x in _show:
            _t = str(_x.get('title') or '').strip() or str(_x.get('url') or '')
            rows.append('🔖 ' + self._sdisp(_t)[:40])
        return _show, rows

    def _wv_bm_list(self, wv=None, act=None):
        """悬浮条上的「🔖 打开书签」：小窗口列书签，点一条就在当前这个浏览器窗口里打开"""
        try:
            _bm = self.web_action_browser
            _all = [x for x in (getattr(_bm, 'bookmarks', None) or []) if str(x.get('url') or '').strip()]
            if not _all:
                self._nat_toast('还没有书签，先点 ☆ 收藏这一页')
                self._dlg_log('打开书签：书签是空的')
                return False
            if act is None:
                act = self._dlg_activity()
            if not act:
                self._nat_toast('弹窗打不开，先看 tmp/ui_dialog.log')
                return False
            from java import jclass, dynamic_proxy
            from java.lang import Runnable
            AlertDialog = jclass('android.app.AlertDialog')
            DialogInterface = jclass('android.content.DialogInterface')
            _OnClick = DialogInterface.OnClickListener

            _show, rows = self._wv_bm_rows()

            class _Pick(dynamic_proxy(_OnClick)):
                def __init__(s):
                    super().__init__()

                def onClick(s, dlg, which):
                    try:
                        dlg.dismiss()
                    except Exception:
                        pass
                    try:
                        _bm2 = _show[int(which)]
                    except Exception:
                        return
                    _u2 = str(_bm2.get('url') or '').strip()
                    if not _u2:
                        return
                    try:
                        if wv is not None:
                            wv.loadUrl(_u2)
                            self._dlg_log('打开书签：%s -> %s' % (str(_bm2.get('title') or '')[:30], _u2[:70]))
                            try:
                                self._nat_toast('正在打开：%s' % (self._sdisp(str(_bm2.get('title') or ''))[:20] or _u2[:20]))
                            except Exception:
                                pass
                        else:
                            self._sys_open_url(_u2)
                    except Exception as _le:
                        self._dlg_log('打开书签失败：%s' % _le)
                        try:
                            self._nat_toast('打开失败：%s' % _le)
                        except Exception:
                            pass

            class _R(dynamic_proxy(Runnable)):
                def __init__(s):
                    super().__init__()

                def run(s):
                    try:
                        b = AlertDialog.Builder(act)
                        b.setTitle('🔖 书签（共 %d 条）' % len(rows))
                        b.setItems(rows, _Pick())
                        b.setNegativeButton('取消', None)
                        b.create().show()
                        self._dlg_log('弹出书签小窗：%d 条' % len(rows))
                    except Exception as _e:
                        self._dlg_log('书签小窗失败：%s' % _e)

            act.runOnUiThread(_R())
            return True
        except Exception as _e:
            self._dlg_log('打开书签异常：%s' % _e)
            return False

    def _wv_unstick(self, wv):
        """WebView 已经停在 baiduboxapp:// 这类链接上（也就是「网页无法打开 / ERR_UNKNOWN_URL_SCHEME」那张图）时，
        把它拉回来：能拆出里面真正的网址就打开它，拆不出就退回上一页并提示一句。
        返回值只为日志好看：'' 没卡 / 'reload' 已改开真网址 / 'back' 已退回 / 'toast' 只提示了。"""
        try:
            _u = str(wv.getUrl() or '')
        except Exception:
            return ''
        _low = _u.strip().lower()
        if not _low or _low.startswith(('http://', 'https://', 'file://',
                                        'about:', 'data:', 'blob:', 'javascript:')):
            try:
                self._wv_stuck_key = ''
            except Exception:
                pass
            return ''
        _key = _u.strip()[:200]
        _again = (str(getattr(self, '_wv_stuck_key', '') or '') == _key)
        _inner = self._wv_inner_url(_u)
        if _inner:
            try:
                wv.loadUrl(_inner)
                self._wv_stuck_key = ''
                self._dlg_log('卡在自定义链接上，已改开里面的真网址：%s' % _inner[:80])
                return 'reload'
            except Exception as _re:
                self._dlg_log('改开真网址失败：%s' % _re)
                return ''
        self._wv_stuck_key = _key
        if not _again:
            try:
                self._nat_toast('这个链接得用对应 App 开，已退回上一页')
            except Exception:
                pass
        try:
            if wv.canGoBack():
                wv.goBack()
                if not _again:
                    self._dlg_log('卡在自定义链接上（拆不出网址），已退回上一页：%s' % _u[:70])
                return 'back'
        except Exception:
            pass
        # 2026-11-12 v214：没上一页可退，就回到刚才那张能打开的网页——别把「网页无法打开」留在屏幕上
        _back = ''
        try:
            _back = str(getattr(self, '_wv_last_ok', '') or '')
        except Exception:
            _back = ''
        if _back and _back.strip().lower().startswith(('http://', 'https://', 'file://')):
            try:
                wv.loadUrl(_back)
                if not _again:
                    self._dlg_log('卡在自定义链接上，没上一页，已退回最后一张能打开的网页：%s' % _back[:70])
                return 'reload'
            except Exception as _be:
                self._dlg_log('退回最后一张网页失败：%s' % _be)
        if not _again:
            self._dlg_log('卡在自定义链接上（拆不出网址，也没有上一页）：%s' % _u[:70])
        return 'toast'

    def _wv_should(self, arg, view=None):
        """WebView 里点了链接怎么处理：http(s) 就地加载；baiduboxapp:// 这类自定义 scheme 一律拦住，
        绝不交给 WebView 当网页加载（那样就会弹「网页无法打开 / ERR_UNKNOWN_URL_SCHEME」）；
        能从中拆出真正的 http 地址就在原窗口打开，拆不出就提示一句只有对应 App 能开。"""
        try:
            _t = str(arg)
            try:
                if hasattr(arg, 'getUrl'):
                    _t = str(arg.getUrl().toString())
            except Exception:
                pass
            _low = str(_t).strip().lower()
            if not _low:
                return False
            if _low.startswith(('http://', 'https://', 'file://',
                                'about:', 'data:', 'javascript:', 'blob:')):
                # 2026-11-12 v216：点了明确是要下载的文件（zip、txt、json、apk…）就别在浏览器里打开，
                # 直接交给下载器——不然 txt/json 这种会被当网页显示出来。
                # 想改清单/关掉这条规则：/storage/emulated/0/tmp/webview_dl_ext.txt
                try:
                    _de = self._wv_dl_ext_of(_t)
                except Exception:
                    _de = ''
                if _de:
                    self._dlg_log('点了 .%s 文件，按下载处理，不在浏览器里打开：%s' % (_de, str(_t)[:80]))
                    try:
                        self._wv_download(_t, '', '', '', '', None)
                    except Exception as _dwe:
                        self._dlg_log('交下载器失败：%s' % _dwe)
                    return True
                return False
            _inner = self._wv_inner_url(_t)
            if _inner:
                self._dlg_log('外部跳转里拆出真地址，就地打开：%s' % _inner[:80])
                if view is not None:
                    try:
                        view.loadUrl(_inner)
                        return True
                    except Exception as _le:
                        self._dlg_log('就地打开失败，改丢给系统：%s' % _le)
                try:
                    self._sys_open_url(_inner)
                except Exception:
                    pass
                return True
            self._dlg_log('拦下外部跳转（不让 WebView 加载）：%s' % str(_t)[:70])
            try:
                self._nat_toast('这个链接得用对应 App 开，浏览器里打不开')
            except Exception:
                pass
            return True
        except Exception as _e:
            self._dlg_log('跳转判断出错：%s' % _e)
            try:
                _l2 = str(arg).strip().lower()
            except Exception:
                _l2 = ''
            return not (_l2.startswith(('http://', 'https://', 'file://',
                                        'about:', 'data:', 'javascript:', 'blob:')))

    def _sys_open_url(self, url, title=''):
        """脚本自己发 ACTION_VIEW 让系统浏览器打开；拿不到 Activity 就返回 False"""
        try:
            from java import jclass
            _u = str(url or '').strip()
            if not _u:
                return False
            if not _u.startswith(('http://', 'https://', 'file://')):
                _u = 'https://' + _u
            act = self._dlg_activity()
            if not act:
                self._dlg_log('系统浏览器：拿不到 Activity')
                return False
            Intent = jclass('android.content.Intent')
            Uri = jclass('android.net.Uri')
            it = Intent(Intent.ACTION_VIEW)
            it.setData(Uri.parse(_u))
            it.addFlags(0x10000000)
            if title:
                try:
                    it.putExtra('android.intent.extra.TITLE', str(title))
                except Exception:
                    pass
            act.startActivity(it)
            self._dlg_log('系统浏览器已打开：%s' % _u[:70])
            return True
        except Exception as e:
            self._dlg_log('系统浏览器打开失败：%s' % e)
            return False

    def _webview_open(self, url, title=''):
        """能用全屏浏览器就用；不能就回 False，让调用方走宿主老路"""
        try:
            if not self._webview_enabled():
                return False
            _u = str(url or '').strip()
            if not _u:
                return False
            if not _u.startswith(('http://', 'https://', 'file://')):
                _u = 'https://' + _u
            # 2026-11-11 v210：同一张卡片可能既走 action、又被壳当点播 id 送进详情。
            # 同一瞬间（0.8 秒内）的重复请求只开一次，免得叠出两个窗口；
            # 时间留得短，用户自己过一会儿再点同一个书签照样能打开。
            try:
                _now = time.time()
                _last = getattr(self, '_wv_open_last', None) or ('', 0.0)
                if _last[0] == _u and (_now - float(_last[1])) < 0.8:
                    self._dlg_log('同一个网址一瞬间被请求了两次，没再开新窗口：%s' % _u[:60])
                    return True
                self._wv_open_last = (_u, _now)
            except Exception:
                pass
            return self._show_full_webview(url=_u)
        except Exception as e:
            self._dlg_log('全屏浏览器跳过：%s' % e)
            return False

    def _dlg_toast(self, msg):
        """原生 Toast；拿不到界面就只写日志"""
        try:
            self._nat_toast(msg)
        except Exception as e:
            self._dlg_log('Toast 失败：%s' % e)

    def _res_msg(self, res, default='完成'):
        """从动作结果里抽一句话，用来 Toast"""
        try:
            if isinstance(res, dict):
                if res.get('toast'):
                    return str(res['toast'])[:120]
                L = res.get('list') or []
                if L and isinstance(L[0], dict):
                    nm = str(L[0].get('vod_name') or '').strip()
                    rm = str(L[0].get('vod_remarks') or '').strip()
                    if nm:
                        return (nm + (' · ' + rm if rm else ''))[:120]
                if res.get('msg'):
                    return str(res['msg'])[:120]
                return default
            if isinstance(res, str):
                try:
                    d = json.loads(res)
                    if isinstance(d, dict) and d.get('msg'):
                        return str(d['msg'])[:120]
                except Exception:
                    pass
                return res[:120] or default
        except Exception:
            pass
        return default

    def _act_ask(self, cmd, cfg):
        """原生输入框（不阻塞）：填完在回调里跑这条命令，跑完 Toast 一句话"""
        cfg = cfg or {}
        title = str(cfg.get('title') or '输入')
        msg = str(cfg.get('msg') or '')
        fields = []
        try:
            if isinstance(cfg.get('input'), list):
                for x in cfg['input']:
                    if isinstance(x, dict):
                        fields.append({'id': str(x.get('id') or 'text'),
                                       'name': str(x.get('name') or x.get('label') or ''),
                                       'tip': str(x.get('tip') or x.get('hint') or ''),
                                       'value': str(x.get('value') or '')})
        except Exception:
            fields = []
        if not fields:
            fields = [{'id': str(cfg.get('id') or 'text'), 'name': '', 'tip': '',
                       'value': str(cfg.get('value') or '')}]
        act = self._dlg_activity()
        if not act:
            self._dlg_log('没有 Activity，弹不了：%s' % cmd[:40])
            self._dlg_toast('弹窗打不开，先看 tmp/ui_dialog.log')
            return False
        try:
            from java import jclass, dynamic_proxy
            from java.lang import Runnable
            AlertDialog = jclass('android.app.AlertDialog')
            LinearLayout = jclass('android.widget.LinearLayout')
            TextView = jclass('android.widget.TextView')
            EditText = jclass('android.widget.EditText')
            ScrollView = jclass('android.widget.ScrollView')
            Color = jclass('android.graphics.Color')
            TypedValue = jclass('android.util.TypedValue')
            DialogInterface = jclass('android.content.DialogInterface')
            View = jclass('android.view.View')
            Button = jclass('android.widget.Button')
            _OnClick = DialogInterface.OnClickListener
            ui = {'ets': []}

            def _dp(v):
                try:
                    return int(TypedValue.applyDimension(1, float(v),
                               act.getResources().getDisplayMetrics()) + 0.5)
                except Exception:
                    return int(float(v) * 3)

            def _collect():
                out = {}
                for n, f in enumerate(fields):
                    try:
                        out[str(f.get('id') or ('f%d' % n))] = str(ui['ets'][n].getText().toString())
                    except Exception:
                        out[str(f.get('id') or ('f%d' % n))] = ''
                return out

            def _go(vals):
                def _work():
                    try:
                        payload = {'actionId': cmd, 'id': str(fields[0].get('id') or 'text'),
                                   'type': str(cfg.get('type') or 'input'),
                                   'value': (list(vals.values())[0] if len(vals) == 1 else vals),
                                   'input': [{'id': k, 'value': v} for k, v in vals.items()]}
                        self._dlg_log('提交 %s → %s' % (cmd[:40], json.dumps(vals, ensure_ascii=False)[:150]))
                        res = self._action_impl(json.dumps(payload, ensure_ascii=False))
                        self._dlg_toast(self._res_msg(res))
                    except Exception as e:
                        self._dlg_log('执行失败：%s' % e)
                        self._dlg_toast('执行失败：%s' % e)
                try:
                    import threading
                    threading.Thread(target=_work, daemon=True).start()
                except Exception:
                    _work()

            class _Pos(dynamic_proxy(_OnClick)):
                def __init__(s):
                    super().__init__()

                def onClick(s, dlg, which):
                    try:
                        vals = _collect()
                    except Exception:
                        vals = {}
                    try:
                        dlg.dismiss()
                    except Exception:
                        pass
                    _go(vals)

            class _Neg(dynamic_proxy(_OnClick)):
                def __init__(s):
                    super().__init__()

                def onClick(s, dlg, which):
                    try:
                        dlg.dismiss()
                    except Exception:
                        pass

            class _Browse(dynamic_proxy(_OnClick)):
                def __init__(s):
                    super().__init__()

                def onClick(s, dlg, which):
                    try:
                        cur = ''
                        try:
                            cur = str(ui['ets'][0].getText().toString()).strip()
                        except Exception:
                            pass
                        self._dlg_pick(act, cur or '/storage/emulated/0',
                                       lambda p: ui['ets'][0].setText(p))
                    except Exception as e:
                        self._dlg_log('浏览失败：%s' % e)

            class _Pick(dynamic_proxy(View.OnClickListener)):
                """字段旁边那个「选择…」：调起目录/文件浏览框"""

                def __init__(s, et, sd=''):
                    super().__init__()
                    s.et = et
                    s.sd = sd

                def onClick(s, v):
                    try:
                        cur = str(s.et.getText().toString()).strip()
                        _start = cur or '/storage/emulated/0'
                        try:
                            if os.path.isfile(_start):
                                _start = os.path.dirname(_start) or '/storage/emulated/0'
                        except Exception:
                            pass
                        self._dlg_pick(act, _start, lambda p: s.et.setText(p))
                    except Exception as e:
                        self._dlg_log('选择按钮失败：%s' % e)

            class _Show(dynamic_proxy(Runnable)):
                def __init__(s):
                    super().__init__()

                def run(s):
                    try:
                        sc = ScrollView(act)
                        lay = LinearLayout(act)
                        lay.setOrientation(1)
                        _pad = _dp(18)
                        lay.setPadding(_pad, _dp(8), _pad, _dp(4))
                        if msg:
                            tv = TextView(act)
                            tv.setText(str(msg))
                            tv.setTextSize(12.5)
                            tv.setTextColor(Color.rgb(117, 117, 117))
                            tv.setPadding(0, 0, 0, _dp(8))
                            lay.addView(tv)
                        ui['ets'] = []
                        for f in fields:
                            nm = str(f.get('name') or '')
                            tip = str(f.get('tip') or '')
                            if nm or tip:
                                tv2 = TextView(act)
                                tv2.setText(nm + (('　' + tip) if tip else ''))
                                tv2.setTextSize(12.0)
                                tv2.setTextColor(Color.rgb(96, 125, 139))
                                tv2.setPadding(0, _dp(4), 0, 0)
                                lay.addView(tv2)
                            et = EditText(act)
                            et.setText(str(f.get('value') or ''))
                            _sd = str(f.get('selectData') or '')
                            _need = self._dlg_needs_pick(f)
                            if _need:
                                _row = LinearLayout(act)
                                _row.setOrientation(0)
                                _row.addView(et, LinearLayout.LayoutParams(0, -2, 1.0))
                                _row.setGravity(16)
                                _bt = Button(act)
                                _bt.setText('选择…' if 'dir' in _sd.lower() or '目录' in (nm + tip) else '选文件…')
                                _row.addView(_bt, LinearLayout.LayoutParams(-2, -2))
                                lay.addView(_row)
                                _bt.setOnClickListener(_Pick(et, _sd))
                            else:
                                lay.addView(et)
                            ui['ets'].append(et)
                        sc.addView(lay)
                        b = AlertDialog.Builder(act)
                        b.setTitle(str(title))
                        b.setView(sc)
                        b.setPositiveButton('确定', _Pos())
                        b.setNegativeButton('取消', _Neg())
                        if len(fields) == 1:
                            _nm = str(fields[0].get('name') or '') + str(fields[0].get('tip') or '') + str(fields[0].get('id') or '')
                            if any(k in _nm for k in ('路径', '目录', '文件夹', '文件', '保存到', 'path', 'dir', 'file')):
                                b.setNeutralButton('浏览…', _Browse())
                        d = b.create()
                        try:
                            d.setCancelable(False)
                            d.setCanceledOnTouchOutside(False)
                        except Exception:
                            pass
                        d.show()
                        try:
                            ui['ets'][0].requestFocus()
                        except Exception:
                            pass
                        self._dlg_log('弹出输入框：%s（%d 个框）' % (str(title)[:40], len(fields)))
                    except Exception as e:
                        self._dlg_log('弹输入框失败：%s' % e)

            act.runOnUiThread(_Show())
            return True
        except Exception as e:
            self._dlg_log('输入框异常：%s' % e)
            self._dlg_toast('弹窗异常：%s' % e)
            return False

    def homeContent(self, filter=False):
        return self._dlg_fix_page(self._raw_homeContent(filter))

    def searchContent(self, key, quick=False, pg='1'):
        return self._dlg_fix_page(self._raw_searchContent(key, quick, pg))

    def categoryContent(self, tid, pg='1', filter=False, extend=None):
        return self._dlg_fix_page(self._raw_categoryContent(tid, pg, filter, extend))

    def detailContent(self, ids):
        return self._dlg_fix_page(self._raw_detailContent(ids))

    def action(self, action_str):
        """新写法：收到纯命令字符串；老写法：收到 JSON（内部调用/保留项），照旧回 dict"""
        _raw = action_str if isinstance(action_str, str) else str(action_str or '')
        _plain = bool(_raw) and not _raw.lstrip().startswith('{')
        if not _plain:
            try:
                return self._action_impl(_raw)
            except Exception as e:
                return {'toast': '动作出错：%s' % e}
        cmd = _raw.strip()
        self._dlg_log('动作：%s' % cmd[:90])
        try:
            cfg = self._act_map_load().get(cmd)
        except Exception:
            cfg = None
        if cfg and str(cfg.get('type') or '') in ('input', 'multiInput'):
            self._act_ask(cmd, cfg)
            return self._act_reply('在弹窗里填，填完点确定')
        _arg = json.dumps({'actionId': cmd}, ensure_ascii=False)
        if cfg and cfg.get('json'):
            _arg = str(cfg['json'])
        try:
            res = self._action_impl(_arg)
        except Exception as e:
            self._dlg_log('动作出错：%s' % e)
            return self._act_reply('出错：%s' % e)
        if isinstance(res, dict) and (isinstance(res.get('list'), list) or 'action' in res):
            # 页面（勾选状态、列表刷新）或者「让宿主开浏览器」这类指令：原样回（顺手把坏字节洗掉）
            return self._deep_safe(res)
        if res is None:
            # 不认识的命令：不弹气泡，也别回 None —— 这个壳收到 None 会直接报错
            return {'toast': ''}
        return self._act_reply(self._res_msg(res), res)

    def _act_reply(self, msg, res=None):
        """动作跑完回给壳的那一句。

        2026-11-11 v211：以前回的是 json 字符串（{"msg": "…"}）。这个壳（影视＋）拿到字符串后
        会先把它编码一遍再显示，屏幕上就变成 "{\"msg\": \"…\"}" 这样一串（用户截图那个）。
        壳对「对象」处理是正常的（页面、结果卡都是对象），所以这里改成：
        先自己弹一个干净的系统气泡（_nat_toast，真机上一直好使），回给壳的对象里不再带 msg，
        壳就不会再自己吐一句；气泡弹不出来时才退回老写法，至少还有提示。
        """
        _m = self._sdisp(str(msg or ''))
        if res is None:
            res = {'toast': _m}
        try:
            if self._nat_toast(_m):
                _out = dict(res) if isinstance(res, dict) else {'toast': _m}
                _out.pop('msg', None)
                _out['toast'] = _m
                return self._deep_safe(_out)
        except Exception as e:
            self._dlg_log('回话气泡弹不出：%s' % e)
        _out2 = dict(res) if isinstance(res, dict) else {}
        _out2['msg'] = _m
        return self._deep_safe(_out2)

    def _action_impl(self, action_str):
        try:
            if isinstance(action_str, str):
                try:
                    obj = json.loads(action_str)
                except:
                    if action_str.startswith(('http://', 'https://')):
                        return self.web_action_browser._open_url_action(action_str)
                    obj = {"action": action_str}
            else:
                obj = action_str
            act = obj.get('action', '') or obj.get('actionId', '')

            # 主题菜单里点了某一项：宿主会把那一行的文字当成动作 id 发回来
            _fpick = self._fc_menu_pick(act)
            if not _fpick:
                _fv = obj.get('value')
                if isinstance(_fv, dict) and _fv.get('menu'):
                    _fpick = self._fc_menu_pick(_fv.get('menu'))
                elif isinstance(_fv, str) and _fv.strip():
                    _fpick = self._fc_menu_pick(_fv)
            if _fpick:
                return self._fc_menu_do(_fpick[0], _fpick[1])

            # 内层 py 插件发出来的动作，先转给它自己处理
            if isinstance(obj, dict):
                _pl = str(obj.get('_pyplug') or '')
                if not _pl:
                    _aid = str(obj.get('actionId') or obj.get('action') or '')
                    if _aid:
                        _pl = self._pyplug_action_owner_map().get(_aid, '')
                if _pl:
                    _payload = self._pyplug_action_payload(obj)
                    return self._pyplug_action(_pl, json.dumps(_payload, ensure_ascii=False))

            if act == 'APK_INSTALL_SETTINGS':
                ok = self._apk_open_settings(obj.get('pkg') or '')
                return {'list': [{
                    'vod_id': 'apk_settings',
                    'vod_name': '⚙️ ' + ('已打开「安装未知应用」设置页' if ok else '没能打开设置页'),
                    'vod_pic': self._generate_colored_icon('#2196F3' if ok else '#F44336', '⚙'),
                    'vod_remarks': '把本应用的开关打开，然后回去重新点那个 APK' if ok else '请手动到 系统设置 → 应用 → 特殊权限 里打开',
                    'style': {'type': 'list'}, 'vod_player': '书'
                }], 'page': 1, 'pagecount': 1}
            
            # ========== 动作分类里加自定义源：电视直播 / 短视频 / 画廊（添加 / 设置 / 删除）==========
            for _ck, _cops in _CUSTOM_ACT.items():
                for _cop, _caid in _cops.items():
                    if act == _caid:
                        return self._custom_source_action(_ck, _cop, obj, act)

            if isinstance(act, str) and act.startswith('回收站切换|'):
                try:
                    _nm3 = self.b64u_decode(act.split('|', 1)[1])
                    _sel3 = self._trash_sel_set()
                    _show3 = re.sub(r'^\d+_', '', _nm3)
                    if _nm3 in _sel3:
                        _sel3.discard(_nm3)
                        return {'toast': '⬜ 取消：%s（已选 %d 个）' % (_show3, len(_sel3))}
                    _sel3.add(_nm3)
                    return {'toast': '☑️ 选中：%s（已选 %d 个）' % (_show3, len(_sel3))}
                except Exception as _e3:
                    return {'toast': '⚠️ 操作失败：%s' % _e3}
            if isinstance(act, str) and act.startswith('回收站恢复单个|'):
                try:
                    _p6 = self.b64u_decode(act.split('|', 1)[1])
                    _n6 = os.path.basename(_p6)
                    _mp6 = self._trash_map_load()
                    _orig6 = str(_mp6.get(_n6) or '')
                    _roots6 = [x for x in (getattr(self, 'root_paths', []) or []) if x]
                    _dst6 = _orig6 or os.path.join(_roots6[0] if _roots6 else '/storage/emulated/0/Download',
                                                   re.sub(r'^\d+_', '', _n6))
                    _pd6 = os.path.dirname(_dst6)
                    if _pd6 and not os.path.isdir(_pd6):
                        os.makedirs(_pd6, exist_ok=True)
                    if os.path.exists(_dst6):
                        _r6, _e6 = os.path.splitext(_dst6)
                        _dst6 = _r6 + '_恢复' + _e6
                    shutil.move(_p6, _dst6)
                    if _n6 in _mp6:
                        del _mp6[_n6]
                    self._trash_map_save(_mp6)
                    return {'list': [self._filop_card('↩️ 已恢复到：' + _dst6, os.path.dirname(_dst6),
                                                      icon_key='folder', raw_id=True,
                                                      link=self.FOLDER_PREFIX + self.b64u_encode(os.path.dirname(_dst6)))],
                            'page': 1, 'pagecount': 1, 'toast': '已恢复'}
                except Exception as _e6b:
                    return {'toast': '⚠️ 恢复失败：%s' % _e6b}
            if isinstance(act, str) and act.startswith('回收站彻底删除|'):
                try:
                    _p7 = self.b64u_decode(act.split('|', 1)[1])
                    if os.path.isdir(_p7):
                        shutil.rmtree(_p7, ignore_errors=True)
                    elif os.path.exists(_p7):
                        os.remove(_p7)
                    _mp7 = self._trash_map_load()
                    _mp7.pop(os.path.basename(_p7), None)
                    self._trash_map_save(_mp7)
                    return {'toast': '🗑️ 已彻底删除'}
                except Exception as _e7:
                    return {'toast': '⚠️ 删除失败：%s' % _e7}
            # ========== 服务器端口（2026-11-11 v203：上一版漏了这一段，点了等于没接）==========
            if act in ('服务器端口', '端口设置', '服务器端口刷新', '服务器端口手动'):
                _pv = ''
                if isinstance(obj, dict):
                    _pv = _web_port_normalize(obj.get('value', ''))
                if act == '服务器端口手动' and not str(_pv).strip():
                    try:
                        self._act_ask('服务器端口手动', {'type': 'input', 'id': 'text',
                                                        'title': '✍️ 手动填端口',
                                                        'msg': '填端口号；填 0 或留空＝改回自动找'})
                        return {'toast': '在弹窗里填，填完点确定'}
                    except Exception as _ae:
                        _web_port_log('弹输入框失败：%s' % _ae)
                        return {'toast': '输入框弹不出来，直接用端口页里那几个按钮'}
                if str(_pv).strip():
                    _ok, _msg = _web_port_apply(_pv)
                    _pg = _wport_page()
                    _pg['toast'] = _msg.split('\n')[0]
                    return _pg
                return _wport_page()
            if isinstance(act, str) and act.startswith('端口设置|'):
                _pv = act.split('|', 1)[1].strip()
                if _pv.lower() in ('auto', '0', '', '自动'):
                    _ok, _msg = _web_port_apply('')
                else:
                    _ok, _msg = _web_port_apply(_pv)
                _pg = _wport_page()
                _pg['toast'] = _msg.split('\n')[0]
                return _pg

            # ========== 磁力/电驴链接多选（2026-11-11 v202）==========
            if isinstance(act, str) and act.startswith('磁力'):
                _mres = self._magnet_action(act)
                if _mres is not None:
                    return _mres
            # ========== 选择模式：点一下切换，只弹提示，不刷新页面 ==========
            if isinstance(act, str) and act.startswith('文件操作切换|'):
                try:
                    _rest = act[len('文件操作切换|'):]
                    _dp, _, _tp = _rest.partition('|')
                    _dir = self.b64u_decode(_dp)
                    _tg = self.b64u_decode(_tp)
                    self._filop_do_verb('t:' + self.b64u_encode(_tg), _dir)
                    _msg = str(getattr(self, '_filop_msg', '') or '已切换')
                    if '已选' not in _msg and '已选 0' not in _msg:
                        _msg = '%s（这层共 %d 个）' % (_msg, len(self._filop_sel_set()))
                    # 能自己弹气泡就只回一句话：页面不动、可以接着点下一个
                    if self._nat_toast(_msg):
                        # 同上：气泡弹过了，别让壳再吐 json
                        return {'toast': _msg}
                    # 弹不出气泡时退回「整页 + toast」，至少提示还在
                    _tpage = self._filop_page(self.b64u_encode(_dir))
                    _tpage['toast'] = _msg
                    return _tpage
                except Exception as _tog_e:
                    return {'toast': '⚠️ 切换失败：%s' % _tog_e}
            if isinstance(act, str) and act.startswith('压缩包切换|'):
                try:
                    _rest = act[len('压缩包切换|'):]
                    _ap, _, _mp = _rest.partition('|')
                    _arc = self.b64u_decode(_ap)
                    _mem = self.b64u_decode(_mp)
                    _sset = self._zip_sel_set(_arc)
                    if _mem in _sset:
                        _sset.discard(_mem)
                        _msg = '⬜ 已取消 %s' % os.path.basename(_mem.rstrip('/'))
                    else:
                        _sset.add(_mem)
                        _msg = '☑️ 已选择 %s' % os.path.basename(_mem.rstrip('/'))
                    _nn = len([m for m in _sset if not m.endswith('/')])
                    _zdir = os.path.dirname(str(_mem).rstrip('/'))
                    if _zdir:
                        _zdir += '/'
                    _zpage = self._zip_page(self.ZIP_PREFIX + self.b64u_encode(_arc) + '|' + self.b64u_encode(_zdir))
                    _zpage['toast'] = _msg + '（已选 %d 个文件）' % _nn
                    return _zpage
                except Exception as _zt_e:
                    return {'toast': '⚠️ 切换失败：%s' % _zt_e}

            # ========== 文件操作：复制 / 剪切 / 删除 / 重命名 ==========
            if isinstance(act, str) and act.startswith(('文件操作复制|', '文件操作剪切|', '文件操作删除|', '文件操作重命名|')):
                try:
                    return self._filop_do_action(act, obj)
                except Exception as _fop_e:
                    try:
                        self.log('文件操作出错: %s' % _fop_e)
                    except Exception:
                        pass
                    return self._filop_result(False, '❌ 操作出错：%s' % _fop_e, '')

            if isinstance(act, str) and act.startswith('文件操作进入|'):
                try:
                    _go_path = self.b64u_decode(act.split('|', 1)[1])
                except Exception:
                    _go_path = ''
                if not _go_path or not os.path.exists(_go_path):
                    return {'list': [self._filop_card('❌ 这个路径打不开了', _go_path or '(空)', '#F44336', 'x')],
                            'page': 1, 'pagecount': 1}
                return self._filop_page(self.b64u_encode(_go_path))

            if isinstance(act, str) and act.startswith('文件操作删除选中|'):
                try:
                    _dd = self.b64u_decode(act.split('|', 1)[1])
                except Exception:
                    _dd = ''
                vals = self._pick_action_inputs(obj)
                if not str(vals.get('__text__') or '').strip():
                    self._filop_msg = '已取消，什么都没删'
                    return self._filop_list_page(_dd) if os.path.isdir(_dd) else {'list': [], 'page': 1, 'pagecount': 1}
                _sel = [p for p in sorted(self._filop_sel_set()) if os.path.exists(p)]
                if not _sel:
                    self._filop_msg = '⚠️ 还没选文件'
                    return self._filop_list_page(_dd) if os.path.isdir(_dd) else {'list': [], 'page': 1, 'pagecount': 1}
                ok = 0
                fail = 0
                for _p in _sel:
                    try:
                        _ok1, _m1 = (self._delete_folder_to_trash(_p) if os.path.isdir(_p)
                                     else self._delete_to_trash(_p))
                        ok += 1 if _ok1 else 0
                        fail += 0 if _ok1 else 1
                    except Exception:
                        fail += 1
                self._filop_sel_set().clear()
                self._filop_dirs().clear()
                _back = getattr(self, 'select_mode_dir', None) or _dd
                try:
                    self._disable_select_mode()
                except Exception:
                    pass
                self._filop_msg = ''
                _msg = '🗑️ 已移进回收站 %d 个%s' % (ok, ('，失败 %d 个' % fail) if fail else '')
                if os.path.isdir(_back):
                    return self._filop_jump(_back, _msg)
                if os.path.isdir(_dd):
                    return self._filop_jump(_dd, _msg)
                return {'list': [self._filop_card('🗑️ 已删除 %d 个' % ok, '', '#4CAF50', 'v')], 'page': 1, 'pagecount': 1}

            if isinstance(act, str) and act.startswith('文件操作批量选|'):
                try:
                    _bd = self.b64u_decode(act.split('|', 1)[1])
                except Exception:
                    _bd = ''
                if not os.path.isdir(_bd):
                    return {'list': [self._filop_card('❌ 这个文件夹打不开了', _bd, '#F44336', 'x')], 'page': 1, 'pagecount': 1}
                vals = self._pick_action_inputs(obj)
                words = [w.strip().lower() for w in str(vals.get('__text__') or '').replace('，', ' ').split() if w.strip()]
                if not words:
                    self._filop_msg = '没输入关键词，什么都没选'
                    return self._filop_list_page(_bd)
                sel = self._filop_sel_set()
                hit = 0
                try:
                    for _n in sorted(os.listdir(_bd)):
                        _p = os.path.join(_bd, _n)
                        if not os.path.isfile(_p):
                            continue
                        if any(w in _n.lower() for w in words):
                            if _p not in sel:
                                sel.add(_p)
                            hit += 1
                except Exception as _be:
                    self._filop_msg = '⚠️ 选的时候出错：%s' % _be
                    return self._filop_list_page(_bd)
                self._filop_msg = ('🔢 按「%s」选中 %d 个，现在一共 %d 个' % (' '.join(words), hit, len(sel))) if hit else ('没找到名字带「%s」的文件' % ' '.join(words))
                return self._filop_list_page(_bd)

            if isinstance(act, str) and act.startswith('文件操作选中|'):
                try:
                    _op = self.b64u_decode(act.split('|', 1)[1])
                except Exception:
                    _op = ''
                vals = self._pick_action_inputs(obj)
                if not str(vals.get('__text__') or '').strip():
                    return {'toast': '取消，没动'}
                if not _op or not os.path.exists(_op):
                    return {'toast': '这个文件已经不在了'}
                sel = self._filop_sel_set()
                if _op in sel:
                    sel.discard(_op)
                    return {'toast': '⬜ 已取消 %s（已选 %d 个）' % (os.path.basename(_op)[:16], len(sel))}
                sel.add(_op)
                return {'toast': '☑️ 已选 %s（已选 %d 个）' % (os.path.basename(_op)[:16], len(sel))}

            if isinstance(act, str) and (act.startswith('解压全部|') or act.startswith('解压这个|')):
                try:
                    _kind, _rest = act.split('|', 1)
                    _p = _rest.split('|')
                    _arc = self.b64u_decode(_p[0])
                    _mem = self.b64u_decode(_p[1]) if len(_p) > 1 else ''
                    if _kind == '解压全部':
                        _lab = '这个位置里的全部内容' if _mem else '整个压缩包'
                    else:
                        _lab = os.path.basename(_mem)
                    _vals = self._pick_action_inputs(obj)
                    _dest = str(_vals.get('__text__') or '').strip()
                    self._zip_log('收到解压请求 kind=%s arc=%s 输入=%r' % (_kind, _arc, _dest))
                    if not _dest:
                        _dest = os.path.join(os.path.dirname(_arc) or '/',
                                             os.path.splitext(os.path.basename(_arc))[0] or '解压结果')
                        self._zip_log('没拿到路径，改用默认 %s' % _dest)
                    if not os.path.isfile(_arc):
                        return {'list': [self._filop_card('❌ 压缩包不在了', _arc, '#F44336', 'x')], 'page': 1, 'pagecount': 1}
                    _n, _out = self._zip_extract(_arc, _mem, _dest)
                    self._zip_log('完成 %d 个 -> %s' % (_n, _out))
                    return self._zip_jump(_out, _n)
                except Exception as _xe:
                    return {'list': [self._filop_card('❌ 解压失败', str(_xe), '#F44336', 'x')], 'page': 1, 'pagecount': 1}

            if isinstance(act, str) and act.startswith('解压直取|'):
                try:
                    _p = act.split('|')[1:]
                    _arc = self.b64u_decode(_p[0]) if len(_p) > 0 else ''
                    _mem = self.b64u_decode(_p[1]) if len(_p) > 1 else ''
                    _dst = self.b64u_decode(_p[2]) if len(_p) > 2 else ''
                    self._zip_log('直取解压 arc=%s 到 %s' % (_arc, _dst))
                    if not os.path.isfile(_arc):
                        return {'toast': '压缩包不在了', 'list': [self._filop_card('❌ 压缩包不在了', _arc, '#F44336', 'x')], 'page': 1, 'pagecount': 1}
                    _n, _out = self._zip_extract(_arc, _mem, _dst)
                    self._zip_log('完成 %d 个 -> %s' % (_n, _out))
                    return self._zip_jump(_out, _n)
                except Exception as _xe:
                    self._zip_log('直取失败 %s' % _xe)
                    return {'toast': '解压失败：%s' % _xe, 'list': [self._filop_card('❌ 解压失败', str(_xe), '#F44336', 'x')], 'page': 1, 'pagecount': 1}

            if isinstance(act, str) and act.startswith('压缩包选文件夹|'):
                try:
                    _p = act.split('|')[1:]
                    _arc = self.b64u_decode(_p[0]) if _p else ''
                    _key = self.b64u_decode(_p[1]) if len(_p) > 1 else ''
                    _vals = self._pick_action_inputs(obj)
                    if not str(_vals.get('__text__') or '').strip():
                        return {'toast': '取消，没动'}
                    _sel = self._zip_sel_set(_arc)
                    if _key in _sel:
                        _sel.discard(_key)
                        _msg = '⬜ 已取消 %s' % _key.rstrip('/').split('/')[-1]
                    else:
                        _sel.add(_key)
                        _msg = '☑️ 已选中文件夹 %s' % _key.rstrip('/').split('/')[-1]
                    _nf = len([m for m in _sel if not m.endswith('/')])
                    _nd = len([m for m in _sel if m.endswith('/')])
                    return {'toast': '%s（已选 %d 个文件、%d 个文件夹）' % (_msg, _nf, _nd)}
                except Exception as _e:
                    return {'toast': '选中失败：%s' % _e}

            if isinstance(act, str) and act.startswith('压缩包全选文件夹|'):
                try:
                    _p = act.split('|')[1:]
                    _arc = self.b64u_decode(_p[0]) if _p else ''
                    _basep = self.b64u_decode(_p[1]) if len(_p) > 1 else ''
                    _sel = self._zip_sel_set(_arc)
                    _entries = self._zip_entries(_arc)
                    _ds = set()
                    for _fn, _s, _isd in _entries:
                        if not _fn.startswith(_basep):
                            continue
                        _r = _fn[len(_basep):].lstrip('/')
                        if '/' in _r or _isd:
                            _t = _r.split('/')[0]
                            if _t:
                                _ds.add(_basep + _t + '/')
                    _sel.update(_ds)
                    return {'toast': '☑️ 已勾上 %d 个文件夹（共选 %d 个）' % (len(_ds), len(_sel))}
                except Exception as _e:
                    return {'toast': '全选失败：%s' % _e}

            if isinstance(act, str) and act.startswith('压缩包选中|'):
                try:
                    _p = act.split('|')[1:]
                    _arc = self.b64u_decode(_p[0]) if _p else ''
                    _m = self.b64u_decode(_p[1]) if len(_p) > 1 else ''
                    _vals = self._pick_action_inputs(obj)
                    if not str(_vals.get('__text__') or '').strip():
                        return {'toast': '取消，没动'}
                    _sel = self._zip_sel_set(_arc)
                    if _m in _sel:
                        _sel.discard(_m)
                        _msg = '⬜ 已取消 %s（已选 %d 个）' % (os.path.basename(_m), len(_sel))
                    else:
                        _sel.add(_m)
                        _msg = '☑️ 已选 %s（已选 %d 个）' % (os.path.basename(_m), len(_sel))
                    return {'toast': _msg}
                except Exception as _e:
                    return {'toast': '选中失败：%s' % _e}

            if isinstance(act, str) and act.startswith('解压选中|'):
                try:
                    _arc = self.b64u_decode(act.split('|', 1)[1])
                    _sel = self._zip_sel_set(_arc)
                    _members = sorted(_sel)
                    _vals = self._pick_action_inputs(obj)
                    _dest = str(_vals.get('__text__') or '').strip()
                    self._zip_log('解压选中 %d 个 -> %r' % (len(_members), _dest))
                    if not _members:
                        return {'toast': '还没选中任何文件', 'list': [self._filop_card('ℹ️ 还没选中文件', '先点文件把它勾上', '#FF9800', 'i')], 'page': 1, 'pagecount': 1}
                    if not os.path.isfile(_arc):
                        return {'toast': '压缩包不在了', 'list': [self._filop_card('❌ 压缩包不在了', _arc, '#F44336', 'x')], 'page': 1, 'pagecount': 1}
                    if not _dest:
                        _dest = os.path.join(os.path.dirname(_arc) or '/',
                                             os.path.splitext(os.path.basename(_arc))[0] or '解压结果')
                    _n, _out = self._zip_extract(_arc, '', _dest, members=_members)
                    _sel.clear()
                    self._zip_log('选中解压完成 %d -> %s' % (_n, _out))
                    return self._zip_jump(_out, _n)
                except Exception as _xe:
                    self._zip_log('选中解压失败 %s' % _xe)
                    return {'toast': '解压失败：%s' % _xe, 'list': [self._filop_card('❌ 解压失败', str(_xe), '#F44336', 'x')], 'page': 1, 'pagecount': 1}

            if isinstance(act, str) and act.startswith('文本复制|'):
                try:
                    _p = self.b64u_decode(act.split('|', 1)[1])
                    _t, _e = self._edit_read(_p)
                    _ok = self._pyplug_copy_text(_t)
                    self._edit_msg = '全文已复制到剪贴板' if _ok else '复制失败'
                    _res = self._edit_page(_p)
                    _res['toast'] = '全文已复制，去记事本粘贴即可' if _ok else '复制失败，剪贴板不可用'
                    return _res
                except Exception as _ee:
                    return {'toast': '复制失败：%s' % _ee}

            if isinstance(act, str) and act.startswith('系统打开文本|'):
                try:
                    _p = self.b64u_decode(act.split('|', 1)[1])
                    _st, _msg = self._open_text_app(_p)
                    self._edit_msg = _msg
                    _res = self._edit_page(_p)
                    _res['toast'] = _msg
                    return _res
                except Exception as _ee:
                    self._text_log('系统打开异常: %s' % _ee)
                    return {'toast': '调不起来：%s' % _ee}

            if isinstance(act, str) and act.startswith('文本行改|'):
                try:
                    _parts = act.split('|')
                    _path = self.b64u_decode(_parts[1])
                    _off = int(_parts[2]) if len(_parts) > 2 else 0
                    _vals = obj.get('input') if isinstance(obj, dict) else None
                    _fields = {}
                    if isinstance(_vals, list):
                        for _it in _vals:
                            if isinstance(_it, dict):
                                _fields[str(_it.get('id') or '')] = _it.get('value')
                    if not _fields:
                        _fields = dict(self._pick_action_inputs(obj) or {})
                        _fields.pop('__text__', None)
                    _text, _enc = self._edit_read(_path)
                    _lines = _text.split('\n')
                    _n = 0
                    for _k, _v in _fields.items():
                        if _k.startswith('l') and _k[1:].isdigit():
                            _idx = _off + int(_k[1:])
                            if _idx < len(_lines):
                                _nv = '' if _v is None else str(_v)
                                if _nv != _lines[_idx]:
                                    _lines[_idx] = _nv
                                    _n += 1
                    _extra = str(_fields.get('__extra__') or '')
                    if _extra:
                        if _lines and _lines[-1] == '':
                            _lines[-1] = _extra
                        else:
                            _lines.append(_extra)
                    self._edit_write(_path, '\n'.join(_lines), _enc)
                    self._edit_msg = '已保存 · 这一段改了 %d 行' % _n
                    _res = self._edit_page(_path)
                    _res['toast'] = '已保存（改了 %d 行）' % _n
                    return _res
                except Exception as _ee:
                    return {'toast': '没改成：%s' % _ee}

            if isinstance(act, str) and act.startswith(('文件内搜条目|', '文件内搜频道|')):
                try:
                    _live_mode = act.startswith('文件内搜频道|')
                    _fp = self.b64u_decode(act.split('|', 1)[1])
                    try:
                        self._search_log('收到动作 %s' % json.dumps(obj, ensure_ascii=False)[:900])
                    except Exception:
                        pass
                    _kw = self._search_read_kw(obj)
                    if not _kw:
                        self._search_log('没读到关键词（见上面那行 obj）')
                        return {'toast': '没读到关键词，看 /storage/emulated/0/tmp/file_search.log'}
                    self._search_state_set(_fp, 'live' if _live_mode else 'db', _kw)
                    _page = self._live_search_page(_fp, _kw, 1) if _live_mode else self._db_search_page(_fp, _kw, 1)
                    try:
                        _page['refresh'] = 1
                        _page['toast'] = '搜到 %s 条「%s」' % (_page.get('total'), _kw)
                    except Exception:
                        pass
                    try:
                        self._search_log('搜「%s」%s → 命中 %s 条' % (_kw, '频道' if _live_mode else '视频', _page.get('total')))
                    except Exception:
                        pass
                    return _page
                except Exception as _se:
                    try:
                        self._search_log('搜索异常 %s' % _se)
                    except Exception:
                        pass
                    return {'toast': '搜索失败：%s' % _se}

            if isinstance(act, str) and act.startswith('文本查找|'):
                try:
                    _path = self.b64u_decode(act.split('|', 1)[1])
                    _vals = self._pick_action_inputs(obj)
                    _kw = str(_vals.get('__text__') or '').strip()
                    if not _kw:
                        _res = self._edit_page(_path)
                        _res['toast'] = '没输入关键词'
                        return _res
                    return self._edit_by_keyword(_path, _kw)
                except Exception as _ee:
                    return {'toast': '查找失败：%s' % _ee}

            if isinstance(act, str) and act.startswith(('文本改写|', '文本追加|', '文本换行|', '文本删行|', '文本替换|')):
                try:
                    _kind_map = {'文本改写|': 'set', '文本追加|': 'append', '文本换行|': 'replace_line',
                                 '文本删行|': 'del_line', '文本替换|': 'swap'}
                    _kind = ''
                    _b64p = ''
                    for _k, _v in _kind_map.items():
                        if act.startswith(_k):
                            _kind = _v
                            _b64p = act[len(_k):]
                            break
                    _path = self.b64u_decode(_b64p)
                    _vals = self._pick_action_inputs(obj)
                    _txt = str(_vals.get('__text__') or '')
                    if not _txt.strip():
                        self._edit_msg = '取消，没改'
                        return self._edit_page(_path)
                    _n = self._edit_apply(_path, _kind, _txt)
                    self._edit_msg = '已保存 · 现在 %d 行' % _n
                    _res = self._edit_page(_path)
                    _res['toast'] = '已保存（%d 行）' % _n
                    return _res
                except Exception as _ee:
                    self._edit_msg = '没改成：%s' % _ee
                    try:
                        _res = self._edit_page(self.b64u_decode(act.split('|', 1)[1]))
                        _res['toast'] = '没改成：%s' % _ee
                        return _res
                    except Exception:
                        return {'toast': '没改成：%s' % _ee}

            if isinstance(act, str) and act.startswith('文件操作选文件夹|'):
                try:
                    _p = act.split('|')[1:]
                    _cur = self.b64u_decode(_p[0]) if _p else ''
                    _full = self.b64u_decode(_p[1]) if len(_p) > 1 else ''
                    _vals = self._pick_action_inputs(obj)
                    if not str(_vals.get('__text__') or '').strip():
                        return {'toast': '取消，没动'}
                    _ds = self._filop_dirs()
                    if _full in _ds:
                        _ds.discard(_full)
                        return {'toast': '⬜ 已取消 %s（已勾 %d 个文件夹）' % (os.path.basename(_full), len(_ds))}
                    _ds.add(_full)
                    return {'toast': '☑️ 已勾上 %s（共 %d 个文件夹）' % (os.path.basename(_full), len(_ds))}
                except Exception as _e:
                    return {'toast': '勾选失败：%s' % _e}

            if act == '文件操作无动作':
                return {'list': [self._filop_card('ℹ️ 这一格只是提示', '点下面的文件夹或文件', '#2196F3', 'i')],
                        'page': 1, 'pagecount': 1}

            if act == '文件操作入口':
                _start_dir = ''
                for _one_root in self.root_paths:
                    if os.path.isdir(_one_root):
                        _start_dir = _one_root
                        break
                if not _start_dir:
                    return {'list': [self._filop_card('❌ 没有可用的根目录', '去首页加一个常用路径', '#F44336', 'x')],
                            'page': 1, 'pagecount': 1}
                return self._filop_page(self.b64u_encode(_start_dir))

            # ========== 界面排列：网格 / 列表 切换 ==========
            if act == '排列切换':
                _new_mode = ViewModeConfig.toggle()
                _is_list = (_new_mode == VIEW_MODE_LIST)
                _label = '📋 列表排列' if _is_list else '🖼 网格排列'
                return {
                    'toast': '已切到' + _label,
                    'list': [{
                        'vod_id': 'action_result',
                        'vod_name': '🔀 已切换到' + _label,
                        'vod_pic': self._generate_colored_icon('#2196F3', '≡' if _is_list else '▦'),
                        'vod_remarks': '所有分类页、文件页、py 页都跟着变；返回上一页再进就生效',
                        'style': {'type': 'list'},
                        'vod_player': '书'
                    }],
                    'page': 1, 'pagecount': 1, 'limit': 1, 'total': 1
                }

            # ========== 封面自检 ==========
            if act == '封面自检':
                return self._cover_selftest()

            if act == '封面诊断':
                return self._cover_diag_list()

            if act == '封面缓存体检':
                return self._cover_cache_audit()

            # ========== 磁力链接设置 ==========
            if act == '磁力链接设置':
                input_text = obj.get('url', '') or obj.get('value', '')
                if isinstance(input_text, dict):
                    input_text = input_text.get('text', '')
                if input_text and input_text.strip():
                    try:
                        new_count = int(input_text.strip())
                        if 10 <= new_count <= 5000:
                            global MAX_MAGNET_ITEMS
                            MAX_MAGNET_ITEMS = new_count
                            MagnetConfigManager.set_max_items(new_count)
                            self.dir_cache.clear()
                            self.dir_cache_time.clear()
                            return {
                                'list': [{
                                    'vod_id': 'action_result',
                                    'vod_name': f'✅ 磁力链接数量已设置为: {new_count} 条',
                                    'vod_pic': self._generate_colored_icon("#4CAF50", "✓"),
                                    'vod_remarks': f'每次最多读取 {new_count} 条磁力链接\n已保存到配置文件，重启后仍然有效',
                                    'style': {'type': 'list'},
                                    'vod_player': '书'
                                }],
                                'page': 1,
                                'pagecount': 1
                            }
                        else:
                            return {
                                'list': [{
                                    'vod_id': 'action_result',
                                    'vod_name': '❌ 数量范围: 10 ~ 5000',
                                    'vod_pic': self._generate_colored_icon("#F44336", "✗"),
                                    'vod_remarks': '请输入 10-5000 之间的数字',
                                    'style': {'type': 'list'},
                                    'vod_player': '书'
                                }],
                                'page': 1,
                                'pagecount': 1
                            }
                    except ValueError:
                        return {
                            'list': [{
                                'vod_id': 'action_result',
                                'vod_name': '❌ 请输入有效的数字',
                                'vod_pic': self._generate_colored_icon("#F44336", "✗"),
                                'vod_remarks': f'当前值: {MagnetConfigManager.get_max_items()}',
                                'style': {'type': 'list'},
                                'vod_player': '书'
                            }],
                            'page': 1,
                            'pagecount': 1
                        }
                else:
                    return {
                        'actionId': '单项输入',
                        'id': 'text',
                        'type': 'input',
                        'title': '🧲 磁力链接设置',
                        'tip': f'当前每次读取 {MagnetConfigManager.get_max_items()} 条\n请输入新数量 (10-5000)',
                        'value': str(MagnetConfigManager.get_max_items()),
                        'msg': '请输入磁力链接最大读取数量'
                    }
            
            # ========== 磁力读取模式切换 ==========
            if act == '磁力读取模式':
                current_mode = MagnetConfigManager.get_read_mode()
                if current_mode == MAGNET_READ_MODE_ORDER:
                    MagnetConfigManager.set_read_mode(MAGNET_READ_MODE_RANDOM)
                    new_mode_display = "🎲 随机"
                    mode_desc = "每次打开磁力文件时，从所有链接中随机抽取指定数量的链接"
                else:
                    MagnetConfigManager.set_read_mode(MAGNET_READ_MODE_ORDER)
                    new_mode_display = "📋 顺序"
                    mode_desc = "每次打开磁力文件时，从开头顺序读取指定数量的链接"
                
                global MAGNET_READ_MODE
                MAGNET_READ_MODE = MagnetConfigManager.get_read_mode()
                
                self.dir_cache.clear()
                self.dir_cache_time.clear()
                self.audio_list_cache.clear()
                self.audio_list_cache_time.clear()
                
                return {
                    'list': [{
                        'vod_id': 'action_result',
                        'vod_name': f'✅ 磁力读取模式已切换为: {new_mode_display}',
                        'vod_pic': self._generate_colored_icon("#4CAF50", "🔄"),
                        'vod_remarks': f'{mode_desc}\n当前数量: {MagnetConfigManager.get_max_items()} 条\n已保存到配置文件，重启后仍然有效',
                        'style': {'type': 'list'},
                        'vod_player': '书'
                    }],
                    'page': 1,
                    'pagecount': 1
                }
            
            # ========== 其他动作 ==========
            if act == '单项输入':
                if self.pending_rename_path:
                    new_name = obj.get('url', '') or obj.get('value', '')
                    if isinstance(new_name, dict):
                        new_name = new_name.get('text', '')
                    elif isinstance(new_name, str):
                        new_name = new_name.strip()
                    if new_name:
                        old_path = self.pending_rename_path
                        old_name = os.path.basename(old_path)
                        is_dir = self.pending_rename_is_dir
                        if is_dir:
                            new_full_name = new_name
                        else:
                            old_ext = os.path.splitext(old_name)[1]
                            new_full_name = new_name + old_ext
                        new_path = os.path.join(os.path.dirname(old_path), new_full_name)
                        if os.path.exists(new_path):
                            self.pending_rename_path = None
                            self.pending_rename_is_dir = False
                            return {
                                "action": {
                                    "actionId": "toast",
                                    "msg": f"❌ 目标已存在: {new_full_name}"
                                }
                            }
                        try:
                            os.rename(old_path, new_path)
                            old_dir = os.path.dirname(old_path)
                            self.dir_cache.pop(f"dir_{old_dir}", None)
                            self.dir_cache_time.pop(f"dir_{old_dir}", None)
                            if is_dir:
                                self.dir_cache.pop(f"dir_{old_path}", None)
                                self.dir_cache_time.pop(f"dir_{old_path}", None)
                                self.audio_list_cache.pop(old_path, None)
                                self.audio_list_cache_time.pop(old_path, None)
                            if old_path in self.selected_items:
                                self.selected_items.remove(old_path)
                                self.selected_items.append(new_path)
                            if self.select_mode_dir == old_path:
                                self.select_mode_dir = new_path
                            self.pending_rename_path = None
                            self.pending_rename_is_dir = False
                            type_text = "文件夹" if is_dir else "文件"
                            return {
                                "action": {
                                    "actionId": "重命名成功",
                                    "msg": f"✅ 重命名{type_text}成功: {old_name} → {new_full_name}"
                                }
                            }
                        except Exception as e:
                            self.pending_rename_path = None
                            self.pending_rename_is_dir = False
                            return {
                                "action": {
                                    "actionId": "toast",
                                    "msg": f"❌ 重命名失败: {str(e)}"
                                }
                            }
                    else:
                        self.pending_rename_path = None
                        self.pending_rename_is_dir = False
                        return {
                            "action": {
                                "actionId": "toast",
                                "msg": "❌ 名称不能为空"
                            }
                        }
                else:
                    url = obj.get('url', '') or obj.get('value', '')
                    if isinstance(url, dict):
                        url = url.get('text', '')
                    if url and url.strip():
                        if not url.startswith(('http://', 'https://')):
                            url = 'https://' + url
                        return self.web_action_browser._open_url_action(url, '打开的网页')
                    else:
                        tip = obj.get('tip', '请输入网址')
                        title = obj.get('title', '🌐 访问网址')
                        return {
                            'actionId': '单项输入',
                            'id': 'text',
                            'type': 'input',
                            'title': title,
                            'tip': tip,
                            'value': '',
                            'msg': '请输入'
                        }
            
            if isinstance(act, str) and act.startswith('OPEN_URL|'):
                _pp = act.split('|')
                url = self.b64u_decode(_pp[1]) if len(_pp) > 1 else ''
                _ttl = self.b64u_decode(_pp[2]) if len(_pp) > 2 else ''
                if url:
                    if self._webview_open(url, _ttl):
                        return {'toast': '🌐 已用全屏浏览器打开：%s' % (_ttl or url)[:40]}
                    if self._sys_open_url(url, _ttl):
                        return {'toast': '🌐 已交给系统浏览器打开：%s' % (_ttl or url)[:40]}
                    return self.web_action_browser._open_url_action(url, _ttl)

            if act == 'OPEN_URL':
                url = obj.get('url', '')
                if url:
                    if self._webview_open(url, obj.get('title', '')):
                        return {'toast': '🌐 已用全屏浏览器打开：%s' % str(url)[:40]}
                    if self._sys_open_url(url, obj.get('title', '')):
                        return {'toast': '🌐 已交给系统浏览器打开：%s' % str(url)[:40]}
                    _tt = obj.get('title', '')
                    if self._webview_open(url, _tt):
                        return {'toast': '🌐 已用全屏浏览器打开：%s' % (_tt or url)[:40]}
                    return self.web_action_browser._open_url_action(url, _tt)
            
            if act == '添加常用路径':
                vals = self._pick_action_inputs(obj)
                name = self._common_path_tidy(vals.get('name') or '')
                pth = self._common_path_tidy(vals.get('path') or vals.get('folder') or vals.get('dir') or '')
                text = str(vals.get('__text__') or '')
                if not pth and text:
                    if '@' in text:
                        _n, _p = text.split('@', 1)
                        name = name or self._common_path_tidy(_n)
                        pth = self._common_path_tidy(_p)
                    else:
                        pth = self._common_path_tidy(text)
                if not pth:
                    return {
                        'actionId': '添加常用路径',
                        'type': 'multiInput',
                        'title': '➕ 添加常用路径',
                        'msg': '选一个文件夹，给它起个名字',
                        'input': self._path_pick_inputs(False)
                    }
                if not pth:
                    return self._common_path_card(False, '❌ 路径是空的\n\n请按 名称@路径 的格式填写')
                if not pth.startswith('/') and ':' not in pth:
                    pth = '/storage/emulated/0/' + pth.lstrip('/')
                if pth.endswith('/') and len(pth) > 1:
                    pth = pth.rstrip('/')
                if not name:
                    name = os.path.basename(pth) or pth
                paths = self.web_action_browser._load_common_paths_static()
                for it in paths:
                    if it['path'] == pth:
                        return self._common_path_card(False, '❌ 这个路径已经在了\n\n📌 %s\n📂 %s' % (it['name'], pth))
                paths.append({'name': name, 'path': pth})
                saved = self.web_action_browser._save_common_paths_static(paths)
                exists = os.path.isdir(pth)
                msg = ('✅ 已添加常用路径\n\n📌 %s\n📂 %s' % (name, pth))
                if not exists:
                    msg += '\n\n⚠️ 这个路径现在还不存在，插卡后会自动出现'
                if not saved:
                    msg += '\n\n⚠️ 保存失败，重启宿主后可能丢失'
                return self._common_path_card(True, msg)

            if act in ('添加主题', '添加文件夹封面'):
                vals = self._pick_action_inputs(obj)
                name = str(vals.get('name') or vals.get('theme') or '').strip()
                link = str(vals.get('url') or vals.get('link') or '').strip()
                if not link:
                    _raw = obj.get('value')
                    _t = ''
                    if isinstance(_raw, str):
                        _t = _raw
                    elif isinstance(_raw, dict):
                        _t = str(_raw.get('text') or _raw.get('input') or _raw.get('value') or '')
                    _t = str(_t or '').replace('\n', ' ').replace('\r', ' ').strip().strip('"').strip("'")
                    if _t:
                        if '@' in _t:
                            _n, _l = _t.split('@', 1)
                            name = name or _n.strip()
                            link = _l.strip()
                        else:
                            link = _t.split()[0]
                link = str(link or '').strip().strip('"').strip("'")
                if link:
                    link = link.split()[0]
                self._fc_log('收到主题 名字=%r 链接=%r' % (name, link))
                rows_all, _idx_now = self.web_action_browser._folder_cover_get()
                _n_b = len([1 for _r in rows_all if _r.get('builtin')])
                if not link:
                    return {
                        'actionId': '添加主题',
                        'type': 'multiInput',
                        'title': '🖼️ 添加主题',
                        'msg': '名字随便起，之后在主题列表里好认；链接要 http 开头',
                        'input': [{'id': 'name', 'name': '主题名字', 'tip': '留空就是「主题N」', 'value': name or ''},
                                  {'id': 'url', 'name': '主题图片链接', 'tip': 'http 或 https 开头', 'value': ''}]
                    }
                if not link.lower().startswith(('http://', 'https://')):
                    link = 'https://' + link.lstrip('/')
                for _r in rows_all:
                    if str(_r.get('url') or '').strip() == link:
                        _nm0 = str(_r.get('name') or '').strip() or '某个主题'
                        return self._common_path_card(False, '⚠️ 这张已经有了（%s）\n\n现在一共 %d 个主题' % (
                            _nm0, len(rows_all)))
                local = self.web_action_browser._cover_cache_one(link)
                if not name:
                    name = '主题%d' % (len(rows_all) - _n_b + 1)
                rows_all.append({'name': name, 'url': link, 'local': local or ''})
                ok = self.web_action_browser._folder_cover_save(rows_all, _idx_now)
                self._fc_pic_at = 0
                self._fc_pic_val = ''
                self._fc_log('加主题 名字=%s 链接=%s 缓存=%s 保存=%s 自己加=%d' % (
                    name, link, local or '无', ok, len(rows_all) - _n_b))
                msg = '✅ 已加主题「%s」\n\n内置 %d 个，自己加了 %d 个\n%s' % (
                    name, _n_b, len(rows_all) - _n_b,
                    '图已存到手机' if local else '图没下载下来，先用链接显示（不影响用）')
                if not ok:
                    msg += '\n\n⚠️ 保存失败，重启宿主后可能丢'
                return self._common_path_card(True, msg)

            if act in ('主题切换', '文件夹封面切换'):
                rows, idx = self.web_action_browser._folder_cover_get()
                self._fc_log('切换菜单：共 %d 张，当前第 %d 张' % (len(rows), idx + 1))
                if rows:
                    return self._fc_menu_card('文件夹封面切换', '🔀 点哪个就换成哪个', rows, '▶')
                _paths = self.web_action_browser._load_common_paths_static()
                _moved = []
                for _it in _paths:
                    _cs = _it.get('covers') if isinstance(_it.get('covers'), list) else []
                    if not _cs:
                        _c0 = str(_it.get('cover') or '').strip()
                        _cs = [_c0] if _c0 else []
                    if len(_cs) < 2:
                        continue
                    try:
                        _i = int(_it.get('cover_idx') or 0)
                    except Exception:
                        _i = 0
                    _i = (_i + 1) % len(_cs)
                    _it['cover_idx'] = _i
                    _it['cover'] = _cs[0]
                    _moved.append('%s → %d/%d' % (_it.get('name'), _i + 1, len(_cs)))
                if _moved:
                    _ok = self.web_action_browser._save_common_paths_static(_paths)
                    return self._common_path_card(_ok, '✅ 换成各文件夹自己的下一张\n\n' + '\n'.join(_moved))
                return self._common_path_card(False, '⚠️ 还没加过文件夹封面\n\n先用「🖼️ 添加文件夹封面」加一张')

            if act in ('删除主题', '删除文件夹封面'):
                rows, idx = self.web_action_browser._folder_cover_get()
                if not rows:
                    return self._common_path_card(False, '⚠️ 现在一张文件夹封面都没有')
                self._fc_log('删除菜单：共 %d 张' % len(rows))
                return self._fc_menu_card('删除文件夹封面', '🗑️ 点哪个就删哪个', rows, '✕')

            if act == 'py封面链接':
                raw = obj.get('value', '') or obj.get('url', '') or ''
                if isinstance(raw, dict):
                    raw = raw.get('text', '') or raw.get('input', '') or raw.get('value', '') or ''
                link = str(raw or '').replace('\n', ' ').replace('\r', ' ').strip().strip('"').strip("'")
                link = link.split()[0] if link.split() else ''
                if not link:
                    ok = self.web_action_browser._py_cover_api_set('')
                    self._fc_log('py封面链接 恢复默认')
                    return self._common_path_card(ok, '✅ 已恢复默认链接\n\n🎨 ' + PYPLUG_CAT_WALLPAPER_API
                                                  if ok else '⚠️ 没保存上，重启宿主后可能还原')
                if not link.lower().startswith(('http://', 'https://')):
                    link = 'http://' + link.lstrip('/')
                ok = self.web_action_browser._py_cover_api_set(link)
                self._fc_log('py封面链接 改成 %s 保存=%s' % (link, ok))
                return self._common_path_card(ok, ('✅ 已换成\n\n🎨 %s\n\n重新进一次 py 页就按新链接取封面' % link)
                                              if ok else '⚠️ 没保存上，重启宿主后可能还原')

            if act == '删除常用路径':
                raw = obj.get('value', '') or obj.get('url', '') or ''
                if isinstance(raw, dict):
                    raw = raw.get('text', '') or raw.get('input', '')
                key = self._common_path_tidy(raw)
                if not key:
                    return {
                        'actionId': '单项输入',
                        'id': 'text',
                        'type': 'input',
                        'title': '🗑️ 删除常用路径',
                        'tip': '输入名称或路径',
                        'value': '',
                        'msg': '要删哪个？'
                    }
                paths = self.web_action_browser._load_common_paths_static()
                keep, removed = [], []
                for it in paths:
                    if it['name'] == key or it['path'] == key or it['path'].rstrip('/') == key.rstrip('/'):
                        removed.append(it)
                    else:
                        keep.append(it)
                if not removed:
                    return self._common_path_card(False, '❌ 没找到「%s」\n\n现有: %s' % (
                        key, '、'.join([x['name'] for x in paths]) or '（空）'))
                self.web_action_browser._save_common_paths_static(keep)
                return self._common_path_card(True, '🗑️ 已删除\n\n' + '\n'.join(
                    ['📌 %s\n📂 %s' % (x['name'], x['path']) for x in removed]))

            if act == '修改常用路径':
                raw = obj.get('value', '') or obj.get('url', '') or ''
                if isinstance(raw, dict):
                    raw = raw.get('text', '') or raw.get('input', '')
                raw = str(raw or '').strip()
                if not raw:
                    return {
                        'actionId': '单项输入',
                        'id': 'text',
                        'type': 'input',
                        'title': '✏️ 修改常用路径',
                        'tip': '格式: 原名|新名称|新路径\n后两项可只写一个',
                        'value': '',
                        'msg': '要改哪个？'
                    }
                parts = [self._common_path_tidy(x) for x in raw.split('|')]
                if len(parts) < 2:
                    return self._common_path_card(False, '❌ 格式不对\n\n请用: 原名|新名称\n或 原名|新名称|新路径')
                old, new_name = parts[0], parts[1]
                new_path = parts[2] if len(parts) >= 3 else ''
                if new_path:
                    if not new_path.startswith('/') and ':' not in new_path:
                        new_path = '/storage/emulated/0/' + new_path.lstrip('/')
                    if new_path.endswith('/') and len(new_path) > 1:
                        new_path = new_path.rstrip('/')
                paths = self.web_action_browser._load_common_paths_static()
                hit = None
                for it in paths:
                    if it['name'] == old or it['path'] == old:
                        hit = it
                        break
                if hit is None:
                    return self._common_path_card(False, '❌ 没找到「%s」\n\n现有: %s' % (
                        old, '、'.join([x['name'] for x in paths]) or '（空）'))
                if new_name:
                    hit['name'] = new_name
                if new_path:
                    hit['path'] = new_path
                self.web_action_browser._save_common_paths_static(paths)
                return self._common_path_card(True, '✏️ 已修改\n\n📌 %s\n📂 %s' % (hit['name'], hit['path']))

            if isinstance(act, str) and act.startswith('改常用路径名|'):
                try:
                    _pth = self.b64u_decode(act.split('|', 1)[1])
                except Exception:
                    _pth = ''
                vals = self._pick_action_inputs(obj)
                _nm = self._common_path_tidy(vals.get('__text__') or vals.get('text') or '')
                if not _nm:
                    return self._common_path_card(False, '没改名：名字是空的')
                paths = self.web_action_browser._load_common_paths_static()
                hit = None
                for it in paths:
                    if os.path.normpath(str(it.get('path') or '')) == os.path.normpath(_pth):
                        hit = it
                        break
                if hit is None:
                    return self._common_path_card(False, '❌ 常用路径里没有这个\n\n📂 ' + _pth)
                hit['name'] = _nm
                ok = self.web_action_browser._save_common_paths_static(paths)
                msg = '✅ 已改名\n\n📌 ' + _nm + '\n📂 ' + _pth
                if not ok:
                    msg += '\n\n⚠️ 保存失败，重启宿主后可能丢失'
                return self._common_path_card(True, msg)

            if isinstance(act, str) and act.startswith('删常用路径|'):
                try:
                    _pth = self.b64u_decode(act.split('|', 1)[1])
                except Exception:
                    _pth = ''
                vals = self._pick_action_inputs(obj)
                _yes = str(vals.get('__text__') or vals.get('text') or '').strip()
                if not _yes:
                    return self._common_path_card(False, '已取消，没删')
                paths = self.web_action_browser._load_common_paths_static()
                hit = None
                for it in paths:
                    if os.path.normpath(str(it.get('path') or '')) == os.path.normpath(_pth):
                        hit = it
                        break
                if hit is None:
                    return self._common_path_card(False, '❌ 常用路径里没有这个\n\n📂 ' + _pth)
                left = [x for x in paths
                        if os.path.normpath(str(x.get('path') or '')) != os.path.normpath(_pth)]
                ok = self.web_action_browser._save_common_paths_static(left)
                msg = '🗑️ 已从常用路径删掉\n\n📌 ' + str(hit.get('name') or '') + '\n📂 ' + _pth
                if not ok:
                    msg += '\n\n⚠️ 保存失败，重启宿主后可能丢失'
                return self._common_path_card(True, msg)

            if isinstance(act, str) and act.startswith('删除py书签|'):
                try:
                    _pth = self.b64u_decode(act.split('|', 1)[1])
                except Exception:
                    _pth = ''
                if not _pth:
                    return self._common_path_card(False, '❌ 没拿到 py 路径\n\n请重新从 py 首页点「删除书签」')
                vals = self._pick_action_inputs(obj)
                _yes = str(vals.get('__text__') or vals.get('text') or '').strip()
                if not _yes:
                    return self._common_path_card(False, '已取消，没删')
                mounts = self.web_action_browser._load_py_mounts_static()
                hit = None
                for it in mounts:
                    if os.path.normpath(str(it.get('path') or '')) == os.path.normpath(_pth):
                        hit = it
                        break
                if hit is None:
                    return self._common_path_card(False, '❌ py书签 里没有这个\n\n📄 %s' % _pth)
                left = [x for x in mounts
                        if os.path.normpath(str(x.get('path') or '')) != os.path.normpath(_pth)]
                ok = self.web_action_browser._save_py_mounts_static(left)
                msg = ('🗑️ 已从 py书签 删掉\n\n🧩 %s\n📄 %s\n\n（首页/设置里的挂载分类不受影响）'
                       % (hit.get('name') or os.path.basename(_pth), _pth))
                if not ok:
                    msg += '\n\n⚠️ 保存失败，重启宿主后可能丢失'
                return self._common_path_card(True, msg)

            if isinstance(act, str) and act.startswith('删除首页挂载|'):
                try:
                    _pth = self.b64u_decode(act.split('|', 1)[1])
                except Exception:
                    _pth = ''
                if not _pth:
                    return self._common_path_card(False, '❌ 没拿到 py 路径\n\n请重新进这个 py，再点一次「删除挂载」')
                vals = self._pick_action_inputs(obj)
                _yes = str(vals.get('__text__') or vals.get('text') or '').strip()
                if not _yes:
                    return self._common_path_card(False, '已取消，没删')
                mounts = self.web_action_browser._load_home_mounts_static()
                hit = None
                for it in mounts:
                    if os.path.normpath(str(it.get('path') or '')) == os.path.normpath(_pth):
                        hit = it
                        break
                if hit is None:
                    return self._common_path_card(False, '❌ 首页挂载里没有这个\n\n📄 ' + _pth)
                left = [x for x in mounts
                        if os.path.normpath(str(x.get('path') or '')) != os.path.normpath(_pth)]
                ok = self.web_action_browser._save_home_mounts_static(left)
                _nm = str(hit.get('name') or os.path.basename(_pth))
                if _nm.lower().endswith('.py'):
                    _nm = _nm[:-3]
                msg = ('🗑️ 已删除挂载\n\n🧩 %s\n📄 %s\n\n回首页（或重开宿主）那颗「🧩 %s」就没了'
                       % (_nm, _pth, _nm))
                if not ok:
                    msg += '\n\n⚠️ 保存失败，重启宿主后可能丢失'
                return self._common_path_card(True, msg)

            if isinstance(act, str) and act.startswith('设置首页挂载|'):
                try:
                    _pth = self.b64u_decode(act.split('|', 1)[1])
                except Exception:
                    _pth = ''
                if not _pth:
                    return self._common_path_card(False, '❌ 没拿到 py 路径\n\n请重新进这个 py，再点一次「设置挂载」')
                vals = self._pick_action_inputs(obj)
                name = self._common_path_tidy(vals.get('name') or '') or os.path.basename(_pth)
                if str(name).lower().endswith('.py'):
                    name = str(name)[:-3]
                if not name:
                    name = os.path.basename(_pth)
                cover = str(vals.get('cover') or '').strip()
                mounts = self.web_action_browser._load_home_mounts_static()
                hit = None
                for it in mounts:
                    if os.path.normpath(str(it.get('path') or '')) == os.path.normpath(_pth):
                        hit = it
                        break
                if hit is None:
                    rec = {'name': name, 'path': _pth}
                    if cover:
                        rec['cover'] = cover
                    mounts.append(rec)
                    head = '✅ 已挂到首页'
                else:
                    hit['name'] = name
                    if cover:
                        hit['cover'] = cover
                    else:
                        hit.pop('cover', None)
                    head = '✏️ 已更新挂载'
                ok = self.web_action_browser._save_home_mounts_static(mounts)
                msg = head + '\n\n🧩 %s\n📄 %s' % (name, _pth)
                if not os.path.isfile(_pth):
                    msg += '\n\n⚠️ 这个文件现在还不存在，插卡后会自动出现'
                if cover and not self._mount_pic(cover):
                    msg += '\n\n⚠️ 封面没认出来（要 http(s) 网址或已存在的图片文件），已按原文保存'
                if not ok:
                    msg += '\n\n⚠️ 保存失败，重启宿主后可能丢失'
                msg += '\n\n回首页（或重开宿主）就能在「📌 常用路径」前面看到「🧩 %s」' % name
                return self._common_path_card(True, msg)

            if isinstance(act, str) and act.startswith('设置py密码|'):
                # 2026-11-12 v229：给某个 py 设/改/取消密码
                try:
                    _pth = self.b64u_decode(act.split('|', 1)[1])
                except Exception:
                    _pth = ''
                if not _pth:
                    return self._common_path_card(False, '❌ 没拿到 py 路径\n\n请重新从「设置 → 🔒 密码」里点')
                vals = self._pick_action_inputs(obj)
                _pw = str(vals.get('__text__') or vals.get('text') or '').strip()
                _ok, _set = self._pypass_set(_pth, _pw)
                _nm = os.path.basename(_pth)
                if not _ok:
                    return self._common_path_card(False, '❌ 密码没存下去（看看 tmp 能不能写）\n\n📄 %s' % _pth)
                if _set:
                    _hint = ('🔒 已给 %s 设好密码：py书签里它会变成「🔒 名字」，点开要先输密码'
                             % (os.path.basename(_pth) or _pth))
                else:
                    _hint = ('🔓 已取消 %s 的密码：它又能直接点开了' % (os.path.basename(_pth) or _pth))
                # 2026-11-12 v231：设完/取消完直接回刷新过的密码页
                return self._pypass_page_refreshed(_hint)

            if isinstance(act, str) and act.startswith('解锁py|'):
                # 2026-11-12 v229：把某个 py 的密码对一下
                try:
                    _pth = self.b64u_decode(act.split('|', 1)[1])
                except Exception:
                    _pth = ''
                if not _pth:
                    return self._common_path_card(False, '❌ 没拿到 py 路径\n\n重进一次那个 py 再点「🔑 输入密码」')
                vals = self._pick_action_inputs(obj)
                _pw = str(vals.get('__text__') or vals.get('text') or '').strip()
                if self._pypass_check(_pth, _pw):
                    self._pypass_unlock(_pth)
                    # 2026-11-12 v231：密码对了就直接把这个 py 打开（用户要的「输完自动刷新成能打开」）
                    _pg = self._pypass_open_page(_pth)
                    if _pg is not None:
                        try:
                            _pg['toast'] = '✅ 密码对了，已经进来'
                        except Exception:
                            pass
                        return _pg
                    # 进不去（这个 py 自己加载失败之类）就至少把书签页刷新一遍，那张卡已经能点了
                    return self._pypass_mount_page(
                        '✅ 密码对了：%s 现在可以直接点开' % (os.path.basename(_pth) or _pth))
                return self._pypass_result(
                    False, '❌ 密码不对\n\n📄 %s\n\n再输一次；忘了就去「设置 → 🔒 密码」给它重设。' % _pth,
                    [self._pypass_gate_card(_pth)], 'lock')

            if isinstance(act, str) and act.startswith('设置py挂载|'):
                try:
                    _pth = self.b64u_decode(act.split('|', 1)[1])
                except Exception:
                    _pth = ''
                if not _pth:
                    return self._common_path_card(False, '❌ 没拿到 py 路径\n\n请重新从 py 首页点「设置挂载」')
                vals = self._pick_action_inputs(obj)
                name = self._common_path_tidy(vals.get('name') or '') or os.path.basename(_pth)
                if str(name).lower().endswith('.py'):
                    name = str(name)[:-3]
                cover = str(vals.get('cover') or '').strip()
                mounts = self.web_action_browser._load_py_mounts_static()
                hit = None
                for it in mounts:
                    if os.path.normpath(str(it.get('path') or '')) == os.path.normpath(_pth):
                        hit = it
                        break
                if hit is None:
                    rec = {'name': name, 'path': _pth}
                    if cover:
                        rec['cover'] = cover
                    mounts.append(rec)
                    head = '✅ 已加入 py书签'
                else:
                    hit['name'] = name
                    if cover:
                        hit['cover'] = cover
                    else:
                        hit.pop('cover', None)
                    head = '✏️ 已更新挂载'
                ok = self.web_action_browser._save_py_mounts_static(mounts)
                msg = head + '\n\n🧩 %s\n📄 %s' % (name, _pth)
                if cover and not self._mount_pic(cover):
                    msg += '\n\n⚠️ 封面没认出来（要 http(s) 网址或已存在的图片文件），已按原文保存'
                if not os.path.isfile(_pth):
                    msg += '\n\n⚠️ 这个文件现在还不存在，插卡后会自动出现'
                if not ok:
                    msg += '\n\n⚠️ 保存失败，重启宿主后可能丢失'
                return self._common_path_card(True, msg)

            # ===== 挂载：动作里添加，加好会在首页「📌 常用路径」前面铺一个分类（和 py书签 分开存）=====
            if act in ('添加新的挂载', '删除挂载'):
                vals = self._pick_action_inputs(obj)
                raw = str(vals.get('__text__') or '')
                if not raw and isinstance(obj.get('value'), str):
                    raw = str(obj.get('value') or '').strip()
                loader = self.web_action_browser._load_home_mounts_static
                saver = self.web_action_browser._save_home_mounts_static
                mounts = loader()

                def _mnorm(p):
                    p = self._common_path_tidy(p)
                    if p and not p.startswith('/') and ':' not in p:
                        p = '/storage/emulated/0/' + p.lstrip('/')
                    if len(p) > 1 and p.endswith('/'):
                        p = p.rstrip('/')
                    return p

                if act == '添加新的挂载':
                    if not (self._common_path_tidy(vals.get('file') or vals.get('path') or '') or raw):
                        return {
                            'actionId': '添加新的挂载',
                            'type': 'multiInput',
                            'title': '➕ 添加新的挂载',
                            'msg': '选一个 .py 文件挂进来，给它起个名字',
                            'input': self._path_pick_inputs(True),
                        }
                    name = self._common_path_tidy(vals.get('name') or '')
                    pfile = self._common_path_tidy(vals.get('file') or vals.get('path') or '')
                    if not pfile and raw:
                        if '@' in raw:
                            _n, _p = raw.split('@', 1)
                            name = name or self._common_path_tidy(_n)
                            pfile = self._common_path_tidy(_p)
                        else:
                            pfile = self._common_path_tidy(raw)
                    pth = _mnorm(pfile)
                    if not pth:
                        return self._common_path_card(False, '❌ 路径是空的\n\n请点「py 文件」那一行去选文件')
                    if os.path.isdir(pth):
                        return self._common_path_card(False, '❌ 这是个文件夹\n\n挂载要选具体的 .py 文件')
                    if not str(pth).lower().endswith('.py'):
                        return self._common_path_card(False, '❌ 不是 .py 文件\n\n当前选的是：' + pth)
                    if not name:
                        _bn = os.path.basename(pth)
                        name = _bn[:-3] if _bn.lower().endswith('.py') else _bn
                        name = name or pth
                    if not os.path.exists(pth):
                        return self._common_path_card(
                            False, '❌ 这个文件不存在\n\n📄 %s\n\n先把 py 文件放到手机上再挂载' % pth)
                    cover = str(vals.get('cover') or '').strip()
                    for it in mounts:
                        if os.path.normpath(str(it.get('path') or '')) == os.path.normpath(pth):
                            return self._common_path_card(False, '❌ 这个文件已经挂载了\n\n🧩 %s\n📄 %s' % (
                                it.get('name'), pth))
                    _rec = {'name': name, 'path': pth}
                    if cover:
                        _rec['cover'] = cover
                    mounts.append(_rec)
                    ok = saver(mounts)
                    msg = '✅ 已挂载：%s\n\n📄 %s\n\n回首页（或重开宿主）就能在「📌 常用路径」前面看到「🧩 %s」' % (
                        name, pth, name)
                    if cover and not self._mount_pic(cover):
                        msg += '\n\n⚠️ 封面没认出来（要 http(s) 网址或已存在的图片文件），已按原文保存'
                    if not ok:
                        msg += '\n\n⚠️ 保存失败，重启宿主后可能丢失'
                    return self._common_path_card(True, msg)

                if not raw:
                    return {
                        'actionId': '单项输入',
                        'id': 'text',
                        'type': 'input',
                        'title': '🗑️ 删除挂载',
                        'tip': '输入名字就行',
                        'value': '',
                        'msg': '请输入',
                    }
                key = self._common_path_tidy(raw)
                keep, removed = [], []
                for it in mounts:
                    if it.get('name') == key or it.get('path') == key or it.get('path') == _mnorm(key):
                        removed.append(it)
                    else:
                        keep.append(it)
                if not removed:
                    return self._common_path_card(False, '❌ 没找到「%s」\n\n现有: %s' % (
                        key, '、'.join([str(x.get('name') or '') for x in mounts]) or '（空）'))
                saver(keep)
                return self._common_path_card(True, '🗑️ 已删除挂载\n\n' + '\n'.join(
                    ['🧩 %s\n📄 %s' % (x.get('name'), x.get('path')) for x in removed]))

            if act in ('添加py挂载', '删除py挂载', '修改py挂载'):
                vals = self._pick_action_inputs(obj)
                raw = str(vals.get('__text__') or '')
                if not raw and isinstance(obj.get('value'), str):
                    raw = str(obj.get('value') or '').strip()
                tips = {
                    '删除py挂载': '输入名称或目录路径',
                    '修改py挂载': '格式: 原名|新名称|新py文件|新封面\n后面几项可只写一个，封面填 - 表示清空',
                }
                titles = {
                    '添加py挂载': '➕ 添加py书签',
                    '删除py挂载': '🗑️ 删除py书签',
                    '修改py挂载': '✏️ 修改py书签',
                }
                if act == '添加py挂载':
                    if not (self._common_path_tidy(vals.get('file') or vals.get('path') or '') or raw):
                        return {
                            'actionId': act,
                            'type': 'multiInput',
                            'title': titles.get(act, act),
                            'msg': '选一个 .py 文件挂进来，给它起个名字',
                            'input': self._path_pick_inputs(True)
                        }
                elif not raw:
                    return {
                        'actionId': '单项输入',
                        'id': 'text',
                        'type': 'input',
                        'title': titles.get(act, act),
                        'tip': tips.get(act, ''),
                        'value': '',
                        'msg': '请输入'
                    }
                loader = self.web_action_browser._load_py_mounts_static
                saver = self.web_action_browser._save_py_mounts_static
                mounts = loader()

                def _norm(p):
                    p = self._common_path_tidy(p)
                    if p and not p.startswith('/') and ':' not in p:
                        p = '/storage/emulated/0/' + p.lstrip('/')
                    if len(p) > 1 and p.endswith('/'):
                        p = p.rstrip('/')
                    return p

                if act == '添加py挂载':
                    name = self._common_path_tidy(vals.get('name') or '')
                    pfile = self._common_path_tidy(vals.get('file') or vals.get('path') or '')
                    if not pfile and raw:
                        if '@' in raw:
                            _n, _p = raw.split('@', 1)
                            name = name or self._common_path_tidy(_n)
                            pfile = self._common_path_tidy(_p)
                        else:
                            pfile = self._common_path_tidy(raw)
                    pth = _norm(pfile)
                    if not pth:
                        return self._common_path_card(False, '❌ 路径是空的\n\n请按 名称@py文件路径 的格式填写')
                    if os.path.isdir(pth):
                        return self._common_path_card(False, '❌ 这是个文件夹\n\n挂载要填到具体的 .py 文件，例如\n/storage/emulated/0/VodPlus/wwwroot/PY[py]/xxx.py')
                    if not str(pth).lower().endswith('.py'):
                        return self._common_path_card(False, '❌ 不是 .py 文件\n\n当前填的是：' + pth)
                    if not name:
                        name = os.path.basename(pth)[:-3] if os.path.basename(pth).lower().endswith('.py') else os.path.basename(pth)
                        name = name or pth
                    cover = str(vals.get('cover') or '').strip()
                    for it in mounts:
                        if it['path'] == pth:
                            return self._common_path_card(False, '❌ 这个文件已经挂载了\n\n🧩 %s\n📄 %s' % (it['name'], pth))
                    _rec = {'name': name, 'path': pth}
                    if cover:
                        _rec['cover'] = cover
                    mounts.append(_rec)
                    ok = saver(mounts)
                    msg = '✅ 已挂载\n\n🧩 %s\n📄 %s' % (name, pth)
                    if cover:
                        if self._mount_pic(cover):
                            msg += '\n🖼️ 封面已设置'
                        else:
                            msg += '\n\n⚠️ 封面没认出来（要 http(s) 网址或已存在的图片文件），已按原文保存'
                    if not os.path.isfile(pth):
                        msg += '\n\n⚠️ 这个文件现在还不存在，插卡后会自动出现'
                    if not ok:
                        msg += '\n\n⚠️ 保存失败，重启宿主后可能丢失'
                    return self._common_path_card(True, msg)

                if act == '删除py挂载':
                    key = self._common_path_tidy(raw)
                    keep, removed = [], []
                    for it in mounts:
                        if it['name'] == key or it['path'] == key or it['path'] == _norm(key):
                            removed.append(it)
                        else:
                            keep.append(it)
                    if not removed:
                        return self._common_path_card(False, '❌ 没找到「%s」\n\n现有: %s' % (
                            key, '、'.join([x['name'] for x in mounts]) or '（空）'))
                    saver(keep)
                    return self._common_path_card(True, '🗑️ 已删除挂载\n\n' + '\n'.join(
                        ['🧩 %s\n📂 %s' % (x['name'], x['path']) for x in removed]))

                parts = [self._common_path_tidy(x) for x in raw.split('|')]
                if len(parts) < 2:
                    return self._common_path_card(False, '❌ 格式不对\n\n请用: 原名|新名称\n或 原名|新名称|新文件|新封面')
                old, new_name = parts[0], parts[1]
                new_path = _norm(parts[2]) if len(parts) >= 3 else ''
                hit = None
                for it in mounts:
                    if it['name'] == old or it['path'] == old:
                        hit = it
                        break
                if hit is None:
                    return self._common_path_card(False, '❌ 没找到「%s」\n\n现有: %s' % (
                        old, '、'.join([x['name'] for x in mounts]) or '（空）'))
                if new_name:
                    hit['name'] = new_name
                new_cover = parts[3] if len(parts) >= 4 else ''
                if new_path:
                    if os.path.isdir(new_path) or not str(new_path).lower().endswith('.py'):
                        return self._common_path_card(False, '❌ 新路径不是 .py 文件：' + new_path)
                    hit['path'] = new_path
                if new_cover:
                    if new_cover in ('-', '无', '清空'):
                        hit.pop('cover', None)
                    else:
                        hit['cover'] = new_cover
                saver(mounts)
                return self._common_path_card(True, '✏️ 已修改挂载\n\n🧩 %s\n📄 %s' % (hit['name'], hit['path']))

            if isinstance(act, str) and act.startswith('访问网址|'):
                # 也兼容「命令里直接带网址」的写法
                try:
                    obj = dict(obj or {})
                    obj['url'] = act.split('|', 1)[1]
                except Exception:
                    pass
                act = '访问网址'

            if act == '访问网址':
                url = obj.get('url', '') or obj.get('value', '') or obj.get('text', '')
                if isinstance(url, dict):
                    url = url.get('text', '')
                if not str(url or '').strip():
                    # 宿主回传的输入可能挂在 input / inputs / 各项里，这里把能读到的都试一遍
                    try:
                        _in = self._pick_action_inputs(obj) or {}
                        for _k in ('url', 'text', '__text__', 'value'):
                            if str(_in.get(_k) or '').strip():
                                url = _in.get(_k)
                                break
                    except Exception:
                        pass
                if url and url.strip():
                    if not url.startswith(('http://', 'https://')):
                        url = 'https://' + url
                    if self._webview_open(url, '访问的网页'):
                        return {'toast': '🌐 已用全屏浏览器打开'}
                    if self._sys_open_url(url, '访问的网页'):
                        return {'toast': '🌐 已交给系统浏览器打开'}
                    return self.web_action_browser._open_url_action(url, '访问的网页')
                else:
                    return {
                        'actionId': '单项输入',
                        'id': 'text',
                        'type': 'input',
                        'title': '🌐 访问网址',
                        'tip': '输入网址，如 baidu.com',
                        'value': '',
                        'msg': '请输入网址'
                    }
            
            if act == '添加小游戏':
                _v = self._pick_action_inputs(obj) or {}
                _nm = str(_v.get('name') or '').strip()
                _gurl = str(_v.get('url') or '').strip()
                _pic = str(_v.get('cover') or '').strip()
                if not _gurl:
                    return {
                        'actionId': '添加小游戏',
                        'type': 'multiInput',
                        'title': '🎮 添加小游戏',
                        'msg': '网址必填；名称留空就用链接，封面留空用随机图',
                        'input': [
                            {'id': 'name', 'name': '名称', 'tip': '游戏名，留空就用链接', 'value': _nm},
                            {'id': 'url', 'name': '网址', 'tip': 'http 或 https 开头、能直接玩的页面', 'value': ''},
                            {'id': 'cover', 'name': '封面', 'tip': '图片网址或本地图片路径，留空用随机图', 'value': _pic},
                        ],
                    }
                _ok, _msg = GameHall.add_custom(_nm, _gurl, _pic)
                return self._common_path_card(
                    _ok, ('✅ ' if _ok else '❌ ') + str(_msg) +
                    ('\n\n回「🎮 游戏大厅」重新进一次就能看到，排在最前面' if _ok else ''))
            if act == '删除小游戏':
                _v = self._pick_action_inputs(obj) or {}
                _key = str(_v.get('name') or _v.get('__text__') or '').strip()
                if not _key:
                    return {
                        'actionId': '删除小游戏',
                        'type': 'multiInput',
                        'title': '🗑️ 删除小游戏',
                        'msg': '填要删掉的那个名字或网址',
                        'input': [{'id': 'name', 'name': '名称', 'tip': '已经加过的游戏', 'value': ''}],
                    }
                _ok, _msg = GameHall.remove_custom(_key)
                return self._common_path_card(_ok, ('✅ ' if _ok else '❌ ') + str(_msg))
            if act == '添加网页工具':
                _v = self._pick_action_inputs(obj) or {}
                _nm = str(_v.get('name') or '').strip()
                _src = str(_v.get('file') or _v.get('path') or '').strip()
                _root = str(_v.get('root') or '').strip()
                _rel = str(_v.get('rel') or '').strip()
                _cov = str(_v.get('cover') or '').strip()
                if not _src and isinstance(obj.get('url'), str):
                    _src = obj['url'].strip()
                if not _src:
                    return {
                        'actionId': '添加网页工具',
                        'type': 'multiInput',
                        'title': '➕ 添加网页工具',
                        'msg': '先在「本地文件」那一行点开选一个 .php 或 .html',
                        'input': [
                            {'id': 'name', 'name': '名称', 'tip': '工具显示的名字，留空用文件名', 'value': _nm},
                            {'id': 'file', 'name': '本地文件', 'tip': '点这一行选 .php / .html 文件', 'value': '',
                             'selectData': '[file]'},
                            {'id': 'root', 'name': '服务器根目录', 'tip': '留空用默认：' + DEFAULT_WWW_ROOT,
                             'value': _root},
                            {'id': 'rel', 'name': '存放路径', 'tip': '相对根目录，可带子目录，如 tools/reader.php；留空就用原文件名',
                             'value': _rel},
                            {'id': 'cover', 'name': '封面', 'tip': '图片网址或本地图片路径，留空用随机图', 'value': _cov},
                        ],
                    }
                _ok, _msg, _url = self.web_action_browser.web_tool_add(_nm, _src, _root, _rel, _cov)
                if _ok:
                    return {
                        'list': [{
                            'vod_id': 'action_result',
                            'vod_name': '✅ 加好了\n\n🧩 %s\n📄 %s\n🌐 %s' % (_nm or os.path.basename(_url), _msg, _url),
                            'vod_pic': self._generate_colored_icon('#4CAF50', '✓'),
                            'vod_remarks': '去「🛠 工具」里点开就行',
                            'style': {'type': 'list'},
                            'vod_player': '书'
                        }],
                        'page': 1,
                        'pagecount': 1
                    }
                return {
                    'list': [{
                        'vod_id': 'action_result',
                        'vod_name': '❌ %s' % _msg,
                        'vod_pic': self._generate_colored_icon('#F44336', '✗'),
                        'vod_remarks': '添加失败',
                        'style': {'type': 'list'},
                        'vod_player': '书'
                    }],
                    'page': 1,
                    'pagecount': 1
                }
            if act == '删除网页工具':
                _v = self._pick_action_inputs(obj) or {}
                _key = str(_v.get('name') or _v.get('__text__') or '').strip()
                if not _key:
                    return {
                        'actionId': '删除网页工具',
                        'type': 'multiInput',
                        'title': '🗑️ 删除网页工具',
                        'msg': '填要删掉的那个名字或文件名',
                        'input': [{'id': 'name', 'name': '名称', 'tip': '已经加过的工具', 'value': ''}],
                    }
                _ok, _msg = self.web_action_browser.web_tool_remove(_key)
                return {
                    'list': [{
                        'vod_id': 'action_result',
                        'vod_name': ('✅ %s' if _ok else '❌ %s') % _msg,
                        'vod_pic': self._generate_colored_icon('#4CAF50' if _ok else '#F44336', '✓' if _ok else '✗'),
                        'vod_remarks': '删除成功' if _ok else '删除失败',
                        'style': {'type': 'list'},
                        'vod_player': '书'
                    }],
                    'page': 1,
                    'pagecount': 1
                }
            if act == '添加书签':
                _v = self._pick_action_inputs(obj) or {}
                title = str(_v.get('name') or _v.get('title') or '').strip()
                url = str(_v.get('url') or '').strip()
                cover = str(_v.get('cover') or '').strip()
                _txt = str(_v.get('__text__') or '').strip()
                if _txt and not url:                     # 老写法 名称@网址@封面 也认
                    _pp = _txt.split('@')
                    if len(_pp) >= 2:
                        title = title or _pp[0].strip()
                        url = _pp[1].strip()
                        cover = cover or (_pp[2].strip() if len(_pp) >= 3 else '')
                    else:
                        url = _txt
                if not url:
                    return {
                        'actionId': '添加书签',
                        'type': 'multiInput',
                        'title': '📌 添加书签',
                        'msg': '一项一个框；封面留空就用默认图标',
                        'input': [
                            {'id': 'name', 'name': '名称', 'tip': '书签显示的名字', 'value': title},
                            {'id': 'url', 'name': '网址', 'tip': 'http 或 https 开头的地址', 'value': ''},
                            {'id': 'cover', 'name': '封面图',
                             'tip': '图片网址或本地图片路径，留空用默认图标', 'value': cover},
                        ],
                    }
                if not title:
                    title = url
                for bm in self.web_action_browser.bookmarks:
                    if bm['url'] == url:
                        return {
                            'list': [{
                                'vod_id': 'action_result',
                                'vod_name': f'❌ 书签已存在\n\n📌 {bm["title"]}\n🔗 {bm["url"]}',
                                'vod_pic': self._generate_colored_icon("#F44336", "✗"),
                                'vod_remarks': '添加失败',
                                'style': {'type': 'list'},
                                'vod_player': '书'
                            }],
                            'page': 1,
                            'pagecount': 1
                        }
                self.web_action_browser.bookmarks.append({
                    'id': hashlib.md5(url.encode('utf-8', 'surrogateescape')).hexdigest()[:8],
                    'url': url,
                    'title': title,
                    'cover': cover,
                    'add_time': time.time()
                })
                self.web_action_browser._save_bookmarks()
                return {
                    'list': [{
                        'vod_id': 'action_result',
                        'vod_name': '✅ 添加成功！\n\n📌 %s\n🔗 %s...' % (title, url[:50]),
                        'vod_pic': self._generate_colored_icon("#4CAF50", "✓"),
                        'vod_remarks': '添加成功',
                        'style': {'type': 'list'},
                        'vod_player': '书'
                    }],
                    'page': 1,
                    'pagecount': 1
                }
            
            if act == '删除书签':
                input_text = obj.get('url', '') or obj.get('value', '')
                if isinstance(input_text, dict):
                    input_text = input_text.get('text', '')
                if input_text and input_text.strip():
                    for bm in self.web_action_browser.bookmarks[:]:
                        if bm['title'] == input_text or bm['url'] == input_text or input_text in bm['url']:
                            title = bm['title']
                            url = bm['url']
                            self.web_action_browser.bookmarks.remove(bm)
                            self.web_action_browser._save_bookmarks()
                            return {
                                'list': [{
                                    'vod_id': 'action_result',
                                    'vod_name': f'✅ 删除成功！\n\n📌 {title}\n🔗 {url[:50]}...',
                                    'vod_pic': self._generate_colored_icon("#4CAF50", "✓"),
                                    'vod_remarks': '删除成功',
                                    'style': {'type': 'list'},
                                    'vod_player': '书'
                                }],
                                'page': 1,
                                'pagecount': 1
                            }
                    return {
                        'list': [{
                            'vod_id': 'action_result',
                            'vod_name': '❌ 未找到书签\n\n请输入正确的书签名或网址',
                            'vod_pic': self._generate_colored_icon("#F44336", "✗"),
                            'vod_remarks': '删除失败',
                            'style': {'type': 'list'},
                            'vod_player': '书'
                        }],
                        'page': 1,
                        'pagecount': 1
                    }
                else:
                    return {
                        'actionId': '单项输入',
                        'id': 'text',
                        'type': 'input',
                        'title': '🗑️ 删除书签',
                        'tip': '输入书签名或网址',
                        'value': '',
                        'msg': '请输入书签名'
                    }
            
            if act == '修改书签名':
                _v = self._pick_action_inputs(obj) or {}
                old = str(_v.get('old') or _v.get('orig') or '').strip()
                new = str(_v.get('name') or _v.get('new') or '').strip()
                new_cover = str(_v.get('cover') or '').strip()
                _txt = str(_v.get('__text__') or '').strip()
                if _txt and not old:                     # 老写法 原书签|新名称|新封面 也认
                    _pp = _txt.split('|')
                    if len(_pp) >= 2:
                        old, new = _pp[0].strip(), _pp[1].strip()
                        new_cover = new_cover or (_pp[2].strip() if len(_pp) >= 3 else '')
                    else:
                        old = _txt
                if not old or not new:
                    return {
                        'actionId': '修改书签名',
                        'type': 'multiInput',
                        'title': '✏️ 修改书签',
                        'msg': '一项一个框；新封面留空就不改',
                        'input': [
                            {'id': 'old', 'name': '原书签名或网址', 'tip': '要改的是哪个书签', 'value': old},
                            {'id': 'name', 'name': '新名称', 'tip': '改成什么名字', 'value': new},
                            {'id': 'cover', 'name': '新封面图',
                             'tip': '图片网址或本地图片路径，留空就不改', 'value': new_cover},
                        ],
                    }
                for bm in self.web_action_browser.bookmarks:
                    if bm['title'] == old or bm['url'] == old:
                        old_title = bm['title']
                        old_url = bm['url']
                        bm['title'] = new
                        if new_cover:
                            bm['cover'] = new_cover
                        self.web_action_browser._save_bookmarks()
                        return {
                            'list': [{
                                'vod_id': 'action_result',
                                'vod_name': f'✅ 修改成功！\n\n📌 {old_title} → {new}\n🔗 {old_url[:50]}...',
                                'vod_pic': self._generate_colored_icon("#4CAF50", "✓"),
                                'vod_remarks': '修改成功',
                                'style': {'type': 'list'},
                                'vod_player': '书'
                            }],
                            'page': 1,
                            'pagecount': 1
                        }
                return {
                    'list': [{
                        'vod_id': 'action_result',
                        'vod_name': '❌ 未找到书签\n\n请检查原书签名或网址填得对不对',
                        'vod_pic': self._generate_colored_icon("#F44336", "✗"),
                        'vod_remarks': '修改失败',
                        'style': {'type': 'list'},
                        'vod_player': '书'
                    }],
                    'page': 1,
                    'pagecount': 1
                }
            

            return None
        except Exception as e:
            print(f"❌ action 错误: {e}")
            import traceback
            traceback.print_exc()
        return None
    
    def destroy(self):
        self.shutdown()